// __codecvt_utf8_utf16<char16_t>::do_in wrapper, vaddr 0x909718..0x909788
// (28 instructions). It loads this->_Maxcode_ (off 0x10) / this->_Mode_
// (off 0x18), shuffles do_in's args into the engine ABI, and BL's the engine
// with callee-saved x19/x20 (the frm_nxt/to_nxt out-pointers) live across the
// call. Two edits make it self-contained for the host replay:
//   - idx0 PACIASP / idx26 AUTIASP -> NOP (PAC value is 0, so they are no-ops;
//     on device the JIT bails on them and the interpreter runs them as no-ops).
//   - idx19 BL is retargeted to the engine when the two blocks are laid out
//     contiguously (engine first, wrapper second) at run time.
inline constexpr uint32_t kMaplibreDoInWrapper[] = {
    0xd503201fU, 0xd100c3ffU, 0xa9017bfdU, 0xa9024ff4U, 0x910043fdU,
    0xaa0703f3U, 0xaa0603eaU, 0xaa0503e8U, 0xaa0203e9U, 0xf9400806U,
    0xb9401807U, 0xaa0403f4U, 0xaa0303e1U, 0xa9000be5U, 0x910023e2U,
    0x910003e5U, 0xaa0903e0U, 0xaa0803e3U, 0xaa0a03e4U, 0x00000000U,
    0xa94023e9U, 0xf9000288U, 0xf9000269U, 0xa9424ff4U, 0xa9417bfdU,
    0x9100c3ffU, 0xd503201fU, 0xd65f03c0U,
};

class Arm64LiteTranslateRegionTest : public ::testing::Test {
 public:
  template <typename T>
  void Reset(const T code) {
    state_.cpu.insn_addr = ToGuestAddr(code);
  }

  template <typename T>
  bool Run(T& code, GuestAddr expected_stop_addr) {
    Reset(code);
    GuestAddr code_end = ToGuestAddr(bit_cast<char*>(&code[0]) + sizeof(code));
    MachineCode machine_code;
    auto [success, stop_pc] = TryLiteTranslateRegion(state_.cpu.insn_addr,
                                                     &machine_code,
                                                     LiteTranslateParams{
                                                         .end_pc = code_end,
                                                         .allow_dispatch = false,
                                                     });

    if (!success || (stop_pc > code_end)) {
      return false;
    }

    // Install via CodePool so Jmp32 relocations to entry points are reachable.
    HostCodeAddr host_code = GetDefaultCodePoolInstance()->Add(&machine_code);
    TestingRunGeneratedCode(&state_, AsHostCode(host_code), expected_stop_addr);

    EXPECT_EQ(state_.cpu.insn_addr, expected_stop_addr);
    return true;
  }

  // Like Run(), but takes an explicit (code, count) so variable-length regions
  // built at runtime (e.g. the all-conditions branch matrix) can be executed.
  bool RunN(const uint32_t* code, size_t n, GuestAddr expected_stop_addr) {
    GuestAddr start = ToGuestAddr(code);
    GuestAddr code_end = start + n * sizeof(uint32_t);
    state_.cpu.insn_addr = start;
    MachineCode machine_code;
    auto [success, stop_pc] = TryLiteTranslateRegion(start,
                                                     &machine_code,
                                                     LiteTranslateParams{
                                                         .end_pc = code_end,
                                                         .allow_dispatch = false,
                                                     });
    if (!success || (stop_pc > code_end)) {
      return false;
    }
    HostCodeAddr host_code = GetDefaultCodePoolInstance()->Add(&machine_code);
    TestingRunGeneratedCode(&state_, AsHostCode(host_code), expected_stop_addr);
    EXPECT_EQ(state_.cpu.insn_addr, expected_stop_addr);
    return true;
  }

  // Drives the interpreter for a single instruction. Interpreter-only ops
  // (EXT, LDXP/STXP, MRS counter reads, etc.) deliberately bail out of the
  // JIT, so Run() can't exercise them; this path tests them directly.
  void Interpret(const uint32_t& insn) {
    state_.cpu.insn_addr = ToGuestAddr(&insn);
    InterpretInsn(&state_);
  }

 protected:
  ThreadState state_{};
};

// Interpreter-vs-EXPECTED for the NEON structured load/store family (LD1-4 /
// ST1-4, multi-register interleaved and single-lane + replicate). Skia's glyph
// blitter and pixel-format conversion lean heavily on these to de/interleave
// coverage and channels; a mis-decode/mis-interpret here rearranges pixels and
// fragments glyphs in EVERY translation mode (shared decoder), exactly the class
// of the prior LD2-as-contiguous bug. Reference de-interleaving is computed in
// C++ and compared against the interpreter.
TEST_F(Arm64LiteTranslateRegionTest, StructuredLoadStoreInterpreterVsExpected) {
  auto getv = [&](int i, uint8_t out[16]) { memcpy(out, &state_.cpu.v[i], 16); };
  auto zerovs = [&]() {
    for (int i = 0; i < 32; i++) {
      uint64_t z[2] = {0, 0};
      memcpy(&state_.cpu.v[i], z, 16);
    }
  };
  alignas(16) uint8_t mem[128];
  auto fill = [&]() {
    for (int i = 0; i < 128; i++) mem[i] = (uint8_t)((i * 53) ^ 0x3C);
  };
  int checked = 0, fails = 0;
  auto run = [&](uint32_t insn) {
    zerovs();
    state_.cpu.x[0] = ToGuestAddr(mem);
    Interpret(insn);
  };

  // --- Multi-struct interleaved loads: V[rt+r][e] = mem[e*n + r] (elem size es) ---
  struct LdN {
    const char* name;
    uint32_t insn;
    int n;       // number of registers
    int es;      // element size in bytes
    int vlen;    // 8 (Q=0) or 16 (Q=1)
  };
  const LdN ldns[] = {
      {"ld2.16b", 0x4c408000, 2, 1, 16}, {"ld3.16b", 0x4c404000, 3, 1, 16},
      {"ld4.16b", 0x4c400000, 4, 1, 16}, {"ld2.8h", 0x4c408400, 2, 2, 16},
      {"ld2.4s", 0x4c408800, 2, 4, 16},  {"ld2.2d", 0x4c408c00, 2, 8, 16},
      {"ld3.8h", 0x4c404400, 3, 2, 16},  {"ld4.4s", 0x4c400800, 4, 4, 16},
      {"ld2.8b", 0x0c408000, 2, 1, 8},   {"ld3.4h", 0x0c404400, 3, 2, 8},
  };
  for (const LdN& l : ldns) {
    fill();
    run(l.insn);
    const int lanes = l.vlen / l.es;
    for (int r = 0; r < l.n; r++) {
      uint8_t got[16];
      getv(r, got);
      uint8_t want[16];
      memset(want, 0, 16);
      for (int e = 0; e < lanes; e++)
        memcpy(want + e * l.es, mem + (e * l.n + r) * l.es, l.es);
      checked++;
      if (memcmp(got, want, 16) != 0 && fails < 20) {
        fails++;
        ADD_FAILURE() << l.name << " V" << r << " de-interleave mismatch";
      }
    }
  }

  // --- Multi-struct contiguous LD1 (1..4 regs, .16b): V[rt+r] = mem[r*16 ..] ---
  const uint32_t ld1n[4] = {0x4c407000, 0x4c40a000, 0x4c406000, 0x4c402000};
  for (int n = 1; n <= 4; n++) {
    fill();
    run(ld1n[n - 1]);
    for (int r = 0; r < n; r++) {
      uint8_t got[16];
      getv(r, got);
      checked++;
      if (memcmp(got, mem + r * 16, 16) != 0 && fails < 20) {
        fails++;
        ADD_FAILURE() << "ld1x" << n << " V" << r << " contiguous mismatch";
      }
    }
  }

  // --- Multi-struct interleaved STORE: ST2/ST3/ST4 .16b/.8h/.4s ---
  struct StN {
    const char* name;
    uint32_t insn;
    int n;
    int es;
  };
  const StN stns[] = {
      {"st2.16b", 0x4c008000, 2, 1}, {"st3.8h", 0x4c004400, 3, 2}, {"st4.4s", 0x4c000800, 4, 4}};
  for (const StN& st : stns) {
    // Seed source registers V0..V(n-1) with distinct patterns, zero memory.
    zerovs();
    for (int r = 0; r < st.n; r++) {
      uint8_t v[16];
      for (int b = 0; b < 16; b++) v[b] = (uint8_t)(0x10 * (r + 1) + b);
      memcpy(&state_.cpu.v[r], v, 16);
    }
    memset(mem, 0, sizeof(mem));
    state_.cpu.x[0] = ToGuestAddr(mem);
    Interpret(st.insn);
    const int lanes = 16 / st.es;
    uint8_t want[128];
    memset(want, 0, sizeof(want));
    for (int e = 0; e < lanes; e++)
      for (int r = 0; r < st.n; r++) {
        uint8_t src[16];
        memcpy(src, &state_.cpu.v[r], 16);
        memcpy(want + (e * st.n + r) * st.es, src + e * st.es, st.es);
      }
    checked++;
    if (memcmp(mem, want, st.n * 16) != 0 && fails < 20) {
      fails++;
      ADD_FAILURE() << st.name << " interleaved store mismatch";
    }
  }

  // --- Replicate loads: LD1R .16b (all 16 lanes = mem[0]); LD2R .4s ---
  {
    fill();
    run(0x4d40c000);  // ld1r {v0.16b}
    uint8_t got[16];
    getv(0, got);
    checked++;
    bool ok = true;
    for (int b = 0; b < 16; b++) ok &= (got[b] == mem[0]);
    if (!ok && fails < 20) { fails++; ADD_FAILURE() << "ld1r.16b replicate mismatch"; }
  }
  {
    fill();
    run(0x4d60c800);  // ld2r {v0.4s, v1.4s}
    for (int r = 0; r < 2; r++) {
      uint8_t got[16];
      getv(r, got);
      checked++;
      bool ok = true;
      for (int e = 0; e < 4; e++) ok &= (memcmp(got + e * 4, mem + r * 4, 4) == 0);
      if (!ok && fails < 20) { fails++; ADD_FAILURE() << "ld2r.4s V" << r << " replicate mismatch"; }
    }
  }

  EXPECT_GT(checked, 30);
  EXPECT_EQ(fails, 0);
}

// StoreLoad-ordering fix: ARM STLR is sequentially consistent (RCsc) and a full
// DMB/DSB is a full barrier, but x86 TSO does NOT provide StoreLoad ordering. The
// lite JIT must emit an MFENCE for STLR and for a full DMB (SY/ISH/...), while a
// store-only DMB (ISHST) needs none (x86 gives StoreStore for free). Dropping the
// fence caused flaky, timing/GPU-dependent lock-free corruption (Helium glyphs).
TEST_F(Arm64LiteTranslateRegionTest, StoreLoadBarrierEmitsMfence) {
  auto region_bytes = [&](uint32_t insn) -> std::string {
    static uint32_t code[1];
    code[0] = insn;
    GuestAddr start = ToGuestAddr(&code[0]);
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = start + 4, .allow_dispatch = false});
    EXPECT_TRUE(ok);
    std::string s;
    mc.AsString(&s, InstructionSize::OneByte);
    return s;
  };
  // MFENCE = 0F AE F0.
  auto has_mfence = [](const std::string& s) {
    return s.find("0f ae f0") != std::string::npos || s.find("0F AE F0") != std::string::npos;
  };
  EXPECT_TRUE(has_mfence(region_bytes(0x889ffc01))) << "STLR W must emit MFENCE";
  EXPECT_TRUE(has_mfence(region_bytes(0xc89ffc01))) << "STLR X must emit MFENCE";
  EXPECT_TRUE(has_mfence(region_bytes(0xd5033bbf))) << "DMB ISH (full) must emit MFENCE";
  EXPECT_TRUE(has_mfence(region_bytes(0xd5033fbf))) << "DMB SY (full) must emit MFENCE";
  EXPECT_TRUE(has_mfence(region_bytes(0xd5033f9f))) << "DSB SY (full) must emit MFENCE";
  EXPECT_FALSE(has_mfence(region_bytes(0xd5033abf))) << "DMB ISHST (store-only) needs no MFENCE";
  EXPECT_FALSE(has_mfence(region_bytes(0x88dffc01))) << "LDAR needs no MFENCE (x86 acquire is free)";
}

// Interpreter-vs-EXPECTED for fused multiply-add (FMLA/FMLS vector, FMADD/FMSUB
// scalar) — the core operation for matrix-vector coordinate transforms (e.g. a
// glyph-rendering device matrix). ARM FMLA is FUSED (single rounding), so the
// reference uses std::fma. A wrong FMLA mis-transforms every coordinate (glyph
// displacement) — CPU-side and shared interp+JIT. Verified against std::fma and
// JIT-vs-interpreter.
TEST_F(Arm64LiteTranslateRegionTest, FmaInterpreterVsExpected) {
  auto setS4 = [&](int i, float a, float b, float c, float d) {
    float v[4] = {a, b, c, d};
    memcpy(&state_.cpu.v[i], v, 16);
  };
  auto getS4 = [&](int i, float out[4]) { memcpy(out, &state_.cpu.v[i], 16); };
  auto setD2 = [&](int i, double a, double b) {
    double v[2] = {a, b};
    memcpy(&state_.cpu.v[i], v, 16);
  };
  auto getD2 = [&](int i, double out[2]) { memcpy(out, &state_.cpu.v[i], 16); };
  auto bitsf = [](float a, float b) {
    uint32_t x, y;
    memcpy(&x, &a, 4);
    memcpy(&y, &b, 4);
    return x == y;
  };
  auto bitsd = [](double a, double b) {
    uint64_t x, y;
    memcpy(&x, &a, 8);
    memcpy(&y, &b, 8);
    return x == y;
  };

  // Values where fused (single-rounding) differs from non-fused (two-rounding):
  // a*b is inexact and the addend cancels high bits.
  struct F {
    float n, m, d;
  };
  const F cases[] = {{1.0f, 1.0f, 1.0f},
                     {1.1f, 2.2f, 3.3f},
                     {1e18f, 1e18f, -1e36f},
                     {0.1f, 0.1f, -0.01f},
                     {123456.7f, 765432.1f, -9.4e10f},
                     {-3.5f, 2.25f, 7.0f},
                     {16777217.0f, 1.0f, 0.5f}};  // 2^24+1 rounding edge

  for (const F& c : cases) {
    // FMLA v0.4s, v1.4s, v2.4s : v0 = v0 + v1*v2 (fused).
    setS4(0, c.d, c.d, c.d, c.d);
    setS4(1, c.n, c.n, c.n, c.n);
    setS4(2, c.m, c.m, c.m, c.m);
    Interpret(0x4e22cc20);
    float got[4];
    getS4(0, got);
    float exp = std::fma(c.n, c.m, c.d);
    EXPECT_TRUE(bitsf(got[0], exp))
        << "FMLA.4s n=" << c.n << " m=" << c.m << " d=" << c.d << " exp=" << exp
        << " got=" << got[0];

    // FMLS v0.4s, v1.4s, v2.4s : v0 = v0 - v1*v2 (fused) = fma(-n, m, d).
    setS4(0, c.d, c.d, c.d, c.d);
    setS4(1, c.n, c.n, c.n, c.n);
    setS4(2, c.m, c.m, c.m, c.m);
    Interpret(0x4ea2cc20);
    getS4(0, got);
    float expS = std::fma(-c.n, c.m, c.d);
    EXPECT_TRUE(bitsf(got[0], expS)) << "FMLS.4s exp=" << expS << " got=" << got[0];

    // FMLA v0.2d : double.
    setD2(0, c.d, c.d);
    setD2(1, c.n, c.n);
    setD2(2, c.m, c.m);
    Interpret(0x4e62cc20);
    double gotd[2];
    getD2(0, gotd);
    double expd = std::fma((double)c.n, (double)c.m, (double)c.d);
    EXPECT_TRUE(bitsd(gotd[0], expd)) << "FMLA.2d exp=" << expd << " got=" << gotd[0];

    // FMADD s0, s1, s2, s3 : s0 = s3 + s1*s2 (fused).
    setS4(1, c.n, 0, 0, 0);
    setS4(2, c.m, 0, 0, 0);
    setS4(3, c.d, 0, 0, 0);
    Interpret(0x1f020c20);
    getS4(0, got);
    EXPECT_TRUE(bitsf(got[0], exp)) << "FMADD.s exp=" << exp << " got=" << got[0];

    // FMSUB s0, s1, s2, s3 : s0 = s3 - s1*s2 (fused).
    setS4(1, c.n, 0, 0, 0);
    setS4(2, c.m, 0, 0, 0);
    setS4(3, c.d, 0, 0, 0);
    Interpret(0x1f028c20);
    getS4(0, got);
    EXPECT_TRUE(bitsf(got[0], expS)) << "FMSUB.s exp=" << expS << " got=" << got[0];

    // FMLA v0.4s, v1.4s, v2.s[1] : v0[i] = v0[i] + v1[i]*v2[1] (fused, by-element)
    // — the matrix*vector coordinate-transform form.
    setS4(0, c.d, c.d, c.d, c.d);
    setS4(1, c.n, c.n, c.n, c.n);
    setS4(2, 0.0f, c.m, 0.0f, 0.0f);  // indexed element 1 = m
    Interpret(0x4fa21020);            // fmla v0.4s, v1.4s, v2.s[1]
    getS4(0, got);
    EXPECT_TRUE(bitsf(got[0], exp)) << "FMLA.4s by-elem exp=" << exp << " got=" << got[0];
  }
}

// Interpreter-AND-JIT vs independent reference for the scalar/vector FP ops Skia
// uses to position glyphs: FRINTA (round-to-nearest-ties-away — snaps glyph
// coords to the pixel grid; a wrong rounding mis-snaps glyphs), FSQRT, FMINNM/
// FMAXNM (clamping), FCVTZS (float->int coord), SCVTF (int->float). Both tiers
// must match std::, since the gross garble reproduces in BOTH (a shared bug a
// JIT-vs-interp differential cannot see).
TEST_F(Arm64LiteTranslateRegionTest, FpGridOpsInterpAndJitVsExpected) {
  auto bitsf = [](float a, float b) {
    uint32_t x, y;
    memcpy(&x, &a, 4);
    memcpy(&y, &b, 4);
    return x == y || (std::isnan(a) && std::isnan(b));
  };
  auto setS = [&](int i, float a, float b, float c, float d) {
    float v[4] = {a, b, c, d};
    memcpy(&state_.cpu.v[i], v, 16);
  };
  auto getS0 = [&]() {
    float v[4];
    memcpy(v, &state_.cpu.v[0], 16);
    return v[0];
  };

  const float vals[] = {0.0f,  -0.0f,  0.5f,    -0.5f,   1.5f,   2.5f,   -2.5f,
                        1.4999f, 1e-20f, 16.49f, -16.51f, 123.5f, 100000.3f, 0.1f};

  struct Op {
    uint32_t enc;
    const char* name;
    int kind;  // 0=frinta 1=fsqrt 2=fcvtzs 3=scvtf 4=fneg 5=fabs
  };
  const Op unary[] = {{0x6e218820, "frinta", 0}, {0x6ea1f820, "fsqrt", 1},
                      {0x4ea1b820, "fcvtzs", 2}, {0x4e21d820, "scvtf", 3},
                      {0x6ea0f820, "fneg", 4},   {0x4ea0f820, "fabs", 5}};

  auto run_jit = [&](uint32_t insn) {
    static uint32_t code[1];
    code[0] = insn;
    GuestAddr start = ToGuestAddr(&code[0]);
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = start + 4, .allow_dispatch = false});
    if (!ok) return false;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    state_.cpu.insn_addr = start;
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    return true;
  };

  for (const Op& o : unary) {
    for (float v : vals) {
      float exp;
      if (o.kind == 0) {
        exp = std::roundf(v);  // FRINTA: round-to-nearest, ties away from zero
      } else if (o.kind == 1) {
        exp = std::sqrt(v);
      } else if (o.kind == 2) {
        // FCVTZS .4s: float -> int32 (truncate toward zero), result reinterpreted
        // as the int32 bit pattern in the lane.
        int32_t iv;
        if (std::isnan(v)) iv = 0;
        else if (v >= 2147483648.0f) iv = INT32_MAX;
        else if (v <= -2147483649.0f) iv = INT32_MIN;
        else iv = static_cast<int32_t>(v);
        memcpy(&exp, &iv, 4);
      } else if (o.kind == 3) {
        // SCVTF .4s: interpret lane as int32, convert to float.
        int32_t iv = static_cast<int32_t>(v);  // use a small int proxy
        exp = static_cast<float>(iv);
      } else if (o.kind == 4) {
        exp = -v;
      } else {
        exp = std::fabs(v);
      }

      // SCVTF needs an integer input; feed the int bit pattern.
      float in = v;
      if (o.kind == 3) {
        int32_t iv = static_cast<int32_t>(v);
        memcpy(&in, &iv, 4);
      }

      // Interpreter.
      setS(0, 0, 0, 0, 0);
      setS(1, in, in, in, in);
      Interpret(o.enc);
      float gi = getS0();
      EXPECT_TRUE(bitsf(gi, exp)) << o.name << " INTERP v=" << v << " exp=" << exp << " got=" << gi;

      // JIT.
      setS(0, 0, 0, 0, 0);
      setS(1, in, in, in, in);
      if (run_jit(o.enc)) {
        float gj = getS0();
        EXPECT_TRUE(bitsf(gj, exp)) << o.name << " JIT v=" << v << " exp=" << exp << " got=" << gj;
      }
    }
  }
}

// FMAX/FMIN/FMAXNM/FMINNM .4s signed-zero rule (interp AND JIT): for a +-0 tie,
// FMAX returns the MOST-POSITIVE sign (AND of signs) and FMIN the MOST-NEGATIVE
// (OR of signs). x86 MAXPS/MINPS return the 2nd source on a tie, so FMAX was
// wrong for +0-vs-(-0). Also checks normal values + NaN propagation don't
// regress.
TEST_F(Arm64LiteTranslateRegionTest, FpMinMaxSignedZero) {
  const float pz = 0.0f, nz = -0.0f, nan = std::nanf("");
  auto u = [](float f) { uint32_t b; memcpy(&b, &f, 4); return b; };
  auto setS = [&](int i, float a) {
    float v[4] = {a, a, a, a};
    memcpy(&state_.cpu.v[i], v, 16);
  };
  auto got0 = [&]() {
    float v[4];
    memcpy(v, &state_.cpu.v[0], 16);
    return v[0];
  };

  struct Case {
    uint32_t enc;
    const char* name;
    float a, b, exp;
  };
  const Case cases[] = {
      // FMAX (0x4e22f420): +-0 tie -> most positive (+0); -0,-0 -> -0.
      {0x4e22f420, "fmax", pz, nz, pz}, {0x4e22f420, "fmax", nz, pz, pz},
      {0x4e22f420, "fmax", nz, nz, nz}, {0x4e22f420, "fmax", 3.0f, 5.0f, 5.0f},
      {0x4e22f420, "fmax", 5.0f, 3.0f, 5.0f},
      // FMIN (0x4ea2f420): +-0 tie -> most negative (-0); +0,+0 -> +0.
      {0x4ea2f420, "fmin", pz, nz, nz}, {0x4ea2f420, "fmin", nz, pz, nz},
      {0x4ea2f420, "fmin", pz, pz, pz}, {0x4ea2f420, "fmin", 3.0f, 5.0f, 3.0f},
      // FMAXNM (0x4e22c420): same +-0 rule; ignores NaN (returns the number).
      {0x4e22c420, "fmaxnm", pz, nz, pz}, {0x4e22c420, "fmaxnm", nan, 5.0f, 5.0f},
      // FMINNM (0x4ea2c420).
      {0x4ea2c420, "fminnm", pz, nz, nz}, {0x4ea2c420, "fminnm", nan, 5.0f, 5.0f},
  };

  for (const Case& c : cases) {
    // Interpreter.
    setS(0, 0);
    setS(1, c.a);
    setS(2, c.b);
    Interpret(c.enc);
    EXPECT_EQ(u(got0()), u(c.exp)) << c.name << " INTERP a=" << c.a << " b=" << c.b
                                   << " exp_bits=0x" << std::hex << u(c.exp) << " got_bits=0x"
                                   << u(got0()) << std::dec;
    // JIT.
    setS(0, 0);
    setS(1, c.a);
    setS(2, c.b);
    static uint32_t code[1];
    code[0] = c.enc;
    GuestAddr start = ToGuestAddr(&code[0]);
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = start + 4, .allow_dispatch = false});
    if (ok && stop == start + 4) {
      HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
      state_.cpu.insn_addr = start;
      TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
      EXPECT_EQ(u(got0()), u(c.exp)) << c.name << " JIT a=" << c.a << " b=" << c.b
                                     << " exp_bits=0x" << std::hex << u(c.exp) << " got_bits=0x"
                                     << u(got0()) << std::dec;
    }
  }
}

// Focused ground-truth: MLA/MLS .4s with simple known values.
//   v0={1,2,3,4}, v1={10,10,10,10}, v2={2,3,4,5}
//   MLA: v0[i]+=v1[i]*v2[i] -> {21,32,43,54}
//   MLS: v0[i]-=v1[i]*v2[i] -> {-19,-28,-37,-46}
TEST_F(Arm64LiteTranslateRegionTest, NeonMlaMlsGroundTruth) {
  auto setlanes = [&](int reg, uint32_t a, uint32_t b, uint32_t c, uint32_t d) {
    uint32_t v[4] = {a, b, c, d};
    memcpy(&state_.cpu.v[reg], v, 16);
  };
  auto getlanes = [&](int reg, uint32_t out[4]) { memcpy(out, &state_.cpu.v[reg], 16); };
  auto run_jit = [&](uint32_t insn) -> bool {
    static uint32_t code[1];
    code[0] = insn;
    GuestAddr start = ToGuestAddr(&code[0]);
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = start + 4, .allow_dispatch = false});
    if (!ok || stop != start + 4) return false;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    state_.cpu.insn_addr = start;
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    return true;
  };
  struct C { uint32_t enc; const char* name; uint32_t exp[4]; };
  const C cases[] = {
      {0x4ea29420, "mla.4s", {21u, 32u, 43u, 54u}},
      {0x6ea29420, "mls.4s", {(uint32_t)-19, (uint32_t)-28, (uint32_t)-37, (uint32_t)-46}},
  };
  for (const C& c : cases) {
    uint32_t ri[4], rj[4];
    setlanes(0, 1, 2, 3, 4); setlanes(1, 10, 10, 10, 10); setlanes(2, 2, 3, 4, 5);
    Interpret(c.enc);
    getlanes(0, ri);
    setlanes(0, 1, 2, 3, 4); setlanes(1, 10, 10, 10, 10); setlanes(2, 2, 3, 4, 5);
    bool jok = run_jit(c.enc);
    getlanes(0, rj);
    for (int i = 0; i < 4; i++) {
      EXPECT_EQ(ri[i], c.exp[i]) << c.name << " INTERP lane " << i << " got=0x" << std::hex << ri[i]
                                 << " exp=0x" << c.exp[i];
      if (jok)
        EXPECT_EQ(rj[i], c.exp[i]) << c.name << " JIT lane " << i << " got=0x" << std::hex << rj[i]
                                   << " exp=0x" << c.exp[i];
    }
  }

  // Overflow edge: v0=v1=0xFFFFFFFF, v2=0xFFFFFFFD.
  //   product low32 = (-1)*(-3) mod 2^32 = 3.  MLA = 0xFFFFFFFF + 3 = 2.
  //   MLS = 0xFFFFFFFF - 3 = 0xFFFFFFFC.
  // Also v0=v1=0x80000000, v2=4: product low32 = 0x80000000*4 = 0 (mod 2^32).
  //   MLA = 0x80000000 + 0 = 0x80000000.
  struct E { uint32_t enc; const char* name; uint32_t v0, v1, v2, exp; };
  const E edges[] = {
      {0x4ea29420, "mla", 0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFDu, 0x00000002u},
      {0x6ea29420, "mls", 0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFDu, 0xFFFFFFFCu},
      {0x4ea29420, "mla", 0x80000000u, 0x80000000u, 0x00000004u, 0x80000000u},
      {0x4ea29420, "mla", 0x00000001u, 0x00000001u, 0xFFFFFFFEu, 0xFFFFFFFFu},
      {0x6ea29420, "mls", 0x00000001u, 0x00000001u, 0xFFFFFFFEu, 0x00000003u},
  };
  for (const E& e : edges) {
    uint32_t ri[4], rj[4];
    setlanes(0, e.v0, e.v0, e.v0, e.v0);
    setlanes(1, e.v1, e.v1, e.v1, e.v1);
    setlanes(2, e.v2, e.v2, e.v2, e.v2);
    Interpret(e.enc);
    getlanes(0, ri);
    setlanes(0, e.v0, e.v0, e.v0, e.v0);
    setlanes(1, e.v1, e.v1, e.v1, e.v1);
    setlanes(2, e.v2, e.v2, e.v2, e.v2);
    bool jok = run_jit(e.enc);
    getlanes(0, rj);
    EXPECT_EQ(ri[0], e.exp) << e.name << " INTERP v0=0x" << std::hex << e.v0 << " v1=0x" << e.v1
                            << " v2=0x" << e.v2 << " got=0x" << ri[0] << " exp=0x" << e.exp;
    if (jok)
      EXPECT_EQ(rj[0], e.exp) << e.name << " JIT v0=0x" << std::hex << e.v0 << " v1=0x" << e.v1
                              << " v2=0x" << e.v2 << " got=0x" << rj[0] << " exp=0x" << e.exp;
  }

  // Exact multi-lane fuzzer case (a=1,b=2): per-lane DIFFERENT values expose a
  // lane-dependent bug that same-value-all-lanes hides.
  //   v0=v1={0x80000000,0x7FFFFFFF,0xFFFFFFFF,0x00000001}
  //   v2   ={0x00000004,0x00000003,0xFFFFFFFD,0xFFFFFFFE}
  //   MLA lane: v0+v1*v2 -> {0x80000000,0xFFFFFFFC,0x00000002,0xFFFFFFFF}
  {
    const uint32_t exp[4] = {0x80000000u, 0xFFFFFFFCu, 0x00000002u, 0xFFFFFFFFu};
    uint32_t ri[4], rj[4];
    setlanes(0, 0x80000000u, 0x7FFFFFFFu, 0xFFFFFFFFu, 0x00000001u);
    setlanes(1, 0x80000000u, 0x7FFFFFFFu, 0xFFFFFFFFu, 0x00000001u);
    setlanes(2, 0x00000004u, 0x00000003u, 0xFFFFFFFDu, 0xFFFFFFFEu);
    Interpret(0x4ea29420);
    getlanes(0, ri);
    setlanes(0, 0x80000000u, 0x7FFFFFFFu, 0xFFFFFFFFu, 0x00000001u);
    setlanes(1, 0x80000000u, 0x7FFFFFFFu, 0xFFFFFFFFu, 0x00000001u);
    setlanes(2, 0x00000004u, 0x00000003u, 0xFFFFFFFDu, 0xFFFFFFFEu);
    bool jok = run_jit(0x4ea29420);
    getlanes(0, rj);
    for (int i = 0; i < 4; i++) {
      EXPECT_EQ(ri[i], exp[i]) << "MLA multilane INTERP lane " << i << " got=0x" << std::hex
                               << ri[i] << " exp=0x" << exp[i];
      if (jok)
        EXPECT_EQ(rj[i], exp[i]) << "MLA multilane JIT lane " << i << " got=0x" << std::hex
                                 << rj[i] << " exp=0x" << exp[i];
    }
  }
}

// SSHL/USHL/SRSHL/URSHL .4s interpreter vs ARM-ARM EXPECTED. These per-element
// signed/unsigned (rounding) variable shifts BAIL in the lite JIT (interpreter-
// only, so they run interpreted in EVERY mode), are used in fixed-point coverage
// scaling, and have tricky negative-shift / out-of-width / rounding edges — the
// SQRSHRUN/FMAX bug class. The reference is computed in int64 per the ARM
// pseudocode (shift = SInt(Vm[i]<7:0>); >=0 left, <0 right, S forms arithmetic,
// R forms add 1<<(n-1) before the right shift).
TEST_F(Arm64LiteTranslateRegionTest, NeonVarShiftInterpVsExpected) {
  auto setv = [&](int reg, uint32_t a, uint32_t b, uint32_t c, uint32_t d) {
    uint32_t v[4] = {a, b, c, d};
    memcpy(&state_.cpu.v[reg], v, 16);
  };
  auto v0lane = [&](int i) -> uint32_t {
    uint32_t v[4];
    memcpy(v, &state_.cpu.v[0], 16);
    return v[i];
  };
  enum Kind { kS, kU, kSR, kUR };
  auto ref = [](uint32_t vn, int8_t s, Kind k) -> uint32_t {
    bool sgn = (k == kS || k == kSR);
    bool rnd = (k == kSR || k == kUR);
    if (s >= 0) {  // left shift (rounding bit irrelevant)
      if (s >= 32) return 0u;
      return (uint32_t)(vn << s);
    }
    int n = -(int)s;  // right shift by n
    // 64-bit accumulator: sign- or zero-extend the 32-bit source.
    int64_t x = sgn ? (int64_t)(int32_t)vn : (int64_t)(uint32_t)vn;
    if (rnd) {
      if (n <= 63) x += (int64_t)1 << (n - 1);  // round half up
      // n>63 can't occur for int8 shift on 32-bit data in our test set
    }
    int64_t r;
    if (n >= 64) {
      r = sgn ? (x < 0 ? -1 : 0) : 0;
    } else {
      r = sgn ? (x >> n) : (int64_t)((uint64_t)x >> n);
    }
    return (uint32_t)r;
  };

  struct Op { uint32_t enc; const char* name; Kind k; };
  const Op ops[] = {
      {0x4ea24420, "sshl", kS},  {0x6ea24420, "ushl", kU},
      {0x4ea25420, "srshl", kSR}, {0x6ea25420, "urshl", kUR},
  };
  const uint32_t data[] = {0x00000000u, 0x00000001u, 0x7FFFFFFFu, 0x80000000u,
                           0xFFFFFFFFu, 0x12345678u, 0xFFFF0000u, 0x0000FFFFu,
                           0xABCDEF01u, 0x40000000u};
  // shift amounts placed in the low byte of each Vm lane (signed).
  const int8_t shifts[] = {0,  1,   4,   8,   16,  31,  32,  33,
                           -1, -4,  -8,  -16, -31, -32, -33, -40};
  for (const Op& op : ops) {
    for (uint32_t d : data) {
      for (int8_t s : shifts) {
        setv(1, d, d, d, d);
        uint32_t sm = (uint32_t)(uint8_t)s;  // low byte = signed shift
        setv(2, sm, sm, sm, sm);
        setv(0, 0, 0, 0, 0);
        Interpret(op.enc);
        uint32_t want = ref(d, s, op.k);
        EXPECT_EQ(v0lane(0), want)
            << op.name << " d=0x" << std::hex << d << " s=" << std::dec << (int)s << " got=0x"
            << std::hex << v0lane(0) << " exp=0x" << want;
      }
    }
  }
}

// 128-bit (Q-register) SIMD LDP/STP interp-vs-EXPECTED. This is the core of
// bionic memcpy/memmove (ldp q,q / stp q,q), which copies glyph-mask rows; the
// #3 garble looks like a stride/layout shear of the mask, so a wrong 128-bit
// pair load/store (byte order, half, offset scale, pre/post writeback) is the
// prime suspect. Bailed in lite, interpreter-only, untested (only d/s pairs were).
TEST_F(Arm64LiteTranslateRegionTest, NeonQRegLdpStpInterpVsExpected) {
  alignas(16) static uint8_t buf[1024];
  auto fill = [&]() { for (int i = 0; i < 1024; i++) buf[i] = (uint8_t)(i * 7 + 11); };
  auto getv = [&](int r, uint8_t out[16]) { memcpy(out, &state_.cpu.v[r], 16); };
  auto setv = [&](int r, int seed) {
    uint8_t v[16];
    for (int i = 0; i < 16; i++) v[i] = (uint8_t)(seed * 31 + i * 13 + 5);
    memcpy(&state_.cpu.v[r], v, 16);
  };

  // LDP cases: {enc, rt1, rt2, access_off, wb_delta} ; wb_delta=INT_MIN => no writeback
  const int NWB = 0x7fffffff;
  struct LC { uint32_t enc; int rt1, rt2, aoff, wb; };
  const LC ld[] = {
      {0xad400400, 0, 1, 0, NWB},      {0xad410c02, 2, 3, 32, NWB},
      {0xadc08400, 0, 1, 16, 16},      // pre-index: addr=base+16, x0=base+16
      {0xacc11404, 4, 5, 0, 32},       // post-index: addr=base, x0=base+32
      {0xad7f0400, 0, 1, -32, NWB},    {0xad4f1c06, 6, 7, 480, NWB}};
  for (const LC& c : ld) {
    fill();
    GuestAddr base = ToGuestAddr(buf) + 512;  // mid-buffer so -32 is valid
    state_.cpu.x[0] = base;
    for (int r = 0; r < 8; r++) state_.cpu.v[r] = 0;
    Interpret(c.enc);
    uint8_t g1[16], g2[16];
    getv(c.rt1, g1);
    getv(c.rt2, g2);
    const uint8_t* mem = buf + (base - ToGuestAddr(buf)) + c.aoff;
    EXPECT_EQ(memcmp(g1, mem, 16), 0) << "LDP enc=0x" << std::hex << c.enc << " rt1 mismatch";
    EXPECT_EQ(memcmp(g2, mem + 16, 16), 0) << "LDP enc=0x" << std::hex << c.enc << " rt2 mismatch";
    if (c.wb != NWB)
      EXPECT_EQ(state_.cpu.x[0], base + c.wb) << "LDP enc=0x" << std::hex << c.enc << " writeback";
  }

  // STP cases: {enc, rt1, rt2, access_off, wb_delta}
  struct SC { uint32_t enc; int rt1, rt2, aoff, wb; };
  const SC st[] = {
      {0xad000400, 0, 1, 0, NWB},   {0xad010c02, 2, 3, 32, NWB},
      {0xad808400, 0, 1, 16, 16},   {0xac811404, 4, 5, 0, 32}};
  for (const SC& c : st) {
    fill();
    GuestAddr base = ToGuestAddr(buf) + 256;
    state_.cpu.x[0] = base;
    setv(c.rt1, c.rt1 + 1);
    setv(c.rt2, c.rt2 + 1);
    Interpret(c.enc);
    uint8_t e1[16], e2[16];
    getv(c.rt1, e1);
    getv(c.rt2, e2);
    const uint8_t* mem = buf + (base - ToGuestAddr(buf)) + c.aoff;
    EXPECT_EQ(memcmp(mem, e1, 16), 0) << "STP enc=0x" << std::hex << c.enc << " mem rt1 mismatch";
    EXPECT_EQ(memcmp(mem + 16, e2, 16), 0) << "STP enc=0x" << std::hex << c.enc << " mem rt2 mismatch";
    if (c.wb != NWB)
      EXPECT_EQ(state_.cpu.x[0], base + c.wb) << "STP enc=0x" << std::hex << c.enc << " writeback";
    // bytes outside [mem, mem+32) must be untouched.
    EXPECT_EQ(buf[(base - ToGuestAddr(buf)) + c.aoff - 1], (uint8_t)(((base - ToGuestAddr(buf)) + c.aoff - 1) * 7 + 11))
        << "STP enc=0x" << std::hex << c.enc << " underflow write";
  }
}

// Bailed two-reg-misc (CMXX-vs-0, ABS/NEG, CLS/CLZ/CNT, SADDLP/UADDLP/SADALP/
// UADALP pairwise-long(+acc), SUQADD/USQADD, SQABS/SQNEG) interp-vs-EXPECTED.
TEST_F(Arm64LiteTranslateRegionTest, NeonBailedTwoRegMiscInterpVsExpected) {
  auto sext = [](uint64_t v, int b) -> int64_t { return (int64_t)(v << (64 - b)) >> (64 - b); };
  auto sclamp = [](int64_t x, int b) -> uint64_t {
    int64_t lo = -(int64_t{1} << (b - 1)), hi = (int64_t{1} << (b - 1)) - 1;
    x = x < lo ? lo : (x > hi ? hi : x);
    return (uint64_t)x & (b == 64 ? ~0ULL : ((1ULL << b) - 1));
  };
  const uint64_t vals[] = {0x0, 0x1, 0x7f, 0x80, 0xff, 0x7fffffff, 0x80000000,
                           0xffffffff, 0x40000000, 0x00010000, 0xdeadbeef, 2, 0xfffffffe};

  // --- unary (result from Vn only): CMXX0/ABS/NEG/CLS/CLZ/CNT ---
  enum UK { C_EQ, C_GT, C_GE, C_LE, C_LT, ABS, NEG, CLS, CLZ, CNT };
  struct U { uint32_t enc; const char* name; int esz; UK k; };
  const U un[] = {
      {0x4ea09820, "cmeq0.4s", 4, C_EQ}, {0x4ea08820, "cmgt0.4s", 4, C_GT},
      {0x6ea08820, "cmge0.4s", 4, C_GE}, {0x6ea09820, "cmle0.4s", 4, C_LE},
      {0x4ea0a820, "cmlt0.4s", 4, C_LT}, {0x4e209820, "cmeq0.16b", 1, C_EQ},
      {0x4e20a820, "cmlt0.16b", 1, C_LT},{0x4ea0b820, "abs.4s", 4, ABS},
      {0x6ea0b820, "neg.4s", 4, NEG},    {0x4e20b820, "abs.16b", 1, ABS},
      {0x4ea04820, "cls.4s", 4, CLS},    {0x6ea04820, "clz.4s", 4, CLZ},
      {0x4e205820, "cnt.16b", 1, CNT}};
  for (const U& op : un) {
    int bits = op.esz * 8;
    uint64_t m = (1ULL << bits) - 1;
    for (uint64_t raw : vals) {
      uint64_t a = raw & m;
      uint8_t vn[16];
      for (int e = 0; e < 16 / op.esz; e++) memcpy(vn + e * op.esz, &a, op.esz);
      memcpy(&state_.cpu.v[1], vn, 16);
      state_.cpu.v[0] = 0;
      Interpret(op.enc);
      uint8_t got[16];
      memcpy(got, &state_.cpu.v[0], 16);
      int64_t sa = sext(a, bits);
      uint64_t want = 0;
      switch (op.k) {
        case C_EQ: want = (a == 0) ? m : 0; break;
        case C_GT: want = (sa > 0) ? m : 0; break;
        case C_GE: want = (sa >= 0) ? m : 0; break;
        case C_LE: want = (sa <= 0) ? m : 0; break;
        case C_LT: want = (sa < 0) ? m : 0; break;
        case ABS: want = (uint64_t)(sa < 0 ? -sa : sa) & m; break;
        case NEG: want = (uint64_t)(-(int64_t)a) & m; break;
        case CLS: { int c = 0; for (int i = bits - 2; i >= 0; i--) {
                      if (((a >> i) & 1) == ((a >> (bits - 1)) & 1)) c++; else break; } want = c; break; }
        case CLZ: { int c = 0; for (int i = bits - 1; i >= 0; i--) {
                      if (((a >> i) & 1) == 0) c++; else break; } want = c; break; }
        case CNT: want = __builtin_popcountll(a & 0xff); break;
      }
      uint64_t g = 0; memcpy(&g, got, op.esz); g &= m;
      EXPECT_EQ(g, want) << op.name << " a=0x" << std::hex << a << " got=0x" << g
                         << " exp=0x" << want;
    }
  }

  // --- pairwise-long (+accumulate): result wide = (src[2i]+src[2i+1]) [+ Vd[i]] ---
  enum LK { SADDLP, UADDLP, SADALP, UADALP };
  struct L { uint32_t enc; const char* name; int ssz; LK k; };  // ssz = src elem bytes
  const L lp[] = {
      {0x4ea02820, "saddlp.2d", 4, SADDLP}, {0x6e202820, "uaddlp.8h", 1, UADDLP},
      {0x4ea06820, "sadalp.2d", 4, SADALP}, {0x6ea06820, "uadalp.2d", 4, UADALP},
      {0x4e206820, "sadalp.8h", 1, SADALP}, {0x6e606820, "uadalp.4s", 2, UADALP}};
  for (const L& op : lp) {
    int sbits = op.ssz * 8, dbits = sbits * 2, dnel = 16 / (op.ssz * 2);
    uint64_t sm = (1ULL << sbits) - 1, dm = (dbits == 64) ? ~0ULL : ((1ULL << dbits) - 1);
    bool acc = (op.k == SADALP || op.k == UADALP), sgn = (op.k == SADDLP || op.k == SADALP);
    uint8_t vn[16], vd[16];
    for (int i = 0; i < 16; i++) { vn[i] = (uint8_t)(i * 23 + 7); vd[i] = (uint8_t)(i * 5 + 1); }
    memcpy(&state_.cpu.v[1], vn, 16);
    memcpy(&state_.cpu.v[0], vd, 16);
    Interpret(op.enc);
    uint8_t got[16];
    memcpy(got, &state_.cpu.v[0], 16);
    auto sel = [&](int i) { uint64_t x = 0; memcpy(&x, vn + i * op.ssz, op.ssz); x &= sm;
                            return sgn ? (uint64_t)sext(x, sbits) : x; };
    auto del = [&](int i) { uint64_t x = 0; memcpy(&x, vd + i * (op.ssz * 2), op.ssz * 2); return x & dm; };
    for (int i = 0; i < dnel; i++) {
      uint64_t s = (sel(2 * i) + sel(2 * i + 1)) & dm;
      uint64_t want = acc ? ((del(i) + s) & dm) : s;
      uint64_t g = 0; memcpy(&g, got + i * (op.ssz * 2), op.ssz * 2); g &= dm;
      EXPECT_EQ(g, want) << op.name << " lane " << i << " got=0x" << std::hex << g
                         << " exp=0x" << want;
    }
  }

  // --- SUQADD/USQADD (saturating mixed-sign accumulate) + SQABS/SQNEG ---
  struct SQ { uint32_t enc; const char* name; int kind; };  // 0 suqadd 1 usqadd 2 sqabs 3 sqneg
  const SQ sq[] = {{0x4ea03820, "suqadd.4s", 0}, {0x6ea03820, "usqadd.4s", 1},
                   {0x4ea07820, "sqabs.4s", 2},  {0x6ea07820, "sqneg.4s", 3}};
  for (const SQ& op : sq) {
    int bits = 32;
    uint64_t m = 0xffffffffULL;
    for (uint64_t raw : vals) {
      uint64_t a = raw & m, d = 0x80000005ULL & m;
      uint8_t vn[16], vd[16];
      for (int e = 0; e < 4; e++) { memcpy(vn + e * 4, &a, 4); memcpy(vd + e * 4, &d, 4); }
      memcpy(&state_.cpu.v[1], vn, 16);
      memcpy(&state_.cpu.v[0], vd, 16);
      Interpret(op.enc);
      uint8_t got[16];
      memcpy(got, &state_.cpu.v[0], 16);
      uint64_t want = 0;
      if (op.kind == 0) want = sclamp(sext(d, bits) + (int64_t)a, bits);              // suqadd
      else if (op.kind == 1) { int64_t r = (int64_t)d + sext(a, bits);                // usqadd
                               r = r < 0 ? 0 : (r > (int64_t)m ? (int64_t)m : r); want = (uint64_t)r & m; }
      else if (op.kind == 2) { int64_t s = sext(a, bits); want = sclamp(s < 0 ? -s : s, bits); }
      else want = sclamp(-sext(a, bits), bits);                                       // sqneg
      uint64_t g = 0; memcpy(&g, got, 4); g &= m;
      EXPECT_EQ(g, want) << op.name << " a=0x" << std::hex << a << " got=0x" << g
                         << " exp=0x" << want;
    }
  }
}

// Bailed shift-by-immediate (SSHR/USHR/SRSHR/URSHR/SSRA/USRA/SHL/SLI/SRI +
// widening SSHLL/USHLL) interp-vs-EXPECTED. Bailed in lite, interpreter-only,
// used for fixed-point coverage scaling. Reference is element-wise ARM ARM.
TEST_F(Arm64LiteTranslateRegionTest, NeonBailedShiftImmInterpVsExpected) {
  enum SK { SSHR, USHR, SRSHR, URSHR, SSRA, USRA, SHL, SLI, SRI, SSHLL, USHLL };
  struct S { uint32_t enc; const char* name; int esz; int n; SK k; };  // esz=src elem bytes
  const S sh[] = {
      {0x4f3b0420, "sshr.4s#5", 4, 5, SSHR},   {0x6f3b0420, "ushr.4s#5", 4, 5, USHR},
      {0x4f0d0420, "sshr.16b#3", 1, 3, SSHR},  {0x6f0d0420, "ushr.16b#3", 1, 3, USHR},
      {0x6f3f0420, "ushr.4s#1", 4, 1, USHR},   {0x6f210420, "ushr.4s#31", 4, 31, USHR},
      {0x4f255420, "shl.4s#5", 4, 5, SHL},     {0x4f0f5420, "shl.16b#7", 1, 7, SHL},
      {0x4f3b2420, "srshr.4s#5", 4, 5, SRSHR}, {0x6f3b2420, "urshr.4s#5", 4, 5, URSHR},
      {0x4f3b1420, "ssra.4s#5", 4, 5, SSRA},   {0x6f3b1420, "usra.4s#5", 4, 5, USRA},
      {0x0f0ba420, "sshll.8h#3", 1, 3, SSHLL}, {0x2f15a420, "ushll.4s#5", 2, 5, USHLL},
      {0x6f255420, "sli.4s#5", 4, 5, SLI},     {0x6f3b4420, "sri.4s#5", 4, 5, SRI}};
  const uint64_t vals[] = {0x0, 0x1, 0x7f, 0x80, 0xff, 0x7fff, 0x8000, 0xffff,
                           0x7fffffff, 0x80000000, 0xffffffff, 0xdeadbeef, 0x12345678};
  for (const S& op : sh) {
    int bits = op.esz * 8;
    uint64_t m = (bits == 64) ? ~0ULL : ((1ULL << bits) - 1);
    bool isLong = (op.k == SSHLL || op.k == USHLL);
    int dbits = isLong ? bits * 2 : bits;
    uint64_t dm = (dbits == 64) ? ~0ULL : ((1ULL << dbits) - 1);
    int dnelem = isLong ? (16 / (op.esz * 2)) : (16 / op.esz);
    for (uint64_t raw : vals) {
      uint64_t a = raw & m;
      // Vn: fill enough lanes. For long ops only the LOW half lanes are used.
      uint8_t vn[16];
      for (int i = 0; i < 16; i++) vn[i] = 0;
      int src_lanes = isLong ? dnelem : (16 / op.esz);
      for (int e = 0; e < src_lanes; e++) memcpy(vn + e * op.esz, &a, op.esz);
      memcpy(&state_.cpu.v[1], vn, 16);
      uint64_t vd = 0x99887766ULL & m;  // for SSRA/USRA/SLI/SRI accumulate/insert
      uint8_t vd0[16];
      for (int e = 0; e < (16 / op.esz); e++) memcpy(vd0 + e * op.esz, &vd, op.esz);
      memcpy(&state_.cpu.v[0], vd0, 16);
      Interpret(op.enc);
      uint8_t got[16];
      memcpy(got, &state_.cpu.v[0], 16);
      int64_t sa = (int64_t)(a << (64 - bits)) >> (64 - bits);
      uint64_t want = 0;
      switch (op.k) {
        case SSHR: want = (uint64_t)(sa >> op.n) & m; break;
        case USHR: want = (op.n >= bits ? 0 : (a >> op.n)) & m; break;
        case SRSHR: want = (uint64_t)((sa + (int64_t{1} << (op.n - 1))) >> op.n) & m; break;
        case URSHR: want = ((a + (1ULL << (op.n - 1))) >> op.n) & m; break;
        case SSRA: want = (vd + ((uint64_t)(sa >> op.n) & m)) & m; break;
        case USRA: want = (vd + ((a >> op.n) & m)) & m; break;
        case SHL: want = (a << op.n) & m; break;
        case SLI: want = ((a << op.n) | (vd & ((1ULL << op.n) - 1))) & m; break;
        case SRI: { uint64_t topmask = m & ~(m >> op.n);
                    want = ((a >> op.n) | (vd & topmask)) & m; break; }
        case SSHLL: want = ((uint64_t)(sa << op.n)) & dm; break;
        case USHLL: want = (a << op.n) & dm; break;
      }
      uint64_t g = 0;
      memcpy(&g, got, isLong ? (op.esz * 2) : op.esz);
      g &= dm;
      EXPECT_EQ(g, want) << op.name << " a=0x" << std::hex << a << " got=0x" << g
                         << " exp=0x" << want;
    }
  }
}

// Bailed pairwise (ADDP/SMAXP/UMAXP/SMINP/UMINP) + across-lanes (ADDV/SMAXV/
// UMINV/UADDLV/SADDLV) interp-vs-EXPECTED. Bailed in lite, interpreter-only,
// heavily used by the rasterizer (addp/uaddlp/uaddlv). Pairwise rearranges;
// across-lanes reduces. Reference is element-wise ARM ARM.
TEST_F(Arm64LiteTranslateRegionTest, NeonBailedPairwiseAcrossInterpVsExpected) {
  auto sext = [](uint64_t v, int bits) -> int64_t {
    return (int64_t)(v << (64 - bits)) >> (64 - bits);
  };
  // --- pairwise ---
  enum PWK { PADD, SMAXP, UMAXP, SMINP, UMINP };
  struct PW { uint32_t enc; const char* name; int esz; PWK k; };
  const PW pw[] = {
      {0x4ea2bc20, "addp.4s", 4, PADD},   {0x4e22bc20, "addp.16b", 1, PADD},
      {0x4ea2a420, "smaxp.4s", 4, SMAXP}, {0x6ea2a420, "umaxp.4s", 4, UMAXP},
      {0x4ea2ac20, "sminp.4s", 4, SMINP}, {0x6ea2ac20, "uminp.4s", 4, UMINP},
      {0x4e22a420, "smaxp.16b", 1, SMAXP}};
  for (const PW& op : pw) {
    int bits = op.esz * 8, ne = 16 / op.esz;
    uint64_t m = (bits == 64) ? ~0ULL : ((1ULL << bits) - 1);
    uint8_t vn[16], vm[16];
    for (int i = 0; i < 16; i++) { vn[i] = (uint8_t)(i * 13 + 1); vm[i] = (uint8_t)(i * 7 + 9); }
    memcpy(&state_.cpu.v[1], vn, 16);
    memcpy(&state_.cpu.v[2], vm, 16);
    state_.cpu.v[0] = 0;
    Interpret(op.enc);
    uint8_t got[16];
    memcpy(got, &state_.cpu.v[0], 16);
    auto el = [&](const uint8_t* v, int i) { uint64_t x = 0; memcpy(&x, v + i * op.esz, op.esz); return x & m; };
    for (int i = 0; i < ne; i++) {
      uint64_t a, b;
      if (i < ne / 2) { a = el(vn, 2 * i); b = el(vn, 2 * i + 1); }
      else { int j = i - ne / 2; a = el(vm, 2 * j); b = el(vm, 2 * j + 1); }
      uint64_t want = 0;
      switch (op.k) {
        case PADD: want = (a + b) & m; break;
        case SMAXP: want = (sext(a, bits) > sext(b, bits) ? a : b); break;
        case UMAXP: want = a > b ? a : b; break;
        case SMINP: want = (sext(a, bits) < sext(b, bits) ? a : b); break;
        case UMINP: want = a < b ? a : b; break;
      }
      uint64_t g = 0; memcpy(&g, got + i * op.esz, op.esz); g &= m;
      EXPECT_EQ(g, want) << op.name << " lane " << i << " got=0x" << std::hex << g
                         << " exp=0x" << want;
    }
  }

  // --- across-lanes (reduce to scalar in Vd[0], rest zeroed) ---
  enum AK { ADDV, SMAXV, UMINV, UADDLV, SADDLV };
  struct AV { uint32_t enc; const char* name; int esz; AK k; };
  const AV av[] = {
      {0x4eb1b820, "addv.4s", 4, ADDV},  {0x4e31b820, "addv.16b", 1, ADDV},
      {0x4e71b820, "addv.8h", 2, ADDV},  {0x4eb0a820, "smaxv.4s", 4, SMAXV},
      {0x6e31a820, "uminv.16b", 1, UMINV},{0x6e303820, "uaddlv.16b", 1, UADDLV},
      {0x6e703820, "uaddlv.8h", 2, UADDLV},{0x4e303820, "saddlv.16b", 1, SADDLV}};
  for (const AV& op : av) {
    int bits = op.esz * 8, ne = 16 / op.esz;
    uint64_t m = (1ULL << bits) - 1;
    uint8_t vn[16];
    for (int i = 0; i < 16; i++) vn[i] = (uint8_t)(i * 11 + 5);
    memcpy(&state_.cpu.v[1], vn, 16);
    state_.cpu.v[0] = ~__uint128_t{0};  // poison, must be overwritten/zeroed
    Interpret(op.enc);
    uint8_t got[16];
    memcpy(got, &state_.cpu.v[0], 16);
    auto el = [&](int i) { uint64_t x = 0; memcpy(&x, vn + i * op.esz, op.esz); return x & m; };
    int64_t acc = 0;
    uint64_t want = 0, dbits = bits;
    if (op.k == ADDV) { for (int i = 0; i < ne; i++) acc += el(i); want = (uint64_t)acc & m; }
    else if (op.k == SMAXV) { acc = sext(el(0), bits); for (int i = 1; i < ne; i++) { int64_t v = sext(el(i), bits); if (v > acc) acc = v; } want = (uint64_t)acc & m; }
    else if (op.k == UMINV) { want = el(0); for (int i = 1; i < ne; i++) if (el(i) < want) want = el(i); }
    else if (op.k == UADDLV) { for (int i = 0; i < ne; i++) acc += (int64_t)el(i); dbits = bits * 2; want = (uint64_t)acc & ((1ULL << dbits) - 1); }
    else if (op.k == SADDLV) { for (int i = 0; i < ne; i++) acc += sext(el(i), bits); dbits = bits * 2; want = (uint64_t)acc & ((1ULL << dbits) - 1); }
    uint64_t g = 0; memcpy(&g, got, (dbits + 7) / 8); g &= ((dbits == 64) ? ~0ULL : ((1ULL << dbits) - 1));
    EXPECT_EQ(g, want) << op.name << " scalar got=0x" << std::hex << g << " exp=0x" << want;
    // bytes above the scalar result must be zero.
    for (int i = (int)((dbits + 7) / 8); i < 16; i++)
      EXPECT_EQ(got[i], 0u) << op.name << " byte " << i << " not zeroed";
  }
}

// Bailed permute (ZIP/UZP/TRN) + table-lookup (TBL/TBX) interp-vs-EXPECTED.
// These REARRANGE elements/bytes between lanes — the textbook cause of "internal
// glyph fragmentation"; Skia uses them to de/interleave coverage channels. All
// bailed in lite, interpreter-only. Reference is the exact ARM ARM permutation.
TEST_F(Arm64LiteTranslateRegionTest, NeonBailedPermuteTblInterpVsExpected) {
  // --- permute: element-wise, esz-byte elements over `total` bytes (16 or 8) ---
  enum PK { ZIP1, ZIP2, UZP1, UZP2, TRN1, TRN2 };
  struct P { uint32_t enc; const char* name; int esz; int total; PK k; };
  const P perm[] = {
      {0x4e023820, "zip1.16b", 1, 16, ZIP1}, {0x4e027820, "zip2.16b", 1, 16, ZIP2},
      {0x4e021820, "uzp1.16b", 1, 16, UZP1}, {0x4e025820, "uzp2.16b", 1, 16, UZP2},
      {0x4e022820, "trn1.16b", 1, 16, TRN1}, {0x4e026820, "trn2.16b", 1, 16, TRN2},
      {0x4e823820, "zip1.4s", 4, 16, ZIP1},  {0x4e821820, "uzp1.4s", 4, 16, UZP1},
      {0x4e422820, "trn1.8h", 2, 16, TRN1},  {0x0e023820, "zip1.8b", 1, 8, ZIP1}};
  for (const P& op : perm) {
    int ne = op.total / op.esz;  // elements
    uint8_t vn[16] = {0}, vm[16] = {0};
    for (int e = 0; e < ne; e++)
      for (int j = 0; j < op.esz; j++) {
        vn[e * op.esz + j] = (uint8_t)(0x10 + e);  // distinct per element
        vm[e * op.esz + j] = (uint8_t)(0x80 + e);
      }
    memcpy(&state_.cpu.v[1], vn, 16);
    memcpy(&state_.cpu.v[2], vm, 16);
    state_.cpu.v[0] = 0;
    Interpret(op.enc);
    uint8_t got[16];
    memcpy(got, &state_.cpu.v[0], 16);
    uint8_t exp[16] = {0};
    auto put = [&](int dstE, const uint8_t* srcV, int srcE) {
      memcpy(exp + dstE * op.esz, srcV + srcE * op.esz, op.esz);
    };
    int half = ne / 2;
    for (int i = 0; i < half; i++) {
      switch (op.k) {
        case ZIP1: put(2 * i, vn, i); put(2 * i + 1, vm, i); break;
        case ZIP2: put(2 * i, vn, half + i); put(2 * i + 1, vm, half + i); break;
        case UZP1: put(i, vn, 2 * i); put(half + i, vm, 2 * i); break;
        case UZP2: put(i, vn, 2 * i + 1); put(half + i, vm, 2 * i + 1); break;
        case TRN1: put(2 * i, vn, 2 * i); put(2 * i + 1, vm, 2 * i); break;
        case TRN2: put(2 * i, vn, 2 * i + 1); put(2 * i + 1, vm, 2 * i + 1); break;
      }
    }
    for (int i = 0; i < 16; i++)
      EXPECT_EQ(got[i], exp[i]) << op.name << " byte " << i << " got=0x" << std::hex
                                << (int)got[i] << " exp=0x" << (int)exp[i];
  }

  // --- TBL/TBX: result[i] = idx<16*nregs ? table[idx] : (TBL?0:Vd[i]) ---
  struct T { uint32_t enc; const char* name; int nregs; int outbytes; bool tbx; };
  const T tbls[] = {
      {0x4e020020, "tbl.16b.1", 1, 16, false}, {0x4e032020, "tbl.16b.2", 2, 16, false},
      {0x0e020020, "tbl.8b.1", 1, 8, false},   {0x4e021020, "tbx.16b.1", 1, 16, true},
      {0x4e044020, "tbl.16b.3", 3, 16, false}};
  for (const T& op : tbls) {
    // table regs v1.. : byte value = reg_local_index*16 + byte (distinct across table)
    for (int r = 0; r < op.nregs; r++) {
      uint8_t tr[16];
      for (int j = 0; j < 16; j++) tr[j] = (uint8_t)(0xC0 + r * 16 + j);
      memcpy(&state_.cpu.v[1 + r], tr, 16);
    }
    // index reg is v(1+nregs); mix in-range and out-of-range indices.
    uint8_t idx[16];
    for (int i = 0; i < 16; i++) idx[i] = (uint8_t)((i * 7 + 3) % (16 * op.nregs + 5));
    memcpy(&state_.cpu.v[1 + op.nregs], idx, 16);
    uint8_t vd0[16];
    for (int i = 0; i < 16; i++) vd0[i] = (uint8_t)(0x33 + i);
    memcpy(&state_.cpu.v[0], vd0, 16);
    Interpret(op.enc);
    uint8_t got[16];
    memcpy(got, &state_.cpu.v[0], 16);
    for (int i = 0; i < op.outbytes; i++) {
      uint8_t ix = idx[i];
      uint8_t want;
      if (ix < 16 * op.nregs)
        want = (uint8_t)(0xC0 + (ix / 16) * 16 + (ix % 16));  // table[ix]
      else
        want = op.tbx ? vd0[i] : 0;
      EXPECT_EQ(got[i], want) << op.name << " out byte " << i << " idx=" << (int)ix
                              << " got=0x" << std::hex << (int)got[i] << " exp=0x" << (int)want;
    }
    for (int i = op.outbytes; i < 16; i++)
      EXPECT_EQ(got[i], 0u) << op.name << " upper byte " << i << " not zeroed";
  }
}

// Bailed narrowing (XTN/SQXTN/UQXTN/SQXTUN), narrow-high (ADDHN/SUBHN/RADDHN/
// RSUBHN), and byte-reverse (REV16/32/64) interp-vs-EXPECTED. All bailed in lite,
// interpreter-only, and they REARRANGE/NARROW bytes — the strongest "internal
// glyph fragmentation" candidates. Reference is element-wise ARM ARM in uint64.
TEST_F(Arm64LiteTranslateRegionTest, NeonBailedNarrowRevInterpVsExpected) {
  // --- narrowing: source .8h/.4s/.2d -> dest .8b/.4h/.2s (lower half, upper 0) ---
  enum NK { XTN, SQXTN, UQXTN, SQXTUN, ADDHN, SUBHN, RADDHN, RSUBHN };
  struct N { uint32_t enc; const char* name; int ssz; NK k; };  // ssz = source elem bytes
  const N narrow[] = {
      {0x0e212820, "xtn.8b", 2, XTN},    {0x0e612820, "xtn.4h", 4, XTN},
      {0x0ea12820, "xtn.2s", 8, XTN},    {0x0e214820, "sqxtn.8b", 2, SQXTN},
      {0x0e614820, "sqxtn.4h", 4, SQXTN},{0x2e214820, "uqxtn.8b", 2, UQXTN},
      {0x2e614820, "uqxtn.4h", 4, UQXTN},{0x2e212820, "sqxtun.8b", 2, SQXTUN},
      {0x2e612820, "sqxtun.4h", 4, SQXTUN},{0x0e224020, "addhn.8b", 2, ADDHN},
      {0x0e624020, "addhn.4h", 4, ADDHN},{0x0e226020, "subhn.8b", 2, SUBHN},
      {0x0e626020, "subhn.4h", 4, SUBHN},{0x2e224020, "raddhn.8b", 2, RADDHN},
      {0x2e626020, "rsubhn.4h", 4, RSUBHN}};
  const uint64_t wv[] = {0x0, 0x1, 0x7f, 0x80, 0xff, 0x100, 0x7fff, 0x8000, 0xffff,
                         0x10000, 0x7fffffff, 0x80000000, 0xffffffff, 0x123456789aLL,
                         0x7fffffffffffffffLL, 0x8000000000000000ULL, 0xffffffffffffffffULL};
  const size_t NW = sizeof(wv) / sizeof(wv[0]);
  for (const N& op : narrow) {
    int sbits = op.ssz * 8, dbits = sbits / 2, nelem = 16 / op.ssz;
    uint64_t smask = (sbits == 64) ? ~0ULL : ((1ULL << sbits) - 1);
    uint64_t dmask = (1ULL << dbits) - 1;
    bool has2 = (op.k >= ADDHN);
    for (size_t ai = 0; ai < NW; ai++) {
      for (size_t bi = 0; bi < (has2 ? NW : 1); bi++) {
        uint64_t a = wv[ai] & smask, b = wv[bi] & smask;
        uint8_t vn[16], vm[16];
        for (int e = 0; e < nelem; e++) {
          memcpy(vn + e * op.ssz, &a, op.ssz);
          memcpy(vm + e * op.ssz, &b, op.ssz);
        }
        memcpy(&state_.cpu.v[1], vn, 16);
        memcpy(&state_.cpu.v[2], vm, 16);
        state_.cpu.v[0] = 0;
        Interpret(op.enc);
        uint8_t got[16];
        memcpy(got, &state_.cpu.v[0], 16);
        int64_t sa = (int64_t)(a << (64 - sbits)) >> (64 - sbits);
        uint64_t want = 0;
        switch (op.k) {
          case XTN: want = a & dmask; break;
          case SQXTN: {
            int64_t lo = -(int64_t{1} << (dbits - 1)), hi = (int64_t{1} << (dbits - 1)) - 1;
            int64_t x = sa < lo ? lo : (sa > hi ? hi : sa); want = (uint64_t)x & dmask; break;
          }
          case UQXTN: want = a > dmask ? dmask : a; break;
          case SQXTUN: { int64_t x = sa < 0 ? 0 : (sa > (int64_t)dmask ? (int64_t)dmask : sa);
                         want = (uint64_t)x & dmask; break; }
          case ADDHN: want = (((a + b) & smask) >> dbits) & dmask; break;
          case SUBHN: want = (((a - b) & smask) >> dbits) & dmask; break;
          case RADDHN: want = (((a + b + (1ULL << (dbits - 1))) & smask) >> dbits) & dmask; break;
          case RSUBHN: want = (((a - b + (1ULL << (dbits - 1))) & smask) >> dbits) & dmask; break;
        }
        uint64_t got_i = 0;
        memcpy(&got_i, got, op.ssz / 2);  // dest lane 0 (dbits)
        got_i &= dmask;
        EXPECT_EQ(got_i, want) << op.name << " a=0x" << std::hex << a << " b=0x" << b
                               << " got=0x" << got_i << " exp=0x" << want;
        // upper 64 bits must be zero (non-2 variant).
        uint64_t hi64;
        memcpy(&hi64, got + 8, 8);
        EXPECT_EQ(hi64, 0u) << op.name << " upper half not zeroed";
      }
    }
  }

  // --- byte reverse: reverse esz-byte elements within csz-byte containers ---
  struct R { uint32_t enc; const char* name; int esz; int csz; };
  const R rev[] = {{0x4e201820, "rev16.16b", 1, 2}, {0x6e200820, "rev32.16b", 1, 4},
                   {0x6e600820, "rev32.8h", 2, 4},  {0x4e200820, "rev64.16b", 1, 8},
                   {0x4ea00820, "rev64.4s", 4, 8}};
  for (const R& op : rev) {
    uint8_t src[16];
    for (int i = 0; i < 16; i++) src[i] = (uint8_t)(i * 17 + 3);
    memcpy(&state_.cpu.v[1], src, 16);
    state_.cpu.v[0] = 0;
    Interpret(op.enc);
    uint8_t got[16], exp[16];
    memcpy(got, &state_.cpu.v[0], 16);
    int epc = op.csz / op.esz;  // elements per container
    for (int c = 0; c < 16; c += op.csz)
      for (int e = 0; e < epc; e++)
        memcpy(exp + c + e * op.esz, src + c + (epc - 1 - e) * op.esz, op.esz);
    for (int i = 0; i < 16; i++)
      EXPECT_EQ(got[i], exp[i]) << op.name << " byte " << i << " got=0x" << std::hex
                                << (int)got[i] << " exp=0x" << (int)exp[i];
  }
}

// Bailed three-same integer ops interp-vs-EXPECTED. Deduction: the decoder is
// exonerated (decoder-vs-objdump diff, 0 mismatches over the real rasterizer) and
// the on-device garble is identical in interpret-only and two-gear, so every
// JIT-IMPLEMENTED op is correct (else the two modes would differ); the bug must
// be an interpreter-semantics edge case in a JIT-BAILED op the rasterizer uses.
// The lite JIT bails SMAX/SMIN/UMAX/UMIN, CMGT/CMGE/CMHI/CMHS/CMTST, SQADD/SQSUB/
// UQADD/UQSUB, and the halving adds — coverage-clamp / compare-mask / saturating
// ops, all interpreter-only and untested this session. Reference computed element-
// wise in int64 per the ARM ARM; edge inputs stress sign/saturation/halving.
TEST_F(Arm64LiteTranslateRegionTest, NeonBailedThreeSameInterpVsExpected) {
  enum K { SMAX, SMIN, UMAX, UMIN, CMGT, CMGE, CMHI, CMHS, CMTST,
           SQADD, UQADD, SQSUB, UQSUB, SHADD, UHADD, SRHADD, URHADD, SHSUB, UHSUB };
  struct Op { uint32_t enc; const char* name; int esz; K k; };
  const Op ops[] = {
      {0x4ea26420, "smax.4s", 4, SMAX},   {0x4ea26c20, "smin.4s", 4, SMIN},
      {0x6ea26420, "umax.4s", 4, UMAX},   {0x6ea26c20, "umin.4s", 4, UMIN},
      {0x4e226420, "smax.16b", 1, SMAX},  {0x6e226420, "umax.16b", 1, UMAX},
      {0x4e626420, "smax.8h", 2, SMAX},   {0x4ea23420, "cmgt.4s", 4, CMGT},
      {0x4ea23c20, "cmge.4s", 4, CMGE},   {0x6ea23420, "cmhi.4s", 4, CMHI},
      {0x6ea23c20, "cmhs.4s", 4, CMHS},   {0x4ea28c20, "cmtst.4s", 4, CMTST},
      {0x4e223420, "cmgt.16b", 1, CMGT},  {0x6e223420, "cmhi.16b", 1, CMHI},
      {0x4ea20c20, "sqadd.4s", 4, SQADD}, {0x6ea20c20, "uqadd.4s", 4, UQADD},
      {0x4ea22c20, "sqsub.4s", 4, SQSUB}, {0x6ea22c20, "uqsub.4s", 4, UQSUB},
      {0x4e220c20, "sqadd.16b", 1, SQADD},{0x6e220c20, "uqadd.16b", 1, UQADD},
      {0x4e620c20, "sqadd.8h", 2, SQADD}, {0x4ea20420, "shadd.4s", 4, SHADD},
      {0x6ea20420, "uhadd.4s", 4, UHADD}, {0x4ea21420, "srhadd.4s", 4, SRHADD},
      {0x6ea21420, "urhadd.4s", 4, URHADD},{0x4ea22420, "shsub.4s", 4, SHSUB},
      {0x6ea22420, "uhsub.4s", 4, UHSUB}, {0x4e220420, "shadd.16b", 1, SHADD},
      {0x6e221420, "urhadd.16b", 1, URHADD}};
  // edge values (interpreted at each esize via masking).
  const uint64_t vals[] = {0x0, 0x1, 0x2, 0x7f, 0x80, 0xff, 0x7fff, 0x8000, 0xffff,
                           0x7fffffff, 0x80000000, 0xffffffff, 0x55, 0xaa, 0x40000000};
  const size_t NV = sizeof(vals) / sizeof(vals[0]);

  auto sat = [](int64_t x, int bits, bool sgn) -> uint64_t {
    if (sgn) {
      int64_t lo = -(int64_t{1} << (bits - 1)), hi = (int64_t{1} << (bits - 1)) - 1;
      if (x < lo) x = lo;
      if (x > hi) x = hi;
    } else {
      int64_t hi = (bits == 64) ? -1 : (int64_t)((uint64_t{1} << bits) - 1);
      if (x < 0) x = 0;
      if ((uint64_t)x > (uint64_t)hi) x = hi;
    }
    uint64_t m = (bits == 64) ? ~0ULL : ((1ULL << bits) - 1);
    return (uint64_t)x & m;
  };
  auto satu = [](uint64_t x, int bits) -> uint64_t {
    uint64_t hi = (bits == 64) ? ~0ULL : ((1ULL << bits) - 1);
    return x > hi ? hi : x;
  };

  for (const Op& op : ops) {
    int bits = op.esz * 8;
    uint64_t emask = (bits == 64) ? ~0ULL : ((1ULL << bits) - 1);
    int nelem = 16 / op.esz;
    for (size_t ai = 0; ai < NV; ai++) {
      for (size_t bi = 0; bi < NV; bi++) {
        // fill all lanes with the (a,b) pair masked to esize.
        uint64_t a = vals[ai] & emask, b = vals[bi] & emask;
        uint8_t vn[16], vm[16];
        for (int e = 0; e < nelem; e++) {
          memcpy(vn + e * op.esz, &a, op.esz);
          memcpy(vm + e * op.esz, &b, op.esz);
        }
        memcpy(&state_.cpu.v[1], vn, 16);
        memcpy(&state_.cpu.v[2], vm, 16);
        state_.cpu.v[0] = 0;
        Interpret(op.enc);
        uint8_t got[16];
        memcpy(got, &state_.cpu.v[0], 16);
        // expected for lane 0 (all lanes identical).
        int64_t sa = (int64_t)(a << (64 - bits)) >> (64 - bits);  // sign-extend
        int64_t sb = (int64_t)(b << (64 - bits)) >> (64 - bits);
        uint64_t ua = a, ub = b;
        uint64_t want = 0;
        switch (op.k) {
          case SMAX: want = sat(sa > sb ? sa : sb, bits, true); break;
          case SMIN: want = sat(sa < sb ? sa : sb, bits, true); break;
          case UMAX: want = ua > ub ? ua : ub; break;
          case UMIN: want = ua < ub ? ua : ub; break;
          case CMGT: want = (sa > sb) ? emask : 0; break;
          case CMGE: want = (sa >= sb) ? emask : 0; break;
          case CMHI: want = (ua > ub) ? emask : 0; break;
          case CMHS: want = (ua >= ub) ? emask : 0; break;
          case CMTST: want = ((ua & ub) != 0) ? emask : 0; break;
          case SQADD: want = sat(sa + sb, bits, true); break;
          case UQADD: want = satu(ua + ub, bits); break;
          case SQSUB: want = sat(sa - sb, bits, true); break;
          case UQSUB: want = (ua >= ub) ? (ua - ub) : 0; break;
          case SHADD: want = (uint64_t)((sa + sb) >> 1) & emask; break;
          case UHADD: want = ((ua + ub) >> 1) & emask; break;
          case SRHADD: want = (uint64_t)((sa + sb + 1) >> 1) & emask; break;
          case URHADD: want = ((ua + ub + 1) >> 1) & emask; break;
          case SHSUB: want = (uint64_t)((sa - sb) >> 1) & emask; break;
          case UHSUB: want = (uint64_t)(((int64_t)ua - (int64_t)ub) >> 1) & emask; break;
        }
        uint64_t got0 = 0;
        memcpy(&got0, got, op.esz);
        EXPECT_EQ(got0, want) << op.name << " a=0x" << std::hex << a << " b=0x" << b
                              << " got=0x" << got0 << " exp=0x" << want;
      }
    }
  }
}

// AdvSimdCopy (DUP/INS/SMOV/UMOV) interp+JIT vs EXPECTED. simpleperf showed
// Interpreter::AdvSimdCopy hot in Helium's rasterizer; these move data between
// lanes / to GP regs, so a wrong lane-index or element-size decode rearranges
// pixels (internal glyph fragmentation). Checking against hand-computed
// expected (not interp-vs-JIT) also catches a shared imm5/imm4-decode bug.
TEST_F(Arm64LiteTranslateRegionTest, NeonCopyInterpAndJitVsExpected) {
  auto run_jit = [&](uint32_t insn) -> bool {
    static uint32_t code[1];
    code[0] = insn;
    GuestAddr start = ToGuestAddr(&code[0]);
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = start + 4, .allow_dispatch = false});
    if (!ok || stop != start + 4) return false;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    state_.cpu.insn_addr = start;
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    return true;
  };
  auto setv = [&](int reg, uint32_t a, uint32_t b, uint32_t c, uint32_t d) {
    uint32_t v[4] = {a, b, c, d};
    memcpy(&state_.cpu.v[reg], v, 16);
  };
  auto v0lane = [&](int i) -> uint32_t {
    uint32_t v[4];
    memcpy(v, &state_.cpu.v[0], 16);
    return v[i];
  };
  // src lanes: distinct so a wrong index is visible. byte/halfword views:
  // v1 = {0x11223344, 0x55667788, 0x99aabbcc, 0xddeeff00}
  const uint32_t L0 = 0x11223344u, L1 = 0x55667788u, L2 = 0x99aabbccu, L3 = 0xddeeff00u;

  // DUP v0.4s, v1.s[2]  -> all lanes = L2
  setv(1, L0, L1, L2, L3); setv(0, 0, 0, 0, 0);
  uint32_t enc = 0x4e140420;  // dup v0.4s, v1.s[2]
  Interpret(enc);
  for (int i = 0; i < 4; i++) EXPECT_EQ(v0lane(i), L2) << "dup.s[2] INTERP lane " << i;
  setv(1, L0, L1, L2, L3); setv(0, 0, 0, 0, 0);
  if (run_jit(enc)) for (int i = 0; i < 4; i++) EXPECT_EQ(v0lane(i), L2) << "dup.s[2] JIT lane " << i;

  // INS v0.s[3], v1.s[1] -> v0 lane3 = L1, others preserved
  setv(1, L0, L1, L2, L3); setv(0, 0xA, 0xB, 0xC, 0xD);
  enc = 0x6e1c2420;  // ins v0.s[3], v1.s[1]
  Interpret(enc);
  EXPECT_EQ(v0lane(0), 0xAu); EXPECT_EQ(v0lane(1), 0xBu);
  EXPECT_EQ(v0lane(2), 0xCu); EXPECT_EQ(v0lane(3), L1) << "ins.s INTERP";
  setv(1, L0, L1, L2, L3); setv(0, 0xA, 0xB, 0xC, 0xD);
  if (run_jit(enc)) { EXPECT_EQ(v0lane(3), L1) << "ins.s JIT"; EXPECT_EQ(v0lane(0), 0xAu); }

  // UMOV w0, v1.s[2] -> x0 = L2 (zero-extended)
  setv(1, L0, L1, L2, L3); state_.cpu.x[0] = 0xDEADBEEFDEADBEEFull;
  enc = 0x0e143c20;  // umov w0, v1.s[2]
  Interpret(enc);
  EXPECT_EQ(state_.cpu.x[0], (uint64_t)L2) << "umov.s INTERP";
  setv(1, L0, L1, L2, L3); state_.cpu.x[0] = 0xDEADBEEFDEADBEEFull;
  if (run_jit(enc)) EXPECT_EQ(state_.cpu.x[0], (uint64_t)L2) << "umov.s JIT";

  // SMOV x0, v1.h[3] -> halfword 3.  v1 bytes LE: 44 33 22 11 88 77 66 55 ...
  //   halfwords: h0=0x3344,h1=0x1122,h2=0x7788,h3=0x5566. h3=0x5566 -> sign-ext
  //   (bit15=0) -> 0x0000000000005566.
  setv(1, L0, L1, L2, L3); state_.cpu.x[0] = 0xDEADBEEFDEADBEEFull;
  enc = 0x4e0e2c20;  // smov x0, v1.h[3]
  Interpret(enc);
  EXPECT_EQ(state_.cpu.x[0], (uint64_t)0x5566u) << "smov.h INTERP got=0x" << std::hex
                                                << state_.cpu.x[0];
  setv(1, L0, L1, L2, L3); state_.cpu.x[0] = 0xDEADBEEFDEADBEEFull;
  if (run_jit(enc)) EXPECT_EQ(state_.cpu.x[0], (uint64_t)0x5566u) << "smov.h JIT";

  // SMOV x0, v1.b[8] -> byte 8.  v1 lane2=0x99aabbcc -> bytes cc bb aa 99.
  //   byte[8]=0xcc -> sign-ext (bit7=1) -> 0xFFFFFFFFFFFFFFCC.
  setv(1, L0, L1, L2, L3); state_.cpu.x[0] = 0;
  enc = 0x4e112c20;  // smov x0, v1.b[8]
  Interpret(enc);
  EXPECT_EQ(state_.cpu.x[0], 0xFFFFFFFFFFFFFFCCull) << "smov.b INTERP got=0x" << std::hex
                                                    << state_.cpu.x[0];
  setv(1, L0, L1, L2, L3); state_.cpu.x[0] = 0;
  if (run_jit(enc)) EXPECT_EQ(state_.cpu.x[0], 0xFFFFFFFFFFFFFFCCull) << "smov.b JIT";
}

// NEON three-same interp-vs-JIT differential fuzz. simpleperf of Helium's
// rasterizer showed Interpreter::AdvSimdThreeSame hot (these ops bail to the
// interpreter inside hot rasterizer regions, so they run interpreted in EVERY
// mode). For an op the lite JIT implements, JIT and interpreter are INDEPENDENT
// implementations, so a divergence here exposes an interpreter (or JIT) bug that
// the on-device interp==JIT garble (a shared-decoder symptom) cannot show. Edge
// inputs stress signed/saturating/shift behaviour (SSHL/USHL with negative and
// out-of-range shift amounts, INT_MIN data) — the SQRSHRUN/FMAX bug class.
TEST_F(Arm64LiteTranslateRegionTest, NeonThreeSameInterpVsJitFuzz) {
  auto run_jit = [&](uint32_t insn) -> bool {
    static uint32_t code[1];
    code[0] = insn;
    GuestAddr start = ToGuestAddr(&code[0]);
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = start + 4, .allow_dispatch = false});
    if (!ok || stop != start + 4) return false;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    state_.cpu.insn_addr = start;
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    return true;
  };

  struct Insn { uint32_t enc; const char* name; bool is_fp; bool acc; };
  const Insn insns[] = {
      {0x4ea28420, "add.4s", 0, 0},   {0x6ea28420, "sub.4s", 0, 0},
      {0x4ea29c20, "mul.4s", 0, 0},   {0x4ea29420, "mla.4s", 0, 1},
      {0x6ea29420, "mls.4s", 0, 1},   {0x4ea26420, "smax.4s", 0, 0},
      {0x4ea26c20, "smin.4s", 0, 0},  {0x6ea26420, "umax.4s", 0, 0},
      {0x6ea26c20, "umin.4s", 0, 0},  {0x4ea24420, "sshl.4s", 0, 0},
      {0x6ea24420, "ushl.4s", 0, 0},  {0x0ea24420, "sshl.2s", 0, 0},
      {0x4e624420, "sshl.8h", 0, 0},  {0x4e224420, "sshl.16b", 0, 0},
      {0x4ee24420, "sshl.2d", 0, 0},  {0x4ea25420, "srshl.4s", 0, 0},
      {0x6ea25420, "urshl.4s", 0, 0}, {0x4ea20c20, "sqadd.4s", 0, 0},
      {0x4ea22c20, "sqsub.4s", 0, 0}, {0x4ea24c20, "sqshl.4s", 0, 0},
      {0x4ea23420, "cmgt.4s", 0, 0},  {0x4ea23c20, "cmge.4s", 0, 0},
      {0x6ea28c20, "cmeq.4s", 0, 0},  {0x6ea23420, "cmhi.4s", 0, 0},
      {0x4e22d420, "fadd.4s", 1, 0},  {0x4ea2d420, "fsub.4s", 1, 0},
      {0x6e22dc20, "fmul.4s", 1, 0},  {0x6e22fc20, "fdiv.4s", 1, 0},
      {0x4e22cc20, "fmla.4s", 1, 1},  {0x4ea2cc20, "fmls.4s", 1, 1},
      {0x4e22f420, "fmax.4s", 1, 0},  {0x4ea2f420, "fmin.4s", 1, 0},
      {0x4e22e420, "fcmeq.4s", 1, 0}, {0x6e22e420, "fcmge.4s", 1, 0},
      {0x6ea2e420, "fcmgt.4s", 1, 0}, {0x4e62d420, "fadd.2d", 1, 0},
      {0x6e62dc20, "fmul.2d", 1, 0},
  };

  // 128-bit input patterns as pairs of u64 {lo, hi}. Mix data + shift-amount
  // ranges; SSHL/USHL read the low signed byte of each element as the count.
  const uint64_t pats[][2] = {
      {0x0000000000000000ULL, 0x0000000000000000ULL},
      {0x7FFFFFFF80000000ULL, 0x00000001FFFFFFFFULL},  // INT_MAX/MIN/1/-1 (32b)
      {0x0000000300000004ULL, 0xFFFFFFFEFFFFFFFDULL},
      {0x0000001F00000020ULL, 0xFFFFFFE1FFFFFFE0ULL},  // shifts +31/+32/-31/-32
      {0x0000004000000001ULL, 0xFFFFFFC0000000FFULL},
      {0x8000000080000000ULL, 0x7FFFFFFF7FFFFFFFULL},
      {0x000000FF000000FEULL, 0xFFFFFF01FFFFFF02ULL},
      {0x3F8000004048F5C3ULL, 0xC2C80000BF800000ULL},  // floats 1.0/3.14/-100/-1
      {0x7F800000FF800000ULL, 0x000000017FC00000ULL},  // +inf/-inf/denorm/NaN
      {0x42F6E97900000000ULL, 0x4F00000041200000ULL},
  };
  const size_t NP = sizeof(pats) / sizeof(pats[0]);

  // Full reset + run one op, returning v0; resets ALL v regs to avoid the
  // cross-iteration carryover that produces false divergences at scale.
  auto run_one = [&](uint32_t enc, size_t a, size_t b, bool acc, bool jit,
                     unsigned __int128* out) -> bool {
    for (int r = 0; r < 32; r++) state_.cpu.v[r] = 0;
    auto setv = [&](int reg, size_t p) {
      uint64_t v[2] = {pats[p][0], pats[p][1]};
      memcpy(&state_.cpu.v[reg], v, 16);
    };
    setv(1, a); setv(2, b); setv(0, acc ? a : 5);
    bool ok = true;
    if (jit) ok = run_jit(enc); else Interpret(enc);
    memcpy(out, &state_.cpu.v[0], 16);
    return ok;
  };

  int compared = 0;
  for (const Insn& in : insns) {
    // FP ops are skipped here: with NaN/Inf input lanes ARM (interpreter
    // produces the default NaN) and x86 MAXPS/MINPS/FMA legitimately differ on
    // NaN propagation, which is a separate concern from the integer/positional
    // path this differential targets. Integer three-same is the focus.
    if (in.is_fp) continue;
    for (size_t a = 0; a < NP; a++) {
      for (size_t b = 0; b < NP; b++) {
        unsigned __int128 vi, vj;
        run_one(in.enc, a, b, in.acc, /*jit=*/false, &vi);
        if (!run_one(in.enc, a, b, in.acc, /*jit=*/true, &vj)) continue;  // op bails
        compared++;
        if (vi == vj) continue;
        // Re-run BOTH in isolation to filter any scale/state artifact before
        // declaring a real divergence.
        unsigned __int128 vi2, vj2;
        run_one(in.enc, a, b, in.acc, false, &vi2);
        run_one(in.enc, a, b, in.acc, true, &vj2);
        if (vi2 == vj2) continue;  // not reproducible in isolation -> artifact
        ADD_FAILURE() << in.name << " a=" << a << " b=" << b << std::hex
                      << " interp=" << (uint64_t)(vi2 >> 64) << ":" << (uint64_t)vi2
                      << " jit=" << (uint64_t)(vj2 >> 64) << ":" << (uint64_t)vj2;
      }
    }
  }
  EXPECT_GT(compared, 100);
}

// FP rounding-mode ops (interp + JIT vs reference): FRINTN/M/P/Z/A (round to
// integral float) and FCVTNS/MS/PS/AS (round + convert to int). Skia's analytic-
// AA coverage uses floor/ceil/round to compute span boundaries; a wrong rounding
// mode (FPCR<->MXCSR mishandling) miscomputes coverage spans. Tie values (2.5,
// -2.5) distinguish ties-even (N) from ties-away (A) and the directed modes.
TEST_F(Arm64LiteTranslateRegionTest, FpRoundingModesInterpAndJit) {
  auto bitsf = [](float a, float b) {
    uint32_t x, y;
    memcpy(&x, &a, 4);
    memcpy(&y, &b, 4);
    return x == y;
  };
  auto setS = [&](float a) {
    float v[4] = {a, a, a, a};
    memcpy(&state_.cpu.v[1], v, 16);
    float z[4] = {0, 0, 0, 0};
    memcpy(&state_.cpu.v[0], z, 16);
  };
  auto getf0 = [&]() {
    float v[4];
    memcpy(v, &state_.cpu.v[0], 16);
    return v[0];
  };
  auto geti0 = [&]() {
    int32_t v[4];
    memcpy(v, &state_.cpu.v[0], 16);
    return v[0];
  };
  auto run_jit = [&](uint32_t insn) {
    static uint32_t code[1];
    code[0] = insn;
    GuestAddr start = ToGuestAddr(&code[0]);
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = start + 4, .allow_dispatch = false});
    if (!ok || stop != start + 4) return false;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    state_.cpu.insn_addr = start;
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    return true;
  };

  const float vals[] = {2.5f,  3.5f,  -2.5f,  -3.5f,  0.5f,   -0.5f,
                        1.5f,  2.49f, 2.51f,  -2.51f, 100.5f, -0.0f};

  struct R {
    uint32_t enc;
    const char* name;
    float (*ref)(float);
  };
  const R rints[] = {
      {0x4e218820, "frintn", [](float f) { return std::nearbyintf(f); }},  // ties-even
      {0x4e219820, "frintm", [](float f) { return std::floor(f); }},
      {0x4ea18820, "frintp", [](float f) { return std::ceil(f); }},
      {0x4ea19820, "frintz", [](float f) { return std::trunc(f); }},
      {0x6e218820, "frinta", [](float f) { return std::round(f); }},  // ties-away
  };
  for (const R& r : rints) {
    for (float v : vals) {
      float exp = r.ref(v);
      setS(v);
      Interpret(r.enc);
      EXPECT_TRUE(bitsf(getf0(), exp)) << r.name << " INTERP v=" << v << " exp=" << exp
                                       << " got=" << getf0();
      setS(v);
      if (run_jit(r.enc))
        EXPECT_TRUE(bitsf(getf0(), exp))
            << r.name << " JIT v=" << v << " exp=" << exp << " got=" << getf0();
    }
  }

  struct C {
    uint32_t enc;
    const char* name;
    float (*round)(float);
  };
  const C cvts[] = {
      {0x4e21a820, "fcvtns", [](float f) { return std::nearbyintf(f); }},
      {0x4e21b820, "fcvtms", [](float f) { return std::floor(f); }},
      {0x4ea1a820, "fcvtps", [](float f) { return std::ceil(f); }},
      {0x4e21c820, "fcvtas", [](float f) { return std::round(f); }},
  };
  for (const C& c : cvts) {
    for (float v : vals) {
      int32_t exp = static_cast<int32_t>(c.round(v));
      setS(v);
      Interpret(c.enc);
      EXPECT_EQ(geti0(), exp) << c.name << " INTERP v=" << v << " exp=" << exp << " got=" << geti0();
      setS(v);
      if (run_jit(c.enc))
        EXPECT_EQ(geti0(), exp) << c.name << " JIT v=" << v << " exp=" << exp << " got=" << geti0();
    }
  }
}

TEST_F(Arm64LiteTranslateRegionTest, AddRegister) {
  static const uint32_t code[] = {
      MovzX(0, 10),       // MOVZ X0, #10
      MovzX(1, 20),       // MOVZ X1, #20
      AddRegX(2, 0, 1),   // ADD X2, X0, X1
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[2], 30ULL);
}

// Interpreter-vs-EXPECTED for NEON-vector FP arith (.4s/.2d FADD/FSUB/FMUL/FDIV)
// and integer-vector ADD/MUL (.4s), against per-lane C++. Curves/diagonals use
// the complex (possibly NEON) coverage path while vertical stems use the simple
// integer path — a per-lane NEON bug would break exactly the symptom seen.
TEST_F(Arm64LiteTranslateRegionTest, NeonVectorInterpreterVsExpected) {
  uint64_t s = 0xC0DEFACEULL;
  auto rnd = [&]() { s = s * 6364136223846793005ULL + 1442695040888963407ULL; return s >> 33; };
  auto rf = [&]() -> double {
    int k = rnd() % 5;
    if (k == 0) return 0.0;
    if (k == 1) return (double)(int)(rnd() % 4000) - 2000.0;
    if (k == 2) return ((double)(int)(rnd() % 20000) - 10000.0) / 256.0;
    double a = (double)(int64_t)(rnd() | 1), b = (double)(int64_t)((rnd() | 1) & 0xffffff) + 1;
    return a / b;
  };
  auto setv = [&](int i, const uint64_t p[2]) { memcpy(&state_.cpu.v[i], p, 16); };
  auto getv = [&](int i, uint64_t p[2]) { memcpy(p, &state_.cpu.v[i], 16); };
  int checked = 0, fails = 0;

  // --- FP vector: .4s and .2d, FADD/FSUB/FMUL/FDIV ---
  for (int iter = 0; iter < 12000 && fails < 30; iter++) {
    int op = rnd() % 4;
    bool d2 = rnd() & 1;  // .2d else .4s
    uint32_t enc4[4] = {0x4E20D400, 0x4EA0D400, 0x6E20DC00, 0x6E20FC00};
    uint32_t enc2[4] = {0x4E60D400, 0x4EE0D400, 0x6E60DC00, 0x6E60FC00};
    uint32_t rd = 0, rn = 1, rm = 2;
    uint32_t insn = (d2 ? enc2[op] : enc4[op]) | (rm << 16) | (rn << 5) | rd;
    uint64_t pn[2], pm[2], pe[2];
    if (d2) {
      double a[2], b[2], r[2];
      for (int j = 0; j < 2; j++) { a[j] = rf(); b[j] = rf(); if (op == 3 && b[j] == 0) b[j] = 1; }
      memcpy(pn, a, 16); memcpy(pm, b, 16);
      for (int j = 0; j < 2; j++)
        r[j] = op == 0 ? a[j] + b[j] : op == 1 ? a[j] - b[j] : op == 2 ? a[j] * b[j] : a[j] / b[j];
      memcpy(pe, r, 16);
    } else {
      float a[4], b[4], r[4];
      for (int j = 0; j < 4; j++) { a[j] = (float)rf(); b[j] = (float)rf(); if (op == 3 && b[j] == 0) b[j] = 1; }
      memcpy(pn, a, 16); memcpy(pm, b, 16);
      for (int j = 0; j < 4; j++)
        r[j] = op == 0 ? a[j] + b[j] : op == 1 ? a[j] - b[j] : op == 2 ? a[j] * b[j] : a[j] / b[j];
      memcpy(pe, r, 16);
    }
    for (int i = 0; i < 32; i++) { uint64_t z[2] = {0, 0}; setv(i, z); }
    setv(rn, pn); setv(rm, pm);
    Interpret(insn);
    uint64_t got[2]; getv(rd, got);
    checked++;
    if ((got[0] != pe[0] || got[1] != pe[1]) && fails < 30) {
      fails++;
      ADD_FAILURE() << "fpvec op" << op << (d2 ? ".2d" : ".4s") << " EXP=0x" << std::hex << pe[1]
                    << pe[0] << " GOT=0x" << got[1] << got[0] << std::dec;
    }
  }

  // --- Integer vector ADD/MUL .4s ---
  for (int iter = 0; iter < 8000 && fails < 30; iter++) {
    bool mul = rnd() & 1;
    uint32_t insn = (mul ? 0x4EA09C00 : 0x4EA08400) | (2 << 16) | (1 << 5) | 0;
    uint32_t a[4], b[4], e[4];
    for (int j = 0; j < 4; j++) { a[j] = (uint32_t)rnd(); b[j] = (uint32_t)rnd(); e[j] = mul ? a[j] * b[j] : a[j] + b[j]; }
    uint64_t pn[2], pm[2], pe[2];
    memcpy(pn, a, 16); memcpy(pm, b, 16); memcpy(pe, e, 16);
    for (int i = 0; i < 32; i++) { uint64_t z[2] = {0, 0}; setv(i, z); }
    setv(1, pn); setv(2, pm);
    Interpret(insn);
    uint64_t got[2]; getv(0, got);
    checked++;
    if ((got[0] != pe[0] || got[1] != pe[1]) && fails < 30) {
      fails++;
      ADD_FAILURE() << "ivec " << (mul ? "mul" : "add") << ".4s EXP=0x" << std::hex << pe[1] << pe[0]
                    << " GOT=0x" << got[1] << got[0] << std::dec;
    }
  }
  EXPECT_GT(checked, 5000);
}

// Interpreter-vs-EXPECTED for the sign-extension-heavy paths not yet covered:
// register-offset loads with SXTW/UXTW (the exact hello-qt failure mode — a
// sign-extended offset register), extended-register ADD/SUB, and SBFX/UBFX.
// FreeType ftgrays indexes its cell array with [base, Wm, sxtw]-style addressing
// where Wm can be negative; a zero-extend-where-sign-extend bug reads the wrong
// cell and fragments diagonal edges.
TEST_F(Arm64LiteTranslateRegionTest, SignExtendPathsInterpreterVsExpected) {
  int checked = 0, fails = 0;
  auto ext = [](uint64_t v, int opt) -> uint64_t {
    switch (opt) {
      case 0: return v & 0xFF;
      case 1: return v & 0xFFFF;
      case 2: return v & 0xFFFFFFFFULL;
      case 3: return v;
      case 4: return (uint64_t)(int64_t)(int8_t)v;
      case 5: return (uint64_t)(int64_t)(int16_t)v;
      case 6: return (uint64_t)(int64_t)(int32_t)v;
      default: return v;
    }
  };

  // --- Register-offset 64-bit load: LDR Xt,[Xn, Rm, <ext> #shift] ---
  alignas(16) uint8_t buf[256];
  for (int i = 0; i < 256; i++) buf[i] = (uint8_t)((i * 31) ^ 0x5A);
  for (int opt = 2; opt <= 6; opt++) {            // UXTW=2, SXTW=6 (and SXTX=3)
    if (opt != 2 && opt != 3 && opt != 6) continue;
    for (int shift = 0; shift <= 3; shift += 3) {  // S=0 or S=1 (LSL #3 for 64-bit)
      for (int sgn = -2; sgn <= 2; sgn++) {
        uint64_t off_reg = (uint64_t)(int64_t)(int32_t)sgn;  // small +/- as W
        uint64_t scaled = ext(off_reg, opt) << shift;
        uint64_t base_addr = ToGuestAddr(buf) + 64;
        uint64_t ea = base_addr + scaled;
        if (ea < ToGuestAddr(buf) || ea + 8 > ToGuestAddr(buf) + 256) continue;
        uint32_t rt = 0, rn = 1, rm = 2;
        uint32_t insn = 0xF8600800 | (rm << 16) | (opt << 13) | ((shift ? 1u : 0u) << 12) |
                        (rn << 5) | rt;
        for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
        state_.cpu.x[rn] = base_addr;
        state_.cpu.x[rm] = off_reg;
        Interpret(insn);
        uint64_t exp = 0;
        memcpy(&exp, ToHostAddr<const uint8_t>(ea), 8);
        checked++;
        if (state_.cpu.x[rt] != exp && fails < 20) {
          fails++;
          ADD_FAILURE() << "ldr[xn,rm,opt=" << opt << ",sh=" << (shift ? 1 : 0)
                        << "] sgn=" << sgn << " EXPECTED=0x" << std::hex << exp << " INTERP=0x"
                        << state_.cpu.x[rt] << std::dec;
        }
      }
    }
  }

  // --- Extended-register ADD/SUB (64-bit): Xd = Xn +/- (ext(Rm,opt) << shift) ---
  uint64_t s = 0x9E37ULL;
  auto rnd = [&]() { s = s * 6364136223846793005ULL + 1442695040888963407ULL; return s >> 33; };
  for (int iter = 0; iter < 8000 && fails < 30; iter++) {
    bool sub = rnd() & 1;
    int opt = rnd() % 8;
    int shift = rnd() % 5;
    uint64_t n = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    uint64_t m = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    uint32_t rd = 1 + rnd() % 9, rn = 1 + rnd() % 9, rm = 1 + rnd() % 9;
    uint32_t base = sub ? 0xCB200000 : 0x8B200000;
    uint32_t insn = base | (rm << 16) | (opt << 13) | (shift << 10) | (rn << 5) | rd;
    for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
    state_.cpu.x[rn] = n;
    state_.cpu.x[rm] = m;
    uint64_t un = state_.cpu.x[rn], um = state_.cpu.x[rm];
    Interpret(insn);
    uint64_t addend = ext(um, opt) << shift;
    uint64_t exp = sub ? un - addend : un + addend;
    checked++;
    if (state_.cpu.x[rd] != exp && fails < 30) {
      fails++;
      ADD_FAILURE() << (sub ? "sub" : "add") << "_ext opt=" << opt << " sh=" << shift << " n=0x"
                    << std::hex << un << " m=0x" << um << " EXPECTED=0x" << exp << " INTERP=0x"
                    << state_.cpu.x[rd] << std::dec;
    }
  }

  // --- SBFX/UBFX (64-bit), all lsb/width ---
  for (int lsb = 0; lsb < 64 && fails < 30; lsb += 5) {
    for (int width = 1; width <= 64 - lsb; width += 7) {
      uint64_t v = 0xF731C95A8E2D6B40ULL;
      uint32_t immr = lsb, imms = lsb + width - 1;
      for (int sgn = 0; sgn < 2; sgn++) {
        uint32_t base = sgn ? 0x93400000 : 0xD3400000;  // SBFM : UBFM
        uint32_t rd = 0, rn = 1;
        uint32_t insn = base | (immr << 16) | (imms << 10) | (rn << 5) | rd;
        for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
        state_.cpu.x[rn] = v;
        Interpret(insn);
        uint64_t field = (v >> lsb) & ((width == 64) ? ~0ULL : ((1ULL << width) - 1));
        uint64_t exp;
        if (sgn) {
          exp = (uint64_t)(((int64_t)(field << (64 - width))) >> (64 - width));
        } else {
          exp = field;
        }
        checked++;
        if (state_.cpu.x[rd] != exp && fails < 30) {
          fails++;
          ADD_FAILURE() << (sgn ? "sbfx" : "ubfx") << " lsb=" << lsb << " w=" << width
                        << " EXPECTED=0x" << std::hex << exp << " INTERP=0x" << state_.cpu.x[rd]
                        << std::dec;
        }
      }
    }
  }
  EXPECT_GT(checked, 1000);
}

// Interpreter-vs-EXPECTED for scalar FP arith (FADD/FSUB/FMUL/FDIV, single &
// double) and int<->float conversions (SCVTF/FCVTZS), against C++ float/double.
// FreeType/Skia use scalar FP for glyph scaling/subpixel positioning; a wrong FP
// op would distort glyphs. Invisible to a JIT-vs-interp differential.
TEST_F(Arm64LiteTranslateRegionTest, ScalarFpInterpreterVsExpected) {
  uint64_t s = 0x1357ACE0ULL;
  auto rnd = [&]() -> uint64_t {
    s = s * 6364136223846793005ULL + 1442695040888963407ULL;
    return s >> 33;
  };
  auto rf = [&]() -> double {  // varied finite, non-NaN values
    int kind = rnd() % 6;
    if (kind == 0) return 0.0;
    if (kind == 1) return (double)(int)(rnd() % 2000) - 1000.0;
    if (kind == 2) return ((double)(int)(rnd() % 20000) - 10000.0) / 64.0;  // 1/64 subpixel
    if (kind == 3) return -((double)(rnd() % 100000)) / 1024.0;
    double a = (double)(int64_t)(rnd() | 1), b = (double)(int64_t)(rnd() | 1);
    return a / b;
  };
  auto setS = [&](int i, float f) {
    uint64_t parts[2] = {0, 0};
    memcpy(parts, &f, 4);
    memcpy(&state_.cpu.v[i], parts, 16);
  };
  auto setD = [&](int i, double f) {
    uint64_t parts[2] = {0, 0};
    memcpy(parts, &f, 8);
    memcpy(&state_.cpu.v[i], parts, 16);
  };
  auto getS = [&](int i) -> float {
    uint64_t parts[2];
    memcpy(parts, &state_.cpu.v[i], 16);
    float f;
    uint32_t b = (uint32_t)parts[0];
    memcpy(&f, &b, 4);
    return f;
  };
  auto getD = [&](int i) -> double {
    uint64_t parts[2];
    memcpy(parts, &state_.cpu.v[i], 16);
    double f;
    memcpy(&f, &parts[0], 8);
    return f;
  };
  auto bitsEq = [](double a, double b) {
    uint64_t x, y;
    memcpy(&x, &a, 8);
    memcpy(&y, &b, 8);
    return x == y;
  };
  auto bitsEqf = [](float a, float b) {
    uint32_t x, y;
    memcpy(&x, &a, 4);
    memcpy(&y, &b, 4);
    return x == y;
  };

  int checked = 0, fails = 0;
  for (int iter = 0; iter < 20000 && fails < 30; iter++) {
    int op = rnd() % 4;  // add sub mul div
    bool dbl = rnd() & 1;
    uint32_t base_s[4] = {0x1E202800, 0x1E203800, 0x1E200800, 0x1E201800};
    uint32_t base_d[4] = {0x1E602800, 0x1E603800, 0x1E600800, 0x1E601800};
    uint32_t rd = 0, rn = 1, rm = 2;
    uint32_t insn = (dbl ? base_d[op] : base_s[op]) | (rm << 16) | (rn << 5) | rd;
    double na = rf(), ma = rf();
    if (op == 3 && ma == 0.0) ma = 1.0;  // skip div-by-zero (inf, separate concern)
    checked++;
    if (dbl) {
      double exp = op == 0 ? na + ma : op == 1 ? na - ma : op == 2 ? na * ma : na / ma;
      setD(rn, na);
      setD(rm, ma);
      Interpret(insn);
      double got = getD(rd);
      if (!bitsEq(got, exp) && !(std::isnan(got) && std::isnan(exp))) {
        fails++;
        ADD_FAILURE() << "fp64 op" << op << " a=" << na << " b=" << ma << " exp=" << exp
                      << " got=" << got;
      }
    } else {
      float nf = (float)na, mf = (float)ma;
      float exp = op == 0 ? nf + mf : op == 1 ? nf - mf : op == 2 ? nf * mf : nf / mf;
      setS(rn, nf);
      setS(rm, mf);
      Interpret(insn);
      float got = getS(rd);
      if (!bitsEqf(got, exp) && !(std::isnan(got) && std::isnan(exp))) {
        fails++;
        ADD_FAILURE() << "fp32 op" << op << " a=" << nf << " b=" << mf << " exp=" << exp
                      << " got=" << got;
      }
    }
  }
  EXPECT_GT(checked, 5000);
}

// Interpreter-vs-EXPECTED for the widening 32x32->64 multiplies SMULL/UMULL and
// multiply-accumulate SMADDL/UMADDL/SMSUBL/UMSUBL, with negative 32-bit operands.
// FreeType ftgrays computes cell AREA as products of 32-bit edge coordinates
// widened to 64-bit; a sign-extension error here corrupts diagonal-edge area
// while axis-aligned (special-cased) edges stay correct — matching the symptom.
TEST_F(Arm64LiteTranslateRegionTest, MulLongInterpreterVsExpected) {
  uint64_t s = 0xF00DBA5EULL;
  auto rnd = [&]() -> uint64_t {
    s = s * 6364136223846793005ULL + 1442695040888963407ULL;
    return s >> 33;
  };
  auto pick = [&]() -> uint64_t {
    switch (rnd() % 9) {
      case 0: return 0;
      case 1: return 1;
      case 2: return 0xFFFFFFFFULL;          // -1 as W
      case 3: return 0x80000000ULL;          // INT32_MIN as W
      case 4: return 0x7FFFFFFFULL;          // INT32_MAX
      case 5: return rnd() % 70000;          // can overflow 32-bit when squared
      case 6: return (uint64_t)0 - (rnd() % 70000);
      default: return ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    }
  };
  struct M { const char* name; uint32_t base; bool sign; int kind; };  // kind 0=mul 1=madd 2=msub
  const M ms[] = {
      {"smull", 0x9B207C00, true, 0}, {"umull", 0x9BA07C00, false, 0},
      {"smaddl", 0x9B200000, true, 1}, {"umaddl", 0x9BA00000, false, 1},
      {"smsubl", 0x9B208000, true, 2}, {"umsubl", 0x9BA08000, false, 2},
  };
  int checked = 0, fails = 0;
  for (int iter = 0; iter < 30000 && fails < 30; iter++) {
    const M& o = ms[rnd() % 6];
    uint32_t rd = 1 + rnd() % 9, rn = 1 + rnd() % 9, rm = 1 + rnd() % 9, ra = 1 + rnd() % 9;
    uint32_t insn = o.base | (rm << 16) | (ra << 10) | (rn << 5) | rd;
    uint64_t n = pick(), m = pick(), a = pick();
    for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
    state_.cpu.x[rn] = n;
    state_.cpu.x[rm] = m;
    state_.cpu.x[ra] = a;
    uint64_t un = state_.cpu.x[rn], um = state_.cpu.x[rm], ua = state_.cpu.x[ra];
    Interpret(insn);
    uint64_t got = state_.cpu.x[rd];
    uint64_t prod = o.sign
                        ? (uint64_t)((int64_t)(int32_t)(uint32_t)un * (int64_t)(int32_t)(uint32_t)um)
                        : ((uint64_t)(uint32_t)un * (uint64_t)(uint32_t)um);
    uint64_t exp = o.kind == 0 ? prod : (o.kind == 1 ? ua + prod : ua - prod);
    checked++;
    if (got != exp) {
      fails++;
      ADD_FAILURE() << o.name << " Wn=0x" << std::hex << (uint32_t)un << " Wm=0x" << (uint32_t)um
                    << " Xa=0x" << ua << " EXPECTED=0x" << exp << " INTERP=0x" << got << std::dec;
    }
  }
  EXPECT_GT(checked, 10000);
}

// Interpreter-vs-EXPECTED for integer stores (STRB/STRH/STR W&X) and STP (W&X),
// verifying the written bytes against an independent reference. FreeType ftgrays
// writes its cell array via exactly these. A wrong store width/order/value is a
// garbled-glyph candidate invisible to a JIT-vs-interp differential.
TEST_F(Arm64LiteTranslateRegionTest, StoresInterpreterVsExpected) {
  int checked = 0, fails = 0;
  struct S { const char* name; uint32_t base; int bytes; };
  const S strs[] = {{"strb", 0x39000000, 1}, {"strh", 0x79000000, 2},
                    {"str_w", 0xB9000000, 4}, {"str_x", 0xF9000000, 8}};
  const uint64_t vals[] = {0x1122334455667788ULL, 0xFFFFFFFFFFFFFFFFULL,
                           0x80000000FF00A55AULL, 0x00000000DEADBEEFULL, 0};
  for (const S& s : strs) {
    for (uint64_t v : vals) {
      for (int off = 0; off + s.bytes <= 90; off += s.bytes) {  // aligned: imm scaled by size
        alignas(16) uint8_t buf[128];
        memset(buf, 0xCC, sizeof(buf));
        uint32_t imm = (uint32_t)(off / s.bytes);
        uint32_t rt = 0, rn = 1;
        uint32_t insn = s.base | (imm << 10) | (rn << 5) | rt;
        for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
        state_.cpu.x[rt] = v;
        state_.cpu.x[rn] = ToGuestAddr(buf);
        Interpret(insn);
        // Expected: low `bytes` of v written at off; rest of buf unchanged (0xCC).
        uint8_t exp[128];
        memset(exp, 0xCC, sizeof(exp));
        memcpy(exp + off, &v, s.bytes);
        checked++;
        if (memcmp(buf, exp, sizeof(buf)) != 0 && fails < 20) {
          fails++;
          uint64_t gotw = 0;
          memcpy(&gotw, buf + off, s.bytes);
          ADD_FAILURE() << s.name << " off=" << off << " v=0x" << std::hex << v << " stored=0x"
                        << gotw << std::dec;
        }
      }
    }
  }
  // STP Xt, Xt2, [Xn, #imm] (64-bit) and STP Wt, Wt2 (32-bit).
  struct P { uint32_t base; int bytes; };
  const P stps[] = {{0xA9000000, 8}, {0x29000000, 4}};
  for (const P& p : stps) {
    for (int k = 0; k < (int)(sizeof(vals) / sizeof(vals[0])); k++) {
      alignas(16) uint8_t buf[128];
      memset(buf, 0xCC, sizeof(buf));
      uint64_t v1 = vals[k], v2 = vals[(k + 2) % 5];
      uint32_t imm7 = 2;  // scaled by access size; offset = 2*bytes
      int off = imm7 * p.bytes;
      uint32_t rt = 0, rt2 = 3, rn = 1;
      uint32_t insn = p.base | (imm7 << 15) | (rt2 << 10) | (rn << 5) | rt;
      for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
      state_.cpu.x[rt] = v1;
      state_.cpu.x[rt2] = v2;
      state_.cpu.x[rn] = ToGuestAddr(buf);
      Interpret(insn);
      uint8_t exp[128];
      memset(exp, 0xCC, sizeof(exp));
      memcpy(exp + off, &v1, p.bytes);
      memcpy(exp + off + p.bytes, &v2, p.bytes);
      checked++;
      if (memcmp(buf, exp, sizeof(buf)) != 0 && fails < 20) {
        fails++;
        uint64_t g1 = 0, g2 = 0;
        memcpy(&g1, buf + off, p.bytes);
        memcpy(&g2, buf + off + p.bytes, p.bytes);
        ADD_FAILURE() << "stp bytes=" << p.bytes << " v1=0x" << std::hex << v1 << " v2=0x" << v2
                      << " got1=0x" << g1 << " got2=0x" << g2 << std::dec;
      }
    }
  }
  EXPECT_GT(checked, 20);
}

// Interpreter-vs-EXPECTED for the conditional-select family across ALL 16
// conditions and many flag states, plus SBFX/UBFX bitfield extraction. A wrong
// condition evaluation (GE/LT/GT/LE depend on N,V) or a wrong signed bitfield
// extract corrupts the rasterizer's branchless coverage clamps. Independent C++
// reference; invisible to a JIT-vs-interp differential.
TEST_F(Arm64LiteTranslateRegionTest, CondAndBitfieldInterpreterVsExpected) {
  // Evaluate ARM condition from packed flags (N@15 Z@14 C@8 V@0).
  auto cond_holds = [](uint32_t cond, uint16_t f) -> bool {
    int N = (f >> 15) & 1, Z = (f >> 14) & 1, C = (f >> 8) & 1, V = (f >> 0) & 1;
    switch (cond >> 1) {
      case 0: return Z;                       // EQ/NE
      case 1: return C;                       // CS/CC
      case 2: return N;                       // MI/PL
      case 3: return V;                       // VS/VC
      case 4: return C && !Z;                 // HI/LS
      case 5: return N == V;                  // GE/LT
      case 6: return (N == V) && !Z;          // GT/LE
      default: return true;                   // AL/NV
    }
    return true;
  };
  auto holds = [&](uint32_t cond, uint16_t f) -> bool {
    bool r = cond_holds(cond, f);
    return (cond & 1) && cond < 14 ? !r : r;  // odd condition (except NV) inverts
  };
  int checked = 0, fails = 0;

  // --- Conditional selects: csel/csinc/csinv/csneg, W and X, all conds ---
  const uint16_t flag_states[] = {0x0000, 0xC101, 0x8000, 0x4000, 0x0100, 0x0001,
                                  0x8001, 0x0101, 0xC000, 0x8100, 0x4001, 0xC100};
  struct CS { uint32_t b64, b32; };
  const CS csops[] = {{0x9A800000, 0x1A800000},   // csel
                      {0x9A800400, 0x1A800400},   // csinc
                      {0xDA800000, 0x5A800000},   // csinv
                      {0xDA800400, 0x5A800400}};  // csneg
  for (int oi = 0; oi < 4; oi++) {
    for (uint32_t cond = 0; cond < 16; cond++) {
      for (uint16_t f : flag_states) {
        for (int w = 0; w < 2; w++) {
          uint64_t n = 0x1122334455667788ULL, m = 0x99AABBCCDDEEFF00ULL;
          uint32_t rd = 0, rn = 1, rm = 2;
          uint32_t insn = (w ? csops[oi].b32 : csops[oi].b64) | (rm << 16) | (cond << 12) |
                          (rn << 5) | rd;
          for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
          state_.cpu.x[rn] = n;
          state_.cpu.x[rm] = m;
          state_.cpu.flags = f;
          Interpret(insn);
          uint64_t got = state_.cpu.x[rd];
          bool t = holds(cond, f);
          uint64_t sel;
          if (t) {
            sel = n;
          } else {
            switch (oi) {
              case 0: sel = m; break;
              case 1: sel = m + 1; break;
              case 2: sel = ~m; break;
              default: sel = (uint64_t)(0 - m); break;
            }
          }
          uint64_t exp = w ? (sel & 0xffffffffULL) : sel;
          checked++;
          if (got != exp && fails < 30) {
            fails++;
            ADD_FAILURE() << "csop" << oi << (w ? ".w" : ".x") << " cond=" << cond << " flags=0x"
                          << std::hex << f << " EXPECTED=0x" << exp << " INTERP=0x" << got
                          << std::dec;
          }
        }
      }
    }
  }
  EXPECT_GT(checked, 1000);
}

// Interpreter-vs-EXPECTED for every signed/unsigned integer load width, at many
// offsets over a buffer full of high-bit-set bytes. Catches a sign/width
// mis-decode (the hello-qt LDPSW class) that a JIT-vs-interp differential cannot
// see. FreeType ftgrays reads its cell array via exactly these loads.
TEST_F(Arm64LiteTranslateRegionTest, LoadsInterpreterVsExpected) {
  alignas(16) uint8_t buf[128];
  for (int i = 0; i < 128; i++) buf[i] = (uint8_t)((i * 37) ^ 0x80);  // many top bits set
  struct L {
    const char* name;
    uint32_t base;  // unsigned-offset encoding, rt/rn/imm = 0
    int bytes;
    bool is_signed;
    bool x_target;  // true=Xt(64), false=Wt(32)
  };
  const L loads[] = {
      {"ldrb", 0x39400000, 1, false, false}, {"ldrh", 0x79400000, 2, false, false},
      {"ldr_w", 0xB9400000, 4, false, false}, {"ldr_x", 0xF9400000, 8, false, true},
      {"ldrsb_w", 0x39C00000, 1, true, false}, {"ldrsb_x", 0x39800000, 1, true, true},
      {"ldrsh_w", 0x79C00000, 2, true, false}, {"ldrsh_x", 0x79800000, 2, true, true},
      {"ldrsw_x", 0xB9800000, 4, true, true},
  };
  int checked = 0, fails = 0;
  for (const L& l : loads) {
    for (int off = 0; off + l.bytes <= 64 && fails < 30; off++) {
      // unsigned offset is scaled by access size; only test aligned offsets.
      if (off % l.bytes != 0) continue;
      uint32_t imm = (uint32_t)(off / l.bytes);
      uint32_t rt = 0, rn = 1;
      uint32_t insn = l.base | (imm << 10) | (rn << 5) | rt;
      uint64_t raw = 0;
      memcpy(&raw, buf + off, l.bytes);  // little-endian assemble
      uint64_t exp;
      if (l.is_signed) {
        int64_t s = (int64_t)(raw << (64 - l.bytes * 8)) >> (64 - l.bytes * 8);
        exp = l.x_target ? (uint64_t)s : ((uint64_t)(uint32_t)(int32_t)s);
      } else {
        exp = raw;  // already zero-extended
      }
      for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
      state_.cpu.x[rt] = 0xDEADBEEFDEADBEEFULL;  // ensure the load overwrites it
      state_.cpu.x[rn] = ToGuestAddr(buf);
      Interpret(insn);
      uint64_t got = state_.cpu.x[rt];
      checked++;
      if (got != exp) {
        fails++;
        ADD_FAILURE() << l.name << " off=" << off << " insn=0x" << std::hex << insn
                      << " bytes=0x" << raw << " EXPECTED=0x" << exp << " INTERP=0x" << got
                      << std::dec;
      }
    }
  }
  EXPECT_GT(checked, 50);
}

// Interpreter-vs-EXPECTED NZCV flag check for ADDS/SUBS (and thus CMP/CMN), both
// W and X forms, against an independent C++ reference. A wrong C (carry/borrow) or
// V (signed overflow) flag makes every conditional select / signed branch in the
// rasterizer's coverage clamps go the wrong way — a garbled-glyph candidate that
// a JIT-vs-interpreter differential cannot see (shared semantics).
TEST_F(Arm64LiteTranslateRegionTest, FlagsInterpreterVsExpected) {
  uint64_t seed = 0xBEEF1234CAFEULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  auto pick = [&]() -> uint64_t {
    switch (rnd() % 11) {
      case 0: return 0;
      case 1: return 1;
      case 2: return ~0ULL;
      case 3: return 0x80000000ULL;
      case 4: return 0x7FFFFFFFULL;
      case 5: return 0xFFFFFFFFULL;
      case 6: return 0x8000000000000000ULL;
      case 7: return 0x7FFFFFFFFFFFFFFFULL;
      case 8: return rnd() % 5;
      case 9: return (uint64_t)0 - (rnd() % 5);
      default: return ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    }
  };
  // Pack to the ThreadState layout: N@15 Z@14 C@8 V@0.
  auto pack = [](int N, int Z, int C, int V) -> uint16_t {
    return (uint16_t)((N << 15) | (Z << 14) | (C << 8) | (V << 0));
  };
  auto flags_add = [&](bool w, uint64_t n, uint64_t m) -> uint16_t {
    if (w) {
      uint32_t a = (uint32_t)n, b = (uint32_t)m, r = a + b;
      int N = (r >> 31) & 1, Z = (r == 0);
      int C = (((uint64_t)a + (uint64_t)b) >> 32) & 1;
      int V = ((~(a ^ b) & (a ^ r)) >> 31) & 1;
      return pack(N, Z, C, V);
    }
    uint64_t r = n + m;
    int N = (r >> 63) & 1, Z = (r == 0);
    int C = (r < n) ? 1 : 0;  // unsigned overflow on add
    int V = ((~(n ^ m) & (n ^ r)) >> 63) & 1;
    return pack(N, Z, C, V);
  };
  auto flags_sub = [&](bool w, uint64_t n, uint64_t m) -> uint16_t {
    if (w) {
      uint32_t a = (uint32_t)n, b = (uint32_t)m, r = a - b;
      int N = (r >> 31) & 1, Z = (r == 0);
      int C = (a >= b) ? 1 : 0;  // no-borrow
      int V = (((a ^ b) & (a ^ r)) >> 31) & 1;
      return pack(N, Z, C, V);
    }
    uint64_t r = n - m;
    int N = (r >> 63) & 1, Z = (r == 0);
    int C = (n >= m) ? 1 : 0;
    int V = (((n ^ m) & (n ^ r)) >> 63) & 1;
    return pack(N, Z, C, V);
  };

  int checked = 0, fails = 0;
  for (int iter = 0; iter < 40000 && fails < 40; iter++) {
    bool is_sub = rnd() & 1;
    bool w = rnd() & 1;
    uint32_t base = is_sub ? (w ? 0x6B000000 : 0xEB000000) : (w ? 0x2B000000 : 0xAB000000);
    uint32_t rd = 1 + rnd() % 9, rn = 1 + rnd() % 9, rm = 1 + rnd() % 9;
    uint32_t insn = base | (rm << 16) | (rn << 5) | rd;
    uint64_t n = pick(), m = pick();
    for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
    state_.cpu.x[rn] = n;
    state_.cpu.x[rm] = m;
    state_.cpu.flags = 0;
    uint64_t un = state_.cpu.x[rn], um = state_.cpu.x[rm];
    Interpret(insn);
    uint16_t got = state_.cpu.flags & 0xC101;
    uint16_t exp = is_sub ? flags_sub(w, un, um) : flags_add(w, un, um);
    checked++;
    if (got != exp) {
      fails++;
      ADD_FAILURE() << "iter " << iter << (is_sub ? " subs" : " adds") << (w ? ".w" : ".x")
                    << " n=0x" << std::hex << un << " m=0x" << um << " EXPECTED_NZCV=0x" << exp
                    << " INTERP_NZCV=0x" << got << std::dec;
    }
  }
  EXPECT_GT(checked, 10000);
}

// Interpreter-vs-EXPECTED fuzzer for integer ALU/div/mul/shift, both W (32-bit)
// and X (64-bit) forms, with edge operands (negatives, INT_MIN, 0, -1). Unlike a
// JIT-vs-interpreter differential (which is blind to a shared decoder/semantics
// bug because both tiers agree), this compares the interpreter against an
// independent C++ reference of the ARM ARM semantics. Targets the FreeType
// ftgrays integer path (FT_DIV_MOD = 32-bit SDIV + 32-bit MSUB on negatives,
// signed area/cover multiply+shift) — a Helium garbled-glyph candidate.
TEST_F(Arm64LiteTranslateRegionTest, IntegerInterpreterVsExpected) {
  uint64_t seed = 0xA5A5F00DD00DULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  // Operand pool biased to edge cases the divide/modulo/shift paths care about.
  auto pick = [&]() -> uint64_t {
    switch (rnd() % 10) {
      case 0: return 0;
      case 1: return 1;
      case 2: return ~0ULL;                 // -1
      case 3: return 0x80000000ULL;         // INT32_MIN (zero-extended)
      case 4: return 0xFFFFFFFF80000000ULL;  // INT32_MIN sign-extended
      case 5: return 0x7FFFFFFFULL;         // INT32_MAX
      case 6: return rnd() % 257;           // small
      case 7: return (uint64_t)0 - (rnd() % 257);  // small negative
      default: return ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    }
  };
  auto z32 = [](uint64_t v) -> uint64_t { return v & 0xffffffffULL; };

  struct Op { const char* name; uint32_t base64; uint32_t base32; bool three; };
  // base64/base32 = encoding with rd/rn/rm/ra = 0; `three` means uses Ra.
  const Op ops[] = {
      {"add", 0x8B000000, 0x0B000000, false}, {"sub", 0xCB000000, 0x4B000000, false},
      {"and", 0x8A000000, 0x0A000000, false}, {"orr", 0xAA000000, 0x2A000000, false},
      {"eor", 0xCA000000, 0x4A000000, false}, {"mul", 0x9B007C00, 0x1B007C00, false},
      {"sdiv", 0x9AC00C00, 0x1AC00C00, false}, {"udiv", 0x9AC00800, 0x1AC00800, false},
      {"asrv", 0x9AC02800, 0x1AC02800, false}, {"lslv", 0x9AC02000, 0x1AC02000, false},
      {"lsrv", 0x9AC02400, 0x1AC02400, false}, {"smulh", 0x9B407C00, 0, false},
      {"madd", 0x9B000000, 0x1B000000, true}, {"msub", 0x9B008000, 0x1B008000, true},
  };

  auto expect = [&](const char* name, bool w, uint64_t n, uint64_t m, uint64_t a) -> uint64_t {
    auto S = [](uint64_t v) { return (int64_t)v; };
    auto S32 = [](uint64_t v) { return (int32_t)(uint32_t)v; };
    std::string op = name;
    if (op == "add") return w ? z32(n + m) : n + m;
    if (op == "sub") return w ? z32(n - m) : n - m;
    if (op == "and") return w ? z32(n & m) : (n & m);
    if (op == "orr") return w ? z32(n | m) : (n | m);
    if (op == "eor") return w ? z32(n ^ m) : (n ^ m);
    if (op == "mul") return w ? z32(n * m) : n * m;
    if (op == "madd") return w ? z32(a + n * m) : a + n * m;
    if (op == "msub") return w ? z32(a - n * m) : a - n * m;
    if (op == "udiv") {
      if (w) { uint32_t mm = (uint32_t)m; return mm == 0 ? 0 : z32((uint32_t)n / mm); }
      return m == 0 ? 0 : n / m;
    }
    if (op == "sdiv") {
      if (w) {
        int32_t nn = S32(n), mm = S32(m);
        if (mm == 0) return 0;
        if (nn == INT32_MIN && mm == -1) return z32((uint32_t)INT32_MIN);
        return z32((uint32_t)(int32_t)(nn / mm));
      }
      int64_t nn = S(n), mm = S(m);
      if (mm == 0) return 0;
      if (nn == INT64_MIN && mm == -1) return (uint64_t)INT64_MIN;
      return (uint64_t)(nn / mm);
    }
    if (op == "asrv") return w ? z32((uint32_t)(S32(n) >> (m & 31))) : (uint64_t)(S(n) >> (m & 63));
    if (op == "lsrv") return w ? z32((uint32_t)n >> (m & 31)) : (n >> (m & 63));
    if (op == "lslv") return w ? z32((uint32_t)n << (m & 31)) : (n << (m & 63));
    if (op == "smulh") return (uint64_t)(((__int128)S(n) * (__int128)S(m)) >> 64);
    return 0;
  };

  int checked = 0;
  for (int iter = 0; iter < 40000; iter++) {
    const Op& o = ops[rnd() % (sizeof(ops) / sizeof(ops[0]))];
    bool w = (o.base32 != 0) && (rnd() & 1);
    if (o.base32 == 0 && w) continue;  // smulh: 64-bit only
    uint32_t base = w ? o.base32 : o.base64;
    uint32_t rd = 1 + rnd() % 9, rn = 1 + rnd() % 9, rm = 1 + rnd() % 9, ra = 1 + rnd() % 9;
    uint32_t insn = base | (rm << 16) | (rn << 5) | rd;
    if (o.three) insn |= (ra << 10);
    uint64_t n = pick(), m = pick(), a = pick();

    for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
    state_.cpu.x[rn] = n;
    state_.cpu.x[rm] = m;
    if (o.three) state_.cpu.x[ra] = a;
    // re-read (rd may alias rn/rm/ra; capture the actual source values used)
    uint64_t un = state_.cpu.x[rn], um = state_.cpu.x[rm], ua = o.three ? state_.cpu.x[ra] : 0;
    Interpret(insn);
    uint64_t got = state_.cpu.x[rd];
    uint64_t exp = expect(o.name, w, un, um, ua);
    checked++;
    if (got != exp) {
      ADD_FAILURE() << "iter " << iter << " " << o.name << (w ? ".w" : ".x") << " insn=0x"
                    << std::hex << insn << " n=0x" << un << " m=0x" << um << " a=0x" << ua
                    << " EXPECTED=0x" << exp << " INTERP=0x" << got << std::dec;
      if (checked > 50) break;  // stop spamming once a class is found
    }
  }
  EXPECT_GT(checked, 10000);
}

// Differential fuzzer: random multi-instruction integer-ALU regions run through
// the lite JIT and the interpreter with identical inputs, comparing every guest
// register. Multi-instruction regions exercise cross-instruction register
// MAPPING and the RDX/RCX/RAX save-restore around DIV/MUL/shift — the scenario a
// register-mapping clobber (a destructive x86 op overwriting a mapped guest reg)
// hides in, which single-instruction tests cannot reach.
TEST_F(Arm64LiteTranslateRegionTest, IntegerRegMapDifferentialFuzz) {
  uint64_t seed = 0x0C0FFEE123456789ULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  const uint32_t kMaxReg = 10;  // x0..x9 — enough to force mapping incl. RDX/RCX slots
  auto gen = [&]() -> uint32_t {
    uint32_t rd = rnd() % kMaxReg, rn = rnd() % kMaxReg, rm = rnd() % kMaxReg,
             ra = rnd() % kMaxReg;
    uint32_t cond = rnd() % 14;        // omit AL(14)/NV(15)
    uint32_t nzcv = rnd() % 16;
    uint32_t imm12 = rnd() % 4096;
    uint32_t immr = rnd() % 64, imms = rnd() % 64;
    switch (rnd() % 24) {
      case 0: return 0x8B000000 | (rm << 16) | (rn << 5) | rd;  // add
      case 1: return 0xCB000000 | (rm << 16) | (rn << 5) | rd;  // sub
      case 2: return 0x8A000000 | (rm << 16) | (rn << 5) | rd;  // and
      case 3: return 0xAA000000 | (rm << 16) | (rn << 5) | rd;  // orr
      case 4: return 0xCA000000 | (rm << 16) | (rn << 5) | rd;  // eor
      case 5: return 0x9B007C00 | (rm << 16) | (rn << 5) | rd;  // mul
      case 6: return 0x9AC00C00 | (rm << 16) | (rn << 5) | rd;  // sdiv
      case 7: return 0x9AC00800 | (rm << 16) | (rn << 5) | rd;  // udiv
      case 8: return 0x9AC02800 | (rm << 16) | (rn << 5) | rd;  // asrv
      case 9: return 0x9AC02000 | (rm << 16) | (rn << 5) | rd;  // lslv
      case 10: return 0x9AC02400 | (rm << 16) | (rn << 5) | rd;  // lsrv
      case 11: return 0x9B407C00 | (rm << 16) | (rn << 5) | rd;  // smulh
      case 12: return 0x9B008000 | (rm << 16) | (ra << 10) | (rn << 5) | rd;  // msub
      case 13: return 0x9B000000 | (rm << 16) | (ra << 10) | (rn << 5) | rd;  // madd
      case 14: return 0xAB000000 | (rm << 16) | (rn << 5) | rd;  // adds
      case 15: return 0xEB000000 | (rm << 16) | (rn << 5) | rd;  // subs
      case 16: return 0xEB00001F | (rm << 16) | (rn << 5);       // cmp (subs xzr)
      case 17: return 0xAB00001F | (rm << 16) | (rn << 5);       // cmn (adds xzr)
      case 18: return 0xFA400000 | (rm << 16) | (cond << 12) | (rn << 5) | nzcv;  // ccmp
      case 19: return 0xBA400000 | (rm << 16) | (cond << 12) | (rn << 5) | nzcv;  // ccmn
      case 20: return 0x9A800000 | (rm << 16) | (cond << 12) | (rn << 5) | rd;  // csel
      case 21: return 0x9A800400 | (rm << 16) | (cond << 12) | (rn << 5) | rd;  // csinc
      case 22: return 0xDA800000 | (rm << 16) | (cond << 12) | (rn << 5) | rd;  // csinv
      case 23: return 0xDA800400 | (rm << 16) | (cond << 12) | (rn << 5) | rd;  // csneg
    }
    (void)imm12; (void)immr; (void)imms;
    return 0xD503201FU;  // nop
  };

  int regions_run = 0;
  for (int iter = 0; iter < 6000; iter++) {
    const int n = 3 + static_cast<int>(rnd() % 6);
    static uint32_t code[16];
    for (int i = 0; i < n; i++) code[i] = static_cast<uint32_t>(gen());
    uint64_t init[31];
    for (int i = 0; i < 31; i++)
      init[i] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    uint16_t init_flags = static_cast<uint16_t>(rnd() & 0xC101);  // N@15 Z@14 C@8 V@0

    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;

    // JIT.
    for (int i = 0; i < 31; i++) state_.cpu.x[i] = init[i];
    state_.cpu.flags = init_flags;
    state_.cpu.insn_addr = start;
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    uint64_t jit_x[31];
    for (int i = 0; i < 31; i++) jit_x[i] = state_.cpu.x[i];
    uint16_t jit_flags = state_.cpu.flags;

    // Interpreter to the same stop PC.
    for (int i = 0; i < 31; i++) state_.cpu.x[i] = init[i];
    state_.cpu.flags = init_flags;
    state_.cpu.insn_addr = start;
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 64)
      InterpretInsn(&state_);
    regions_run++;

    if ((jit_flags & 0xC101) != (state_.cpu.flags & 0xC101)) {
      std::string dis;
      for (int j = 0; j < n; j++) {
        char b[16];
        snprintf(b, sizeof(b), " %08x", code[j]);
        dis += b;
      }
      ADD_FAILURE() << "iter " << iter << " FLAGS diverged: JIT=0x" << std::hex << jit_flags
                    << " INTERP=0x" << state_.cpu.flags << std::dec << " region:" << dis;
    }
    for (int i = 0; i < 31; i++) {
      if (jit_x[i] != state_.cpu.x[i]) {
        std::string dis;
        for (int j = 0; j < n; j++) {
          char b[16];
          snprintf(b, sizeof(b), " %08x", code[j]);
          dis += b;
        }
        ADD_FAILURE() << "iter " << iter << " diverged at x" << i << ": JIT=0x" << std::hex
                      << jit_x[i] << " INTERP=0x" << state_.cpu.x[i] << std::dec << " region:" << dis;
        break;
      }
    }
  }
  EXPECT_GT(regions_run, 1000) << "fuzzer translated too few regions to be meaningful";
}

// Multi-instruction NEON reg-mapping differential fuzzer. ARM NEON 3-operand ops
// are non-destructive (dst, src1, src2 distinct), but x86 SSE ops are destructive
// (dst OP= src), so the lite translator must copy a source into the result before
// operating. A handler that applies the x86 op directly to a MAPPED guest source
// V register clobbers it for the rest of the region — the SIMD analogue of the
// CCMN integer reg-clobber bug, invisible to single-instruction tests because the
// clobbered source is never reused. Dest-reading ops (BSL/BIT/BIF, MLA/MLS) are
// extra-prone. Random multi-insn regions over v0..v15 (forces XMM mapping +
// spill), JIT vs interpreter, diffs every V register. Motivation: Helium's Skia
// rasterizer garbles glyphs under the JIT but renders crisp under interpret-only,
// i.e. a lite-JIT SIMD codegen bug that single-insn NEON fuzzing cannot reach.
TEST_F(Arm64LiteTranslateRegionTest, NeonRegMapDifferentialFuzz) {
  uint64_t seed = 0xBEEF1234DEADC0DEULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  // Full three-same encodings (Rd=0,Rn=1,Rm=2); the generator masks the register
  // fields out and inserts random v0..v15 operands.
  const uint32_t kOps[] = {
      0x4ea28420,  // add.4s
      0x6ea28420,  // sub.4s
      0x4ea29c20,  // mul.4s
      0x4e208420,  // add.16b
      0x4e608420,  // add.8h
      0x4ee28420,  // add.2d
      0x4e201c20,  // and.16b
      0x4ea01c20,  // orr.16b
      0x6e201c20,  // eor.16b
      0x4e601c20,  // bic.16b
      0x4ee01c20,  // orn.16b
      0x6e601c20,  // bsl.16b  (reads dst as the select mask)
      0x6ea01c20,  // bit.16b  (reads dst)
      0x6ee01c20,  // bif.16b  (reads dst)
      0x4ea29420,  // mla.4s   (reads dst, accumulates)
      0x6ea29420,  // mls.4s   (reads dst)
      0x4ea26420,  // smax.4s
      0x4ea26c20,  // smin.4s
      0x6ea26420,  // umax.4s
      0x6ea26c20,  // umin.4s
      0x4ea24420,  // sshl.4s
      0x6ea24420,  // ushl.4s
      0x4ea23420,  // cmgt.4s
      0x6ea28c20,  // cmeq.4s
      // Permute / lane-rearrange ops (Skia interleaves pixel channels with these;
      // a wrong lane map or a source clobber shears the rasterized mask):
      0x4e823820,  // zip1.4s
      0x4e827820,  // zip2.4s
      0x4e821820,  // uzp1.4s
      0x4e825820,  // uzp2.4s
      0x4e822820,  // trn1.4s
      0x4e826820,  // trn2.4s
      0x4e023820,  // zip1.16b
      0x4e021820,  // uzp1.16b
      0x4e022820,  // trn1.16b
      0x4e027820,  // zip2.16b
      0x4e025820,  // uzp2.16b
      0x4e026820,  // trn2.16b
      0x6e022020,  // ext.16b #4
      0x6e023820,  // ext.16b #7
      0x4e000020,  // tbl.16b (1 table reg)  Rt baked v1; masked below
      0x4e001020,  // tbx.16b (1 table reg)
      0x4ea2bc20,  // addp.4s
  };
  const int kNumOps = sizeof(kOps) / sizeof(kOps[0]);
  const uint32_t kMaxReg = 16;  // v0..v15 -> force XMM mapping + spill
  auto gen = [&]() -> uint32_t {
    uint32_t base = kOps[rnd() % kNumOps];
    uint32_t rd = rnd() % kMaxReg, rn = rnd() % kMaxReg, rm = rnd() % kMaxReg;
    return (base & ~0x1F03FFu) | (rm << 16) | (rn << 5) | rd;
  };

  int regions_run = 0;
  for (int iter = 0; iter < 8000; iter++) {
    const int n = 3 + static_cast<int>(rnd() % 6);
    static uint32_t code[16];
    for (int i = 0; i < n; i++) code[i] = gen();
    uint64_t initv[16][2];
    for (int i = 0; i < 16; i++) {
      initv[i][0] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
      initv[i][1] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    }
    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;

    // JIT.
    for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
    for (int i = 0; i < 16; i++) memcpy(&state_.cpu.v[i], initv[i], 16);
    state_.cpu.insn_addr = start;
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    unsigned __int128 jit_v[32];
    for (int i = 0; i < 32; i++) memcpy(&jit_v[i], &state_.cpu.v[i], 16);

    // Interpreter to the same stop PC, identical inputs.
    for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
    for (int i = 0; i < 16; i++) memcpy(&state_.cpu.v[i], initv[i], 16);
    state_.cpu.insn_addr = start;
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 64)
      InterpretInsn(&state_);
    regions_run++;

    for (int i = 0; i < 32; i++) {
      unsigned __int128 iv;
      memcpy(&iv, &state_.cpu.v[i], 16);
      if (jit_v[i] != iv) {
        std::string dis;
        for (int j = 0; j < n; j++) {
          char b[16];
          snprintf(b, sizeof(b), " %08x", code[j]);
          dis += b;
        }
        ADD_FAILURE() << "iter " << iter << " diverged at v" << i << ": JIT=0x" << std::hex
                      << (uint64_t)(jit_v[i] >> 64) << ":" << (uint64_t)jit_v[i] << " INTERP=0x"
                      << (uint64_t)(iv >> 64) << ":" << (uint64_t)iv << std::dec
                      << " region:" << dis;
        break;
      }
    }
  }
  EXPECT_GT(regions_run, 1000) << "fuzzer translated too few regions to be meaningful";
}

// Exhaustive AdvSIMD shift-by-immediate JIT-vs-interpreter differential.
// On-device bisection (forcing SIMD classes to the interpreter via a bail mask)
// localized Helium's garbled-glyph render to the AdvSimdShiftByImm lite-JIT
// handler.  These handlers read Vn and write Vd directly through ThreadState
// memory (rbp-relative) rather than mapped XMM registers, so a single-instruction
// region fully captures their codegen — there is no cross-instruction state for a
// region fuzzer to expose that a per-encoding sweep would miss.  This enumerates
// every (opcode, U, immh, immb, Q) the decoder accepts, drives a set of input
// vectors chosen to stress sign bits / rounding carry / lane boundaries, runs each
// through the JIT and the interpreter from identical state, and diffs Vd (all 128
// bits, including the upper-half-zero behaviour for !Q).  Any encoding the JIT
// declines to translate (success_=false → region ends at start) is skipped: those
// run on the interpreter on-device and cannot be the garble source.
TEST_F(Arm64LiteTranslateRegionTest, AdvSimdShiftByImmDifferential) {
  // Encoding: 0 Q U 011110 immh(4) immb(3) opcode(5) 1 Rn Rd
  auto enc = [](bool q, bool u, uint8_t immh, uint8_t immb, uint8_t opcode,
                uint8_t rn, uint8_t rd) -> uint32_t {
    return (static_cast<uint32_t>(q) << 30) | (static_cast<uint32_t>(u) << 29) |
           (0b011110u << 23) | (static_cast<uint32_t>(immh) << 19) |
           (static_cast<uint32_t>(immb) << 16) | (static_cast<uint32_t>(opcode) << 11) |
           (1u << 10) | (static_cast<uint32_t>(rn) << 5) | rd;
  };
  // Input vectors for Vn (hi:lo).  Cover sign-bit-set lanes at every element
  // width, rounding-carry boundaries, alternating bits, and small magnitudes.
  const uint64_t kInputs[][2] = {
      {0x0000000000000000ULL, 0x0000000000000000ULL},
      {0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL},
      {0x8080808080808080ULL, 0x8080808080808080ULL},
      {0x7F7F7F7F7F7F7F7FULL, 0x7F7F7F7F7F7F7F7FULL},
      {0x8000800080008000ULL, 0x8000800080008000ULL},
      {0x0001000100010001ULL, 0x0001000100010001ULL},
      {0x80000000FFFFFFFFULL, 0x000000017FFFFFFFULL},
      {0x0102040810204080ULL, 0x8040201008040201ULL},
      {0xAAAAAAAAAAAAAAAAULL, 0x5555555555555555ULL},
      {0xFFFFFFFF00000000ULL, 0x00000000FFFFFFFFULL},
      {0x123456789ABCDEF0ULL, 0x0FEDCBA987654321ULL},
      {0xC0C0C0C0C0C0C0C0ULL, 0x4040404040404040ULL},
  };
  const int kNumInputs = sizeof(kInputs) / sizeof(kInputs[0]);
  const uint64_t kSentinelHi = 0xDEADBEEFCAFEBABEULL;
  const uint64_t kSentinelLo = 0x0123456789ABCDEFULL;

  int compared = 0, jit_accepted = 0;
  int failures = 0;
  std::vector<std::string> sigs;
  auto sig_seen = [&](const std::string& s) {
    for (const auto& e : sigs) if (e == s) return true;
    sigs.push_back(s);
    return false;
  };
  for (uint8_t opcode = 0; opcode < 32; opcode++) {
    for (uint8_t u = 0; u <= 1; u++) {
      for (uint8_t q = 0; q <= 1; q++) {
        for (uint8_t immh = 1; immh < 16; immh++) {
          for (uint8_t immb = 0; immb < 8; immb++) {
            // inplace=1 exercises rd == rn: a handler that pre-zeros Vd would
            // clobber the Vn source before reading it (the bug that escaped the
            // rd != rn sweep).  rn is always 1; rd is 0 (separate) or 1 (in-place).
            for (int inplace = 0; inplace <= 1; inplace++) {
            const uint8_t rd = inplace ? 1 : 0;
            uint32_t code[1] = {enc(q, u, immh, immb, opcode, /*rn=*/1, rd)};
            GuestAddr start = ToGuestAddr(&code[0]);
            GuestAddr code_end = start + 4;

            // JIT translate; skip encodings the JIT declines (interp-only).
            MachineCode mc;
            auto [ok, stop] = TryLiteTranslateRegion(
                start, &mc,
                LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
            if (!ok || stop != code_end) continue;
            jit_accepted++;
            HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);

            for (int in = 0; in < kNumInputs; in++) {
              // JIT run.
              for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
              memcpy(&state_.cpu.v[1], kInputs[in], 16);
              uint64_t sent[2] = {kSentinelLo, kSentinelHi};
              if (!inplace) memcpy(&state_.cpu.v[0], sent, 16);
              state_.cpu.insn_addr = start;
              TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
              unsigned __int128 jit_vd;
              memcpy(&jit_vd, &state_.cpu.v[rd], 16);

              // Interpreter run, identical start state.
              for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
              memcpy(&state_.cpu.v[1], kInputs[in], 16);
              if (!inplace) memcpy(&state_.cpu.v[0], sent, 16);
              state_.cpu.insn_addr = start;
              InterpretInsn(&state_);
              unsigned __int128 interp_vd;
              memcpy(&interp_vd, &state_.cpu.v[rd], 16);

              compared++;
              if (jit_vd != interp_vd) {
                failures++;
                char key[64];
                snprintf(key, sizeof(key), "opcode=%d U=%d Q=%d immh=%d inplace=%d", (int)opcode,
                         (int)u, (int)q, (int)immh, inplace);
                if (!sig_seen(key)) {
                  ADD_FAILURE()
                      << "DIVERGE " << key << " (e.g. insn=0x" << std::hex << code[0]
                      << " immb=" << std::dec << (int)immb << " input#" << in << std::hex
                      << " Vn=0x" << kInputs[in][0] << ":" << kInputs[in][1] << " JIT=0x"
                      << (uint64_t)(jit_vd >> 64) << ":" << (uint64_t)jit_vd << " INTERP=0x"
                      << (uint64_t)(interp_vd >> 64) << ":" << (uint64_t)interp_vd
                      << std::dec << ")";
                }
              }
            }
            }  // inplace
          }
        }
      }
    }
  }
  EXPECT_GT(jit_accepted, 50) << "JIT accepted too few shift-imm encodings";
  EXPECT_GT(compared, 500) << "compared too few encoding/input pairs";
  if (failures == 0) {
    printf("AdvSimdShiftByImmDifferential: %d encodings JIT-accepted, %d pairs, ALL MATCH\n",
           jit_accepted, compared);
  }
}

// Byte-lane (.8B/.16B) SLI/SRI (insert) and SRSHR/URSHR/SRSRA/URSRA (rounding)
// shift-by-immediate: JIT codegen pinned to derived expected values (the
// AdvSimdShiftByImmDifferential sweep already covers JIT-vs-interp; this pins
// the exact semantics independently).  Distinguishing cases: the insert mask
// keeps the poisoned dst bits; signed rounding of -1 collapses to 0 while
// unsigned rounding of 0xFF rounds up; signed accumulate is arithmetic
// (SRSHR(-128,1) = -64); shift boundaries #0 / #8; and .8B upper-64 zeroing.
// Encodings assembler-verified (aarch64-linux-gnu clang -c).
TEST_F(Arm64LiteTranslateRegionTest, AdvSimdByteShiftInsertRoundingJitVsExpected) {
  struct C { uint32_t enc; const char* name; uint8_t vn; uint8_t vd; uint8_t want; int lanes; };
  const C cases[] = {
      // SLI keeps Vd's low `shift` bits: Vn 0x05<<3 = 0x28, Vd 0xFF low3 = 0x07 -> 0x2F.
      {0x6f0b5420, "sli.16b#3",   0x05, 0xFF, 0x2F, 16},
      {0x2f0b5420, "sli.8b#3",    0x05, 0xFF, 0x2F, 8},
      // SRI keeps Vd's high `shift` bits: Vn 0xA0>>3 = 0x14, Vd 0xFF high3 = 0xE0 -> 0xF4.
      {0x6f0d4420, "sri.16b#3",   0xA0, 0xFF, 0xF4, 16},
      {0x2f0d4420, "sri.8b#3",    0xA0, 0xFF, 0xF4, 8},
      // SRSHR of -1: (-1 + 4) >> 3 = 0.  Contrast URSHR of 0xFF: (255 + 4) >> 3 = 32.
      {0x4f0d2420, "srshr.16b#3", 0xFF, 0x00, 0x00, 16},
      {0x6f0d2420, "urshr.16b#3", 0xFF, 0x00, 0x20, 16},
      // SRSRA signed accumulate: SRSHR(-128,1) = (-128+1)>>1 arith = -64 (0xC0);
      // Vd 0x10 + 0xC0 = 0xD0 (mod 256).
      {0x4f0f3420, "srsra.16b#1", 0x80, 0x10, 0xD0, 16},
      {0x0f0f3420, "srsra.8b#1",  0x80, 0x10, 0xD0, 8},
      // URSRA accumulate: URSHR(0xFF,3) = 32 (0x20); Vd 0x10 + 0x20 = 0x30.
      {0x6f0d3420, "ursra.16b#3", 0xFF, 0x10, 0x30, 16},
      {0x2f0d3420, "ursra.8b#3",  0xFF, 0x10, 0x30, 8},
      // Boundaries: SRI #8 leaves Vd unchanged; SLI #0 copies Vn; SRSHR #8 -> 0.
      {0x6f084420, "sri.16b#8",   0x3C, 0x5A, 0x5A, 16},
      {0x6f085420, "sli.16b#0",   0x3C, 0xFF, 0x3C, 16},
      {0x4f082420, "srshr.16b#8", 0xFF, 0x00, 0x00, 16},
  };
  for (const C& c : cases) {
    for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
    uint8_t vn[16], vd[16];
    memset(vn, c.vn, 16);
    memset(vd, c.vd, 16);
    memcpy(&state_.cpu.v[1], vn, 16);
    memcpy(&state_.cpu.v[0], vd, 16);
    const uint32_t code[1] = {c.enc};
    ASSERT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)))
        << c.name << ": JIT declined the byte form";
    uint8_t got[16];
    memcpy(got, &state_.cpu.v[0], 16);
    for (int i = 0; i < c.lanes; i++) {
      EXPECT_EQ(got[i], c.want)
          << c.name << " lane " << i << " got=0x" << std::hex << (int)got[i]
          << " want=0x" << (int)c.want;
    }
    for (int i = c.lanes; i < 16; i++) {
      EXPECT_EQ(got[i], 0u) << c.name << " upper lane " << i << " not zeroed";
    }
  }
}

// Exhaustive scalar FP<->integer conversion (FpIntConversion) JIT-vs-interpreter
// differential.  Covers FCVTZS/FCVTZU (truncate), FCVTNS/NU/PS/PU/MS/MU (round
// modes), FCVTAS/AU (ties-away), SCVTF/UCVTF (int->FP), and FMOV GP<->FP across
// sf={0,1} and ftype={S,D}.  This handler snaps glyph coordinates float<->int in
// Skia, so it is in the hot path for web-text rendering; this pins its
// per-instruction codegen against the interpreter so a future regression in any
// rounding/saturation branch is caught at build time.  Drives FP-domain inputs
// (fractional/tie/overflow/NaN/Inf) and integer inputs, runs each
// single-instruction region through the JIT and the interpreter from identical
// state, and diffs both the GP destination and the V destination (the FP->GP
// path writes Xd; the GP->FP path writes Vd; FMOV does either).
TEST_F(Arm64LiteTranslateRegionTest, FpIntConversionDifferential) {
  // Encoding: sf 0 0 11110 ftype 1 rmode opcode 000000 Rn Rd
  auto enc = [](bool sf, uint8_t ftype, uint8_t rmode, uint8_t opcode, uint8_t rn,
                uint8_t rd) -> uint32_t {
    return (static_cast<uint32_t>(sf) << 31) | (0b11110u << 24) |
           (static_cast<uint32_t>(ftype) << 22) | (1u << 21) |
           (static_cast<uint32_t>(rmode) << 19) | (static_cast<uint32_t>(opcode) << 16) |
           (static_cast<uint32_t>(rn) << 5) | rd;
  };
  // FP test values (exercised as both float and double sources) and integer
  // sources for the int->FP direction.
  const double kFp[] = {
      0.0, -0.0, 0.5, -0.5, 1.5, -1.5, 2.5, -2.5, 1.4, 1.6, -1.4, -1.6,
      3.49, 3.51, -3.49, -3.51, 100.9, -100.9, 0.9999, -0.9999,
      127.5, 128.5, 255.5, 65535.5, 2147483647.0, 2147483648.0,
      -2147483648.0, -2147483649.0, 4294967295.0, 4294967296.0,
      9.2233720368547758e18, -9.2233720368547758e18, 1.8446744073709552e19,
      1e30, -1e30, 16777216.5, 16777217.0,
      std::numeric_limits<double>::quiet_NaN(),
      std::numeric_limits<double>::infinity(),
      -std::numeric_limits<double>::infinity(),
  };
  const int kNumFp = sizeof(kFp) / sizeof(kFp[0]);
  const int64_t kInt[] = {
      0, 1, -1, 2, -2, 7, -7, 127, -128, 255, 256, 1000, -1000, 65535, 65536,
      0x7FFFFFFFLL, -0x80000000LL, 0xFFFFFFFFLL, 0x100000000LL,
      0x123456789ABCDEFLL, -0x123456789ABCDEFLL, INT64_MAX, INT64_MIN, -1LL /*u64 max*/,
  };
  const int kNumInt = sizeof(kInt) / sizeof(kInt[0]);
  const uint8_t RN = 5, RD = 6;
  const uint64_t kSentX = 0xCAFEF00DDEADBEEFULL;
  const uint64_t kSentVlo = 0x1122334455667788ULL, kSentVhi = 0x99AABBCCDDEEFF00ULL;

  // (rmode, opcode) pairs the decoder maps; we just sweep all and let the JIT
  // decline what it can't translate.
  int jit_accepted = 0, compared = 0, failures = 0;
  std::vector<std::string> sigs;
  auto sig_seen = [&](const std::string& s) {
    for (const auto& e : sigs) if (e == s) return true;
    sigs.push_back(s);
    return false;
  };

  for (uint8_t sf = 0; sf <= 1; sf++) {
    for (uint8_t ftype = 0; ftype <= 1; ftype++) {       // 00=S, 01=D
      for (uint8_t rmode = 0; rmode < 4; rmode++) {
        for (uint8_t opcode = 0; opcode < 8; opcode++) {
          uint32_t code[1] = {enc(sf, ftype, rmode, opcode, RN, RD)};
          GuestAddr start = ToGuestAddr(&code[0]);
          GuestAddr code_end = start + 4;
          MachineCode mc;
          auto [ok, stop] = TryLiteTranslateRegion(
              start, &mc,
              LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
          if (!ok || stop != code_end) continue;
          jit_accepted++;
          HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);

          // Number of input rows: max of FP and int sets so both directions get
          // good coverage; index each with modulo.
          const int rows = (kNumFp > kNumInt ? kNumFp : kNumInt);
          for (int r = 0; r < rows; r++) {
            const double fv = kFp[r % kNumFp];
            const int64_t iv = kInt[r % kNumInt];
            // Build the V[RN] source: float bits for ftype=S, double for D.
            uint64_t vlo;
            if (ftype == 0) {
              float f = static_cast<float>(fv);
              uint32_t fb;
              memcpy(&fb, &f, 4);
              vlo = fb;  // upper 32 zero
            } else {
              memcpy(&vlo, &fv, 8);
            }

            auto setup = [&]() {
              for (int i = 0; i < 31; i++) state_.cpu.x[i] = kSentX;
              for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
              state_.cpu.x[RN] = static_cast<uint64_t>(iv);
              memcpy(&state_.cpu.v[RN], &vlo, 8);
              uint64_t sv[2] = {kSentVlo, kSentVhi};
              memcpy(&state_.cpu.v[RD], sv, 16);
              state_.cpu.x[RD] = kSentX;
              state_.cpu.insn_addr = start;
            };

            setup();
            TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
            uint64_t jit_xd = state_.cpu.x[RD];
            unsigned __int128 jit_vd;
            memcpy(&jit_vd, &state_.cpu.v[RD], 16);

            setup();
            InterpretInsn(&state_);
            uint64_t interp_xd = state_.cpu.x[RD];
            unsigned __int128 interp_vd;
            memcpy(&interp_vd, &state_.cpu.v[RD], 16);

            compared++;
            if (jit_xd != interp_xd || jit_vd != interp_vd) {
              failures++;
              char key[80];
              snprintf(key, sizeof(key), "sf=%d ftype=%d rmode=%d opcode=%d", (int)sf,
                       (int)ftype, (int)rmode, (int)opcode);
              if (!sig_seen(key)) {
                ADD_FAILURE()
                    << "DIVERGE " << key << " (insn=0x" << std::hex << code[0]
                    << std::dec << " row=" << r << " fv=" << fv << " iv=0x" << std::hex
                    << (uint64_t)iv << " | Xd JIT=0x" << jit_xd << " INTERP=0x" << interp_xd
                    << " | Vd JIT=0x" << (uint64_t)(jit_vd >> 64) << ":" << (uint64_t)jit_vd
                    << " INTERP=0x" << (uint64_t)(interp_vd >> 64) << ":"
                    << (uint64_t)interp_vd << std::dec << ")";
              }
            }
          }
        }
      }
    }
  }
  EXPECT_GT(jit_accepted, 20) << "JIT accepted too few FpIntConversion encodings";
  EXPECT_GT(compared, 200);
  if (failures == 0) {
    printf("FpIntConversionDifferential: %d encodings JIT-accepted, %d pairs, ALL MATCH\n",
           jit_accepted, compared);
  }
}

// Multi-instruction register-mapping differential for scalar FP<->integer
// conversions.  FpIntConversion uses GetReg/SetReg to read/write mapped guest
// x-registers; a handler that destructively touched a MAPPED source register
// would corrupt it for the rest of the region (the CCMN reg-clobber class),
// invisible to a single-instruction test that never re-reads the clobbered
// register.  This interleaves FCVTZS/SCVTF/FMOV/FCVTNS/etc. with GP-ALU ops over
// x0..x7 (forcing GP mapping + spill), runs JIT vs interpreter from identical
// state, and diffs every x and v register to guard against such a clobber.
TEST_F(Arm64LiteTranslateRegionTest, FpIntConversionRegMapDifferentialFuzz) {
  uint64_t seed = 0x9E3779B97F4A7C15ULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  auto encFpInt = [](bool sf, uint8_t ftype, uint8_t rmode, uint8_t opcode, uint8_t rn,
                     uint8_t rd) -> uint32_t {
    return (static_cast<uint32_t>(sf) << 31) | (0b11110u << 24) |
           (static_cast<uint32_t>(ftype) << 22) | (1u << 21) |
           (static_cast<uint32_t>(rmode) << 19) | (static_cast<uint32_t>(opcode) << 16) |
           (static_cast<uint32_t>(rn) << 5) | rd;
  };
  // (sf, ftype, rmode, opcode) templates the JIT translates.
  struct FpIntTmpl { uint8_t sf, ftype, rmode, opcode; };
  const FpIntTmpl kFpInt[] = {
      {0, 0, 3, 0}, {1, 1, 3, 0},  // FCVTZS Wd,Sn / Xd,Dn
      {0, 0, 3, 1}, {1, 1, 3, 1},  // FCVTZU Wd,Sn / Xd,Dn
      {0, 0, 0, 2}, {1, 1, 0, 2},  // SCVTF  Sd,Wn / Dd,Xn
      {0, 0, 0, 3}, {1, 1, 0, 3},  // UCVTF  Sd,Wn / Dd,Xn
      {0, 0, 0, 6}, {0, 0, 0, 7},  // FMOV   Wd,Sn / Sd,Wn
      {1, 1, 0, 6}, {1, 1, 0, 7},  // FMOV   Xd,Dn / Dd,Xn
      {0, 0, 0, 0}, {1, 1, 0, 0},  // FCVTNS Wd,Sn / Xd,Dn
      {0, 0, 1, 0}, {1, 1, 2, 0},  // FCVTPS Wd,Sn / FCVTMS Xd,Dn
      {0, 0, 0, 4}, {1, 1, 0, 4},  // FCVTAS Wd,Sn / Xd,Dn
      {0, 0, 3, 0},                // pad
  };
  const int kNumFpInt = sizeof(kFpInt) / sizeof(kFpInt[0]);
  // GP-ALU 3-register ops (base encodings with rd/rn/rm = 0).
  const uint32_t kAlu[] = {
      0x8B000000,  // add  Xd, Xn, Xm
      0xCB000000,  // sub  Xd, Xn, Xm
      0xAA000000,  // orr  Xd, Xn, Xm
      0x8A000000,  // and  Xd, Xn, Xm
      0xCA000000,  // eor  Xd, Xn, Xm
      0x0B000000,  // add  Wd, Wn, Wm
      0x4B000000,  // sub  Wd, Wn, Wm
  };
  const int kNumAlu = sizeof(kAlu) / sizeof(kAlu[0]);
  const uint8_t kMaxReg = 8;  // x0..x7 / v0..v7 -> force mapping + spill

  auto gen = [&]() -> uint32_t {
    uint8_t rd = rnd() % kMaxReg, rn = rnd() % kMaxReg;
    if (rnd() % 2 == 0) {
      const FpIntTmpl& t = kFpInt[rnd() % kNumFpInt];
      return encFpInt(t.sf, t.ftype, t.rmode, t.opcode, rn, rd);
    }
    uint8_t rm = rnd() % kMaxReg;
    return (kAlu[rnd() % kNumAlu] & ~0x1F03FFu) | (static_cast<uint32_t>(rm) << 16) |
           (static_cast<uint32_t>(rn) << 5) | rd;
  };

  int regions_run = 0;
  for (int iter = 0; iter < 12000; iter++) {
    const int n = 3 + static_cast<int>(rnd() % 7);
    static uint32_t code[16];
    for (int i = 0; i < n; i++) code[i] = gen();
    uint64_t initx[8];
    uint64_t initv[8][2];
    for (int i = 0; i < 8; i++) {
      initx[i] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
      // FP-ish lane values that stay mostly in-range for the conversions.
      initv[i][0] = ((rnd() & 0xffffULL) << 16) | 0x40000000ULL;
      initv[i][1] = 0;
    }
    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;

    auto setup = [&]() {
      for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
      for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
      for (int i = 0; i < 8; i++) {
        state_.cpu.x[i] = initx[i];
        memcpy(&state_.cpu.v[i], initv[i], 16);
      }
      state_.cpu.insn_addr = start;
    };

    setup();
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    setup();
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    uint64_t jit_x[31];
    unsigned __int128 jit_v[32];
    for (int i = 0; i < 31; i++) jit_x[i] = state_.cpu.x[i];
    for (int i = 0; i < 32; i++) memcpy(&jit_v[i], &state_.cpu.v[i], 16);

    setup();
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 64)
      InterpretInsn(&state_);
    regions_run++;

    bool diverged = false;
    for (int i = 0; i < 31 && !diverged; i++) {
      if (jit_x[i] != state_.cpu.x[i]) {
        std::string dis;
        for (int j = 0; j < n; j++) { char b[16]; snprintf(b, sizeof(b), " %08x", code[j]); dis += b; }
        ADD_FAILURE() << "iter " << iter << " diverged at x" << i << ": JIT=0x" << std::hex
                      << jit_x[i] << " INTERP=0x" << state_.cpu.x[i] << std::dec
                      << " region:" << dis;
        diverged = true;
      }
    }
    for (int i = 0; i < 32 && !diverged; i++) {
      unsigned __int128 iv;
      memcpy(&iv, &state_.cpu.v[i], 16);
      if (jit_v[i] != iv) {
        std::string dis;
        for (int j = 0; j < n; j++) { char b[16]; snprintf(b, sizeof(b), " %08x", code[j]); dis += b; }
        ADD_FAILURE() << "iter " << iter << " diverged at v" << i << ": JIT=0x" << std::hex
                      << (uint64_t)(jit_v[i] >> 64) << ":" << (uint64_t)jit_v[i] << " INTERP=0x"
                      << (uint64_t)(iv >> 64) << ":" << (uint64_t)iv << std::dec
                      << " region:" << dis;
        diverged = true;
      }
    }
    if (diverged) break;
  }
  EXPECT_GT(regions_run, 2000) << "fuzzer translated too few regions to be meaningful";
}

// HIGH-REGISTER-PRESSURE mixed-region differential.  Helium's residual blank
// diagonal glyphs (w/v/k/A/T) are a region-structural lite-JIT bug invisible to
// the existing fuzzers because they use few guest registers (x0..x9) and so never
// exhaust the 13-entry GP pool.  Large real glyph-rasterizer regions DO exhaust
// it, forcing GetReg's spill-to-temp path, SIMD handlers' AllocTempReg under a
// near-full pool, the Alloc()/AllocTemp() high-water (max_temp_regs_allocated)
// reservation, and early region termination (IsGpRegPoolLow).  This interleaves
// GP-ALU, NEON three-same, scalar FP arithmetic, FP<->int conversions, and vector
// shift/fixed-point-conversion ops over x0..x18 / v0..v18 in long (up to 16-insn)
// regions, runs JIT vs interpreter from identical state, and diffs every x and v
// register, looking for a spill/pressure-triggered clobber.
TEST_F(Arm64LiteTranslateRegionTest, HighPressureMixedRegionDifferentialFuzz) {
  uint64_t seed = 0xD1CEC0DE5EED1234ULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  const uint32_t R = 19;  // x0..x18 / v0..v18 -> blow past the 13-entry GP pool
  // NEON three-same (Rd=0,Rn=1,Rm=2 base; reg fields masked & re-inserted).
  const uint32_t kNeon3[] = {
      0x4ea28420, 0x6ea28420, 0x4ea29c20, 0x4e208420, 0x4e608420, 0x4ee28420,
      0x4e201c20, 0x4ea01c20, 0x6e201c20, 0x4ea29420 /*mla*/, 0x6ea29420 /*mls*/,
      0x4ea26420 /*smax*/, 0x6ea26c20 /*umin*/, 0x4ea24420 /*sshl*/, 0x4ea23420 /*cmgt*/,
  };
  // Scalar FP arith (ftype S/D) FADD/FSUB/FMUL/FDIV (Rd=0,Rn=1,Rm=2 base).
  const uint32_t kFpArith[] = {
      0x1e202800, 0x1e203800, 0x1e200800, 0x1e201800,  // S: fadd/fsub/fmul/fdiv
      0x1e602800, 0x1e603800, 0x1e600800, 0x1e601800,  // D
  };
  // Vector shift-imm incl. the just-fixed fixed-point conversions (Rd=0,Rn=1).
  const uint32_t kVShift[] = {
      0x4f2a5400 /*shl.4s #10*/, 0x6f2a0400 /*ushr.4s*/, 0x4f2a0400 /*sshr.4s*/,
      0x4f25e400 /*scvtf.4s #fbits*/, 0x4f25fc00 /*fcvtzs.4s*/,
      0x4f60e400 /*scvtf.2d*/, 0x6f60e400 /*ucvtf.2d*/,
  };
  // FpIntConversion templates (sf,ftype,rmode,opcode).
  struct FI { uint8_t sf, ft, rm, op; };
  const FI kFpInt[] = {
      {0,0,3,0},{1,1,3,0},{0,0,3,1},{1,1,0,2},{0,0,0,2},{0,0,0,7},{0,0,0,6},
      {1,1,0,7},{0,0,0,0},{1,1,2,0},{0,0,0,4},
  };
  auto encFI = [](FI t, uint8_t rn, uint8_t rd) -> uint32_t {
    return (uint32_t(t.sf) << 31) | (0b11110u << 24) | (uint32_t(t.ft) << 22) |
           (1u << 21) | (uint32_t(t.rm) << 19) | (uint32_t(t.op) << 16) |
           (uint32_t(rn) << 5) | rd;
  };
  const uint32_t kAlu[] = {0x8B000000, 0xCB000000, 0x8A000000, 0xAA000000, 0xCA000000,
                           0x0B000000, 0x4B000000, 0x9B007C00 /*mul*/};
  auto gen = [&]() -> uint32_t {
    uint8_t rd = rnd() % R, rn = rnd() % R, rm = rnd() % R;
    switch (rnd() % 6) {
      case 0: case 1: {  // GP-ALU 3-reg
        uint32_t base = kAlu[rnd() % (sizeof(kAlu)/sizeof(kAlu[0]))];
        return (base & ~0x1F03FFu) | (uint32_t(rm) << 16) | (uint32_t(rn) << 5) | rd;
      }
      case 2: {  // NEON three-same
        uint32_t base = kNeon3[rnd() % (sizeof(kNeon3)/sizeof(kNeon3[0]))];
        return (base & ~0x1F03FFu) | (uint32_t(rm) << 16) | (uint32_t(rn) << 5) | rd;
      }
      case 3: {  // scalar FP arith
        uint32_t base = kFpArith[rnd() % (sizeof(kFpArith)/sizeof(kFpArith[0]))];
        return (base & ~0x1F03E0u) | (uint32_t(rm) << 16) | (uint32_t(rn) << 5) | rd;
      }
      case 4: {  // vector shift / fixed-point conversion
        uint32_t base = kVShift[rnd() % (sizeof(kVShift)/sizeof(kVShift[0]))];
        return (base & ~0x3E0u & ~0x1Fu) | (uint32_t(rn) << 5) | rd;
      }
      default:  // FpIntConversion
        return encFI(kFpInt[rnd() % (sizeof(kFpInt)/sizeof(kFpInt[0]))], rn, rd);
    }
  };

  int regions_run = 0;
  for (int iter = 0; iter < 20000; iter++) {
    const int n = 4 + static_cast<int>(rnd() % 13);
    static uint32_t code[20];
    for (int i = 0; i < n; i++) code[i] = gen();
    uint64_t initx[R];
    uint64_t initv[R][2];
    // Each 32-bit lane is a finite normal float (exp 0x7D, no NaN/Inf); viewed
    // as a 64-bit double each pair is also finite (exp ~0x3e8).  This keeps the
    // FP ops away from benign ARM-vs-x86 NaN-PAYLOAD differences (which are not
    // a translator bug) while still exercising conversions and arithmetic.
    auto lane = [&]() -> uint32_t { return 0x3e800000u | (uint32_t)(rnd() & 0x003fffffu); };
    for (uint32_t i = 0; i < R; i++) {
      initx[i] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
      initv[i][0] = (uint64_t)lane() | ((uint64_t)lane() << 32);
      initv[i][1] = (uint64_t)lane() | ((uint64_t)lane() << 32);
    }
    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;

    auto setup = [&]() {
      for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
      for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
      for (uint32_t i = 0; i < R; i++) {
        state_.cpu.x[i] = initx[i];
        memcpy(&state_.cpu.v[i], initv[i], 16);
      }
      state_.cpu.insn_addr = start;
    };

    setup();
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    setup();
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    uint64_t jit_x[31];
    unsigned __int128 jit_v[32];
    for (int i = 0; i < 31; i++) jit_x[i] = state_.cpu.x[i];
    for (int i = 0; i < 32; i++) memcpy(&jit_v[i], &state_.cpu.v[i], 16);

    setup();
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 80)
      InterpretInsn(&state_);
    regions_run++;

    int target = -1;  // 0..30 = x, 100+i = v
    for (int i = 0; i < 31 && target < 0; i++)
      if (jit_x[i] != state_.cpu.x[i]) target = i;
    for (int i = 0; i < 32 && target < 0; i++) {
      unsigned __int128 iv; memcpy(&iv, &state_.cpu.v[i], 16);
      if (jit_v[i] != iv) target = 100 + i;
    }
    if (target < 0) continue;

    // Delta-debug: greedily reduce the region to the minimal instruction set
    // that still diverges at `target` (same inputs), to expose the root cause.
    auto divergesAt = [&](const uint32_t* c, int m) -> bool {
      GuestAddr s = ToGuestAddr(c);
      GuestAddr e = s + static_cast<GuestAddr>(m) * 4;
      auto init = [&]() {
        for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
        for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
        for (uint32_t i = 0; i < R; i++) { state_.cpu.x[i] = initx[i]; memcpy(&state_.cpu.v[i], initv[i], 16); }
        state_.cpu.insn_addr = s;
      };
      init();
      MachineCode m2;
      auto [ok2, stop2] = TryLiteTranslateRegion(
          s, &m2, LiteTranslateParams{.end_pc = e, .allow_dispatch = false});
      if (!ok2 || stop2 != e) return false;
      HostCodeAddr hc2 = GetDefaultCodePoolInstance()->Add(&m2);
      TestingRunGeneratedCode(&state_, AsHostCode(hc2), stop2);
      uint64_t jx = 0; unsigned __int128 jv = 0;
      if (target < 100) jx = state_.cpu.x[target]; else memcpy(&jv, &state_.cpu.v[target - 100], 16);
      init();
      int g = 0;
      while (state_.cpu.insn_addr >= s && state_.cpu.insn_addr < stop2 && g++ < 80) InterpretInsn(&state_);
      if (target < 100) return jx != state_.cpu.x[target];
      unsigned __int128 iv; memcpy(&iv, &state_.cpu.v[target - 100], 16); return jv != iv;
    };
    static uint32_t cur[20]; int m = n;
    for (int i = 0; i < n; i++) cur[i] = code[i];
    bool changed = true;
    while (changed) {
      changed = false;
      for (int i = 0; i < m; i++) {
        static uint32_t trial[20]; int tm = 0;
        for (int j = 0; j < m; j++) if (j != i) trial[tm++] = cur[j];
        if (tm > 0 && divergesAt(trial, tm)) {
          for (int j = 0; j < tm; j++) cur[j] = trial[j];
          m = tm; changed = true; break;
        }
      }
    }
    std::string dis, inx, inv;
    for (int j = 0; j < m; j++) { char b[16]; snprintf(b, sizeof(b), " %08x", cur[j]); dis += b; }
    for (uint32_t i = 0; i < R; i++) { char b[32]; snprintf(b, sizeof(b), " x%u=0x%llx", i, (unsigned long long)initx[i]); inx += b; }
    for (uint32_t i = 0; i < R; i++) { char b[48]; snprintf(b, sizeof(b), " v%u=0x%llx:%llx", i, (unsigned long long)initv[i][1], (unsigned long long)initv[i][0]); inv += b; }
    ADD_FAILURE() << "iter " << iter << " MINIMAL(" << m << ") diverged at "
                  << (target < 100 ? "x" : "v") << (target < 100 ? target : target - 100)
                  << " region:" << dis << "\n  initx:" << inx << "\n  initv:" << inv;
    break;
  }
  EXPECT_GT(regions_run, 3000) << "fuzzer translated too few regions to be meaningful";
}

// Memory-backed NEON structured load/store (LD1-4 / ST1-4) differential fuzzer.
// Skia's A8 glyph blitter de/interleaves coverage and channels with LD2/LD4/ST4
// in a post-indexed loop (`ld4 {...},[ptr],#stride`); a wrong de-interleave lane
// map OR a wrong post-index writeback advances pointers incorrectly and shears
// the rasterized mask — the exact web-text glyph shear, which renders crisp under
// interpret-only but garbled under the lite JIT. The single-instruction probes
// (hello-glyphblit's vld4/vst4) never exercise the writeback loop. This runs
// random short regions of these ops over v0..v7 with base x10 into a scratch
// buffer, JIT vs interpreter, and diffs every V register, the base register, AND
// the resulting memory.
TEST_F(Arm64LiteTranslateRegionTest, NeonStructuredLoadStoreDifferentialFuzz) {
  uint64_t seed = 0x5712ABCD9933EF01ULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  // Base encodings (Rt=v0, Rn=x0, Rm per note). The generator inserts a random
  // first vector reg (Rt in 0..7) and the fixed base register x10 (Rn=10).
  const uint32_t kOps[] = {
      0x4cdf0000,  // ld4 {v0-v3}.16b, [x0], #64
      0x4c9f0000,  // st4 {v0-v3}.16b, [x0], #64
      0x4c400000,  // ld4 {v0-v3}.16b, [x0]      (no writeback)
      0x4cdf0800,  // ld4 {v0-v3}.4s,  [x0], #64
      0x4cdf8000,  // ld2 {v0-v1}.16b, [x0], #32
      0x4cdf8400,  // ld2 {v0-v1}.8h,  [x0], #32
      0x4cdf4000,  // ld3 {v0-v2}.16b, [x0], #48
      0x4cdf2000,  // ld1 {v0-v3}.16b, [x0], #64
      0x4c9f8000,  // st2 {v0-v1}.16b, [x0], #32
      0x4cc50000,  // ld4 {v0-v3}.16b, [x0], x5
      0x4c408400,  // ld2 {v0-v1}.8h,  [x0]
      // Single-structure / replicate forms (AdvSimdSingleStruct) with writeback:
      0x4ddfc140,  // ld1r {v0.16b}, [x0], #1
      0x4ddfc940,  // ld1r {v0.4s},  [x0], #4
      0x0ddf0d40,  // ld1  {v0.b}[3], [x0], #1
      0x4ddf8140,  // ld1  {v0.s}[2], [x0], #4
      0x0d9f0d40,  // st1  {v0.b}[3], [x0], #1
      0x4d9f8140,  // st1  {v0.s}[2], [x0], #4
      0x0dff9140,  // ld2  {v0.s,v1.s}[1], [x0], #8
      0x4d40c140,  // ld1r {v0.16b}, [x0]
  };
  const int kNumOps = sizeof(kOps) / sizeof(kOps[0]);
  alignas(16) static uint8_t buf[4096];
  static uint8_t buf_init[4096];
  static uint8_t jit_buf[4096];

  int regions_run = 0;
  for (int iter = 0; iter < 6000; iter++) {
    for (size_t i = 0; i < sizeof(buf); i++) buf[i] = static_cast<uint8_t>(rnd());
    memcpy(buf_init, buf, sizeof(buf));
    uint64_t initv[16][2];
    for (int i = 0; i < 16; i++) {
      initv[i][0] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
      initv[i][1] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    }
    const uint64_t base_addr = ToGuestAddr(&buf[1024]);
    const uint64_t x5_off = 16 + (rnd() % 6) * 16;  // 16..96, 16-aligned, forward

    const int n = 1 + static_cast<int>(rnd() % 4);
    static uint32_t code[8];
    for (int i = 0; i < n; i++) {
      uint32_t base = kOps[rnd() % kNumOps];
      uint32_t rt = rnd() % 8;
      code[i] = (base & ~0x3FFu) | (10u << 5) | rt;  // Rn=x10, Rt=v(rt)
    }
    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;

    auto setup = [&]() {
      for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
      for (int i = 0; i < 16; i++) memcpy(&state_.cpu.v[i], initv[i], 16);
      for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
      state_.cpu.x[10] = base_addr;
      state_.cpu.x[5] = x5_off;
      state_.cpu.insn_addr = start;
    };

    // JIT.
    setup();
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    unsigned __int128 jit_v[32];
    for (int i = 0; i < 32; i++) memcpy(&jit_v[i], &state_.cpu.v[i], 16);
    uint64_t jit_x10 = state_.cpu.x[10];
    memcpy(jit_buf, buf, sizeof(buf));

    // Restore memory, run interpreter to the same stop PC.
    memcpy(buf, buf_init, sizeof(buf));
    setup();
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 16)
      InterpretInsn(&state_);
    regions_run++;

    bool diverged = false;
    std::string what;
    for (int i = 0; i < 32 && !diverged; i++) {
      unsigned __int128 iv;
      memcpy(&iv, &state_.cpu.v[i], 16);
      if (jit_v[i] != iv) {
        diverged = true;
        what = "v" + std::to_string(i);
      }
    }
    if (!diverged && jit_x10 != state_.cpu.x[10]) {
      diverged = true;
      what = "x10(base) jit=0x" + std::to_string(jit_x10) + " int=0x" + std::to_string(state_.cpu.x[10]);
    }
    if (!diverged && memcmp(jit_buf, buf, sizeof(buf)) != 0) {
      diverged = true;
      what = "memory";
    }
    if (diverged) {
      std::string dis;
      for (int j = 0; j < n; j++) {
        char b[16];
        snprintf(b, sizeof(b), " %08x", code[j]);
        dis += b;
      }
      ADD_FAILURE() << "iter " << iter << " diverged at " << what << " x5off=" << x5_off
                    << " region:" << dis;
    }
  }
  EXPECT_GT(regions_run, 500) << "fuzzer translated too few regions to be meaningful";
}

// Scalar FP + FP<->int differential fuzzer over FINITE inputs (no NaN/Inf, which
// legitimately differ in x86 vs ARM default-NaN propagation). Covers the scalar
// arithmetic and conversion ops Skia uses for analytic-AA coverage geometry
// (FADD/FMUL/FSUB/FDIV/FMADD/FMAXNM/FRINTA + FCVTZS/FCVTZU/SCVTF/UCVTF/FCVT/FMOV/
// FCVTNS/FCVTMS). Multi-instruction over s0..s7 (and the GP result of FCVT-to-int
// / FMOV-to-gp), JIT vs interpreter, diffs every V and GP register.
TEST_F(Arm64LiteTranslateRegionTest, ScalarFpDifferentialFuzz) {
  uint64_t seed = 0x9E3779B97F4A7C15ULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  struct Op {
    uint32_t enc;
    uint32_t mask;  // rd/rn(/rm/ra)
  };
  const Op ops[] = {
      {0x1e222820, 0x1F03FF}, {0x1e220820, 0x1F03FF}, {0x1e223820, 0x1F03FF},  // fadd/fmul/fsub s
      {0x1e221820, 0x1F03FF}, {0x1e226820, 0x1F03FF},                          // fdiv / fmaxnm s
      {0x1f020c20, 0x1F83FF},  // fmadd s (rd/rn/rm/ra)
      {0x1e380020, 0x3FF},    {0x1e390020, 0x3FF},                             // fcvtzs/fcvtzu w<-s
      {0x1e220020, 0x3FF},    {0x1e230020, 0x3FF},                             // scvtf/ucvtf s<-w
      {0x1e624020, 0x3FF},    {0x1e22c020, 0x3FF},                             // fcvt s<-d / d<-s
      {0x1e260020, 0x3FF},    {0x1e270020, 0x3FF},                             // fmov w<-s / s<-w
      {0x1e200020, 0x3FF},    {0x1e300020, 0x3FF},    {0x1e264020, 0x3FF},     // fcvtns/fcvtms/frinta
  };
  const int kNum = sizeof(ops) / sizeof(ops[0]);
  const uint32_t kMaxReg = 8;
  // Finite float bit patterns to seed registers (both s and w views).
  const uint32_t fbits[] = {0x3f800000, 0x40490fdb, 0xc2c80000, 0xbf800000, 0x41200000,
                            0x3dcccccd, 0x447a0000, 0x00000005, 0xc0000000, 0x42f6e979};
  const int NF = sizeof(fbits) / sizeof(fbits[0]);
  auto gen = [&]() -> uint32_t {
    const Op& o = ops[rnd() % kNum];
    uint32_t e = o.enc & ~o.mask;
    if (o.mask & 0x7C00) e |= static_cast<uint32_t>(rnd() % kMaxReg) << 10;  // ra (fmadd)
    if (o.mask & 0x1F0000) e |= static_cast<uint32_t>(rnd() % kMaxReg) << 16;
    if (o.mask & 0x3E0) e |= static_cast<uint32_t>(rnd() % kMaxReg) << 5;
    if (o.mask & 0x1F) e |= static_cast<uint32_t>(rnd() % kMaxReg);
    return e;
  };

  int regions_run = 0;
  for (int iter = 0; iter < 9000; iter++) {
    const int n = 3 + static_cast<int>(rnd() % 6);
    static uint32_t code[16];
    for (int i = 0; i < n; i++) code[i] = gen();
    uint64_t initx[31];
    unsigned __int128 initv[8];
    for (int i = 0; i < 31; i++)
      initx[i] = static_cast<uint64_t>(fbits[rnd() % NF]) | (static_cast<uint64_t>(rnd() % 64) << 32);
    for (int i = 0; i < 8; i++) {
      uint64_t lo = static_cast<uint64_t>(fbits[rnd() % NF]) |
                    (static_cast<uint64_t>(fbits[rnd() % NF]) << 32);
      memcpy(&initv[i], &lo, 8);
      uint64_t hi = 0;
      memcpy(reinterpret_cast<uint8_t*>(&initv[i]) + 8, &hi, 8);
    }
    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;

    auto setup = [&]() {
      for (int i = 0; i < 31; i++) state_.cpu.x[i] = initx[i];
      for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
      for (int i = 0; i < 8; i++) memcpy(&state_.cpu.v[i], &initv[i], 16);
      state_.cpu.flags = 0;
      state_.cpu.insn_addr = start;
    };

    setup();
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    uint64_t jit_x[31];
    unsigned __int128 jit_v[32];
    for (int i = 0; i < 31; i++) jit_x[i] = state_.cpu.x[i];
    for (int i = 0; i < 32; i++) memcpy(&jit_v[i], &state_.cpu.v[i], 16);

    setup();
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 64)
      InterpretInsn(&state_);
    regions_run++;

    bool diverged = false;
    std::string what;
    for (int i = 0; i < 31 && !diverged; i++)
      if (jit_x[i] != state_.cpu.x[i]) { diverged = true; what = "x" + std::to_string(i); }
    for (int i = 0; i < 32 && !diverged; i++) {
      unsigned __int128 iv;
      memcpy(&iv, &state_.cpu.v[i], 16);
      if (jit_v[i] != iv) { diverged = true; what = "v" + std::to_string(i); }
    }
    if (diverged) {
      std::string dis;
      for (int j = 0; j < n; j++) {
        char b[16];
        snprintf(b, sizeof(b), " %08x", code[j]);
        dis += b;
      }
      ADD_FAILURE() << "iter " << iter << " diverged at " << what << " region:" << dis;
    }
  }
  EXPECT_GT(regions_run, 1000) << "fuzzer translated too few regions to be meaningful";
}

// Multi-instruction NEON differential fuzzer for the remaining lite-JIT SIMD
// classes: shift-by-immediate, two-reg-misc (neg/abs/not/rev/cnt/xtn/clz/rbit),
// across-lanes, compare-against-zero, dup/ins element, three-different widening
// (umull/uaddl/uaddw/...), and modified-immediate. Each op carries the mask of
// register fields to randomize (rd / rd+rn / rd+rn+rm), keeping shift/lane
// immediates intact. Same crisp-interpret / garbled-JIT motivation as the
// three-same and structured-load/store fuzzers: a lite-JIT SIMD codegen bug
// shears Skia's glyph mask, so every JIT-handled SIMD op must match the
// interpreter over multi-instruction (mapping-forcing) regions.
TEST_F(Arm64LiteTranslateRegionTest, NeonMiscRegMapDifferentialFuzz) {
  uint64_t seed = 0x13579BDF2468ACE0ULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  struct Op {
    uint32_t enc;
    uint32_t mask;  // which of rm(0x1F0000)/rn(0x3E0)/rd(0x1F) to randomize
  };
  const Op ops[] = {
      {0x4f235420, 0x3FF},     {0x6f3b0420, 0x3FF},     {0x4f3b0420, 0x3FF},  // shl/ushr/sshr.4s
      {0x4f0a5420, 0x3FF},     {0x6f0e0420, 0x3FF},                           // shl/ushr.16b
      {0x0f0d8420, 0x3FF},     {0x0f0aa420, 0x3FF},     {0x2f0aa420, 0x3FF},  // shrn/sshll/ushll
      {0x6f235420, 0x3FF},     {0x6f3d4420, 0x3FF},                           // sli/sri.4s
      {0x6ea0b820, 0x3FF},     {0x4ea0b820, 0x3FF},     {0x6e205820, 0x3FF},  // neg/abs/not
      {0x4e201820, 0x3FF},     {0x6e200820, 0x3FF},     {0x4ea00820, 0x3FF},  // rev16/rev32/rev64
      {0x4e205820, 0x3FF},     {0x0e212820, 0x3FF},     {0x2e214820, 0x3FF},  // cnt/xtn/uqxtn
      {0x6ea04820, 0x3FF},     {0x6e605820, 0x3FF},                           // clz/rbit
      {0x6e303820, 0x3FF},     {0x4e31b820, 0x3FF},                           // uaddlv/addv
      {0x4ea09820, 0x3FF},     {0x6ea08820, 0x3FF},                           // cmeq0/cmge0
      {0x4e0c0420, 0x3FF},     {0x4e070420, 0x3FF},     {0x4e0c1c20, 0x3FF},  // dup elem / ins elem
      {0x2e22c020, 0x1F03FF},  {0x0e22c020, 0x1F03FF},                        // umull/smull
      {0x2e220020, 0x1F03FF},  {0x2e222020, 0x1F03FF},                        // uaddl/usubl
      {0x2e228020, 0x1F03FF},  {0x0e228020, 0x1F03FF},  {0x2e227020, 0x1F03FF},  // umlal/smlal/uabdl
      {0x2e221020, 0x1F03FF},  {0x2e223020, 0x1F03FF},  {0x0e22e020, 0x1F03FF},  // uaddw/usubw/pmull
      {0x4f000420, 0x1F},      {0x6f000420, 0x1F},      {0x4f00e4e0, 0x1F},
      {0x4f03f600, 0x1F},  // movi.4s / mvni.4s / movi.16b / fmov.4s #1.0
  };
  const int kNum = sizeof(ops) / sizeof(ops[0]);
  const uint32_t kMaxReg = 16;
  auto gen = [&]() -> uint32_t {
    const Op& o = ops[rnd() % kNum];
    uint32_t e = o.enc & ~o.mask;
    if (o.mask & 0x1F0000) e |= static_cast<uint32_t>(rnd() % kMaxReg) << 16;  // rm
    if (o.mask & 0x3E0) e |= static_cast<uint32_t>(rnd() % kMaxReg) << 5;      // rn
    if (o.mask & 0x1F) e |= static_cast<uint32_t>(rnd() % kMaxReg);            // rd
    return e;
  };

  int regions_run = 0;
  for (int iter = 0; iter < 9000; iter++) {
    const int n = 3 + static_cast<int>(rnd() % 6);
    static uint32_t code[16];
    for (int i = 0; i < n; i++) code[i] = gen();
    uint64_t initv[16][2];
    for (int i = 0; i < 16; i++) {
      initv[i][0] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
      initv[i][1] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    }
    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;

    for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
    for (int i = 0; i < 16; i++) memcpy(&state_.cpu.v[i], initv[i], 16);
    state_.cpu.insn_addr = start;
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    unsigned __int128 jit_v[32];
    for (int i = 0; i < 32; i++) memcpy(&jit_v[i], &state_.cpu.v[i], 16);

    for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
    for (int i = 0; i < 16; i++) memcpy(&state_.cpu.v[i], initv[i], 16);
    state_.cpu.insn_addr = start;
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 64)
      InterpretInsn(&state_);
    regions_run++;

    for (int i = 0; i < 32; i++) {
      unsigned __int128 iv;
      memcpy(&iv, &state_.cpu.v[i], 16);
      if (jit_v[i] != iv) {
        std::string dis;
        for (int j = 0; j < n; j++) {
          char b[16];
          snprintf(b, sizeof(b), " %08x", code[j]);
          dis += b;
        }
        ADD_FAILURE() << "iter " << iter << " diverged at v" << i << ": JIT=0x" << std::hex
                      << (uint64_t)(jit_v[i] >> 64) << ":" << (uint64_t)jit_v[i] << " INTERP=0x"
                      << (uint64_t)(iv >> 64) << ":" << (uint64_t)iv << std::dec
                      << " region:" << dis;
        break;
      }
    }
  }
  EXPECT_GT(regions_run, 1000) << "fuzzer translated too few regions to be meaningful";
}

// Integer ADDRESS-MATH differential fuzzer: shifted/extended-register ALU
// (`add x,x,x,lsl #n` / `add x,x,w,uxtw #n`), ADD/SUB immediate, logical-shifted,
// bitfield (ubfx/sbfx/bfi/ubfiz), shift-by-immediate, and move-wide (movk/movz).
// These compute the pointer/stride arithmetic of Skia's rasterizer row loop
// (`base + y*stride`, `ptr + index<<shift`); a single miscompiled extend/shift or
// bitfield extract drifts a stride and shears the glyph mask. The original
// IntegerRegMapDifferentialFuzz covers only plain (unshifted) ALU, so these
// addressing forms were untested. Multi-instruction regions over x0..x9, JIT vs
// interpreter, diff all GP regs + flags.
TEST_F(Arm64LiteTranslateRegionTest, IntegerAddrRegMapDifferentialFuzz) {
  uint64_t seed = 0x77AA33CC11EE99BBULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  struct Op {
    uint32_t enc;
    uint32_t mask;
  };
  const Op ops[] = {
      {0x8b020c20, 0x1F03FF}, {0x8b420820, 0x1F03FF}, {0x8b820420, 0x1F03FF},  // add lsl/lsr/asr
      {0xcb021020, 0x1F03FF}, {0x8b224820, 0x1F03FF}, {0x8b22c420, 0x1F03FF},  // sub lsl / add uxtw/sxtw
      {0x8b226c20, 0x1F03FF}, {0xcb22c820, 0x1F03FF}, {0x0b020c20, 0x1F03FF},  // add uxtx / sub sxtw / add(w) lsl
      {0x8a020c20, 0x1F03FF}, {0xaa420820, 0x1F03FF}, {0xca821020, 0x1F03FF},  // and/orr/eor shifted
      {0x8a220420, 0x1F03FF},                                                  // bic shifted
      {0x91019020, 0x3FF},    {0x916aa820, 0x3FF},    {0xd100c820, 0x3FF},     // add #imm / add #imm,lsl12 / sub #imm
      {0xd3442c20, 0x3FF},    {0x93442c20, 0x3FF},    {0xb37c1c20, 0x3FF},     // ubfx/sbfx/bfi
      {0xd37c1c20, 0x3FF},    {0xd354c420, 0x3FF},    {0x53042c20, 0x3FF},     // ubfiz / ubfx / ubfx(w)
      {0xd37be820, 0x3FF},    {0xd345fc20, 0x3FF},    {0x9345fc20, 0x3FF},     // lsl/lsr/asr imm
      {0xf2a24680, 0x1F},     {0xd2c24680, 0x1F},                             // movk / movz
  };
  const int kNum = sizeof(ops) / sizeof(ops[0]);
  const uint32_t kMaxReg = 10;  // x0..x9
  auto gen = [&]() -> uint32_t {
    const Op& o = ops[rnd() % kNum];
    uint32_t e = o.enc & ~o.mask;
    if (o.mask & 0x1F0000) e |= static_cast<uint32_t>(rnd() % kMaxReg) << 16;
    if (o.mask & 0x3E0) e |= static_cast<uint32_t>(rnd() % kMaxReg) << 5;
    if (o.mask & 0x1F) e |= static_cast<uint32_t>(rnd() % kMaxReg);
    return e;
  };

  int regions_run = 0;
  for (int iter = 0; iter < 9000; iter++) {
    const int n = 3 + static_cast<int>(rnd() % 6);
    static uint32_t code[16];
    for (int i = 0; i < n; i++) code[i] = gen();
    uint64_t init[31];
    for (int i = 0; i < 31; i++)
      init[i] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    uint16_t init_flags = static_cast<uint16_t>(rnd() & 0xC101);

    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;

    for (int i = 0; i < 31; i++) state_.cpu.x[i] = init[i];
    state_.cpu.flags = init_flags;
    state_.cpu.insn_addr = start;
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    uint64_t jit_x[31];
    for (int i = 0; i < 31; i++) jit_x[i] = state_.cpu.x[i];
    uint16_t jit_flags = state_.cpu.flags;

    for (int i = 0; i < 31; i++) state_.cpu.x[i] = init[i];
    state_.cpu.flags = init_flags;
    state_.cpu.insn_addr = start;
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 64)
      InterpretInsn(&state_);
    regions_run++;

    for (int i = 0; i < 31; i++) {
      if (jit_x[i] != state_.cpu.x[i]) {
        std::string dis;
        for (int j = 0; j < n; j++) {
          char b[16];
          snprintf(b, sizeof(b), " %08x", code[j]);
          dis += b;
        }
        ADD_FAILURE() << "iter " << iter << " diverged at x" << i << ": JIT=0x" << std::hex
                      << jit_x[i] << " INTERP=0x" << state_.cpu.x[i] << std::dec
                      << " region:" << dis;
        break;
      }
    }
  }
  EXPECT_GT(regions_run, 1000) << "fuzzer translated too few regions to be meaningful";
}

// Differential fuzzer for the remaining unfuzzed ops seen disassembling Helium's
// hot lite-JIT regions: GP byte-reverse / bit ops (REV/REV32/REV16/RBIT/CLZ/CLS,
// X and W) used in Chromium's hash-table hashing, and DUP-general (GP->vector
// broadcast, .2d/.4s/.8h/.16b). Multi-instruction over x0..x9 and v0..v9, JIT vs
// interpreter, diffs all GP and V registers.
TEST_F(Arm64LiteTranslateRegionTest, RevAndDupGeneralDifferentialFuzz) {
  uint64_t seed = 0xCAFEF00DD15EA5E5ULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  struct Op {
    uint32_t enc;
    uint32_t mask;  // rd/rn (0x3FF)
  };
  const Op ops[] = {
      {0xdac00c20, 0x3FF}, {0xdac00820, 0x3FF}, {0xdac00420, 0x3FF},  // rev/rev32/rev16 x
      {0xdac00020, 0x3FF}, {0xdac01020, 0x3FF}, {0xdac01420, 0x3FF},  // rbit/clz/cls x
      {0x5ac00820, 0x3FF}, {0x5ac00420, 0x3FF}, {0x5ac00020, 0x3FF},  // rev/rev16/rbit w
      {0x5ac01020, 0x3FF},                                            // clz w
      {0x4e080c20, 0x3FF}, {0x4e040c20, 0x3FF},                       // dup v.2d/v.4s, gp
      {0x4e020c20, 0x3FF}, {0x4e010c20, 0x3FF},                       // dup v.8h/v.16b, gp
  };
  const int kNum = sizeof(ops) / sizeof(ops[0]);
  const uint32_t kMaxReg = 10;
  auto gen = [&]() -> uint32_t {
    const Op& o = ops[rnd() % kNum];
    uint32_t e = o.enc & ~o.mask;
    e |= static_cast<uint32_t>(rnd() % kMaxReg) << 5;
    e |= static_cast<uint32_t>(rnd() % kMaxReg);
    return e;
  };

  int regions_run = 0;
  for (int iter = 0; iter < 9000; iter++) {
    const int n = 3 + static_cast<int>(rnd() % 6);
    static uint32_t code[16];
    for (int i = 0; i < n; i++) code[i] = gen();
    uint64_t initx[31];
    unsigned __int128 initv[10];
    for (int i = 0; i < 31; i++)
      initx[i] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    for (int i = 0; i < 10; i++) {
      uint64_t lo = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
      uint64_t hi = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
      memcpy(&initv[i], &lo, 8);
      memcpy(reinterpret_cast<uint8_t*>(&initv[i]) + 8, &hi, 8);
    }
    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;
    auto setup = [&]() {
      for (int i = 0; i < 31; i++) state_.cpu.x[i] = initx[i];
      for (int i = 0; i < 32; i++) state_.cpu.v[i] = 0;
      for (int i = 0; i < 10; i++) memcpy(&state_.cpu.v[i], &initv[i], 16);
      state_.cpu.flags = 0;
      state_.cpu.insn_addr = start;
    };
    setup();
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    uint64_t jit_x[31];
    unsigned __int128 jit_v[32];
    for (int i = 0; i < 31; i++) jit_x[i] = state_.cpu.x[i];
    for (int i = 0; i < 32; i++) memcpy(&jit_v[i], &state_.cpu.v[i], 16);
    setup();
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 64)
      InterpretInsn(&state_);
    regions_run++;
    bool d = false;
    std::string what;
    for (int i = 0; i < 31 && !d; i++)
      if (jit_x[i] != state_.cpu.x[i]) { d = true; what = "x" + std::to_string(i); }
    for (int i = 0; i < 32 && !d; i++) {
      unsigned __int128 iv;
      memcpy(&iv, &state_.cpu.v[i], 16);
      if (jit_v[i] != iv) { d = true; what = "v" + std::to_string(i); }
    }
    if (d) {
      std::string dis;
      for (int j = 0; j < n; j++) { char b[16]; snprintf(b, sizeof(b), " %08x", code[j]); dis += b; }
      ADD_FAILURE() << "iter " << iter << " diverged at " << what << " region:" << dis;
    }
  }
  EXPECT_GT(regions_run, 1000) << "fuzzer translated too few regions to be meaningful";
}

// Conditional-branch evaluation differential: for every condition code and every
// NZCV combination, and for CBZ/CBNZ/TBZ/TBNZ over a range of register values,
// run the single-branch region through the lite JIT and the interpreter and
// assert the resulting guest PC (taken vs not-taken) matches. A miscompiled
// condition makes a rasterizer loop iterate the wrong number of times and drifts
// its stride — the lite-JIT glyph shear (crisp interpret-only). Straight-line
// fuzzers never evaluate a branch, so this class was untested.
TEST_F(Arm64LiteTranslateRegionTest, ConditionalBranchEvalDifferential) {
  auto branch_pc = [&](uint32_t insn, uint16_t flags, uint64_t x0, bool jit) -> uint64_t {
    static uint32_t code[1];
    code[0] = insn;
    GuestAddr start = ToGuestAddr(&code[0]);
    for (int i = 0; i < 31; i++) state_.cpu.x[i] = 0;
    state_.cpu.x[0] = x0;
    state_.cpu.flags = flags;
    state_.cpu.insn_addr = start;
    if (jit) {
      MachineCode mc;
      auto [ok, stop] = TryLiteTranslateRegion(
          start, &mc, LiteTranslateParams{.end_pc = start + 4, .allow_dispatch = false});
      if (!ok) return ~0ULL;
      HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
      TestingRunGeneratedCode(&state_, AsHostCode(hc), state_.cpu.insn_addr);
    } else {
      InterpretInsn(&state_);
    }
    return state_.cpu.insn_addr - start;  // 8 = taken (+8), 4 = fall through
  };

  // B.<cond> #8 over all conditions x all NZCV.
  for (uint32_t cond = 0; cond < 14; cond++) {  // skip AL(14)/NV(15)
    uint32_t insn = 0x54000040u | cond;
    for (uint32_t f = 0; f < 16; f++) {
      uint16_t flags = static_cast<uint16_t>((((f >> 3) & 1) << 15) | (((f >> 2) & 1) << 14) |
                                             (((f >> 1) & 1) << 8) | ((f & 1) << 0));  // N Z C V
      uint64_t j = branch_pc(insn, flags, 0, true);
      if (j == ~0ULL) continue;
      uint64_t i = branch_pc(insn, flags, 0, false);
      EXPECT_EQ(j, i) << "b.cond cond=" << cond << " flags=0x" << std::hex << flags;
    }
  }
  // CBZ/CBNZ x0 and TBZ/TBNZ x0,#5 over representative register values.
  const uint64_t xs[] = {0, 1, 0x20, 0xFFFFFFFFULL, 0x100000000ULL, ~0ULL, 0x20ULL << 0};
  const uint32_t mems[] = {0xb4000040u, 0xb5000040u, 0x36280040u, 0x37280040u};  // cbz/cbnz/tbz#5/tbnz#5
  for (uint32_t insn : mems) {
    for (uint64_t x0 : xs) {
      uint64_t j = branch_pc(insn, 0, x0, true);
      if (j == ~0ULL) continue;
      uint64_t i = branch_pc(insn, 0, x0, false);
      EXPECT_EQ(j, i) << "test-branch insn=0x" << std::hex << insn << " x0=0x" << x0;
    }
  }
}

// Memory-backed GP load/store differential fuzzer with WRITEBACK. The Skia
// rasterizer advances row/source pointers with post/pre-indexed loads and stores
// (`ldrb w,[src],#1`, `str ...,[dst],#stride`); a wrong writeback or address
// computation drifts pointers and shears the rasterized mask — the lite-JIT glyph
// shear (crisp interpret-only, garbled JIT). The IntegerRegMapDifferentialFuzz
// covers ALU but not load/store; this covers post/pre-index, register offset
// (scaled + extended), pairs, and signed/sized variants. Base x10 points into a
// scratch buffer; offset reg x5 is small. JIT vs interpreter, diff all GP regs
// (incl. the written-back base) and the resulting memory.
TEST_F(Arm64LiteTranslateRegionTest, GpLoadStoreWritebackDifferentialFuzz) {
  uint64_t seed = 0x0A11CE5EED9001FFULL;
  auto rnd = [&]() -> uint64_t {
    seed = seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return seed >> 33;
  };
  struct Op {
    uint32_t enc;
    bool pair;
  };
  const Op ops[] = {
      {0xf8410401, false}, {0xf8410c01, false}, {0xf8010401, false}, {0xf8010c01, false},  // ldr/str x post/pre #16
      {0x38401401, false}, {0x38001401, false}, {0x78402401, false}, {0x78002401, false},  // ldrb/strb/ldrh/strh post
      {0xb8404401, false}, {0xb8004401, false},                                            // ldr/str w post #4
      {0xa8c10801, true},  {0xa8810801, true},  {0xa9c10801, true},                        // ldp/stp post / ldp pre
      {0xf8656801, false}, {0xf8657801, false}, {0xf8256801, false}, {0x38656801, false},  // ldr/str [x0,x5{,lsl#3}] / ldrb
      {0xf8654801, false}, {0xb8804401, false}, {0x38801401, false}, {0xb8803001, false},  // ldr [x0,w5,uxtw] / ldrsw / ldrsb / ldursw
      {0xf9400c01, false},                                                                 // ldr [x0,#24]
      // Acquire/release atomics (refcount/hash paths, seen in Helium's hot JIT):
      {0x88dffd41, false}, {0xc8dffd41, false}, {0x889ffd41, false}, {0xc89ffd41, false},  // ldar/stlr w/x
      {0x08dffd41, false}, {0x48dffd41, false}, {0x089ffd41, false},                       // ldarb/ldarh/stlrb
  };
  const int kNum = sizeof(ops) / sizeof(ops[0]);
  alignas(16) static uint8_t buf[4096];
  static uint8_t buf_init[4096];
  static uint8_t jit_buf[4096];

  auto pick_rt = [&]() -> uint32_t {  // a data reg, never x5(offset)/x10(base)/x31
    uint32_t r;
    do {
      r = rnd() % 31;
    } while (r == 5 || r == 10);
    return r;
  };

  int regions_run = 0;
  for (int iter = 0; iter < 9000; iter++) {
    for (size_t i = 0; i < sizeof(buf); i++) buf[i] = static_cast<uint8_t>(rnd());
    memcpy(buf_init, buf, sizeof(buf));
    uint64_t initx[31];
    for (int i = 0; i < 31; i++)
      initx[i] = ((rnd() & 0xffffffffULL) << 32) | (rnd() & 0xffffffffULL);
    const uint64_t base_addr = ToGuestAddr(&buf[1024]);
    initx[10] = base_addr;
    initx[5] = 8;  // register offset (<=64 when lsl#3); keeps accesses in bounds

    const int n = 1 + static_cast<int>(rnd() % 4);
    static uint32_t code[8];
    for (int i = 0; i < n; i++) {
      const Op& o = ops[rnd() % kNum];
      uint32_t rt = pick_rt();
      uint32_t e = o.enc & ~0x3FFu;          // clear Rt + Rn
      e |= (10u << 5) | rt;                  // Rn = x10, Rt
      if (o.pair) {
        uint32_t rt2;
        do {
          rt2 = pick_rt();
        } while (rt2 == rt);
        e = (e & ~0x7C00u) | (rt2 << 10);    // Rt2
      }
      code[i] = e;
    }
    GuestAddr start = ToGuestAddr(&code[0]);
    GuestAddr code_end = start + static_cast<GuestAddr>(n) * 4;

    auto setup = [&]() {
      for (int i = 0; i < 31; i++) state_.cpu.x[i] = initx[i];
      state_.cpu.flags = 0;
      state_.cpu.insn_addr = start;
    };

    // JIT.
    setup();
    MachineCode mc;
    auto [ok, stop] = TryLiteTranslateRegion(
        start, &mc, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = false});
    if (!ok || stop > code_end || stop == start) continue;
    HostCodeAddr hc = GetDefaultCodePoolInstance()->Add(&mc);
    TestingRunGeneratedCode(&state_, AsHostCode(hc), stop);
    uint64_t jit_x[31];
    for (int i = 0; i < 31; i++) jit_x[i] = state_.cpu.x[i];
    memcpy(jit_buf, buf, sizeof(buf));

    // Restore memory, interpret to the same stop PC.
    memcpy(buf, buf_init, sizeof(buf));
    setup();
    int guard = 0;
    while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < stop && guard++ < 16)
      InterpretInsn(&state_);
    regions_run++;

    bool diverged = false;
    std::string what;
    for (int i = 0; i < 31 && !diverged; i++) {
      if (jit_x[i] != state_.cpu.x[i]) {
        diverged = true;
        char b[48];
        snprintf(b, sizeof(b), "x%d jit=0x%llx int=0x%llx", i, (unsigned long long)jit_x[i],
                 (unsigned long long)state_.cpu.x[i]);
        what = b;
      }
    }
    if (!diverged && memcmp(jit_buf, buf, sizeof(buf)) != 0) {
      diverged = true;
      what = "memory";
    }
    if (diverged) {
      std::string dis;
      for (int j = 0; j < n; j++) {
        char b[16];
        snprintf(b, sizeof(b), " %08x", code[j]);
        dis += b;
      }
      ADD_FAILURE() << "iter " << iter << " diverged at " << what << " region:" << dis;
    }
  }
  EXPECT_GT(regions_run, 1000) << "fuzzer translated too few regions to be meaningful";
}

// Differential test of a real-world bump-allocator placement-new region: two CBZ
// guards followed by a ldr/add/stp/str/adr construction sequence that builds a
// vtable'd object in a freshly-allocated buffer and advances the arena descriptor.
// Runs the region through the lite JIT and the interpreter with identical memory
// and asserts the descriptor and constructed object match bit-for-bit — guarding
// the chained allocator-construction path against codegen divergence.
TEST_F(Arm64LiteTranslateRegionTest, AllocatorConstructionRegionDifferential) {
  static const uint32_t code[] = {
      0x34000054,  // cbz w20, +8        (fall through: x20!=0)
      0xb40004b5,  // cbz x21, +0x94     (fall through: x21!=0)
      0xf9400268,  // ldr x8, [x19]
      0x8b1402a9,  // add x9, x21, x20
      0xa900a675,  // stp x21, x9, [x19, #8]
      0xf90002a8,  // str x8, [x21]
      0xf9400668,  // ldr x8, [x19, #8]
      0x91002109,  // add x9, x8, #8
      0xf9000669,  // str x9, [x19, #8]
      0xd503201f,  // nop
      0x100c05c9,  // adr x9, +0x180b8
      0xf9000509,  // str x9, [x8, #8]
      0xf9400668,  // ldr x8, [x19, #8]
      0x91002109,  // add x9, x8, #8
      0xf9000669,  // str x9, [x19, #8]
      0x3900211f,  // strb wzr, [x8, #8]
      0xf9400668,  // ldr x8, [x19, #8]
      0x91000508,  // add x8, x8, #1
      0xa9002268,  // stp x8, x8, [x19]
  };
  // CRITICAL: use the SAME desc/buf addresses for both runs so absolute pointers
  // written into the descriptor are directly comparable.
  alignas(16) uint64_t desc[8];
  alignas(16) uint8_t buf[0x40];
  uint64_t jit_desc[8];
  uint8_t jit_buf[0x40];

  auto setup = [&]() {
    memset(desc, 0, sizeof(desc));
    memset(buf, 0xCD, sizeof(buf));
    desc[0] = 0xAAAA5555AAAA5555ULL;  // [x19] sentinel -> stored into [x21]
    for (int i = 0; i < 32; i++) state_.cpu.x[i] = 0;
    state_.cpu.x[19] = ToGuestAddr(desc);
    state_.cpu.x[20] = 0x200;
    state_.cpu.x[21] = ToGuestAddr(buf);
  };

  // JIT path, then snapshot the resulting memory.
  setup();
  ASSERT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  memcpy(jit_desc, desc, sizeof(desc));
  memcpy(jit_buf, buf, sizeof(buf));

  // Interpreter path: same memory addresses, step every instruction.
  setup();
  GuestAddr start = ToGuestAddr(code);
  GuestAddr end = start + sizeof(code);
  state_.cpu.insn_addr = start;
  int guard = 0;
  while (state_.cpu.insn_addr >= start && state_.cpu.insn_addr < end && guard++ < 64) {
    InterpretInsn(&state_);
  }

  // The descriptor (x19[0..2]) and the constructed object (buffer) must match bit-for-bit.
  EXPECT_EQ(jit_desc[0], desc[0]) << "descriptor[0] (cur) JIT vs interp";
  EXPECT_EQ(jit_desc[1], desc[1]) << "descriptor[1] (begin) JIT vs interp";
  EXPECT_EQ(jit_desc[2], desc[2]) << "descriptor[2] (end) JIT vs interp";
  EXPECT_EQ(0, memcmp(jit_buf, buf, sizeof(buf))) << "buffer bytes JIT vs interp";
}

// Helpers for the interpreter NEON regression tests below.
static void SetV(ThreadState* state, int i, uint64_t lo, uint64_t hi) {
  uint64_t parts[2] = {lo, hi};
  memcpy(&state->cpu.v[i], parts, 16);
}
static void GetV(ThreadState* state, int i, uint64_t* lo, uint64_t* hi) {
  uint64_t parts[2];
  memcpy(parts, &state->cpu.v[i], 16);
  *lo = parts[0];
  *hi = parts[1];
}

// EXT .8B (Q=0) in the interpreter: the concatenation is Vm:Vn with Vm at byte
// offset 8 (not 16). Previously result lanes [8,15] pulled Vn's stale upper half.
TEST_F(Arm64LiteTranslateRegionTest, ExtByte8bInterpreter) {
  const uint32_t insn = 0x2e021820;  // ext v0.8b, v1.8b, v2.8b, #3
  SetV(&state_, 0, 0, 0);
  SetV(&state_, 1, 0x8138268683868942ULL, 0x7741559918559252ULL);  // hi must be ignored
  SetV(&state_, 2, 0x3622262609912460ULL, 0x8051243884390451ULL);
  Interpret(insn);
  uint64_t lo, hi;
  GetV(&state_, 0, &lo, &hi);
  EXPECT_EQ(lo, 0x9124608138268683ULL) << "EXT .8b low half (bytes 5-7 must come from Vm)";
  EXPECT_EQ(hi, 0ULL) << "EXT .8b must zero bits[127:64]";
}

// SADALP .4h (Q=0) accumulate in the interpreter must zero bits[127:64] rather
// than leaving the prior destination's stale upper half.
TEST_F(Arm64LiteTranslateRegionTest, SadalpUpperHalfZeroInterpreter) {
  const uint32_t insn = 0x0e206820;  // sadalp v0.4h, v1.8b
  SetV(&state_, 0, 0x0010001000100010ULL, 0xAAAAAAAAAAAAAAAAULL);  // dst accumulator + stale hi
  SetV(&state_, 1, 0x0101010101010101ULL, 0);
  Interpret(insn);
  uint64_t lo, hi;
  GetV(&state_, 0, &lo, &hi);
  EXPECT_EQ(lo, 0x0012001200120012ULL) << "SADALP accumulate (each pair 1+1=2, +0x10)";
  EXPECT_EQ(hi, 0ULL) << "SADALP .4h Q=0 must zero bits[127:64]";
}

// SRSHL .4s in the interpreter: a negative per-lane shift count is a signed
// rounding arithmetic right shift, not a logical shift.
TEST_F(Arm64LiteTranslateRegionTest, SrshlSignedRoundingInterpreter) {
  const uint32_t insn = 0x4ea15400;  // srshl v0.4s, v0.4s, v1.4s
  // lanes: -16>>4(round)=-1 ; +16>>4=+1 ; INT_MIN>>2=0xE0000000 ; +1>>1=+1
  SetV(&state_, 0, 0x00000010FFFFFFF0ULL, 0x0000000180000000ULL);
  SetV(&state_, 1, 0x000000FC000000FCULL, 0x000000FF000000FEULL);  // shifts -4,-4,-2,-1
  Interpret(insn);
  uint64_t lo, hi;
  GetV(&state_, 0, &lo, &hi);
  EXPECT_EQ(lo, 0x00000001FFFFFFFFULL) << "SRSHL lanes 0,1: -1 and +1 (arithmetic+round)";
  EXPECT_EQ(hi, 0x00000001E0000000ULL) << "SRSHL lanes 2,3: 0xE0000000 and +1";
}

// LDTRSB/LDTRSH/LDTRSW (unprivileged signed loads) must decode (not Undefined or
// misroute) and sign-extend. Regression for the bit21 load/store dispatch split.
TEST_F(Arm64LiteTranslateRegionTest, LdtrSignedLoadsInterpreter) {
  alignas(8) uint8_t buf[16];
  memset(buf, 0, sizeof(buf));
  buf[1] = 0x80;                                          // for ldtrsb [x1,#1]
  *reinterpret_cast<uint16_t*>(&buf[2]) = 0x8000;         // for ldtrsh [x1,#2]
  *reinterpret_cast<uint32_t*>(&buf[4]) = 0x80000000U;    // for ldtrsw [x1,#4]
  state_.cpu.x[1] = ToGuestAddr(buf);
  Interpret(0x38c01820);  // ldtrsb w0, [x1, #1]
  EXPECT_EQ(state_.cpu.x[0], 0xFFFFFF80ULL) << "LDTRSB sign-extends byte to Wt";
  state_.cpu.x[1] = ToGuestAddr(buf);
  Interpret(0x78802820);  // ldtrsh x0, [x1, #2]
  EXPECT_EQ(state_.cpu.x[0], 0xFFFFFFFFFFFF8000ULL) << "LDTRSH sign-extends half to Xt";
  state_.cpu.x[1] = ToGuestAddr(buf);
  Interpret(0xb8804820);  // ldtrsw x0, [x1, #4]
  EXPECT_EQ(state_.cpu.x[0], 0xFFFFFFFF80000000ULL) << "LDTRSW sign-extends word to Xt";
}

TEST_F(Arm64LiteTranslateRegionTest, AddImmediate) {
  static const uint32_t code[] = {
      MovzX(0, 100),      // MOVZ X0, #100
      AddImmX(0, 0, 5),   // ADD X0, X0, #5
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[0], 105ULL);
}

TEST_F(Arm64LiteTranslateRegionTest, SubImmediate) {
  static const uint32_t code[] = {
      MovzX(0, 100),      // MOVZ X0, #100
      SubImmX(0, 0, 3),   // SUB X0, X0, #3
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[0], 97ULL);
}

TEST_F(Arm64LiteTranslateRegionTest, SubsSetsFlagsZero) {
  // SUBS X2, X0, X1 where X0==X1 should set Z flag.
  static const uint32_t code[] = {
      MovzX(0, 42),               // MOVZ X0, #42
      MovzX(1, 42),               // MOVZ X1, #42
      // SUBS X2, X0, X1 (shifted reg): sf=1, op=1, S=1, shift=00, imm6=0
      0xEB010002,                  // SUBS X2, X0, X1
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[2], 0ULL);
  // Flags: N=0, Z=1, C=1 (no borrow), V=0
  EXPECT_TRUE(state_.cpu.flags & CPUState::kFlagZero);
  EXPECT_TRUE(state_.cpu.flags & CPUState::kFlagCarry);
  EXPECT_FALSE(state_.cpu.flags & CPUState::kFlagNegative);
  EXPECT_FALSE(state_.cpu.flags & CPUState::kFlagOverflow);
}

TEST_F(Arm64LiteTranslateRegionTest, SubsSetsFlagsNegative) {
  // SUBS X2, X0, X1 where X0 < X1 should set N flag and clear C.
  static const uint32_t code[] = {
      MovzX(0, 5),                // MOVZ X0, #5
      MovzX(1, 10),               // MOVZ X1, #10
      0xEB010002,                  // SUBS X2, X0, X1
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  // 5 - 10 wraps around in unsigned
  EXPECT_EQ(state_.cpu.x[2], static_cast<uint64_t>(-5LL));
  // Flags: N=1, Z=0, C=0 (borrow occurred), V=0
  EXPECT_TRUE(state_.cpu.flags & CPUState::kFlagNegative);
  EXPECT_FALSE(state_.cpu.flags & CPUState::kFlagZero);
  EXPECT_FALSE(state_.cpu.flags & CPUState::kFlagCarry);
  EXPECT_FALSE(state_.cpu.flags & CPUState::kFlagOverflow);
}

TEST_F(Arm64LiteTranslateRegionTest, CmpBranchEqTaken) {
  // CMP X0, #5 with X0=5 → Z=1 → B.EQ taken.
  // JIT region: MOVZ, CMP, B.EQ. Branch exits the region.
  static const uint32_t code[] = {
      MovzX(0, 5),        // MOVZ X0, #5
      CmpImmX(0, 5),      // CMP X0, #5
      Bcond(kCondEQ, 8),  // B.EQ +8 (target = code+8+8 = code+16)
      kNop,               // padding (not translated)
      kNop,               // branch target (not translated)
  };
  // B.EQ is at code+8, target = code+16. JIT exits to code+16.
  GuestAddr branch_target = ToGuestAddr(code) + 16;
  EXPECT_TRUE(Run(code, branch_target));
  EXPECT_EQ(state_.cpu.x[0], 5ULL);
}

TEST_F(Arm64LiteTranslateRegionTest, CmpBranchEqNotTaken) {
  // CMP X0, #5 with X0=10 → Z=0 → B.EQ not taken → fall through.
  static const uint32_t code[] = {
      MovzX(0, 10),       // MOVZ X0, #10
      CmpImmX(0, 5),      // CMP X0, #5
      Bcond(kCondEQ, 8),  // B.EQ +8
  };
  // B.EQ not taken → exit to code+12 (past B.EQ).
  GuestAddr fall_through = ToGuestAddr(code) + sizeof(code);
  EXPECT_TRUE(Run(code, fall_through));
  EXPECT_EQ(state_.cpu.x[0], 10ULL);
}

TEST_F(Arm64LiteTranslateRegionTest, CmpBranchNeTaken) {
  // CMP X0, #5 with X0=10 → Z=0 → B.NE taken.
  static const uint32_t code[] = {
      MovzX(0, 10),       // MOVZ X0, #10
      CmpImmX(0, 5),      // CMP X0, #5
      Bcond(kCondNE, 8),  // B.NE +8 (target = code+16)
      kNop,
      kNop,
  };
  GuestAddr branch_target = ToGuestAddr(code) + 16;
  EXPECT_TRUE(Run(code, branch_target));
}

TEST_F(Arm64LiteTranslateRegionTest, CmpBranchLtTaken) {
  // CMP X0, #10 with X0=5 → N=1, V=0, N!=V → LT taken.
  static const uint32_t code[] = {
      MovzX(0, 5),         // MOVZ X0, #5
      CmpImmX(0, 10),      // CMP X0, #10
      Bcond(kCondLT, 8),   // B.LT +8
      kNop,
      kNop,
  };
  GuestAddr branch_target = ToGuestAddr(code) + 16;
  EXPECT_TRUE(Run(code, branch_target));
}

TEST_F(Arm64LiteTranslateRegionTest, CmpBranchGeTaken) {
  // CMP X0, #5 with X0=10 → N=0, V=0, N==V → GE taken.
  static const uint32_t code[] = {
      MovzX(0, 10),        // MOVZ X0, #10
      CmpImmX(0, 5),       // CMP X0, #5
      Bcond(kCondGE, 8),   // B.GE +8
      kNop,
      kNop,
  };
  GuestAddr branch_target = ToGuestAddr(code) + 16;
  EXPECT_TRUE(Run(code, branch_target));
}

// Exhaustive B.cond matrix: every ARM condition code, taken and not-taken,
// against four NZCV setups built by CMP X0,#imm. This pins the shared
// EmitJumpIfCondNotMet helper (which now tests cpu.flags in memory directly)
// across all conditions including the N==V and C-flag (sub-derived) cases.
TEST_F(Arm64LiteTranslateRegionTest, BranchAllConditions) {
  // Region: <setup...>, B.cond +8, NOP, NOP. Taken exits to B.cond_pc+8
  // (= setup_len+2 words in); not-taken falls through to end_pc.
  auto check = [&](std::initializer_list<uint32_t> setup, uint8_t cond,
                   bool expect_taken) {
    std::vector<uint32_t> code(setup);
    size_t bidx = code.size();
    code.push_back(Bcond(cond, 8));
    code.push_back(kNop);
    code.push_back(kNop);
    GuestAddr base = ToGuestAddr(code.data());
    GuestAddr expected = expect_taken ? base + (bidx + 2) * sizeof(uint32_t)
                                      : base + code.size() * sizeof(uint32_t);
    EXPECT_TRUE(RunN(code.data(), code.size(), expected))
        << "cond=" << static_cast<int>(cond) << " taken=" << expect_taken;
  };
  // Setups via CMP X0,#imm (SUBS XZR,X0,#imm) producing known NZCV:
  //   A: X0=5,  CMP #5  -> N0 Z1 C1 V0
  //   B: X0=10, CMP #5  -> N0 Z0 C1 V0
  //   C: X0=5,  CMP #10 -> N1 Z0 C0 V0
  //   D: X0=INT64_MIN, CMP #1 -> N0 Z0 C1 V1  (signed underflow sets V)
  const std::initializer_list<uint32_t> A = {MovzX(0, 5), CmpImmX(0, 5)};
  const std::initializer_list<uint32_t> B = {MovzX(0, 10), CmpImmX(0, 5)};
  const std::initializer_list<uint32_t> C = {MovzX(0, 5), CmpImmX(0, 10)};
  const std::initializer_list<uint32_t> D = {MovzHwX(0, 0x8000, 3),
                                             CmpImmX(0, 1)};
  check(A, kCondEQ, true);  check(B, kCondEQ, false);   // Z
  check(B, kCondNE, true);  check(A, kCondNE, false);
  check(A, kCondCS, true);  check(C, kCondCS, false);   // C
  check(C, kCondCC, true);  check(A, kCondCC, false);
  check(C, kCondMI, true);  check(A, kCondMI, false);   // N
  check(A, kCondPL, true);  check(C, kCondPL, false);
  check(D, kCondVS, true);  check(A, kCondVS, false);   // V
  check(A, kCondVC, true);  check(D, kCondVC, false);
  check(B, kCondHI, true);  check(A, kCondHI, false);   // C&Z
  check(A, kCondLS, true);  check(B, kCondLS, false);
  check(A, kCondGE, true);  check(C, kCondGE, false);   // N==V
  check(C, kCondLT, true);  check(A, kCondLT, false);
  check(B, kCondGT, true);  check(A, kCondGT, false);   // Z & N==V
  check(A, kCondLE, true);  check(B, kCondLE, false);
  check(A, kCondAL, true);                              // always
}

// Integer CCMP through the refactored ConditionalCompare condition eval.
TEST_F(Arm64LiteTranslateRegionTest, CcmpConditionPaths) {
  // cond TRUE: CCMP does CMP X0,X1 and sets NZCV. X0==X1 -> Z=1.
  // Setup CMP X0,#5 (X0=5) -> Z=1 so the EQ condition is met.
  static const uint32_t taken[] = {
      MovzX(0, 5),                       // X0=5
      MovzX(1, 5),                       // X1=5
      CmpImmX(0, 5),                     // flags: Z=1 (EQ true)
      CcmpRegX(0, 1, /*nzcv=*/0x0, kCondEQ),  // EQ met -> CMP X0,X1 -> Z=1
  };
  EXPECT_TRUE(Run(taken, ToGuestAddr(taken) + sizeof(taken)));
  EXPECT_TRUE(state_.cpu.flags & CPUState::kFlagZero);

  // cond FALSE: CCMP writes the nzcv immediate. Use NE with Z=1 (NE false);
  // nzcv=0x0 -> all flags cleared, in particular Z=0.
  static const uint32_t imm[] = {
      MovzX(0, 5),                       // X0=5
      MovzX(1, 9),                       // X1=9
      CmpImmX(0, 5),                     // flags: Z=1 (NE false)
      CcmpRegX(0, 1, /*nzcv=*/0x0, kCondNE),  // NE not met -> flags = 0
  };
  EXPECT_TRUE(Run(imm, ToGuestAddr(imm) + sizeof(imm)));
  EXPECT_FALSE(state_.cpu.flags & CPUState::kFlagZero);
}

