// Exhaustive CSEL matrix: every ARM condition code, met and not-met, exercising
// the branchless CMOVcc path (EmitCondToBoolReg) for all 16 codes incl. the
// compound (HI/LS/GE/LT/GT/LE) and V-overflow cases. src1=100 (met), src2=200.
TEST_F(Arm64LiteTranslateRegionTest, CselAllConditions) {
  auto check = [&](std::initializer_list<uint32_t> setup, uint8_t cond,
                   bool expect_met) {
    std::vector<uint32_t> code(setup);
    code.push_back(MovzX(1, 100));            // src1 (true case)
    code.push_back(MovzX(2, 200));            // src2 (false case)
    code.push_back(CselX(3, 1, 2, cond));     // X3 = cond ? X1 : X2
    GuestAddr end = ToGuestAddr(code.data()) + code.size() * sizeof(uint32_t);
    EXPECT_TRUE(RunN(code.data(), code.size(), end))
        << "cond=" << static_cast<int>(cond) << " met=" << expect_met;
    EXPECT_EQ(state_.cpu.x[3], expect_met ? 100ULL : 200ULL)
        << "cond=" << static_cast<int>(cond) << " met=" << expect_met;
  };
  // Same NZCV setups as BranchAllConditions:
  //   A: CMP 5,5   -> N0 Z1 C1 V0     B: CMP 10,5  -> N0 Z0 C1 V0
  //   C: CMP 5,10  -> N1 Z0 C0 V0     D: INT64_MIN CMP 1 -> N0 Z0 C1 V1
  const std::initializer_list<uint32_t> A = {MovzX(0, 5), CmpImmX(0, 5)};
  const std::initializer_list<uint32_t> B = {MovzX(0, 10), CmpImmX(0, 5)};
  const std::initializer_list<uint32_t> C = {MovzX(0, 5), CmpImmX(0, 10)};
  const std::initializer_list<uint32_t> D = {MovzHwX(0, 0x8000, 3),
                                             CmpImmX(0, 1)};
  check(A, kCondEQ, true);  check(B, kCondEQ, false);
  check(B, kCondNE, true);  check(A, kCondNE, false);
  check(A, kCondCS, true);  check(C, kCondCS, false);
  check(C, kCondCC, true);  check(A, kCondCC, false);
  check(C, kCondMI, true);  check(A, kCondMI, false);
  check(A, kCondPL, true);  check(C, kCondPL, false);
  check(D, kCondVS, true);  check(A, kCondVS, false);
  check(A, kCondVC, true);  check(D, kCondVC, false);
  check(B, kCondHI, true);  check(A, kCondHI, false);
  check(A, kCondLS, true);  check(B, kCondLS, false);
  check(A, kCondGE, true);  check(C, kCondGE, false);
  check(C, kCondLT, true);  check(A, kCondLT, false);
  check(B, kCondGT, true);  check(A, kCondGT, false);
  check(A, kCondLE, true);  check(B, kCondLE, false);
}

// Region replayed verbatim from libmaplibre's
// mbgl::android::FileSource::getAPIBaseUrl: a back-to-back CMP/CSEL pair with a
// non-flag-setting ADD and SUB sandwiched between each CMP and its CSEL. ARM
// ADD/SUB without the S suffix do NOT touch NZCV, so each CSEL must read the
// flags from its preceding CMP. Inputs: x0 = variant type index (2 here, the
// "is a string" case), x8 = a pointer the value payload is derived from.
//   cmp  w0, #2          ; Z = (x0 == 2)
//   add  x1, x8, #8      ; x1 = payload ptr  (no flags)
//   sub  w8, w0, #3      ; w8 = x0 - 3       (no flags)
//   csel x9, x1, xzr, eq ; x9  = (x0==2) ? x1 : 0
//   cmp  w8, #2          ; C = (w8 >=u 2)
//   csel x22, xzr, x9, lo; x22 = (w8 <u 2) ? 0 : x9
// With x0=2, x8=0x1000: x1=0x1008, x9=0x1008, w8=0xFFFFFFFF (>=u 2 so lo false),
// x22=x9=0x1008. A miscompile here hands getAPIBaseUrl a bogus std::string
// pointer and the from_bytes conversion throws.
TEST_F(Arm64LiteTranslateRegionTest, MaplibreGetApiBaseUrlCselChain) {
  static const uint32_t code[] = {
      0x7100081f,  // cmp  w0, #0x2
      0x91002101,  // add  x1, x8, #0x8
      0x51000c08,  // sub  w8, w0, #0x3
      0x9a9f0029,  // csel x9, x1, xzr, eq
      0x7100091f,  // cmp  w8, #0x2
      0x9a8933f6,  // csel x22, xzr, x9, lo
  };
  state_.cpu.x[0] = 2;
  state_.cpu.x[8] = 0x1000;
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[1], 0x1008ULL);
  EXPECT_EQ(state_.cpu.x[9], 0x1008ULL);
  EXPECT_EQ(state_.cpu.x[22], 0x1008ULL);
}

// Region replayed verbatim from libmaplibre's getAPIBaseUrl: the libc++ SSO
// (small-string) destructor guard for the temporary key string at [sp]:
//   ldrb w8, [sp]            ; w8 = first byte of the std::string control word
//   tbz  w8, #0, skip        ; bit0 == 0 means a SHORT string (no heap buffer)
//   ldr  x0, [sp, #0x10]     ; only reached for a LONG string: load heap ptr
//   bl   operator delete     ; ... and free it
// libc++ stores (size << 1) in the first byte of a short string, so bit0 is
// the "is-long/heap" flag. For the key built here the byte is 0x18 (= 12 << 1,
// bit0 == 0, SHORT), so the tbz MUST be taken and the operator-delete skipped.
// If lite mis-evaluates the test-bit branch and falls through, it frees a
// non-heap SSO pointer, corrupting the heap and making the later baseURL
// from_bytes conversion read garbage. The load base is SP (Rn==31), so this
// also exercises GetRegOrSp on the load path.
TEST_F(Arm64LiteTranslateRegionTest, MaplibreSsoDtorTbzShortString) {
  alignas(16) static uint8_t stack_buf[64] = {};
  stack_buf[0] = 0x18;  // libc++ short-string marker: size 12, bit0 == 0
  static const uint32_t code[] = {
      0x394003e8,  // ldrb w8, [sp]
      0x36000048,  // tbz  w8, #0, +8  (skip the delete for a short string)
      kNop,
      kNop,
  };
  state_.cpu.sp = ToGuestAddr(stack_buf);
  GuestAddr taken_target = ToGuestAddr(code) + 4 + 8;  // tbz pc + 8
  EXPECT_TRUE(Run(code, taken_target));
  EXPECT_EQ(state_.cpu.x[8], 0x18ULL);
}

TEST_F(Arm64LiteTranslateRegionTest, MaplibreSsoDtorTbzLongString) {
  // Mirror of the above with a LONG-string marker (bit0 == 1): the tbz must NOT
  // be taken and execution must fall through past it.
  alignas(16) static uint8_t stack_buf[64] = {};
  stack_buf[0] = 0x19;  // bit0 == 1 -> long/heap string
  static const uint32_t code[] = {
      0x394003e8,  // ldrb w8, [sp]
      0x36000048,  // tbz  w8, #0, +8
      kNop,
      kNop,
  };
  state_.cpu.sp = ToGuestAddr(stack_buf);
  GuestAddr fall_through = ToGuestAddr(code) + sizeof(code);
  EXPECT_TRUE(Run(code, fall_through));
  EXPECT_EQ(state_.cpu.x[8], 0x19ULL);
}

// Full guest-state JIT-vs-interpreter differential for libmaplibre's getAPIBaseUrl
// SSO destructor-guard region, replayed VERBATIM (including the real ldr/bl that
// the simplified Tbz tests above replaced with nops). On-device bisection showed
// that JIT-compiling exactly this 4-insn region (with everything else, including
// the downstream from_bytes, INTERPRETED) deterministically reproduces the
// "wstring_convert: from_bytes error" crash. Since the downstream code runs in
// the interpreter in that config, whatever this region corrupts must be
// guest-visible state (a ThreadState register or guest memory). This test runs
// the region through the lite JIT and the interpreter from an identical initial
// state (using the real register values captured on-device) and diffs EVERY
// field plus the stack, to surface the divergence the single-register tests miss.
TEST_F(Arm64LiteTranslateRegionTest, MaplibreSsoDtorRegionFullStateDiff) {
  static const uint32_t code[] = {
      0x394003e8,  // ldrb w8, [sp]
      0x36000068,  // tbz  w8, #0, +0xc   (short string -> skip ldr+bl)
      0xf9400be0,  // ldr  x0, [sp, #0x10]
      0x94184ba2,  // bl   <operator delete>  (not executed for short string)
  };
  // Real GP register values captured on-device at this region (FAIL run); pointer
  // values are opaque here (the region only dereferences sp), so they exercise the
  // codegen with realistic, value-dependent operands.
  static const uint64_t kInit[31] = {
      0x7eb8e083cfc0, 0x7eb7918eee00, 0x000000000000001f, 0x7eb99081f960,
      0x7eb8e083cc4f, 0x7eb8e083cfdf, 0x000000000010ffff, 0x0000000000000000,
      0x0000000000000018, 0x0000000000000000, 0x0000000000000000, 0x0000000000000000,
      0x0000000000000005, 0x7eb790bffe92, 0x0000000000000000, 0x0000000000000000,
      0x7eb6fd013cc0, 0x7eb7918eadd8, 0x7eb78f400000, 0x7eb91083d310,
      0x7eb790bfff68, 0x7ebaebb4b040, 0x7eb790bfff10, 0x0000000000000000,
      0x0000000000000000, 0x0000000000000000, 0x0000000000000000, 0x0000000000000000,
      0x0000000000000000, 0x7eb790bfff30, 0x7eb6fc9aec9c,
  };
  constexpr size_t kStkSize = 512;
  alignas(16) static uint8_t stk[kStkSize];

  auto setup = [&]() {
    memset(&state_.cpu, 0, sizeof(CPUState));
    for (int i = 0; i < 31; i++) state_.cpu.x[i] = kInit[i];
    memset(stk, 0xCD, sizeof(stk));
    uint64_t sp = ToGuestAddr(stk) + 256;
    *reinterpret_cast<uint8_t*>(sp) = 0x18;          // short-string marker
    *reinterpret_cast<uint64_t*>(sp + 0x10) = 0xCAFEF00DDEADBEEFULL;
    state_.cpu.sp = sp;
  };

  GuestAddr expected = ToGuestAddr(code) + sizeof(code);  // tbz target == region end

  // --- JIT run ---
  setup();
  ASSERT_TRUE(Run(code, expected));
  CPUState jit;
  memcpy(&jit, &state_.cpu, sizeof(CPUState));
  static uint8_t jit_stk[kStkSize];
  memcpy(jit_stk, stk, kStkSize);

  // --- Interpreter run (same initial state) ---
  setup();
  state_.cpu.insn_addr = ToGuestAddr(code);
  InterpretInsn(&state_);  // ldrb w8,[sp]  -> insn_addr = code+4
  InterpretInsn(&state_);  // tbz (taken)   -> insn_addr = code+16
  CPUState itp;
  memcpy(&itp, &state_.cpu, sizeof(CPUState));
  static uint8_t itp_stk[kStkSize];
  memcpy(itp_stk, stk, kStkSize);

  // --- Diff every guest-visible field ---
  EXPECT_EQ(jit.insn_addr, itp.insn_addr) << "insn_addr diverged";
  for (int i = 0; i < 31; i++) {
    EXPECT_EQ(jit.x[i], itp.x[i])
        << "x" << i << " diverged: JIT=0x" << std::hex << jit.x[i]
        << " INTERP=0x" << itp.x[i];
  }
  EXPECT_EQ(jit.sp, itp.sp) << "sp diverged";
  EXPECT_EQ(jit.flags, itp.flags) << "flags diverged";
  EXPECT_EQ(jit.cached_fpcr, itp.cached_fpcr) << "cached_fpcr diverged";
  EXPECT_EQ(jit.emulated_fpsr, itp.emulated_fpsr) << "emulated_fpsr diverged";
  EXPECT_EQ(jit.reservation_address, itp.reservation_address)
      << "reservation_address diverged";
  for (int i = 0; i < 32; i++) {
    EXPECT_EQ(memcmp(&jit.v[i], &itp.v[i], sizeof(jit.v[i])), 0)
        << "v" << i << " diverged";
  }
  EXPECT_EQ(memcmp(jit_stk, itp_stk, kStkSize), 0) << "stack memory diverged";
}

// STLR Wt, [Xn]: size=10, o2=1, L=0, o1=0, Rs=11111, o0=1, Rt2=11111
// Encoding: 10 001000 1 0 0 11111 1 11111 Rn Rt
constexpr uint32_t StlrW(uint8_t rt, uint8_t rn) {
  return 0x889FFC00 | (static_cast<uint32_t>(rn) << 5) | rt;
}

// LDR Wt, [Xn] (unsigned offset 0): size=10, V=0, opc=01
// Encoding: 1011 1001 01 imm12=0 Rn Rt
constexpr uint32_t LdrWUnsigned(uint8_t rt, uint8_t rn) {
  return 0xB9400000 | (static_cast<uint32_t>(rn) << 5) | rt;
}

TEST_F(Arm64LiteTranslateRegionTest, StlrWritesToMemory) {
  // STLR W1, [X0] should write the value in W1 to the address in X0.
  // Then LDR W2, [X0] should read it back.
  static uint32_t target_mem = 0;
  static const uint32_t code[] = {
      MovzX(1, 42),                // MOVZ X1, #42 (value to store)
      StlrW(1, 0),                 // STLR W1, [X0] (store-release)
      LdrWUnsigned(2, 0),          // LDR W2, [X0] (load it back)
  };
  target_mem = 0;
  state_.cpu.x[0] = ToGuestAddr(&target_mem);
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(target_mem, 42u);
  EXPECT_EQ(state_.cpu.x[2], 42ULL);
}

// LDAR/STLR all-size JIT coverage.
// Common constant fields for all LDAR/STLR encodings:
//   size 001000 1 L 0 11111 1 11111 Rn Rt
// where bit22 = L (load=1, store=0) and bits[31:30] = size:
//   00 = B, 01 = H, 10 = W (already covered above), 11 = X.
// STLR base (L=0): 0x089FFC00 with size in bits[31:30].
// LDAR base (L=1, bit22=1): 0x08DFFC00 with size in bits[31:30].
constexpr uint32_t LdarB(uint8_t rt, uint8_t rn) {
  return 0x08DFFC00 | (static_cast<uint32_t>(rn) << 5) | rt;
}
constexpr uint32_t LdarH(uint8_t rt, uint8_t rn) {
  return 0x48DFFC00 | (static_cast<uint32_t>(rn) << 5) | rt;
}
constexpr uint32_t LdarW(uint8_t rt, uint8_t rn) {
  return 0x88DFFC00 | (static_cast<uint32_t>(rn) << 5) | rt;
}
constexpr uint32_t LdarX(uint8_t rt, uint8_t rn) {
  return 0xC8DFFC00 | (static_cast<uint32_t>(rn) << 5) | rt;
}
constexpr uint32_t StlrB(uint8_t rt, uint8_t rn) {
  return 0x089FFC00 | (static_cast<uint32_t>(rn) << 5) | rt;
}
constexpr uint32_t StlrH(uint8_t rt, uint8_t rn) {
  return 0x489FFC00 | (static_cast<uint32_t>(rn) << 5) | rt;
}
constexpr uint32_t StlrX(uint8_t rt, uint8_t rn) {
  return 0xC89FFC00 | (static_cast<uint32_t>(rn) << 5) | rt;
}

TEST_F(Arm64LiteTranslateRegionTest, LdarBZeroExtends) {
  // LDARB W1, [X0]: load one byte and zero-extend into X1.
  // Source has a high-bit-set value (0xA5) to verify zero-extension over
  // any stale high bits in the destination GPR.
  static const uint8_t src = 0xA5;
  static const uint32_t code[] = {
      MovzX(1, 0xFFFF),            // pre-pollute X1 (must be overwritten)
      LdarB(1, 0),                 // LDARB W1, [X0]
  };
  state_.cpu.x[0] = ToGuestAddr(&src);
  state_.cpu.x[1] = 0xDEADBEEFCAFEBABEULL;
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[1], 0xA5ULL);
}

TEST_F(Arm64LiteTranslateRegionTest, LdarHZeroExtends) {
  // LDARH W1, [X0]: load 16 bits and zero-extend into X1.
  static const uint16_t src = 0xA55A;
  static const uint32_t code[] = {
      LdarH(1, 0),                 // LDARH W1, [X0]
  };
  state_.cpu.x[0] = ToGuestAddr(&src);
  state_.cpu.x[1] = 0xDEADBEEFCAFEBABEULL;
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[1], 0xA55AULL);
}

TEST_F(Arm64LiteTranslateRegionTest, LdarWZeroExtends) {
  // LDAR W1, [X0]: load 32 bits and zero-extend into X1.
  static const uint32_t src = 0xDEADBEEF;
  static const uint32_t code[] = {
      LdarW(1, 0),                 // LDAR W1, [X0]
  };
  state_.cpu.x[0] = ToGuestAddr(&src);
  state_.cpu.x[1] = 0xCAFEBABECAFEBABEULL;
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[1], 0xDEADBEEFULL);
}

TEST_F(Arm64LiteTranslateRegionTest, LdarXLoads64Bit) {
  // LDAR X1, [X0]: load full 64 bits into X1.
  static const uint64_t src = 0xCAFEBABEDEADBEEFULL;
  static const uint32_t code[] = {
      LdarX(1, 0),                 // LDAR X1, [X0]
  };
  state_.cpu.x[0] = ToGuestAddr(&src);
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[1], 0xCAFEBABEDEADBEEFULL);
}

TEST_F(Arm64LiteTranslateRegionTest, StlrBWritesByteOnly) {
  // STLRB W1, [X0]: store low 8 bits to [X0]; surrounding bytes untouched.
  static uint8_t buffer[4] = {0xAA, 0xAA, 0xAA, 0xAA};
  static const uint32_t code[] = {
      MovzX(1, 0x5A),              // MOVZ X1, #0x5A (low byte of value)
      StlrB(1, 0),                 // STLRB W1, [X0]
  };
  buffer[0] = 0xAA; buffer[1] = 0xAA; buffer[2] = 0xAA; buffer[3] = 0xAA;
  state_.cpu.x[0] = ToGuestAddr(&buffer[1]);
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(buffer[0], 0xAA);
  EXPECT_EQ(buffer[1], 0x5A);
  EXPECT_EQ(buffer[2], 0xAA);
  EXPECT_EQ(buffer[3], 0xAA);
}

TEST_F(Arm64LiteTranslateRegionTest, StlrBIgnoresHighBits) {
  // STLRB W1, [X0]: only the low 8 bits of W1 are stored. Verify that
  // upper bits of the source register are ignored.
  static uint8_t buffer[2] = {0x00, 0x00};
  static const uint32_t code[] = {
      MovzX(1, 0xFF5A),            // MOVZ X1, #0xFF5A
      StlrB(1, 0),                 // STLRB W1, [X0] (writes 0x5A only)
  };
  buffer[0] = 0x00; buffer[1] = 0xCC;
  state_.cpu.x[0] = ToGuestAddr(&buffer[0]);
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(buffer[0], 0x5A);
  EXPECT_EQ(buffer[1], 0xCC);
}

TEST_F(Arm64LiteTranslateRegionTest, StlrHWritesHalfwordOnly) {
  // STLRH W1, [X0]: store low 16 bits to [X0]; surrounding bytes untouched.
  static uint16_t buffer[2] = {0xAAAA, 0xAAAA};
  static const uint32_t code[] = {
      MovzX(1, 0x5AA5),            // MOVZ X1, #0x5AA5
      StlrH(1, 0),                 // STLRH W1, [X0]
  };
  buffer[0] = 0xAAAA; buffer[1] = 0xAAAA;
  state_.cpu.x[0] = ToGuestAddr(&buffer[0]);
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(buffer[0], 0x5AA5);
  EXPECT_EQ(buffer[1], 0xAAAA);
}

TEST_F(Arm64LiteTranslateRegionTest, StlrXWrites64Bit) {
  // STLR X1, [X0]: store all 64 bits to [X0].
  static uint64_t target_mem = 0;
  static const uint32_t code[] = {
      // X1 = 0x000000000000DEAD (only one MOVZ fits an imm16; the goal is
      // just to put a recognizable non-zero into X1 and verify the full
      // 64-bit store path).
      MovzX(1, 0xDEAD),
      StlrX(1, 0),                 // STLR X1, [X0]
  };
  target_mem = 0xCAFEBABECAFEBABEULL;
  state_.cpu.x[0] = ToGuestAddr(&target_mem);
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(target_mem, 0xDEADULL);
}

TEST_F(Arm64LiteTranslateRegionTest, LdarBStlrBRoundtrip) {
  // STLRB then LDARB roundtrip: store a byte, load it back, verify both
  // halves of the JIT path agree on byte width and zero-extension.
  static uint8_t target_mem = 0;
  static const uint32_t code[] = {
      MovzX(1, 0x7E),              // MOVZ X1, #0x7E (source byte)
      StlrB(1, 0),                 // STLRB W1, [X0]
      LdarB(2, 0),                 // LDARB W2, [X0]
  };
  target_mem = 0;
  state_.cpu.x[0] = ToGuestAddr(&target_mem);
  state_.cpu.x[2] = 0xFFFFFFFFFFFFFFFFULL;
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(target_mem, 0x7E);
  EXPECT_EQ(state_.cpu.x[2], 0x7EULL);
}

// DUP V0.16B, Wn: broadcast byte from GP register to all 16 lanes of V0.
// Encoding: 0 Q=1 0 01110 000 imm5=00001 0 imm4=0001 1 Rn Rd
// = 0100 1110 0000 0001 0000 0111 00 Rn Rd
constexpr uint32_t DupV16B(uint8_t rd, uint8_t rn) {
  return 0x4E010C00 | (static_cast<uint32_t>(rn) << 5) | rd;
}

// STP Q<rt1>, Q<rt2>, [Xn], #32 (post-index, 128-bit pair store)
// opc=10, V=1, type=001(post-index), L=0(store), imm7=2(32/16), Rt2, Rn, Rt
// Encoding: 10 101 1 001 0 0000010 Rt2 Rn Rt
constexpr uint32_t StpQPostIndex(uint8_t rt1, uint8_t rt2, uint8_t rn, int8_t imm_div16) {
  uint32_t imm7 = static_cast<uint32_t>(imm_div16) & 0x7F;
  return 0xAC800000 | (imm7 << 15) | (static_cast<uint32_t>(rt2) << 10) |
         (static_cast<uint32_t>(rn) << 5) | rt1;
}

TEST_F(Arm64LiteTranslateRegionTest, MemsetPattern) {
  // Test the ARM64 memset pattern: DUP V0.16B, W0 + STP Q0, Q0, [X1], #32
  // This writes 32 bytes of the byte value in W0 to the address in X1.
  alignas(16) static uint8_t buffer[64];
  memset(buffer, 0xCC, sizeof(buffer));

  static const uint32_t code[] = {
      DupV16B(0, 0),                 // DUP V0.16B, W0 (broadcast byte)
      StpQPostIndex(0, 0, 1, 2),     // STP Q0, Q0, [X1], #32
  };
  state_.cpu.x[0] = 0xAB;            // byte value to fill
  state_.cpu.x[1] = ToGuestAddr(buffer);
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));

  // First 32 bytes should be 0xAB
  for (int i = 0; i < 32; i++) {
    EXPECT_EQ(buffer[i], 0xAB) << "byte " << i;
  }
  // Remaining bytes should be untouched
  for (int i = 32; i < 64; i++) {
    EXPECT_EQ(buffer[i], 0xCC) << "byte " << i;
  }
  // X1 should be advanced by 32
  EXPECT_EQ(state_.cpu.x[1], ToGuestAddr(buffer) + 32);
}

TEST_F(Arm64LiteTranslateRegionTest, ForwardBranchExtension) {
  // Forward B.EQ should NOT end the region — code after it should also translate.
  // X0=10, CMP X0,#5 → Z=0 → B.EQ not taken → fall through to ADD.
  static const uint32_t code[] = {
      MovzX(0, 10),         // MOVZ X0, #10
      CmpImmX(0, 5),        // CMP X0, #5 → Z=0
      Bcond(kCondEQ, 8),    // B.EQ +8 (forward, not taken)
      AddImmX(0, 0, 1),     // ADD X0, X0, #1 → X0=11 (should be in same region)
      AddImmX(0, 0, 2),     // ADD X0, X0, #2 → X0=13 (branch target, also translated)
  };
  // With forward branch extension, the entire block should be one region.
  // Without it, the region would end at B.EQ and X0 would be 10 (ADD not reached).
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[0], 13ULL);
}

TEST_F(Arm64LiteTranslateRegionTest, ForwardBranchTaken) {
  // Forward B.EQ taken: X0=5, CMP X0,#5 → Z=1 → B.EQ taken → skips ADD X0,#1.
  static const uint32_t code[] = {
      MovzX(0, 5),          // MOVZ X0, #5
      CmpImmX(0, 5),        // CMP X0, #5 → Z=1
      Bcond(kCondEQ, 8),    // B.EQ +8 (forward, taken → skips next insn)
      AddImmX(0, 0, 1),     // ADD X0, X0, #1 (skipped)
      AddImmX(0, 0, 2),     // ADD X0, X0, #2 → X0=7 (branch target)
  };
  // B.EQ is taken, so it exits the region to code+16 (the second ADD).
  // The dispatch will handle code+16 as a new region.
  GuestAddr branch_target = ToGuestAddr(code) + 16;
  EXPECT_TRUE(Run(code, branch_target));
  EXPECT_EQ(state_.cpu.x[0], 5ULL);  // Branch exits before any ADD executes
}
// --- Memset instruction variant tests ---

// STUR Q<rt>, [Xn, #imm9]: Store 128-bit SIMD with unscaled immediate.
// Encoding: 00 111 1 00 10 imm9 00 Rn Rt
constexpr uint32_t SturQ(uint8_t rt, uint8_t rn, int16_t imm9) {
  uint32_t uimm9 = static_cast<uint32_t>(imm9) & 0x1FF;
  return 0x3C800000 | (uimm9 << 12) | (static_cast<uint32_t>(rn) << 5) | rt;
}

// STR Q<rt>, [Xn, Xm]: Store 128-bit SIMD with register offset (no shift).
// Encoding: 00 111 1 00 10 1 Rm 011 0 00 Rn Rt
constexpr uint32_t StrQReg(uint8_t rt, uint8_t rn, uint8_t rm) {
  return 0x3CA06800 | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rt;
}

// STR Q<rt>, [Xn, #uimm12]: Store 128-bit SIMD with unsigned immediate (scaled by 16).
constexpr uint32_t StrQUnsigned(uint8_t rt, uint8_t rn, uint16_t imm12_div16) {
  return 0x3D800000 | (static_cast<uint32_t>(imm12_div16) << 10) |
         (static_cast<uint32_t>(rn) << 5) | rt;
}

// STUR S<rt>, [Xn, #imm9]: Store 32-bit SIMD with unscaled immediate.
// Encoding: 10 111 1 00 00 imm9 00 Rn Rt
constexpr uint32_t SturS(uint8_t rt, uint8_t rn, int16_t imm9) {
  uint32_t uimm9 = static_cast<uint32_t>(imm9) & 0x1FF;
  return 0xBC000000 | (uimm9 << 12) | (static_cast<uint32_t>(rn) << 5) | rt;
}

// STR S<rt>, [Xn, Xm, LSL #2]: Store 32-bit SIMD with register offset and shift.
// Encoding: 10 111 1 00 00 1 Rm 011 S 10 Rn Rt
// S=1 means shift by 2 (log2 of 4 bytes).
constexpr uint32_t StrSRegLsl2(uint8_t rt, uint8_t rn, uint8_t rm) {
  return 0xBC207800 | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rt;
}

// STR S<rt>, [Xn, #uimm]: Store 32-bit SIMD unsigned offset.
constexpr uint32_t StrSUnsigned(uint8_t rt, uint8_t rn, uint16_t imm12_div4) {
  return 0xBD000000 | (static_cast<uint32_t>(imm12_div4) << 10) |
         (static_cast<uint32_t>(rn) << 5) | rt;
}

// STP Q<rt1>, Q<rt2>, [Xn, #imm]: Store pair 128-bit, signed offset.
// opc=10, V=1, type=10(signed-offset), L=0, imm7, Rt2, Rn, Rt1
constexpr uint32_t StpQSigned(uint8_t rt1, uint8_t rt2, uint8_t rn, int8_t imm_div16) {
  uint32_t imm7 = static_cast<uint32_t>(imm_div16) & 0x7F;
  return 0xAD000000 | (imm7 << 15) | (static_cast<uint32_t>(rt2) << 10) |
         (static_cast<uint32_t>(rn) << 5) | rt1;
}

// AND Xd, Xn, Xm, LSR #amount (logical shifted register)
constexpr uint32_t AndRegLsr(uint8_t rd, uint8_t rn, uint8_t rm, uint8_t shift) {
  return 0x8A400000 | (static_cast<uint32_t>(shift) << 10) |
         (static_cast<uint32_t>(rm) << 16) | (static_cast<uint32_t>(rn) << 5) | rd;
}

// SUB Xd, Xn, Xm, LSL #amount (shifted register)
constexpr uint32_t SubRegLsl(uint8_t rd, uint8_t rn, uint8_t rm, uint8_t shift) {
  return 0xCB000000 | (static_cast<uint32_t>(shift) << 10) |
         (static_cast<uint32_t>(rm) << 16) | (static_cast<uint32_t>(rn) << 5) | rd;
}

TEST_F(Arm64LiteTranslateRegionTest, SturQ_NegativeOffset) {
  // STUR Q0, [X1, #-16]: store 16 bytes of V0 at address X1-16.
  alignas(16) static uint8_t buffer[64];
  memset(buffer, 0xCC, sizeof(buffer));

  static const uint32_t code[] = {
      DupV16B(0, 0),           // DUP V0.16B, W0 (fill with 0xAB)
      SturQ(0, 1, -16),        // STUR Q0, [X1, #-16]
  };
  state_.cpu.x[0] = 0xAB;
  state_.cpu.x[1] = ToGuestAddr(buffer + 32);  // X1 points to buffer+32
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));

  // Bytes 0-15: untouched
  for (int i = 0; i < 16; i++) {
    EXPECT_EQ(buffer[i], 0xCC) << "byte " << i;
  }
  // Bytes 16-31: should be 0xAB (stored at X1-16 = buffer+16)
  for (int i = 16; i < 32; i++) {
    EXPECT_EQ(buffer[i], 0xAB) << "byte " << i;
  }
  // Bytes 32-63: untouched
  for (int i = 32; i < 64; i++) {
    EXPECT_EQ(buffer[i], 0xCC) << "byte " << i;
  }
}

