  lanes[2] = 0x4048F5C3u;  // 3.14f -> 3
  lanes[3] = 0xFF800000u;  // -Inf -> 0
  static const uint32_t code[] = {kFcvtmuV4s00};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
