// AdvSimdScalarThreeSame FP16 FMULX scalar Hd via F16C
// round-trip.  Same lift recipe as the FP16 compare family (Pxor + Pinsrw +
// Vcvtph2ps each FP16 source lane into FP32 xmm lane 0); the existing FP32
// FMULX core (Mulss + cmpunord-blend with ±2.0 on the ±0×±inf special case)
// runs unchanged on the lifted operands; the FP32 result is narrowed back
// to FP16 via Vcvtps2ph (real-FP value, not a mask — Vcvtps2ph is the
// right narrow primitive here, NOT Packssdw).
// Encoding (per ARM ARM C7.2 "Advanced SIMD scalar three same (FP16)" —
// bit31=0, bit30=1, bit29=U=0, bits[28:24]=11110, bit23=a=0, bit22=1,
// bit21=0, bits[20:16]=Rm, bits[15:14]=00, bits[13:11]=011, bit10=1):
//   FMULX Hd, Hn, Hm = 0x5E401C00 | (rm<<16) | (rn<<5) | rd  (U=0,a=0,op=011)
// Cross-checked against the existing FcmeqScalarH base (0x5E402400, op=100):
// only opcode_3 bits[13:11] differ (011 vs 100), so the constant deltas
// from FcmeqScalarH by the opcode_3 difference = (100 - 011) << 11 = 0x800.
// 0x5E402400 - 0x800 = 0x5E401C00. ✓
constexpr uint32_t FmulxScalarH(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x5E401C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}

// FMULX Hd: regular finite multiply.  3.0h * 4.0h = 12.0h = 0x4A00.
// 3.0h = 0x4200; 4.0h = 0x4400; 12.0h = 0x4A00.
TEST_F(Arm64LiteTranslateRegionTest, FmulxScalarHRegular) {
  StoreScalarH(state_.cpu, 1, 0x4200u);  // 3.0
  StoreScalarH(state_.cpu, 2, 0x4400u);  // 4.0
  state_.cpu.v[0] = ~__uint128_t{0};  // pre-trash dest
  static const uint32_t code[] = {FmulxScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x4A00u);
  for (int i = 1; i < 8; ++i) {
    EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[i], 0u);
  }
}

// FMULX Hd: +0 * +inf -> +2.0 (canonical FMULX saturation).
// +inf_h = 0x7C00; +2.0h = 0x4000.
TEST_F(Arm64LiteTranslateRegionTest, FmulxScalarHZeroTimesInf) {
  StoreScalarH(state_.cpu, 1, 0x0000u);  // +0.0
  StoreScalarH(state_.cpu, 2, 0x7C00u);  // +inf
  static const uint32_t code[] = {FmulxScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x4000u);
}

// FMULX Hd: -0 * +inf -> -2.0.  Sign = sign(-0) XOR sign(+inf) = 1.
// -2.0h = 0xC000.  The sign-bit XOR happens at FP32 width; the FP16 sign
// bit (bit 15) lifts to FP32 sign bit (bit 31) which is the bit Pslld 31
// isolates.
TEST_F(Arm64LiteTranslateRegionTest, FmulxScalarHNegZeroTimesInf) {
  StoreScalarH(state_.cpu, 1, 0x8000u);  // -0.0
  StoreScalarH(state_.cpu, 2, 0x7C00u);  // +inf
  static const uint32_t code[] = {FmulxScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0xC000u);
}

// FMULX Hd: -inf * +0 -> -2.0 (the (0,inf) cross case is symmetric in the
// operand order; only the XOR'd sign matters).
TEST_F(Arm64LiteTranslateRegionTest, FmulxScalarHNegInfTimesZero) {
  StoreScalarH(state_.cpu, 1, 0xFC00u);  // -inf
  StoreScalarH(state_.cpu, 2, 0x0000u);  // +0.0
  static const uint32_t code[] = {FmulxScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0xC000u);
}

// FMULX Hd: -inf * -0 -> +2.0.  Sign = 1 XOR 1 = 0.
TEST_F(Arm64LiteTranslateRegionTest, FmulxScalarHNegInfTimesNegZero) {
  StoreScalarH(state_.cpu, 1, 0xFC00u);  // -inf
  StoreScalarH(state_.cpu, 2, 0x8000u);  // -0.0
  static const uint32_t code[] = {FmulxScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x4000u);
}

// FMULX Hd: NaN input -> NaN output (any NaN bit pattern; not ±2.0).
// qNaN_h = 0x7E00.  Check via FP16 exponent=0x1F + frac!=0.
TEST_F(Arm64LiteTranslateRegionTest, FmulxScalarHNaNInput) {
  StoreScalarH(state_.cpu, 1, 0x7E00u);  // qNaN
  StoreScalarH(state_.cpu, 2, 0x3C00u);  // 1.0
  static const uint32_t code[] = {FmulxScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint16_t result = reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0];
  EXPECT_EQ(result & 0x7C00u, 0x7C00u);  // exponent all-ones
  EXPECT_NE(result & 0x03FFu, 0u);       // frac non-zero
}

// FMULX Hd: 0 * 5 -> +0 (NOT ±2.0; the special case is 0*inf only).
TEST_F(Arm64LiteTranslateRegionTest, FmulxScalarHZeroTimesFinite) {
  StoreScalarH(state_.cpu, 1, 0x0000u);  // +0.0
  StoreScalarH(state_.cpu, 2, 0x4500u);  // 5.0
  static const uint32_t code[] = {FmulxScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x0000u);
}

// FMULX Hd: negative * negative -> positive.  -2.5h * -4.0h = +10.0h.
// -2.5h = 0xC100; -4.0h = 0xC400; +10.0h = 0x4900.
TEST_F(Arm64LiteTranslateRegionTest, FmulxScalarHNegNeg) {
  StoreScalarH(state_.cpu, 1, 0xC100u);  // -2.5
  StoreScalarH(state_.cpu, 2, 0xC400u);  // -4.0
  static const uint32_t code[] = {FmulxScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x4900u);
}

// FMULX Hd in-place (Vd == Vn): must read Vn before any store to Vd.
// 3.0 * 4.0 = 12.0; upper word lanes of Vd must be zero post-execution.
TEST_F(Arm64LiteTranslateRegionTest, FmulxScalarHInPlace) {
  state_.cpu.v[5] = __uint128_t{0};
  reinterpret_cast<uint16_t*>(&state_.cpu.v[5])[0] = 0x4200u;  // 3.0
  for (int i = 1; i < 8; ++i) {
    reinterpret_cast<uint16_t*>(&state_.cpu.v[5])[i] = 0xAAAAu;
  }
  StoreScalarH(state_.cpu, 2, 0x4400u);  // 4.0
  static const uint32_t code[] = {FmulxScalarH(5, 5, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[5])[0], 0x4A00u);
  for (int i = 1; i < 8; ++i) {
    EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[5])[i], 0u);
  }
}

// AdvSimdScalarThreeSame FP16 FABD scalar Hd via F16C
// round-trip.  Same lift recipe as FMULX H (Pxor + Pinsrw + Vcvtph2ps each
// FP16 source lane into FP32 xmm lane 0); the existing FP32 FABD core
// (Subss + AND with non-sign-bit mask) runs unchanged on the lifted
// operands; the FP32 result is narrowed back to FP16 via Vcvtps2ph
// (real-FP value, not a mask — Vcvtps2ph is the right primitive here).
// Encoding (per ARM ARM C7.2 "Advanced SIMD scalar three same (FP16)" —
// a=1, U=1, opcode_3=010):
//   FABD Hd, Hn, Hm = 0x7EC01400 | (rm<<16) | (rn<<5) | rd
// Cross-check: FacgtScalarH base (a=1, U=1, opcode_3=101) is 0x7EC02C00;
// delta to FABD by opcode_3 difference = (010 - 101) << 11 = -0x1800.
// 0x7EC02C00 - 0x1800 = 0x7EC01400. ✓
constexpr uint32_t FabdScalarH(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x7EC01400u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}

// FABD Hd: positive result (5.0 - 3.5 = 1.5).  5.0h=0x4500, 3.5h=0x4300,
// 1.5h=0x3E00.
TEST_F(Arm64LiteTranslateRegionTest, FabdScalarHPositiveResult) {
  StoreScalarH(state_.cpu, 1, 0x4500u);  // 5.0
  StoreScalarH(state_.cpu, 2, 0x4300u);  // 3.5
  state_.cpu.v[0] = ~__uint128_t{0};  // pre-trash dest
  static const uint32_t code[] = {FabdScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x3E00u);
  for (int i = 1; i < 8; ++i) {
    EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[i], 0u);
  }
}

// FABD Hd: negative subtract pinned to positive by fabs (3.5 - 5.0 = -1.5,
// |...|=1.5).  The Pand against the non-sign-bit mask must clear bit 31 of
// the FP32 (lifted) representation, which then narrows to FP16 with bit
// 15 cleared.
TEST_F(Arm64LiteTranslateRegionTest, FabdScalarHNegativeSubtract) {
  StoreScalarH(state_.cpu, 1, 0x4300u);  // 3.5
  StoreScalarH(state_.cpu, 2, 0x4500u);  // 5.0
  static const uint32_t code[] = {FabdScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x3E00u);
}

// FABD Hd: equal inputs -> +0 (subtract is exact-zero, AND with mask
// keeps it +0).  1.5 - 1.5 = +0.0h = 0x0000.
TEST_F(Arm64LiteTranslateRegionTest, FabdScalarHEqualInputsPositiveZero) {
  StoreScalarH(state_.cpu, 1, 0x3E00u);  // 1.5
  StoreScalarH(state_.cpu, 2, 0x3E00u);  // 1.5
  static const uint32_t code[] = {FabdScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x0000u);
}

// FABD Hd: NaN propagation.  qNaN - finite -> NaN; the AND-with-non-sign
// mask clears the sign bit but leaves the NaN payload intact (high
// fraction bits non-zero, exponent all-ones).
TEST_F(Arm64LiteTranslateRegionTest, FabdScalarHNaNInput) {
  StoreScalarH(state_.cpu, 1, 0x7E00u);  // qNaN
  StoreScalarH(state_.cpu, 2, 0x3C00u);  // 1.0
  static const uint32_t code[] = {FabdScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint16_t result = reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0];
  EXPECT_EQ(result & 0x7C00u, 0x7C00u);  // exponent all-ones (NaN/inf)
  EXPECT_NE(result & 0x03FFu, 0u);       // frac non-zero (NaN, not inf)
  EXPECT_EQ(result & 0x8000u, 0u);       // sign bit cleared by fabs mask
}

// FABD Hd: inf - inf -> NaN (subtract of equal infinities is the canonical
// invalid-op case).  AND with non-sign mask preserves NaN-ness.
TEST_F(Arm64LiteTranslateRegionTest, FabdScalarHInfMinusInf) {
  StoreScalarH(state_.cpu, 1, 0x7C00u);  // +inf
  StoreScalarH(state_.cpu, 2, 0x7C00u);  // +inf
  static const uint32_t code[] = {FabdScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint16_t result = reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0];
  EXPECT_EQ(result & 0x7C00u, 0x7C00u);
  EXPECT_NE(result & 0x03FFu, 0u);
}

// FABD Hd: inf - finite -> +inf.  |+inf| = +inf = 0x7C00.
TEST_F(Arm64LiteTranslateRegionTest, FabdScalarHInfMinusFinite) {
  StoreScalarH(state_.cpu, 1, 0x7C00u);  // +inf
  StoreScalarH(state_.cpu, 2, 0x4500u);  // 5.0
  static const uint32_t code[] = {FabdScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x7C00u);
}

// FABD Hd: -inf - +1 -> -inf, fabs -> +inf (sign bit cleared).
TEST_F(Arm64LiteTranslateRegionTest, FabdScalarHNegInfMinusOne) {
  StoreScalarH(state_.cpu, 1, 0xFC00u);  // -inf
  StoreScalarH(state_.cpu, 2, 0x3C00u);  // 1.0
  static const uint32_t code[] = {FabdScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x7C00u);
}

// FABD Hd in-place (Vd == Vn): the Pinsrw load reads operand bytes before
// any store to Vd, so an in-place encoding must produce the correct result
// with upper word lanes of Vd zero post-execution.
TEST_F(Arm64LiteTranslateRegionTest, FabdScalarHInPlace) {
  state_.cpu.v[5] = __uint128_t{0};
  reinterpret_cast<uint16_t*>(&state_.cpu.v[5])[0] = 0x4500u;  // 5.0
  for (int i = 1; i < 8; ++i) {
    reinterpret_cast<uint16_t*>(&state_.cpu.v[5])[i] = 0xAAAAu;
  }
  StoreScalarH(state_.cpu, 2, 0x4300u);  // 3.5
  static const uint32_t code[] = {FabdScalarH(5, 5, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[5])[0], 0x3E00u);
  for (int i = 1; i < 8; ++i) {
    EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[5])[i], 0u);
  }
}

// AdvSimdScalarThreeSame FP16 FRECPS scalar Hd via F16C
// round-trip.  Same lift recipe as FMULX H / FABD H (Pxor + Pinsrw +
// Vcvtph2ps each FP16 source lane into FP32 xmm lane 0); the existing FP32
// FRECPS Newton-step core (Vfnmadd231ss of K_fma=+2.0 - a*b, with K_sat=+2.0
// blend on `(NOT iu) AND mul_unord`, plus default-qNaN blend on iu) runs
// unchanged on the lifted operands; the FP32 result is narrowed back to FP16
// via Vcvtps2ph (real-FP value, not a mask).  FMA-gated.
// Encoding (per ARM ARM C7.2 "Advanced SIMD scalar three same (FP16)" —
// bit31=0, bit30=1, bit29=U=0, bits[28:24]=11110, bit23=a=0, bit22=1,
// bit21=0, bits[20:16]=Rm, bits[15:14]=00, bits[13:11]=opcode_3=111,
// bit10=1):
//   FRECPS Hd, Hn, Hm = 0x5E403C00 | (rm<<16) | (rn<<5) | rd  (U=0,a=0,op=111)
// Cross-check against FmulxScalarH base (0x5E401C00, op=011): delta by
// opcode_3 difference = (111 - 011) << 11 = 100<<11 = 0x2000.  0x5E401C00 +
// 0x2000 = 0x5E403C00. ✓
constexpr uint32_t FrecpsScalarH(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x5E403C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}

// FRECPS Hd: regular finite Newton step.  2 - 0.5*3 = 0.5 in FP16.
// 0.5h=0x3800, 3.0h=0x4200, 0.5h=0x3800.
TEST_F(Arm64LiteTranslateRegionTest, FrecpsScalarHRegular) {
  StoreScalarH(state_.cpu, 1, 0x3800u);  // 0.5
  StoreScalarH(state_.cpu, 2, 0x4200u);  // 3.0
  state_.cpu.v[0] = ~__uint128_t{0};  // pre-trash dest
  static const uint32_t code[] = {FrecpsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x3800u);
  for (int i = 1; i < 8; ++i) {
    EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[i], 0u);
  }
}

// FRECPS Hd: regular Newton step at the converged fixed point.  2 - 1*1 = 1.
TEST_F(Arm64LiteTranslateRegionTest, FrecpsScalarHFixedPoint) {
  StoreScalarH(state_.cpu, 1, 0x3C00u);  // 1.0
  StoreScalarH(state_.cpu, 2, 0x3C00u);  // 1.0
  static const uint32_t code[] = {FrecpsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x3C00u);
}

// FRECPS Hd: saturation case.  +0 * +inf -> +2.0 (unsigned — FRECPS does NOT
// XOR signs like FMULX).  +2.0h = 0x4000.
TEST_F(Arm64LiteTranslateRegionTest, FrecpsScalarHZeroTimesInf) {
  StoreScalarH(state_.cpu, 1, 0x0000u);  // +0.0
  StoreScalarH(state_.cpu, 2, 0x7C00u);  // +inf
  static const uint32_t code[] = {FrecpsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x4000u);
}

// FRECPS Hd: saturation with negative-zero input.  -0 * +inf -> +2.0
// (NOT -2.0 — FRECPS K_sat is unsigned, no sign XOR).
TEST_F(Arm64LiteTranslateRegionTest, FrecpsScalarHNegZeroTimesInf) {
  StoreScalarH(state_.cpu, 1, 0x8000u);  // -0.0
  StoreScalarH(state_.cpu, 2, 0x7C00u);  // +inf
  static const uint32_t code[] = {FrecpsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x4000u);
}

// FRECPS Hd: saturation with -inf input.  -inf * +0 -> +2.0.
TEST_F(Arm64LiteTranslateRegionTest, FrecpsScalarHNegInfTimesZero) {
  StoreScalarH(state_.cpu, 1, 0xFC00u);  // -inf
  StoreScalarH(state_.cpu, 2, 0x0000u);  // +0.0
  static const uint32_t code[] = {FrecpsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x4000u);
}

// FRECPS Hd: NaN input -> default qNaN, NOT the input NaN payload.
// FP16 default qNaN has exp=0x1F, MSB of frac=1, sign=0.  Pattern:
// 0x7E00 (sign=0, exp=0x1F, frac MSB=1, low frac=0).
TEST_F(Arm64LiteTranslateRegionTest, FrecpsScalarHNaNInput) {
  StoreScalarH(state_.cpu, 1, 0x7E00u);  // qNaN
  StoreScalarH(state_.cpu, 2, 0x3C00u);  // 1.0
  static const uint32_t code[] = {FrecpsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint16_t result = reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0];
  // Default qNaN: sign=0, exp all ones, MSB of frac set.
  EXPECT_EQ(result & 0xFE00u, 0x7E00u);  // sign=0, exp=0x1F, frac MSB=1
}

// FRECPS Hd: zero * finite -> FMA(-0, 5, 2) = +2.0 (ordinary FMA, not
// saturation; saturation only fires on the (0, inf) cross).
TEST_F(Arm64LiteTranslateRegionTest, FrecpsScalarHZeroTimesFinite) {
  StoreScalarH(state_.cpu, 1, 0x0000u);  // +0.0
  StoreScalarH(state_.cpu, 2, 0x4500u);  // 5.0
  static const uint32_t code[] = {FrecpsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x4000u);
}

// FRECPS Hd in-place (Vd == Vn): the Pinsrw load reads operand bytes before
// any store to Vd, so an in-place encoding must produce the correct result
// with upper word lanes of Vd zero post-execution.  0.5 * 3 = 1.5;
// 2 - 1.5 = 0.5.
TEST_F(Arm64LiteTranslateRegionTest, FrecpsScalarHInPlace) {
  state_.cpu.v[5] = __uint128_t{0};
  reinterpret_cast<uint16_t*>(&state_.cpu.v[5])[0] = 0x3800u;  // 0.5
  for (int i = 1; i < 8; ++i) {
    reinterpret_cast<uint16_t*>(&state_.cpu.v[5])[i] = 0xAAAAu;
  }
  StoreScalarH(state_.cpu, 2, 0x4200u);  // 3.0
  static const uint32_t code[] = {FrecpsScalarH(5, 5, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[5])[0], 0x3800u);
  for (int i = 1; i < 8; ++i) {
    EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[5])[i], 0u);
  }
}

// FRSQRTS scalar H (FP16) — JIT-emitted via the same F16C
// round-trip recipe as FRECPS H, with the additional Divss-by-2 step routed
// through `use_single` so it fires on the FP16-lifted FP32 lane 0.  Encoding
// per ARM ARM C7.2.7 "FRSQRTS (scalar)" — a=1, U=0, opcode_3=111 (delta from
// FRECPS H's a=0: bit23 set, which flips 0x5E403C00 to 0x5EC03C00):
//   FRSQRTS Hd, Hn, Hm = 0x5EC03C00 | (rm<<16) | (rn<<5) | rd
// Cross-check vs FRECPS H (a=0, U=0, op=111): bit23 difference = 1<<23 =
// 0x00800000.  0x5E403C00 + 0x800000 = 0x5EC03C00. ✓
constexpr uint32_t FrsqrtsScalarH(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x5EC03C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}

// FRSQRTS Hd: regular finite Newton step.  (3 - 0.5*3)/2 = 0.75 in FP16.
// 0.5h=0x3800, 3.0h=0x4200, 0.75h=0x3A00.
TEST_F(Arm64LiteTranslateRegionTest, FrsqrtsScalarHRegular) {
  StoreScalarH(state_.cpu, 1, 0x3800u);  // 0.5
  StoreScalarH(state_.cpu, 2, 0x4200u);  // 3.0
  state_.cpu.v[0] = ~__uint128_t{0};  // pre-trash dest
  static const uint32_t code[] = {FrsqrtsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x3A00u);
  for (int i = 1; i < 8; ++i) {
    EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[i], 0u);
  }
}

// FRSQRTS Hd: converged fixed point.  (3 - 1*1)/2 = 1.0.
TEST_F(Arm64LiteTranslateRegionTest, FrsqrtsScalarHFixedPoint) {
  StoreScalarH(state_.cpu, 1, 0x3C00u);  // 1.0
  StoreScalarH(state_.cpu, 2, 0x3C00u);  // 1.0
  static const uint32_t code[] = {FrsqrtsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x3C00u);
}

// FRSQRTS Hd: saturation case.  +0 * +inf -> K_sat = +1.5 (FRSQRTS K_sat is
// unsigned, same as FRECPS — no sign XOR).  +1.5h = 0x3E00.
TEST_F(Arm64LiteTranslateRegionTest, FrsqrtsScalarHZeroTimesInf) {
  StoreScalarH(state_.cpu, 1, 0x0000u);  // +0.0
  StoreScalarH(state_.cpu, 2, 0x7C00u);  // +inf
  static const uint32_t code[] = {FrsqrtsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x3E00u);
}

// FRSQRTS Hd: saturation with -inf input.  -inf * +0 -> +1.5.
TEST_F(Arm64LiteTranslateRegionTest, FrsqrtsScalarHNegInfTimesZero) {
  StoreScalarH(state_.cpu, 1, 0xFC00u);  // -inf
  StoreScalarH(state_.cpu, 2, 0x0000u);  // +0.0
  static const uint32_t code[] = {FrsqrtsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x3E00u);
}

// FRSQRTS Hd: NaN input -> default qNaN, NOT the input NaN payload.
TEST_F(Arm64LiteTranslateRegionTest, FrsqrtsScalarHNaNInput) {
  StoreScalarH(state_.cpu, 1, 0x7E00u);  // qNaN
  StoreScalarH(state_.cpu, 2, 0x3C00u);  // 1.0
  static const uint32_t code[] = {FrsqrtsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint16_t result = reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0];
  EXPECT_EQ(result & 0xFE00u, 0x7E00u);
}

// FRSQRTS Hd: zero * finite -> ordinary FMA, NOT saturation.
// (3 - 0*5)/2 = 1.5h = 0x3E00.  Numerically identical to the K_sat value, but
// arrives via the FMA path (the saturation blend is gated on the
// (0, inf)/(inf, 0) cross, which this case does not match).
TEST_F(Arm64LiteTranslateRegionTest, FrsqrtsScalarHZeroTimesFinite) {
  StoreScalarH(state_.cpu, 1, 0x0000u);  // +0.0
  StoreScalarH(state_.cpu, 2, 0x4500u);  // 5.0
  static const uint32_t code[] = {FrsqrtsScalarH(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[0])[0], 0x3E00u);
}

// FRSQRTS Hd in-place (Vd == Vn): like FRECPS H in-place, Pinsrw loads operand
// bytes before any store.  (3 - 0.5*3)/2 = 0.75 = 0x3A00.
TEST_F(Arm64LiteTranslateRegionTest, FrsqrtsScalarHInPlace) {
  state_.cpu.v[5] = __uint128_t{0};
  reinterpret_cast<uint16_t*>(&state_.cpu.v[5])[0] = 0x3800u;  // 0.5
  for (int i = 1; i < 8; ++i) {
    reinterpret_cast<uint16_t*>(&state_.cpu.v[5])[i] = 0xAAAAu;
  }
  StoreScalarH(state_.cpu, 2, 0x4200u);  // 3.0
  static const uint32_t code[] = {FrsqrtsScalarH(5, 5, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[5])[0], 0x3A00u);
  for (int i = 1; i < 8; ++i) {
    EXPECT_EQ(reinterpret_cast<const uint16_t*>(&state_.cpu.v[5])[i], 0u);
  }
}

// AdvSimdScalarPairwise JIT — ADDP scalar (D) and FADDP
// scalar (S/D non-FP16).  Encoding (ARM ARM "Advanced SIMD scalar pairwise",
// C7.2.6 "ADDP (scalar)", C7.2.66 "FADDP (scalar)"):
//   ADDP  Vd.D, Vn.2D    = 0x5EF1B800 | (rn<<5) | rd  (U=0 size=11 op=11011)
//   FADDP Sd, Vn.2S      = 0x7E30D800 | (rn<<5) | rd  (U=1 size=00 op=01101)
//   FADDP Dd, Vn.2D      = 0x7E70D800 | (rn<<5) | rd  (U=1 size=01 op=01101)
constexpr uint32_t AddpScalarD(uint8_t rd, uint8_t rn) {
  return 0x5EF1B800u | (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t FaddpScalarS(uint8_t rd, uint8_t rn) {
  return 0x7E30D800u | (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t FaddpScalarD(uint8_t rd, uint8_t rn) {
  return 0x7E70D800u | (static_cast<uint32_t>(rn) << 5) | rd;
}

// ADDP scalar D: Vn.D[0]=10, Vn.D[1]=20 -> Vd.D[0]=30, upper 8 bytes zero.
TEST_F(Arm64LiteTranslateRegionTest, AddpScalarDPositive) {
  state_.cpu.v[1] =
      (static_cast<__uint128_t>(uint64_t{20}) << 64) | uint64_t{10};
  state_.cpu.v[0] = ~__uint128_t{0};  // pre-trash dest
  static const uint32_t code[] = {AddpScalarD(0, 1)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint64_t lane0, lane1;
  std::memcpy(&lane0, &state_.cpu.v[0], 8);
  std::memcpy(&lane1, reinterpret_cast<const uint8_t*>(&state_.cpu.v[0]) + 8, 8);
  EXPECT_EQ(lane0, uint64_t{30});
  EXPECT_EQ(lane1, uint64_t{0});
}

// ADDP scalar D: 64-bit wraparound. (2^63 - 1) + 1 = 2^63 (mod 2^64).
TEST_F(Arm64LiteTranslateRegionTest, AddpScalarDWrap) {
  state_.cpu.v[1] =
      (static_cast<__uint128_t>(uint64_t{1}) << 64) |
      uint64_t{0x7FFFFFFFFFFFFFFFULL};
  static const uint32_t code[] = {AddpScalarD(0, 1)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint64_t lane0;
  std::memcpy(&lane0, &state_.cpu.v[0], 8);
  EXPECT_EQ(lane0, uint64_t{0x8000000000000000ULL});
}

// ADDP scalar D in-place (Vd == Vn): must still observe Vn's original
// lanes, not the post-write Vd.  10 + 20 = 30.
TEST_F(Arm64LiteTranslateRegionTest, AddpScalarDInPlace) {
  state_.cpu.v[3] =
      (static_cast<__uint128_t>(uint64_t{20}) << 64) | uint64_t{10};
  static const uint32_t code[] = {AddpScalarD(3, 3)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint64_t lane0, lane1;
  std::memcpy(&lane0, &state_.cpu.v[3], 8);
  std::memcpy(&lane1, reinterpret_cast<const uint8_t*>(&state_.cpu.v[3]) + 8, 8);
  EXPECT_EQ(lane0, uint64_t{30});
  EXPECT_EQ(lane1, uint64_t{0});
}

// FADDP Sd, Vn.2S: 1.5 + 2.5 = 4.0; lanes 1..3 zero.
TEST_F(Arm64LiteTranslateRegionTest, FaddpScalarSPositive) {
  uint32_t lane_bits[4] = {0, 0, 0, 0};
  float a = 1.5f, b = 2.5f;
  std::memcpy(&lane_bits[0], &a, 4);
  std::memcpy(&lane_bits[1], &b, 4);
  std::memcpy(&state_.cpu.v[1], lane_bits, 16);
  state_.cpu.v[0] = ~__uint128_t{0};
  static const uint32_t code[] = {FaddpScalarS(0, 1)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  float result;
  std::memcpy(&result, &state_.cpu.v[0], sizeof(float));
  EXPECT_FLOAT_EQ(result, 4.0f);
  uint32_t upper[3];
  std::memcpy(upper, reinterpret_cast<const uint8_t*>(&state_.cpu.v[0]) + 4, 12);
  EXPECT_EQ(upper[0], 0u);
  EXPECT_EQ(upper[1], 0u);
  EXPECT_EQ(upper[2], 0u);
}

// FADDP Sd, Vn.2S with NaN input -> NaN result.
TEST_F(Arm64LiteTranslateRegionTest, FaddpScalarSNaN) {
  uint32_t lane_bits[4] = {0, 0, 0, 0};
  float a = std::nanf(""), b = 1.0f;
  std::memcpy(&lane_bits[0], &a, 4);
  std::memcpy(&lane_bits[1], &b, 4);
  std::memcpy(&state_.cpu.v[1], lane_bits, 16);
  static const uint32_t code[] = {FaddpScalarS(0, 1)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  float result;
  std::memcpy(&result, &state_.cpu.v[0], sizeof(float));
  EXPECT_TRUE(std::isnan(result));
}

// FADDP Dd, Vn.2D: 3.0 + 4.0 = 7.0; upper 8 bytes zero.
TEST_F(Arm64LiteTranslateRegionTest, FaddpScalarDPositive) {
  double a = 3.0, b = 4.0;
  uint64_t lane_bits[2];
  std::memcpy(&lane_bits[0], &a, 8);
  std::memcpy(&lane_bits[1], &b, 8);
  std::memcpy(&state_.cpu.v[1], lane_bits, 16);
  state_.cpu.v[0] = ~__uint128_t{0};
  static const uint32_t code[] = {FaddpScalarD(0, 1)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  double result;
  std::memcpy(&result, &state_.cpu.v[0], sizeof(double));
  EXPECT_DOUBLE_EQ(result, 7.0);
  uint64_t upper;
  std::memcpy(&upper, reinterpret_cast<const uint8_t*>(&state_.cpu.v[0]) + 8, 8);
  EXPECT_EQ(upper, uint64_t{0});
}

// FADDP Dd, Vn.2D with infinity propagation: +inf + 1.0 = +inf.
TEST_F(Arm64LiteTranslateRegionTest, FaddpScalarDInfFinite) {
  double a = std::numeric_limits<double>::infinity(), b = 1.0;
  uint64_t lane_bits[2];
  std::memcpy(&lane_bits[0], &a, 8);
  std::memcpy(&lane_bits[1], &b, 8);
  std::memcpy(&state_.cpu.v[1], lane_bits, 16);
  static const uint32_t code[] = {FaddpScalarD(0, 1)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  double result;
  std::memcpy(&result, &state_.cpu.v[0], sizeof(double));
  EXPECT_EQ(result, std::numeric_limits<double>::infinity());
}

// FADDP Sd, Vn.2S in-place (Vd == Vn): must read both lanes of Vn before
// overwriting Vd.
TEST_F(Arm64LiteTranslateRegionTest, FaddpScalarSInPlace) {
  uint32_t lane_bits[4] = {0, 0, 0, 0};
  float a = 0.5f, b = 0.25f;
  std::memcpy(&lane_bits[0], &a, 4);
  std::memcpy(&lane_bits[1], &b, 4);
  std::memcpy(&state_.cpu.v[5], lane_bits, 16);
  static const uint32_t code[] = {FaddpScalarS(5, 5)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  float result;
  std::memcpy(&result, &state_.cpu.v[5], sizeof(float));
  EXPECT_FLOAT_EQ(result, 0.75f);
  uint32_t upper[3];
  std::memcpy(upper, reinterpret_cast<const uint8_t*>(&state_.cpu.v[5]) + 4, 12);
  EXPECT_EQ(upper[0], 0u);
  EXPECT_EQ(upper[1], 0u);
  EXPECT_EQ(upper[2], 0u);
}

// AdvSimdScalarPairwise JIT — FMAXP / FMINP / FMAXNMP /
// FMINNMP scalar (S/D non-FP16).  Encoding (ARM ARM "Advanced SIMD scalar
// pairwise", C7.2 — U=1 FP leg, opcode=01111 for max/min, opcode=01100 for
// maxnm/minnm; size[1] selects min(=1) vs max(=0) family; size[0] selects
// S(=0) vs D(=1)):
//   FMAXP   Sd, Vn.2S = 0x7E30F800 | (rn<<5) | rd
//   FMAXP   Dd, Vn.2D = 0x7E70F800 | (rn<<5) | rd
//   FMINP   Sd, Vn.2S = 0x7EB0F800 | (rn<<5) | rd
//   FMINP   Dd, Vn.2D = 0x7EF0F800 | (rn<<5) | rd
//   FMAXNMP Sd, Vn.2S = 0x7E30C800 | (rn<<5) | rd
//   FMAXNMP Dd, Vn.2D = 0x7E70C800 | (rn<<5) | rd
//   FMINNMP Sd, Vn.2S = 0x7EB0C800 | (rn<<5) | rd
//   FMINNMP Dd, Vn.2D = 0x7EF0C800 | (rn<<5) | rd
constexpr uint32_t FmaxpScalarS(uint8_t rd, uint8_t rn) {
  return 0x7E30F800u | (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t FmaxpScalarD(uint8_t rd, uint8_t rn) {
  return 0x7E70F800u | (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t FminpScalarS(uint8_t rd, uint8_t rn) {
  return 0x7EB0F800u | (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t FminpScalarD(uint8_t rd, uint8_t rn) {
  return 0x7EF0F800u | (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t FmaxnmpScalarS(uint8_t rd, uint8_t rn) {
  return 0x7E30C800u | (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t FmaxnmpScalarD(uint8_t rd, uint8_t rn) {
  return 0x7E70C800u | (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t FminnmpScalarS(uint8_t rd, uint8_t rn) {
  return 0x7EB0C800u | (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t FminnmpScalarD(uint8_t rd, uint8_t rn) {
  return 0x7EF0C800u | (static_cast<uint32_t>(rn) << 5) | rd;
}

// FMAXP Sd: 1.5, 2.5 -> 2.5; lanes 1..3 zero.
TEST_F(Arm64LiteTranslateRegionTest, FmaxpScalarSPositive) {
  uint32_t lane_bits[4] = {0, 0, 0, 0};
  float a = 1.5f, b = 2.5f;
  std::memcpy(&lane_bits[0], &a, 4);
  std::memcpy(&lane_bits[1], &b, 4);
  std::memcpy(&state_.cpu.v[1], lane_bits, 16);
  state_.cpu.v[0] = ~__uint128_t{0};
  static const uint32_t code[] = {FmaxpScalarS(0, 1)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  float result;
  std::memcpy(&result, &state_.cpu.v[0], sizeof(float));
  EXPECT_FLOAT_EQ(result, 2.5f);
  uint32_t upper[3];
  std::memcpy(upper, reinterpret_cast<const uint8_t*>(&state_.cpu.v[0]) + 4, 12);
  EXPECT_EQ(upper[0], 0u);
  EXPECT_EQ(upper[1], 0u);
  EXPECT_EQ(upper[2], 0u);
}

