  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  float r[4];
  LoadVec4S(state_.cpu, 0, r);
  // Vd = 1.0 - a*a  = std::fma(-a, a, 1.0)
