  // -8 (0xFF..F8) >>s 1 = -4 (0xFF..FC).  Shift = -1 sign-extended from 0xFF.
  state_.cpu.v[1] = static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFF8ULL});
