TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2DRightArithmeticMixedLanesJit) {
  // Lane 0: 0x8000_0000_0000_0000 (INT64_MIN) >>s 1 = 0xC000_0000_0000_0000
  // (sign extension preserved; SSHL semantics).  sh = -1 (0xFF).
  // Lane 1: 0xFFFF...FF (-1 signed) >>s 4 = 0xFFFF...FF (sign extension fills
  // top bits).  sh = -4 (0xFC).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFFFULL})
                      << 64) |
                     static_cast<__uint128_t>(uint64_t{0x8000000000000000ULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xFCULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0xFFULL});
  static const uint32_t code[] = {SqshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            uint64_t{0xC000000000000000ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64),
            uint64_t{0xFFFFFFFFFFFFFFFFULL});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2DRightBy64SignBroadcastJit) {
  // sh = -64 both lanes.  SAR by 63 broadcasts the sign bit.
  // Lane 0: a = 0x7FFF... (positive) → 0.  Lane 1: a = 0xFFFF... (negative)
  // → 0xFFFF... (still all ones — sign bit preserved).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFFFULL})
                      << 64) |
                     static_cast<__uint128_t>(uint64_t{0x7FFFFFFFFFFFFFFFULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xC0ULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0xC0ULL});
  static const uint32_t code[] = {SqshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64),
            uint64_t{0xFFFFFFFFFFFFFFFFULL});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2DPerLaneIndependentJit) {
  // Cross-lane independence with distinct directions.
  // Lane 0: 0x1 << 4 = 0x10 (positive, no saturation).
  // Lane 1: 0xFFFF_FFFF_FFFF_FFFE (-2 signed) >>s 1 = 0xFFFF...FF (-1).
  // sh = -1 (0xFF).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFFEULL})
                      << 64) |
                     static_cast<__uint128_t>(uint64_t{0x1ULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xFFULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0x4ULL});
  static const uint32_t code[] = {SqshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0x10ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64),
            uint64_t{0xFFFFFFFFFFFFFFFFULL});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2DUpperBytesOfShiftIgnoredJit) {
  // Per-lane shift uses only the LOW byte of Vm[lane*8:lane*8+8]; upper 7
  // bytes per lane ignored.  Same shape as UQSHL.2D variant.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0x2ULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0x1ULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xBADBADBADBADBA08ULL})
                      << 64) |
                     static_cast<__uint128_t>(uint64_t{0xDEADBEEFCAFEBA04ULL});
  static const uint32_t code[] = {SqshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0x10ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0x200ULL});
}

// SQSHL.2S/.4S vector form (per-lane signed saturating
// variable shift across 2 or 4 32-bit lanes).  Encoded as AdvSimdThreeSame
// Q∈{0,1}, U=0, size=10, opcode=01001.  Mirrors the SQSHL.2D recipe with
// width-32 substitutions: ShllByCl / SarlByCl, Cmpq sh,32 instead of 64,
// saturation pivot INT32_MAX / INT32_MIN built via `Sarl sh, 31; Movl a,
// INT32_MAX; Xorl a, sh` (sign-aware).  Q=0 zeroes Vd[127:64].
constexpr uint32_t SqshlVec2S(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x0EA04C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t SqshlVec4S(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x4EA04C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2S4SEncodingsMatchLlvmMc) {
  // Verified via llvm-mc:
  //   sqshl v0.2s, v1.2s, v2.2s = 0x0ea24c20
  //   sqshl v0.4s, v1.4s, v2.4s = 0x4ea24c20
  EXPECT_EQ(SqshlVec2S(0, 1, 2), 0x0ea24c20u);
  EXPECT_EQ(SqshlVec4S(0, 1, 2), 0x4ea24c20u);
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2SLeftSmallBothLanesJit) {
  // Lane 0: 0x1 << 8 = 0x100.  Lane 1: 0x2 << 16 = 0x20000.  No saturation.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0x2u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x1u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{16}) << 32) |
                     static_cast<__uint128_t>(uint32_t{8});
  static const uint32_t code[] = {SqshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x20000ULL} << 32) | uint64_t{0x100ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2SOverflowSentinelJit) {
  // Sign-aware back-shift saturation sentinels at .2S width:
  // Lane 0: a=INT32_MIN (0x80000000), sh=1 -> back-shift via SAR gives
  //          0 != 0x80000000 (overflow toward neg), saturate INT32_MIN.
  // Lane 1: a=INT32_MAX (0x7FFFFFFF), sh=1 -> 0xFFFFFFFE has high bit set;
  //          SAR back-shift gives -1 (0xFFFFFFFF) != 0x7FFFFFFF, saturate
  //          INT32_MAX.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0x7FFFFFFFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x80000000u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{1}) << 32) |
                     static_cast<__uint128_t>(uint32_t{1});
  static const uint32_t code[] = {SqshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x7FFFFFFFULL} << 32) | uint64_t{0x80000000ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec4SLeftAllLanesJit) {
  // 4 lanes.  Lanes 0/1: small positive (no saturation).  Lanes 2/3 verify
  // Q=1 populates Vd[127:64] with mixed signed saturation:
  //   Lane 2: a=0x10000 (positive), sh=16 -> 0x10000<<16 = 0x100000000
  //           truncates to 0 in 32-bit; SAR back-shift gives 0 !=
  //           0x10000 -> saturate INT32_MAX (positive).
  //   Lane 3: a=-1 (0xFFFFFFFF, negative in 32-bit signed), sh=1 -> -2
  //           (0xFFFFFFFE), back-shift SAR by 1 gives -1; equal to
  //           original -> NO saturation, result 0xFFFFFFFE.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0xFFFFFFFFu}) << 96) |
                    (static_cast<__uint128_t>(uint32_t{0x10000u}) << 64) |
                    (static_cast<__uint128_t>(uint32_t{0x2u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x1u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{1}) << 96) |
                    (static_cast<__uint128_t>(uint32_t{16}) << 64) |
                    (static_cast<__uint128_t>(uint32_t{4}) << 32) |
                     static_cast<__uint128_t>(uint32_t{2});
  static const uint32_t code[] = {SqshlVec4S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  // Low 64: lane 0 = 1<<2 = 4; lane 1 = 2<<4 = 0x20.
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x20ULL} << 32) | uint64_t{0x4ULL});
  // Hi  64: lane 2 = saturate INT32_MAX; lane 3 = 0xFFFFFFFE (-2).
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64),
            (uint64_t{0xFFFFFFFEULL} << 32) | uint64_t{0x7FFFFFFFULL});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2SLeftBy32MixedZeroNonzeroJit) {
  // sh=32 both lanes: a==0 ? 0 : sign-aware saturation target.
  // Lane 0: a=0 -> 0.
  // Lane 1: a=INT32_MIN (negative) -> saturate INT32_MIN.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0x80000000u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x0u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{32}) << 32) |
                     static_cast<__uint128_t>(uint32_t{32});
  static const uint32_t code[] = {SqshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x80000000ULL} << 32) | uint64_t{0x0ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2SRightArithmeticMixedLanesJit) {
  // SSHL semantics on negative shifts (arithmetic right shift; no
  // saturation possible).
  // Lane 0: 0x80000000 (INT32_MIN) >>s 1 = 0xC0000000 (sign-extended).
  // Lane 1: 0xFFFFFFFF (-1) >>s 4 = 0xFFFFFFFF (sign stays).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0xFFFFFFFFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x80000000u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0xFCu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xFFu});
  static const uint32_t code[] = {SqshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0xFFFFFFFFULL} << 32) | uint64_t{0xC0000000ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2SRightBy32SignBroadcastJit) {
  // sh=-32 both lanes: SAR by W-1=31 broadcasts the sign bit.  Distinguishes
  // SQSHL from UQSHL (which zeros on |sh|>=W).
  // Lane 0: a = -1 (0xFFFFFFFF) -> SAR by 31 = 0xFFFFFFFF (stays -1).
  // Lane 1: a = 0x7FFFFFFF (positive) -> SAR by 31 = 0 (sign bit is 0).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0x7FFFFFFFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xFFFFFFFFu});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0xE0u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xE0u});
  static const uint32_t code[] = {SqshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x0ULL} << 32) | uint64_t{0xFFFFFFFFULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2SUpperHalfZeroedJit) {
  // Q=0 must zero Vd[127:64].  Pre-set Vd to all-ones; sh=0 leaves low 64
  // bits = Vn lanes; upper 64 bits MUST be zero after the JIT region.
  state_.cpu.v[0] = ~static_cast<__uint128_t>(0);
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0xCAFEBABEu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xDEADBEEFu});
  state_.cpu.v[2] = 0;
  static const uint32_t code[] = {SqshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0xCAFEBABEULL} << 32) | uint64_t{0xDEADBEEFULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2SPerLaneIndependentJit) {
  // Cross-lane independence: lane 0 saturates (positive arm), lane 1
  // takes the right-shift path.  Verifies `back` scratch reuse doesn't
  // leak state.
  // Lane 0: a=INT32_MAX, sh=4 -> 0x7FFFFFFF<<4 truncates with bit loss
  //         -> saturate INT32_MAX.
  // Lane 1: a=0x100, sh=-4 (0xFC) -> SAR by 4 = 0x10 (no saturation).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0x100u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x7FFFFFFFu});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0xFCu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{4u});
  static const uint32_t code[] = {SqshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x10ULL} << 32) | uint64_t{0x7FFFFFFFULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SqshlVec2SUpperBytesOfShiftIgnoredJit) {
  // Per-lane shift uses only the LOW byte of Vm[lane*4:lane*4+4]; upper 3
  // bytes per lane ignored.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0x2u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x1u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0xBADBA008u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xDEADBE04u});
  static const uint32_t code[] = {SqshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x200ULL} << 32) | uint64_t{0x10ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

// UQSHL / SQSHL .4H / .8H vector form (per-lane saturating
// variable shift at 16-bit width).  Encoded as AdvSimdThreeSame size=01,
// opcode=01001, U=1 (UQSHL) or U=0 (SQSHL).  Mirrors the .2S/.4S recipe with
// width-16 substitutions: Movzxwl (UQSHL) / Movsxwl (SQSHL) lane load;
// Cmpq sh, 16 thresholds; UQSHL detects overflow via "any bit set in
// shifted-result[31:16]" (Movzxwl-loaded a has upper 16 = 0); SQSHL detects
// signed-16 overflow via the sign-ext-from-low-16 identity
// (Shll back, 16; Sarl back, 16; Cmpl back, a).  UQSHL saturates to
// UINT16_MAX (0xFFFF); SQSHL saturates to INT16_MAX/INT16_MIN selected via
// `Sarl sh, 31; Movl a, 0x7FFF; Xorl a, sh`.  Movw store discards harmless
// upper bits of the 32-bit result GPR.  Q=0 zeroes Vd[127:64] post-loop.
constexpr uint32_t UqshlVec4H(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x2E604C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t UqshlVec8H(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x6E604C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t SqshlVec4H(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x0E604C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t SqshlVec8H(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x4E604C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}

TEST_F(Arm64LiteTranslateRegionTest, QshlVec4H8HEncodingsMatchLlvmMc) {
  // Verified via llvm-mc:
  //   uqshl v0.4h, v1.4h, v2.4h = 0x2e624c20
  //   uqshl v0.8h, v1.8h, v2.8h = 0x6e624c20
  //   sqshl v0.4h, v1.4h, v2.4h = 0x0e624c20
  //   sqshl v0.8h, v1.8h, v2.8h = 0x4e624c20
  EXPECT_EQ(UqshlVec4H(0, 1, 2), 0x2e624c20u);
  EXPECT_EQ(UqshlVec8H(0, 1, 2), 0x6e624c20u);
  EXPECT_EQ(SqshlVec4H(0, 1, 2), 0x0e624c20u);
  EXPECT_EQ(SqshlVec8H(0, 1, 2), 0x4e624c20u);
}

TEST_F(Arm64LiteTranslateRegionTest, UqshlVec4HLeftSmallAllLanesJit) {
  // 4 lanes, all positive arm, no saturation.  Lane 0: 1<<1=2.  Lane 1:
  // 2<<2=8.  Lane 2: 3<<3=0x18.  Lane 3: 4<<4=0x40.
  state_.cpu.v[1] = Pack4H(0x0001, 0x0002, 0x0003, 0x0004);
  state_.cpu.v[2] = Pack4H(0x0001, 0x0002, 0x0003, 0x0004);
  static const uint32_t code[] = {UqshlVec4H(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            static_cast<uint64_t>(Pack4H(0x0002, 0x0008, 0x0018, 0x0040)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqshlVec4HSaturationSentinelJit) {
  // Width-16 back-shift overflow check.  Boundary verification:
  // Lane 0: a=0x8000, sh=1 → 0x10000 in 32-bit (bit 16 set) → saturate
  //          to UINT16_MAX = 0xFFFF.
  // Lane 1: a=0x4000, sh=1 → 0x8000 (no bit-16) → no saturation, 0x8000.
  // Lane 2: a=0xFFFF, sh=1 → 0x1FFFE (bit 16 set) → saturate to 0xFFFF.
  // Lane 3: a=0x0001, sh=15 → 0x8000 (no bit-16) → no saturation, 0x8000.
  state_.cpu.v[1] = Pack4H(0x8000, 0x4000, 0xFFFF, 0x0001);
  state_.cpu.v[2] = Pack4H(0x0001, 0x0001, 0x0001, 0x000F);
  static const uint32_t code[] = {UqshlVec4H(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            static_cast<uint64_t>(Pack4H(0xFFFF, 0x8000, 0xFFFF, 0x8000)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqshlVec8HMixedLanesAllPopulatedJit) {
  // Q=1 8 lanes, mixed quadrants, lanes 4-7 in Vd[127:64].
  // L0: 1<<1=2.  L1: a=0x80, sh=8 → 0x8000 (no overflow).
  // L2: a=0xFFFF, sh=2 → 0x3FFFC (bit 16 set) → 0xFFFF.
  // L3: a=0, sh=10 → 0.
  // L4: a=5, sh=-1 (0xFF) → 2.    L5: a=0xFFFF, sh=-8 (0xF8) → 0xFF.
  // L6: a=0x8000, sh=-15 (0xF1) → 1.  L7: a=0x0001, sh=15 (positive arm)
  //                                        → 0x8000 (no overflow).
  state_.cpu.v[1] = Pack8H(0x0001, 0x0080, 0xFFFF, 0x0000,
                           0x0005, 0xFFFF, 0x8000, 0x0001);
  state_.cpu.v[2] = Pack8H(0x0001, 0x0008, 0x0002, 0x000A,
                           0x00FF, 0x00F8, 0x00F1, 0x000F);
  static const uint32_t code[] = {UqshlVec8H(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.v[0],
            Pack8H(0x0002, 0x8000, 0xFFFF, 0x0000,
                   0x0002, 0x00FF, 0x0001, 0x8000));
}

TEST_F(Arm64LiteTranslateRegionTest, UqshlVec4HLeftBy16MixedZeroNonzeroJit) {
  // sh=16 all lanes: a==0 → 0, else UINT16_MAX (L_pos_big arm).
  state_.cpu.v[1] = Pack4H(0x0000, 0x0001, 0x7FFF, 0xCAFE);
  state_.cpu.v[2] = Pack4H(0x0010, 0x0010, 0x0010, 0x0010);
  static const uint32_t code[] = {UqshlVec4H(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            static_cast<uint64_t>(Pack4H(0x0000, 0xFFFF, 0xFFFF, 0xFFFF)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqshlVec4HRightLogicalAllLanesJit) {
  // Negative arm 0 < |sh| < 16: a >>u |sh| (logical right shift).
  // L0: 0x8000 >>u 1 = 0x4000 (NO sign extension; UQSHL/USHL semantics).
  //      sh=-1 (0xFF).
  // L1: 0xFFFF >>u 4 = 0x0FFF.    sh=-4 (0xFC).
  // L2: 0xCAFE >>u 8 = 0x00CA.    sh=-8 (0xF8).
  // L3: 0x8000 >>u 15 = 0x0001.   sh=-15 (0xF1).
  state_.cpu.v[1] = Pack4H(0x8000, 0xFFFF, 0xCAFE, 0x8000);
  state_.cpu.v[2] = Pack4H(0x00FF, 0x00FC, 0x00F8, 0x00F1);
  static const uint32_t code[] = {UqshlVec4H(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            static_cast<uint64_t>(Pack4H(0x4000, 0x0FFF, 0x00CA, 0x0001)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqshlVec4HRightBy16ZeroesAllJit) {
  // sh=-16 all lanes: |sh|>=16 → 0 (UQSHL right shift cannot overflow).
  state_.cpu.v[1] = Pack4H(0x7FFF, 0xFFFF, 0xCAFE, 0x8000);
  state_.cpu.v[2] = Pack4H(0x00F0, 0x00F0, 0x00F0, 0x00F0);
  static const uint32_t code[] = {UqshlVec4H(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

