TEST_F(Arm64LiteTranslateRegionTest, SrshlVec8BLeftSmallMixedSignsJit) {
  // Positive arm (left shifts truncate).  Mix of positive and negative
  // `a` values; left-shift result low 8 is the same regardless of
  // signedness.
  // L0: a=+0x01 sh=4 -> 0x10.
  // L1: a=-0x02 (0xFE) sh=3 -> 0xF0 (low 8 of 0xFFFFFFF0).
  // L2: a=INT8_MIN (0x80) sh=0 -> 0x80.
  // L3: a=INT8_MAX (0x7F) sh=1 -> 0xFE (signed overflow, low 8 truncates).
  // L4..L7: zero shift, identity.
  state_.cpu.v[1] = Pack8B(0x01, 0xFE, 0x80, 0x7F, 0x12, 0x34, 0x56, 0x78);
  state_.cpu.v[2] = Pack8B(0x04, 0x03, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00);
  static const uint32_t code[] = {SrshlVec8B(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            static_cast<uint64_t>(
                Pack8B(0x10, 0xF0, 0x80, 0xFE, 0x12, 0x34, 0x56, 0x78)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SrshlVec8BSarVsShrSentinelJit) {
  // SAR-vs-SHR distinguisher for the negative-arm signed data shift.
  // `a` values chosen so SAR and SHR diverge at sh=-1.
  // L0: a=0x80 (INT8_MIN) sh=-1:
  //   Movsxbl(a)=0xFFFFFF80; SarlByCl(1) -> 0xFFFFFFC0; round = (a>>0)&1
  //   = 0; low 8 = 0xC0 (-64).  SHR alt: 0x40.
  // L1: a=0xFF (-1) sh=-1:
  //   Movsxbl(a)=0xFFFFFFFF; SarlByCl(1) -> 0xFFFFFFFF; round = 1;
  //   sum = 0; low 8 = 0x00.  SHR alt: 0x7F+1 = 0x80.
  // L2: a=0xF8 (-8) sh=-1:
  //   Movsxbl(a)=0xFFFFFFF8; SarlByCl(1) -> 0xFFFFFFFC; round = 0;
  //   low 8 = 0xFC (-4).  SHR alt: 0x7C.
  // L3: a=0xF9 (-7) sh=-1:
  //   Movsxbl(a)=0xFFFFFFF9; SarlByCl(1) -> 0xFFFFFFFC; round = 1;
  //   low 8 = 0xFD (-3).  SHR alt: 0x7D.
  // L4..L7: zero shift, identity.
  state_.cpu.v[1] = Pack8B(0x80, 0xFF, 0xF8, 0xF9, 0xDE, 0xAD, 0xBE, 0xEF);
  state_.cpu.v[2] = Pack8B(0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x00);
  static const uint32_t code[] = {SrshlVec8B(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            static_cast<uint64_t>(
                Pack8B(0xC0, 0x00, 0xFC, 0xFD, 0xDE, 0xAD, 0xBE, 0xEF)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SrshlVec8BRightRoundedMixedLanesJit) {
  // Negative arm with mixed positive/negative `a` and varying |sh|.
  // L0: a=+0x10 sh=-2: SAR(0x10, 2) = 0x04; round = (0x10>>u 1)&1 = 0
  //     -> 0x04.
  // L1: a=-0x10 (0xF0) sh=-2: Movsxbl(a)=0xFFFFFFF0; SarlByCl(2) =
  //     0xFFFFFFFC; round = (0xFFFFFFF0>>u 1)&1 = 0 -> low 8 = 0xFC (-4).
  // L2: a=+0x07 sh=-2: SAR(0x7, 2) = 0x1; round = (0x7>>u 1)&1 = 1
  //     -> 0x02.
  // L3: a=-0x07 (0xF9) sh=-2: Movsxbl(a)=0xFFFFFFF9; SarlByCl(2) =
  //     0xFFFFFFFE; round = (0xFFFFFFF9 >>u 1) & 1 = 0 -> low 8 = 0xFE
  //     (-2).
  // L4..L7: zero shift, identity.
  state_.cpu.v[1] = Pack8B(0x10, 0xF0, 0x07, 0xF9, 0x12, 0x34, 0x56, 0x78);
  state_.cpu.v[2] = Pack8B(0xFE, 0xFE, 0xFE, 0xFE, 0x00, 0x00, 0x00, 0x00);
  static const uint32_t code[] = {SrshlVec8B(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            static_cast<uint64_t>(
                Pack8B(0x04, 0xFC, 0x02, 0xFE, 0x12, 0x34, 0x56, 0x78)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SrshlVec8BRightBy8ZeroJit) {
  // SRSHL collapses |sh|>=W into the zero branch (unlike URSHL, which
  // has a dedicated |sh|=W bit-(W-1)-only branch).  At |sh|=8 the
  // signed-bias 1<<7 sums with any int8 `a` to a non-negative int16 in
  // [0, 2^8-1] which >>s 8 = 0.  Test sh=-8 (the collapsed boundary).
  state_.cpu.v[1] = Pack8B(0x80, 0xFF, 0x7F, 0x01, 0xCA, 0xFE, 0xBA, 0xBE);
  state_.cpu.v[2] = Pack8B(0xF8, 0xF8, 0xF8, 0xF8, 0xF8, 0xF8, 0xF8, 0xF8);
  static const uint32_t code[] = {SrshlVec8B(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, SrshlVec16BMixedQuadrantsAllLanesJit) {
  // Q=1: all 16 B-lanes populated with a mix of the four SRSHL quadrants:
  //   L0:  left small pos:                a=0x01 sh=4    -> 0x10
  //   L1:  left by 8, zero:               a=0xFF sh=8    -> 0x00
  //   L2:  SAR small neg-a:               a=0xF8 sh=-1   -> 0xFC
  //   L3:  SAR small pos-a:               a=0x07 sh=-2   -> 0x02
  //   L4:  SAR by 8, zero (neg-a):        a=0xFF sh=-8   -> 0x00
  //   L5:  SAR by 8, zero (pos-a):        a=0x7F sh=-8   -> 0x00
  //   L6:  SAR by 9, zero:                a=0x80 sh=-9   -> 0x00
  //   L7:  left small neg:                a=0xFE sh=2    -> 0xF8
  //   L8:  identity (sh=0):               a=0xAB sh=0    -> 0xAB
  //   L9:  SAR by 4 neg-a:                a=0xF0 sh=-4   -> 0xFF
  //   L10: SAR by 3 pos-a:                a=0x10 sh=-3   -> 0x02
  //   L11: left small pos:                a=0x05 sh=1    -> 0x0A
  //   L12: SAR neg-a -1 with round:       a=0xF9 sh=-1   -> 0xFD
  //   L13: SAR neg-a -1 no round:         a=0xF8 sh=-1   -> 0xFC
  //   L14: signed wrap (positive arm):    a=0x7F sh=1    -> 0xFE
  //   L15: left zero data:                a=0x00 sh=4    -> 0x00
  state_.cpu.v[1] = Pack16B(0x01, 0xFF, 0xF8, 0x07, 0xFF, 0x7F, 0x80, 0xFE,
                            0xAB, 0xF0, 0x10, 0x05, 0xF9, 0xF8, 0x7F, 0x00);
  state_.cpu.v[2] = Pack16B(0x04, 0x08, 0xFF, 0xFE, 0xF8, 0xF8, 0xF7, 0x02,
                            0x00, 0xFC, 0xFD, 0x01, 0xFF, 0xFF, 0x01, 0x04);
  static const uint32_t code[] = {SrshlVec16B(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.v[0],
            Pack16B(0x10, 0x00, 0xFC, 0x02, 0x00, 0x00, 0x00, 0xF8,
                    0xAB, 0xFF, 0x02, 0x0A, 0xFD, 0xFC, 0xFE, 0x00));
}

TEST_F(Arm64LiteTranslateRegionTest, SrshlVec8BUpperHalfZeroedJit) {
  // Q=0 must zero Vd[127:64].  Pre-set Vd to all-ones; sh=0 leaves low
  // 64 bits = Vn lanes; upper 64 bits MUST be zero after the JIT region.
  state_.cpu.v[0] = ~static_cast<__uint128_t>(0);
  state_.cpu.v[1] = Pack8B(0xDE, 0xAD, 0xBE, 0xEF, 0xCA, 0xFE, 0xBA, 0xBE);
  state_.cpu.v[2] = 0;
  static const uint32_t code[] = {SrshlVec8B(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            static_cast<uint64_t>(
                Pack8B(0xDE, 0xAD, 0xBE, 0xEF, 0xCA, 0xFE, 0xBA, 0xBE)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

// UQRSHL.2D vector form (per-lane unsigned saturating
// rounded variable shift across two 64-bit lanes).  Encoded as
// AdvSimdThreeSame Q=1, size=11, opcode=01011, U=1.  Combines UQSHL.2D
// positive arm (shift-then-back-shift overflow + saturate-to-UINT64_MAX)
// with URSHL.2D negative arm (overflow-safe rounding + dedicated |sh|=64
// bit-63-only branch).
constexpr uint32_t UqrshlVec2D(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x6EE05C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DEncodingMatchesLlvmMc) {
  // `uqrshl v0.2d, v1.2d, v2.2d` = 0x6ee25c20.
  EXPECT_EQ(UqrshlVec2D(0, 1, 2), 0x6ee25c20u);
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DLeftSmallNoSaturationJit) {
  // Lane 0: 0x1 << 8 = 0x100.  Lane 1: 0x2 << 16 = 0x20000.  No saturation
  // (back-shift recovers original a in both lanes).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0x2ULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0x1ULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{16}) << 64) |
                     static_cast<__uint128_t>(uint64_t{8});
  static const uint32_t code[] = {UqrshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0x100ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0x20000ULL});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DLeftSaturatesBothLanesJit) {
  // Lane 0: 0xFFFF_FFFF_FFFF_FFFF << 1 → saturates to UINT64_MAX
  // (back-shift gives 0x7FFF…FF ≠ original; overflow detected).
  // Lane 1: 0x8000_0000_0000_0000 << 1 → saturates to UINT64_MAX (bit 63
  // pushed off the top; back-shift gives 0).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0x8000000000000000ULL})
                      << 64) |
                     static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFFFULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{1}) << 64) |
                     static_cast<__uint128_t>(uint64_t{1});
  static const uint32_t code[] = {UqrshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            uint64_t{0xFFFFFFFFFFFFFFFFULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64),
            uint64_t{0xFFFFFFFFFFFFFFFFULL});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DLeftBy64SaturatesBothJit) {
  // sh = 64 both lanes: non-zero a saturates to UINT64_MAX; zero a stays 0.
  // Lane 0: a = 0 → 0 (L_zero branch).  Lane 1: a = 1 → UINT64_MAX.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0x1ULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0x0ULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{64}) << 64) |
                     static_cast<__uint128_t>(uint64_t{64});
  static const uint32_t code[] = {UqrshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64),
            uint64_t{0xFFFFFFFFFFFFFFFFULL});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DRightRoundedMixedLanesJit) {
  // Lane 0: a = 31, sh = -1.  (31 >>u 1) + ((31 >>u 0) & 1) = 15 + 1 = 16.
  // Lane 1: a = 0x100, sh = -4.  (0x100 >>u 4) + ((0x100 >>u 3) & 1)
  //   = 0x10 + 0 = 0x10.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0x100ULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0x1FULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xFCULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0xFFULL});
  static const uint32_t code[] = {UqrshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0x10ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0x10ULL});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DRightNoOverflowAtUintMaxJit) {
  // Both lanes a = UINT64_MAX, sh = -1.  Naive
  //   (UINT64_MAX + (1<<0)) >>u 1
  // would wrap during the bias addition (UINT64_MAX + 1 = 0).  The
  // overflow-safe identity used by the recipe gives
  //   (UINT64_MAX >>u 1) + ((UINT64_MAX >>u 0) & 1) = 2^63 - 1 + 1 = 2^63.
  // Verified that bit 63 is preserved (no truncation, no saturation —
  // saturation only on left-shift quadrant).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFFFULL})
                      << 64) |
                     static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFFFULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xFFULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0xFFULL});
  static const uint32_t code[] = {UqrshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            uint64_t{0x8000000000000000ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64),
            uint64_t{0x8000000000000000ULL});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DRightBy64RoundBitOnlyJit) {
  // sh = -64 both lanes: result = (a >>u 63) — bit 63 of a only.
  // Lane 0: a bit63=1 → 1.  Lane 1: a bit63=0 → 0.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0x7FFFFFFFFFFFFFFFULL})
                      << 64) |
                     static_cast<__uint128_t>(uint64_t{0x8000000000000000ULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xC0ULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0xC0ULL});
  static const uint32_t code[] = {UqrshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{1});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DRightBy65ZeroJit) {
  // sh = -65 both lanes: |sh|>=65 → 0 (rounding term dominates per ARM ARM).
  // sh byte = 0xBF (-65 sign-extended).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFFFULL})
                      << 64) |
                     static_cast<__uint128_t>(uint64_t{0x8000000000000000ULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xBFULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0xBFULL});
  static const uint32_t code[] = {UqrshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DPerLaneIndependentJit) {
  // Cross-lane independence with distinct quadrants — saturation in one
  // lane must not bleed into the rounding-arm computation of the other.
  // Lane 0: a = UINT64_MAX, sh = 1 → saturates to UINT64_MAX.
  // Lane 1: a = 0x100, sh = -4 → 0x10 (rounded, no saturation possible).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0x100ULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFFFULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xFCULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0x1ULL});
  static const uint32_t code[] = {UqrshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            uint64_t{0xFFFFFFFFFFFFFFFFULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0x10ULL});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2DUpperBytesOfShiftIgnoredJit) {
  // Per-lane shift uses only the LOW byte of Vm[lane*8:lane*8+8]; upper 7
  // bytes per lane ignored.  Same invariant as URSHL.2D / UQSHL.2D /
  // SQSHL.2D / SRSHL.2D variants.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint64_t{0x2ULL}) << 64) |
                     static_cast<__uint128_t>(uint64_t{0x1ULL});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint64_t{0xBADBADBADBADBA08ULL})
                      << 64) |
                     static_cast<__uint128_t>(uint64_t{0xDEADBEEFCAFEBA04ULL});
  static const uint32_t code[] = {UqrshlVec2D(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0x10ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0x200ULL});
}

// UQRSHL .2S / .4S vector forms (per-lane unsigned
// saturating rounded variable shift across 32-bit lanes).  Encoded as
// AdvSimdThreeSame Q={0,1}, size=10, opcode=01011, U=1.  Same quadrant
// structure as UQRSHL.2D but with width-32 thresholds and a Q=0 Vd[127:64]
// zero-extend after the lane loop.
constexpr uint32_t UqrshlVec2S(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x2EA05C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}
constexpr uint32_t UqrshlVec4S(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x6EA05C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2S4SEncodingsMatchLlvmMc) {
  // `uqrshl v0.2s, v1.2s, v2.2s` = 0x2ea25c20.
  // `uqrshl v0.4s, v1.4s, v2.4s` = 0x6ea25c20.
  EXPECT_EQ(UqrshlVec2S(0, 1, 2), 0x2ea25c20u);
  EXPECT_EQ(UqrshlVec4S(0, 1, 2), 0x6ea25c20u);
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2SSaturationPivotSentinelJit) {
  // Positive-arm back-shift overflow check at width-32:
  // Lane 0: a=0x80000000 sh=1 -> (0x80000000<<1)=0x100000000, back-shift
  //         (uint32_t)(0x100000000>>1) = 0, != original 0x80000000 -> overflow
  //         -> saturate to UINT32_MAX (0xFFFFFFFF).
  // Lane 1: a=0x7FFFFFFF sh=1 -> (0x7FFFFFFF<<1)=0xFFFFFFFE, back-shift
  //         (uint32_t)(0xFFFFFFFE>>1) = 0x7FFFFFFF, == original -> no
  //         overflow -> result 0xFFFFFFFE.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0x80000000u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x7FFFFFFFu});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0x1u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x1u});
  static const uint32_t code[] = {UqrshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0xFFFFFFFFULL} << 32) | uint64_t{0xFFFFFFFEULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2SRightNoOverflowAtUintMaxJit) {
  // Negative-arm overflow-safe rounding identity at the UINT32_MAX boundary:
  // a=UINT32_MAX sh=-1 -> (UINT32_MAX>>u 1) + ((UINT32_MAX>>u 0) & 1)
  //                      = 0x7FFFFFFF + 1 = 0x80000000.  Same as URSHL.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0xFFFFFFFFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xFFFFFFFFu});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0xFFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xFFu});  // sh = -1 (signed byte).
  static const uint32_t code[] = {UqrshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x80000000ULL} << 32) | uint64_t{0x80000000ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2SLeftBy32MixedZeroNonzeroJit) {
  // Positive-arm sh==32: lane 0 a=0 -> 0; lane 1 a=UINT32_MAX -> UINT32_MAX.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0xFFFFFFFFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x0u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0x20u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x20u});  // sh = 32.
  static const uint32_t code[] = {UqrshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0xFFFFFFFFULL} << 32) | uint64_t{0x0ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2SRightBy32RoundBitOnlyJit) {
  // |sh|=32 round-bit-alone branch (bit 31 of a):
  // Lane 0 a=0x80000000 -> 1.  Lane 1 a=0x7FFFFFFF -> 0.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0x7FFFFFFFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x80000000u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0xE0u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xE0u});  // sh = -32.
  static const uint32_t code[] = {UqrshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x0ULL} << 32) | uint64_t{0x1ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2SRightBy33ZeroJit) {
  // |sh|>32 collapse-to-zero: a=0xDEADBEEF sh=-33 -> 0 (both lanes).
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0xDEADBEEFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xDEADBEEFu});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0xDFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xDFu});  // sh = -33.
  static const uint32_t code[] = {UqrshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]), uint64_t{0});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec4SMixedQuadrantsAllLanesJit) {
  // Q=1 four-lane population with mixed saturation + rounding quadrants:
  // lane 0: a=0x80000000 sh=1 -> overflow saturate to UINT32_MAX (0xFFFFFFFF).
  // lane 1: a=UINT32_MAX  sh=-1 -> (UINT32_MAX>>u 1)+1 = 0x80000000.
  // lane 2: a=1           sh=3 -> 8.
  // lane 3: a=3           sh=-1 -> (3>>u 1)+((3>>u 0)&1) = 1+1 = 2.
  state_.cpu.v[1] =
      (static_cast<__uint128_t>(uint32_t{0x3u}) << 96) |
      (static_cast<__uint128_t>(uint32_t{0x1u}) << 64) |
      (static_cast<__uint128_t>(uint32_t{0xFFFFFFFFu}) << 32) |
       static_cast<__uint128_t>(uint32_t{0x80000000u});
  state_.cpu.v[2] =
      (static_cast<__uint128_t>(uint32_t{0xFFu}) << 96) |
      (static_cast<__uint128_t>(uint32_t{0x3u}) << 64) |
      (static_cast<__uint128_t>(uint32_t{0xFFu}) << 32) |
       static_cast<__uint128_t>(uint32_t{0x1u});  // sh = {1, -1, 3, -1}.
  static const uint32_t code[] = {UqrshlVec4S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x80000000ULL} << 32) | uint64_t{0xFFFFFFFFULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64),
            (uint64_t{0x2ULL} << 32) | uint64_t{0x8ULL});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2SUpperHalfZeroedJit) {
  // Q=0 Vd[127:64] zero-extend invariant.  Pre-set Vd = all-ones, then
  // no-op UQRSHL .2S with sh=0 leaves Vd[63:0] = Vn[63:0] and Vd[127:64] = 0.
  state_.cpu.v[0] = ~static_cast<__uint128_t>(0);
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0xCAFEBABEu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xDEADBEEFu});
  state_.cpu.v[2] = 0;  // sh = 0 (both lanes).
  static const uint32_t code[] = {UqrshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0xCAFEBABEULL} << 32) | uint64_t{0xDEADBEEFULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2SPerLaneIndependentJit) {
  // Cross-lane independence: lane 0 in positive saturation quadrant; lane 1
  // in rounded right-shift quadrant.  `scratch` reuse across the two arms
  // doesn't leak state.
  // Lane 0: a=0x80000000 sh=1 -> saturate to UINT32_MAX.
  // Lane 1: a=0xFFFFFFFD sh=-1 -> (0xFFFFFFFD>>u 1)+((0xFFFFFFFD>>u 0)&1)
  //                              = 0x7FFFFFFE + 1 = 0x7FFFFFFF.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0xFFFFFFFDu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x80000000u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0xFFu}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x1u});
  static const uint32_t code[] = {UqrshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x7FFFFFFFULL} << 32) | uint64_t{0xFFFFFFFFULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

TEST_F(Arm64LiteTranslateRegionTest, UqrshlVec2SUpperBytesOfShiftIgnoredJit) {
  // Per-lane shift uses only the LOW byte of Vm[lane*4:lane*4+4]; upper 3
  // bytes per lane ignored.
  state_.cpu.v[1] = (static_cast<__uint128_t>(uint32_t{0x2u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0x1u});
  state_.cpu.v[2] = (static_cast<__uint128_t>(uint32_t{0xBADBA008u}) << 32) |
                     static_cast<__uint128_t>(uint32_t{0xDEADBE04u});
  static const uint32_t code[] = {UqrshlVec2S(0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0]),
            (uint64_t{0x200ULL} << 32) | uint64_t{0x10ULL});
  EXPECT_EQ(static_cast<uint64_t>(state_.cpu.v[0] >> 64), uint64_t{0});
}

// SQRSHL.2D vector form (per-lane signed saturating
// rounded variable shift across two 64-bit lanes).  Encoded as
// AdvSimdThreeSame Q=1, size=11, opcode=01011, U=0.  Combines SQSHL.2D
// positive arm (SAR-back-shift overflow detector + sign-broadcast
// XOR-with-INT64_MAX saturation picker) with SRSHL.2D negative arm
// (overflow-safe rounding identity with SAR data shift + SHR round-bit
// extract; |sh|>=64 collapses to zero, NO dedicated |sh|=64 branch).
constexpr uint32_t SqrshlVec2D(uint8_t rd, uint8_t rn, uint8_t rm) {
  return 0x4EE05C00u | (static_cast<uint32_t>(rm) << 16) |
         (static_cast<uint32_t>(rn) << 5) | rd;
}

