  // round_bit = (UINT64_MAX >>u 0) & 1 = 1; sum = 0x8000_..._0000.
  state_.cpu.v[1] = static_cast<__uint128_t>(uint64_t{0xFFFFFFFFFFFFFFFFULL});
  state_.cpu.v[2] = static_cast<__uint128_t>(uint64_t{0xFFULL});  // -1
