// EXT q=1 with odd imm4 — regression pins for the decoder dispatch bug
// where EXT was mis-routed to AdvSimdPermute (UZP/TRN/ZIP) when imm4
// had its low bit set (bit 11 of the encoding = 1).  AdvSimdPermute's
// predicate matched on bits[11:10]=10 without checking bit 29, but
// Permute requires bit 29 = 0 while EXT has bit 29 = 1.  Fixed in
// decoder.h:AdvSIMD permute dispatch.
constexpr uint32_t kExtVec16B_idx1  = 0x6e020820;  // ext v0.16b, v1.16b, v2.16b, #1
constexpr uint32_t kExtVec16B_idx7  = 0x6e023820;  // ext v0.16b, v1.16b, v2.16b, #7
constexpr uint32_t kExtVec16B_idx15 = 0x6e027820;  // ext v0.16b, v1.16b, v2.16b, #15

TEST_F(Arm64LiteTranslateRegionTest, ExtVec16BIdx1OddImm) {
  uint8_t vn[16] = {0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17,
                    0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F};
  uint8_t vm[16] = {0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27,
                    0x28, 0x29, 0x2A, 0x2B, 0x2C, 0x2D, 0x2E, 0x2F};
  std::memcpy(&state_.cpu.v[1], vn, 16);
  std::memcpy(&state_.cpu.v[2], vm, 16);
  std::memset(&state_.cpu.v[0], 0xAA, 16);
  static const uint32_t code[] = {kExtVec16B_idx1};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  // Result = Vn[1..15] || Vm[0].
  for (int i = 0; i < 15; ++i) EXPECT_EQ(r[i], vn[1 + i]) << "byte " << i;
  EXPECT_EQ(r[15], vm[0]) << "byte 15";
}

TEST_F(Arm64LiteTranslateRegionTest, ExtVec16BIdx7OddImm) {
  uint8_t vn[16] = {0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17,
                    0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F};
  uint8_t vm[16] = {0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27,
                    0x28, 0x29, 0x2A, 0x2B, 0x2C, 0x2D, 0x2E, 0x2F};
  std::memcpy(&state_.cpu.v[1], vn, 16);
  std::memcpy(&state_.cpu.v[2], vm, 16);
  std::memset(&state_.cpu.v[0], 0xAA, 16);
  static const uint32_t code[] = {kExtVec16B_idx7};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  // Result = Vn[7..15] || Vm[0..6].
  for (int i = 0; i < 9; ++i) EXPECT_EQ(r[i], vn[7 + i]) << "byte " << i;
  for (int i = 9; i < 16; ++i) EXPECT_EQ(r[i], vm[i - 9]) << "byte " << i;
}

TEST_F(Arm64LiteTranslateRegionTest, ExtVec16BIdx15OddImm) {
  uint8_t vn[16] = {0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17,
                    0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F};
  uint8_t vm[16] = {0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27,
                    0x28, 0x29, 0x2A, 0x2B, 0x2C, 0x2D, 0x2E, 0x2F};
  std::memcpy(&state_.cpu.v[1], vn, 16);
  std::memcpy(&state_.cpu.v[2], vm, 16);
  std::memset(&state_.cpu.v[0], 0xAA, 16);
  static const uint32_t code[] = {kExtVec16B_idx15};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  // Result = Vn[15] || Vm[0..14].
  EXPECT_EQ(r[0], vn[15]) << "byte 0";
  for (int i = 1; i < 16; ++i) EXPECT_EQ(r[i], vm[i - 1]) << "byte " << i;
}

// DUP (general) q=0 vector JIT
// DUP Vd.8B, Wn / DUP Vd.2S, Wn — broadcast a GP register to the lower
// 64 bits of Vd and zero the upper 64 bits per ARM D-register semantics.
// The Q=1 forms (.16B / .4S / .2D) are already covered by MemsetPattern
// and friends; these tests pin the new Q=0 path including the shared
// PSLLDQ-8 / PSRLDQ-8 upper-zero tail.
constexpr uint32_t kDupGenVec8B_W0 = 0x0e010c00;  // dup v0.8b, w0
constexpr uint32_t kDupGenVec8B_W7 = 0x0e010ce0;  // dup v0.8b, w7
constexpr uint32_t kDupGenVec2S_W0 = 0x0e040c00;  // dup v0.2s, w0
constexpr uint32_t kDupGenVec2S_W7 = 0x0e040ce0;  // dup v0.2s, w7
constexpr uint32_t kDupGenVec4H_W0 = 0x0e020c00;  // dup v0.4h, w0
constexpr uint32_t kDupGenVec8H_W0 = 0x4e020c00;  // dup v0.8h, w0
constexpr uint32_t kDupGenVec8H_W7 = 0x4e020ce0;  // dup v0.8h, w7

TEST_F(Arm64LiteTranslateRegionTest, DupGenVec8B_FromW0) {
  // dup v0.8b, w0  — fills v0[0..7] with byte 0xAB; v0[8..15] = 0.
  std::memset(&state_.cpu.v[0], 0xCC, 16);  // sentinel: must be overwritten
  state_.cpu.x[0] = 0x123456789abcdeabULL;   // low byte = 0xAB
  static const uint32_t code[] = {kDupGenVec8B_W0};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  for (int i = 0; i < 8; ++i) EXPECT_EQ(r[i], 0xABu) << "lower byte " << i;
  for (int i = 8; i < 16; ++i) EXPECT_EQ(r[i], 0u) << "upper byte " << i;
}

TEST_F(Arm64LiteTranslateRegionTest, DupGenVec8B_FromW7_ZeroByte) {
  // dup v0.8b, w7  — w7 low byte = 0; v0[0..7] = 0; v0[8..15] = 0.
  // Pre-seeds v0 with non-zero garbage so a stuck upper-half zeroing
  // would surface as a sentinel leak.
  std::memset(&state_.cpu.v[0], 0xFE, 16);
  state_.cpu.x[7] = 0xDEADBEEFCAFE0000ULL;  // low byte = 0x00
  static const uint32_t code[] = {kDupGenVec8B_W7};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  for (int i = 0; i < 16; ++i) EXPECT_EQ(r[i], 0u) << "byte " << i;
}

TEST_F(Arm64LiteTranslateRegionTest, DupGenVec2S_FromW0) {
  // dup v0.2s, w0  — fills v0.s[0] and v0.s[1] with 0xDEADBEEF;
  // v0.s[2] and v0.s[3] zeroed.
  std::memset(&state_.cpu.v[0], 0xAA, 16);
  state_.cpu.x[0] = 0x11223344DEADBEEFULL;  // low 32 bits = 0xDEADBEEF
  static const uint32_t code[] = {kDupGenVec2S_W0};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint32_t r[4];
  std::memcpy(r, &state_.cpu.v[0], 16);
  EXPECT_EQ(r[0], 0xDEADBEEFu) << "low s lane 0";
  EXPECT_EQ(r[1], 0xDEADBEEFu) << "low s lane 1";
  EXPECT_EQ(r[2], 0u) << "upper s lane 2";
  EXPECT_EQ(r[3], 0u) << "upper s lane 3";
}

TEST_F(Arm64LiteTranslateRegionTest, DupGenVec2S_FromW7) {
  // dup v0.2s, w7  — same as above but sourcing from x7 to exercise
  // the Rn != 0 path.  Upper half of x7 (above bit 31) must be
  // ignored by Movd; if it were Movq instead, the upper-zero tail
  // would still zero v0.s[2..3] correctly, but this test pins the
  // intended truncation semantics.
  std::memset(&state_.cpu.v[0], 0x33, 16);
  state_.cpu.x[7] = 0xFFFFFFFF12345678ULL;  // low 32 bits = 0x12345678
  static const uint32_t code[] = {kDupGenVec2S_W7};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint32_t r[4];
  std::memcpy(r, &state_.cpu.v[0], 16);
  EXPECT_EQ(r[0], 0x12345678u) << "low s lane 0";
  EXPECT_EQ(r[1], 0x12345678u) << "low s lane 1";
  EXPECT_EQ(r[2], 0u) << "upper s lane 2";
  EXPECT_EQ(r[3], 0u) << "upper s lane 3";
}

TEST_F(Arm64LiteTranslateRegionTest, DupGenVec4H_FromW0) {
  // dup v0.4h, w0  — broadcast low halfword of w0 to v0.h[0..3];
  // v0.h[4..7] (upper 64 bits) zeroed per ARM D-register semantics.
  // Pre-seeds v0 so a missing upper-zero would leak the sentinel.
  std::memset(&state_.cpu.v[0], 0x77, 16);
  state_.cpu.x[0] = 0xDEADBEEF0000BEEFULL;  // low halfword = 0xBEEF
  static const uint32_t code[] = {kDupGenVec4H_W0};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint16_t r[8];
  std::memcpy(r, &state_.cpu.v[0], 16);
  for (int i = 0; i < 4; ++i) EXPECT_EQ(r[i], 0xBEEFu) << "low h lane " << i;
  for (int i = 4; i < 8; ++i) EXPECT_EQ(r[i], 0u) << "upper h lane " << i;
}

TEST_F(Arm64LiteTranslateRegionTest, DupGenVec8H_FromW0) {
  // dup v0.8h, w0  — broadcast low halfword of w0 to all 8 h lanes
  // (Q=1, no upper-zero tail).
  std::memset(&state_.cpu.v[0], 0xCC, 16);
  state_.cpu.x[0] = 0x123456780000ABCDULL;  // low halfword = 0xABCD
  static const uint32_t code[] = {kDupGenVec8H_W0};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint16_t r[8];
  std::memcpy(r, &state_.cpu.v[0], 16);
  for (int i = 0; i < 8; ++i) EXPECT_EQ(r[i], 0xABCDu) << "h lane " << i;
}

TEST_F(Arm64LiteTranslateRegionTest, DupGenVec8H_FromW7_HighBitsIgnored) {
  // dup v0.8h, w7 with x7 having garbage in bits[31:16] — DUP general
  // only consumes the low 16 bits of Wn for the H form, so the upper
  // 16 bits of the 32-bit source must be ignored.  This pins that
  // Pshuflw imm=0 selects halfword[0] (xmm bits[15:0]) and not a
  // higher-numbered halfword that could have caught a stale value
  // from the GP move.
  std::memset(&state_.cpu.v[0], 0x55, 16);
  state_.cpu.x[7] = 0xFFFFFFFFAAAA1234ULL;  // bits[15:0] = 0x1234; bits[31:16] = 0xAAAA
  static const uint32_t code[] = {kDupGenVec8H_W7};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint16_t r[8];
  std::memcpy(r, &state_.cpu.v[0], 16);
  for (int i = 0; i < 8; ++i) EXPECT_EQ(r[i], 0x1234u) << "h lane " << i;
}

// __memset_aarch64 1024-byte zero-fill reproduction.
//
// Reproduces the path Bionic's linker takes when scrubbing a freshly
// re-allocated 1024-byte chunk from BionicSmallObjectAllocator.  That chunk
// backs the ZIP central-directory hash table (calloc-allocated, with the
// linker's calloc proxying directly to BionicAllocator::alloc — see
// __dl_calloc at linker64+0x99f44 — without an extra memset; the small-
// object allocator's own per-block memset is the only zeroing pass).
//
// Earlier debugging traced the VkCapsViewer splash hang to that table containing
// non-zero garbage after allocation: every probed bucket showed leftover
// heap content with `top12bits == 0` and a non-zero lower 20 bits, which
// AddToMap can never produce for a real ZIP entry.  That signature is what
// you get when the 1024-byte zero pass over the chunk silently drops a
// scattering of writes.
//
// The instruction sequence below is taken verbatim from
// __dl___memset_aarch64+0xa4..+0x118 (the big-size, non-DC-ZVA fallback at
// linker64+0x49d60 onward, joined to the 0x49db8 entry that Berberis
// reaches because the DCZID_EL0 ZVA check fails).  Pre-fills the buffer
// with 0xdeadbeef so any missed store leaks the sentinel.
TEST_F(Arm64LiteTranslateRegionTest, MemsetAarch64_1024ByteZeroFill_Unrolled) {
  // Unrolled variant: replaces the b.hi loop with 15 inline iterations so the
  // test runs end-to-end in one JIT region (the framework's allow_dispatch=
  // false setting otherwise stops after the first backward-branch exit).
  // If every individual STR Q / STP Q / DUP V translation is correct, the
  // buffer is fully zeroed; any silently-dropped store leaks the 0xdeadbeef
  // sentinel byte-by-byte.  This is what __memset_aarch64 ends up doing on
  // a 1024-byte zero fill: 2 head STRs, 15 main-loop iterations each writing
  // 64 bytes via 2 paired-Q STPs, then 2 tail STPs.
  static constexpr size_t kSize = 1024;
  alignas(16) static uint8_t buffer[kSize];
  for (size_t i = 0; i < kSize / 4; ++i) {
    reinterpret_cast<uint32_t*>(buffer)[i] = 0xdeadbeefU;
  }

  // stp q0, q0, [x3, #0x20]:  0xAD010060
  // stp q0, q0, [x3, #0x40]:  0xAD020060
  // add x3, x3, #0x40:        0x91010063
  // stp q0, q0, [x4, #-0x40]: 0xAD3E0080
  // stp q0, q0, [x4, #-0x20]: 0xAD3F0080
  static const uint32_t code[] = {
      0x4e010c20,  // dup v0.16b, w1
      0x8b020004,  // add x4, x0, x2
      0x927cec03,  // and x3, x0, #~0xf
      0x3d800000,  // str q0, [x0]
      0x3d800460,  // str q0, [x3, #0x10]
      // iter 0
      0xad010060, 0xad020060, 0x91010063,
      // iter 1
      0xad010060, 0xad020060, 0x91010063,
      // iter 2
      0xad010060, 0xad020060, 0x91010063,
      // iter 3
      0xad010060, 0xad020060, 0x91010063,
      // iter 4
      0xad010060, 0xad020060, 0x91010063,
      // iter 5
      0xad010060, 0xad020060, 0x91010063,
      // iter 6
      0xad010060, 0xad020060, 0x91010063,
      // iter 7
      0xad010060, 0xad020060, 0x91010063,
      // iter 8
      0xad010060, 0xad020060, 0x91010063,
      // iter 9
      0xad010060, 0xad020060, 0x91010063,
      // iter 10
      0xad010060, 0xad020060, 0x91010063,
      // iter 11
      0xad010060, 0xad020060, 0x91010063,
      // iter 12
      0xad010060, 0xad020060, 0x91010063,
      // iter 13
      0xad010060, 0xad020060, 0x91010063,
      // iter 14
      0xad010060, 0xad020060, 0x91010063,
      0xad3e0080,  // stp q0, q0, [x4, #-0x40]
      0xad3f0080,  // stp q0, q0, [x4, #-0x20]
  };

  state_.cpu.x[0] = ToGuestAddr(buffer);
  state_.cpu.x[1] = 0;
  state_.cpu.x[2] = kSize;

  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));

  size_t first_nonzero = kSize;
  for (size_t i = 0; i < kSize; ++i) {
    if (buffer[i] != 0u) {
      first_nonzero = i;
      break;
    }
  }
  EXPECT_EQ(first_nonzero, kSize)
      << "first non-zero byte at offset " << first_nonzero
      << " (value 0x" << std::hex
      << static_cast<unsigned>(buffer[first_nonzero == kSize ? 0 : first_nonzero])
      << "); buffer must be fully zeroed";
}

// dispatch-enabled b.hi memset loop (VkCaps regression)
//
// Companion to MemsetAarch64_1024ByteZeroFill_Unrolled above.  That test
// inlines the loop body 15 times so the whole memset runs in a single JIT
// region with the framework's default allow_dispatch=false.  Production sets
// allow_dispatch=true (runtime/arm64/translator_x86_64.cc), so the backward
// b.hi at __memset_aarch64+0x10c becomes a region exit + EmitDirectDispatch
// per iteration: each iteration's tail spills mapped guest regs via
// StoreMappedRegs(), mirrors MXCSR->FPSR (gated on fp_dirty_), Movq's the
// target guest PC into rax, and re-enters the dispatcher; the dispatcher's
// TranslationCache lookup for the loop-body PC finds the cached region and
// jumps right back in.  If anything that path drops — a stale q0/x3/x2
// mapping, a CodePool collision, a wrong NZCV save/restore around the
// dispatcher's signal check, etc. — a fraction of the 64-byte stores per
// iteration are lost.  That matches the bucket-corruption signature
// (top12==0, low20!=0) observed in earlier debugging: a freshly calloc'd
// 1024-byte ZipStringOffset20 bucket table comes out partially zeroed.
//
// This test installs the loop body as a real TranslationCache entry so
// EmitDirectDispatch's lookup for the b.hi target hits the same region and
// the loop iterates via the production dispatch path, not by inlining.
class Arm64LiteTranslateRegionDispatchTest : public ::testing::Test {
 public:
  template <typename T>
  bool RunWithDispatch(const T& code, GuestAddr expected_stop_addr) {
    state_.cpu.insn_addr = ToGuestAddr(code);
    GuestAddr code_start = ToGuestAddr(code);
    GuestAddr code_end = ToGuestAddr(bit_cast<char*>(&code[0]) + sizeof(code));
    MachineCode machine_code;
    auto [success, stop_pc] = TryLiteTranslateRegion(state_.cpu.insn_addr,
                                                     &machine_code,
                                                     LiteTranslateParams{
                                                         .end_pc = code_end,
                                                         .allow_dispatch = true,
                                                     });
    if (!success || (stop_pc > code_end)) {
      return false;
    }

    auto* cache = TranslationCache::GetInstance();
    GuestCodeEntry* entry = cache->AddAndLockForTranslation(code_start, 0);
    if (!entry) {
      return false;
    }
    HostCodeAddr host_code = GetDefaultCodePoolInstance()->Add(&machine_code);
    size_t region_size = stop_pc - code_start;
    cache->SetTranslatedAndUnlock(code_start,
                                  entry,
                                  static_cast<uint32_t>(region_size),
                                  GuestCodeEntry::Kind::kLiteTranslated,
                                  {host_code, machine_code.install_size()});

    TestingRunGeneratedCode(&state_, AsHostCode(host_code), expected_stop_addr);
    EXPECT_EQ(state_.cpu.insn_addr, expected_stop_addr);

    // Drop the cache entry so subsequent tests at the same PC start fresh
    // and aren't subject to stale state from a previous test run.
    cache->InvalidateGuestRange(code_start, code_end);
    return true;
  }

  // translate every region inside [code, code+sizeof(code))
  // by walking forward from code[0] and re-translating from each region's
  // stop_pc until end-of-code is reached.  Dispatch back-edges between
  // regions then resolve via TranslationCache lookups, letting the loop
  // iterate to natural termination.
  template <typename T>
  bool RunMultiRegion(const T& code, GuestAddr expected_stop_addr) {
    state_.cpu.insn_addr = ToGuestAddr(code);
    GuestAddr code_start = ToGuestAddr(code);
    GuestAddr code_end = ToGuestAddr(bit_cast<char*>(&code[0]) + sizeof(code));
    auto* cache = TranslationCache::GetInstance();

    HostCodeAddr first_host_code = 0;
    GuestAddr cur = code_start;
    while (cur < code_end) {
      MachineCode machine_code;
      auto [success, stop_pc] = TryLiteTranslateRegion(cur,
                                                       &machine_code,
                                                       LiteTranslateParams{
                                                           .end_pc = code_end,
                                                           .allow_dispatch = true,
                                                       });
      if (!success || (stop_pc > code_end) || stop_pc == cur) {
        return false;
      }
      GuestCodeEntry* entry = cache->AddAndLockForTranslation(cur, 0);
      if (!entry) {
        return false;
      }
      HostCodeAddr host_code = GetDefaultCodePoolInstance()->Add(&machine_code);
      size_t region_size = stop_pc - cur;
      cache->SetTranslatedAndUnlock(cur,
                                    entry,
                                    static_cast<uint32_t>(region_size),
                                    GuestCodeEntry::Kind::kLiteTranslated,
                                    {host_code, machine_code.install_size()});
      if (cur == code_start) {
        first_host_code = host_code;
      }
      cur = stop_pc;
    }

    TestingRunGeneratedCode(&state_, AsHostCode(first_host_code), expected_stop_addr);
    EXPECT_EQ(state_.cpu.insn_addr, expected_stop_addr);

    cache->InvalidateGuestRange(code_start, code_end);
    return true;
  }

 protected:
  ThreadState state_{};
};

// Full guest-state JIT-vs-interpreter differential for libmaplibre's getAPIBaseUrl
// SSO destructor-guard region, run via the REAL dispatch path (allow_dispatch=true,
// EmitDirectDispatch chaining through the TranslationCache) — the configuration
// the device uses. On-device whole-library bisection (interpret one library /
// offset window at a time, JIT the rest) cleanly localized the "from_bytes error"
// crash to JIT of exactly this region. The allow_dispatch=false Run() differential
// showed identical state, so this exercises the one untested variable: dispatch.
TEST_F(Arm64LiteTranslateRegionDispatchTest, MaplibreSsoDtorRegionDispatchFullStateDiff) {
  static const uint32_t code[] = {
      0x394003e8,  // ldrb w8, [sp]
      0x36000068,  // tbz  w8, #0, +0xc   (short string -> skip ldr+bl)
      0xf9400be0,  // ldr  x0, [sp, #0x10]
      0x94184ba2,  // bl   <operator delete>
  };
  static const uint64_t kInit[31] = {
      0x7eb8e083cfc0, 0x7eb7918eee00, 0x000000000000001f, 0x7eb99081f960,
      0x7eb8e083cc4f, 0x7eb8e083cfdf, 0x000000000010ffff, 0x0000000000000000,
      0x0000000000000018, 0x0000000000000000, 0x0000000000000000, 0x0000000000000000,
      0x0000000000000005, 0x7eb790bffe92, 0x0000000000000000, 0x0000000000000000,
      0x7eb6fd013cc0, 0x7eb7918eadd8, 0x7eb78f400000, 0x7eb91083d310,
      0x7eb790bfff68, 0x7ebaebb4b040, 0x7eb790bfff10, 0x0000000000000000,
      0x0000000000000000, 0x0000000000000000, 0x0000000000000000, 0x0000000000000000,
      0x0000000000000000, 0x7eb790bfff30, 0x7eb6fc9aec9c,
  };
  constexpr size_t kStkSize = 512;
  alignas(16) static uint8_t stk[kStkSize];
  auto setup = [&]() {
    memset(&state_.cpu, 0, sizeof(CPUState));
    for (int i = 0; i < 31; i++) state_.cpu.x[i] = kInit[i];
    memset(stk, 0xCD, sizeof(stk));
    uint64_t sp = ToGuestAddr(stk) + 256;
    *reinterpret_cast<uint8_t*>(sp) = 0x18;
    *reinterpret_cast<uint64_t*>(sp + 0x10) = 0xCAFEF00DDEADBEEFULL;
    state_.cpu.sp = sp;
  };

  GuestAddr code_start = ToGuestAddr(code);
  GuestAddr code_end = code_start + sizeof(code);  // == tbz target (586cac)

  // --- JIT run via the real dispatch path ---
  setup();
  state_.cpu.insn_addr = code_start;
  MachineCode machine_code;
  auto [success, stop_pc] = TryLiteTranslateRegion(
      code_start, &machine_code, LiteTranslateParams{.end_pc = code_end, .allow_dispatch = true});
  ASSERT_TRUE(success);
  auto* cache = TranslationCache::GetInstance();
  GuestCodeEntry* entry = cache->AddAndLockForTranslation(code_start, 0);
  ASSERT_NE(entry, nullptr);
  HostCodeAddr host_code = GetDefaultCodePoolInstance()->Add(&machine_code);
  cache->SetTranslatedAndUnlock(code_start, entry, static_cast<uint32_t>(stop_pc - code_start),
                                GuestCodeEntry::Kind::kLiteTranslated,
                                {host_code, machine_code.install_size()});
  // Install the tbz target (code_end) as a stop stub so EmitDirectDispatch's
  // chaining lookup resolves and cleanly returns to the harness.
  GuestCodeEntry* tentry = cache->AddAndLockForTranslation(code_end, 0);
  ASSERT_NE(tentry, nullptr);
  cache->SetTranslatedAndUnlock(code_end, tentry, 4, GuestCodeEntry::Kind::kSpecialHandler,
                                {kEntryExitGeneratedCode, 0});

  TestingRunGeneratedCode(&state_, AsHostCode(host_code), code_end);
  CPUState jit;
  memcpy(&jit, &state_.cpu, sizeof(CPUState));
  static uint8_t jit_stk[kStkSize];
  memcpy(jit_stk, stk, kStkSize);
  cache->InvalidateGuestRange(code_start, code_end + 4);

  // --- Interpreter run ---
  setup();
  state_.cpu.insn_addr = code_start;
  InterpretInsn(&state_);  // ldrb
  InterpretInsn(&state_);  // tbz (taken) -> code_end
  CPUState itp;
  memcpy(&itp, &state_.cpu, sizeof(CPUState));
  static uint8_t itp_stk[kStkSize];
  memcpy(itp_stk, stk, kStkSize);

  // --- Diff ---
  EXPECT_EQ(jit.insn_addr, itp.insn_addr) << "insn_addr diverged";
  for (int i = 0; i < 31; i++) {
    EXPECT_EQ(jit.x[i], itp.x[i]) << "x" << i << " diverged: JIT=0x" << std::hex << jit.x[i]
                                  << " INTERP=0x" << itp.x[i];
  }
  EXPECT_EQ(jit.sp, itp.sp) << "sp diverged";
  EXPECT_EQ(jit.flags, itp.flags) << "flags diverged";
  EXPECT_EQ(jit.cached_fpcr, itp.cached_fpcr) << "cached_fpcr diverged";
  EXPECT_EQ(jit.emulated_fpsr, itp.emulated_fpsr) << "emulated_fpsr diverged";
  EXPECT_EQ(jit.reservation_address, itp.reservation_address) << "reservation_address diverged";
  for (int i = 0; i < 32; i++)
    EXPECT_EQ(memcmp(&jit.v[i], &itp.v[i], sizeof(jit.v[i])), 0) << "v" << i << " diverged";
  EXPECT_EQ(memcmp(jit_stk, itp_stk, kStkSize), 0) << "stack memory diverged";
}

TEST_F(Arm64LiteTranslateRegionDispatchTest, MemsetAarch64_1024ByteZeroFill_BhiLoop) {
  // Loop body only — start PC == b.hi target PC, so EmitDirectDispatch's
  // TranslationCache lookup at the backward branch hits the same region.
  // 16 iterations × 64 bytes = 1024 bytes written, starting at +0x20 from
  // the initial x3.
  static const uint32_t code[] = {
      0xad010060,  // [0]  stp q0, q0, [x3, #0x20]
      0xad020060,  // [4]  stp q0, q0, [x3, #0x40]
      0x91010063,  // [8]  add x3, x3, #0x40
      0xf1010042,  // [12] subs x2, x2, #0x40
      0x54ffff88,  // [16] b.hi -16  -> back to [0]
  };

  // Buffer is sized to cover the loop's write range with leading and trailing
  // sentinel guards.  Each iteration writes [x3+0x20, x3+0x60); after 16
  // iterations x3 has advanced by 16*0x40 = 1024 bytes, so the union of
  // written addresses is [buffer+0x20, buffer+0x20+1024) = [32, 1056).
  constexpr size_t kBufferSize = 1088;
  alignas(16) static uint8_t buffer[kBufferSize];
  for (size_t i = 0; i < kBufferSize / sizeof(uint32_t); ++i) {
    reinterpret_cast<uint32_t*>(buffer)[i] = 0xdeadbeefU;
  }

  state_.cpu.x[3] = ToGuestAddr(buffer);
  state_.cpu.x[2] = 1024;
  std::memset(&state_.cpu.v[0], 0, 16);  // v0 = 0 (the value to splat).

  EXPECT_TRUE(RunWithDispatch(code, ToGuestAddr(code) + sizeof(code)));

  // x2 should be 0 (16 iterations of -0x40), x3 should be buffer + 1024.
  EXPECT_EQ(state_.cpu.x[2], 0ULL) << "loop counter must reach zero";
  EXPECT_EQ(state_.cpu.x[3], ToGuestAddr(buffer) + 1024)
      << "x3 must have advanced by 16 * 0x40 bytes";

  // Bytes [32, 1056) must be fully zeroed.  Any non-zero byte means a STP
  // store was dropped — likely because a mapped-register spill or restore
  // around the dispatcher misbehaved between iterations.
  size_t first_nonzero = 1056;
  for (size_t i = 32; i < 1056; ++i) {
    if (buffer[i] != 0u) {
      first_nonzero = i;
      break;
    }
  }
  EXPECT_EQ(first_nonzero, 1056u)
      << "first non-zero byte at offset " << first_nonzero
      << " (iteration " << ((first_nonzero - 32) / 64) << ", value 0x" << std::hex
      << static_cast<unsigned>(buffer[first_nonzero == 1056 ? 32 : first_nonzero])
      << "); the b.hi loop must zero every byte in [32, 1056)";

  // Sentinel sanity: the guard ranges outside the loop's write window must
  // still hold the sentinel.  If these fire, the loop wrote out of bounds.
  EXPECT_EQ(reinterpret_cast<uint32_t*>(buffer)[0], 0xdeadbeefU)
      << "leading sentinel clobbered — loop wrote below x3+0x20";
  EXPECT_EQ(reinterpret_cast<uint32_t*>(buffer)[1056 / sizeof(uint32_t)], 0xdeadbeefU)
      << "trailing sentinel clobbered — loop wrote past x3+0x20+1024";
}

// Full __dl___memset_aarch64 body, from the function entry at linker offset
// 0x49cc0 through the ret at 0x49ddc.  Earlier tests
// (MemsetAarch64_1024ByteZeroFill_Unrolled and _BhiLoop) cover only the
// post-0x49d60 large-size body in isolation.  The VkCaps wedge investigation
// in handoffs -279..-284 has narrowed the wedge to "the 1024-byte
// BionicSmallObjectAllocator slab is not fully zeroed before AddToMap starts
// writing".  The body itself zeroes correctly under multi-region dispatch
// (see the two existing tests), so the next-most-likely cause is the
// prologue at 0x49cc0..0x49cd8 routing wrongly: if the JIT mistranslates
// the b.lo at 0x49ccc or the b.hs at 0x49cd8, the function exits via the
// 16..64-byte path or the small-path return at 0x49cf8, leaving most of
// the buffer untouched.
//
// For size=1024, w1=0, x0=16-aligned, the executed path is:
//   49cc0 bti c
//   49cc4 dup v0.16b, w1                      ; v0 = 16x 0
//   49cc8 cmp x2, #0x10                       ; 1024 >= 16
//   49ccc b.lo +0x34 → 49d00                  ; NOT taken
//   49cd0 add x4, x0, x2                      ; x4 = end of buffer
//   49cd4 cmp x2, #0x40                       ; 1024 >= 64
//   49cd8 b.hs +0x68 → 49d40                  ; TAKEN
//   49d40 and x3, x0, #~0xf                   ; x3 = aligned-down x0
//   49d44 cmp x2, #0x80                       ; 1024 > 128
//   49d48 b.hi +0x18 → 49d60                  ; TAKEN
//   49d60 str q0, [x0]                         ; bytes 0..16
//   49d64 str q0, [x3, #0x10]                 ; bytes 16..32
//   49d68 tst w1, #0xff                       ; w1=0, Z=1
//   49d6c b.ne +0x4c → 49db8                  ; NOT taken
//   49d70 mrs x5, DCZID_EL0                   ; 0x10 on Berberis
//   49d74 and x5, x5, #0x1f                   ; 0x10
//   49d78 cmp x5, #0x4                        ; 0x10 != 0x4
//   49d7c b.ne +0x3c → 49db8                  ; TAKEN
//   49db8 sub x2, x4, x3                      ; remaining size
//   49dbc sub x2, x2, #0x60                   ; -= 96
//   49dc0 stp q0, q0, [x3, #0x20]             ; loop top
//   49dc4 stp q0, q0, [x3, #0x40]
//   49dc8 add x3, x3, #0x40
//   49dcc subs x2, x2, #0x40
//   49dd0 b.hi -0x10 → 49dc0                  ; loops 15x
//   49dd4 stp q0, q0, [x4, #-0x40]             ; final tail
//   49dd8 stp q0, q0, [x4, #-0x20]
//   49ddc ret                                  ; → x30
//
// Layout: the code[] array spans 0x49cc0..0x49ddc.  Each instruction sits at
// its file-relative offset within the buffer, so the b.lo / b.hs / b.hi
// relative branches resolve correctly inside the buffer.  Unreachable slots
// (the small-buffer path and the dc-zva path) are encoded faithfully too,
// so a wrong b.lo/b.hi target lands on real linker instructions and either
// crashes obviously or produces a wrong result.  x30 is set to the address
// just past the end of code[] so the final ret terminates the test cleanly.
// DISABLED because RunMultiRegion walks linearly and does not pre-install a
// region at the b.hi backward-branch target (offset 0x100 / linker 49dc0),
// so the loop's intra-region dispatch fails at run time — a test-framework
// limitation, not a translator bug.  The companion MrsDczidEl0_BneTakenWhenNotFour
// test isolates the actual JIT/decoder bug (sysreg enum mismatch in decoder.h)
// and PASSES after the fix.  Re-enable this test once RunMultiRegion grows
// branch-target region installation, OR rewrite with unrolled iterations.
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       DISABLED_MemsetAarch64_FullBodyFrom0x49cc0_1024ByteZeroFill) {
  static const uint32_t code[] = {
      // 0x49cc0 — prologue
      0xd503245f,  // [0x00] bti c
      0x4e010c20,  // [0x04] dup v0.16b, w1
      0xf100405f,  // [0x08] cmp x2, #0x10
      0x540001a3,  // [0x0c] b.lo +0x34 → 0x40
      0x8b020004,  // [0x10] add x4, x0, x2
      0xf101005f,  // [0x14] cmp x2, #0x40
      0x54000342,  // [0x18] b.hs +0x68 → 0x80
      // 0x49cdc — 16..64-byte path (dead for size=1024)
      0xd2800203,  // [0x1c] mov x3, #0x10
      0x8a420463,  // [0x20] and x3, x3, x2, lsr #1
      0xcb030085,  // [0x24] sub x5, x4, x3
      0x3d800000,  // [0x28] str q0, [x0]
      0x3ca36800,  // [0x2c] str q0, [x0, x3]
      0x3c9f00a0,  // [0x30] stur q0, [x5, #-0x10]
      0x3c9f0080,  // [0x34] stur q0, [x4, #-0x10]
      0xd65f03c0,  // [0x38] ret
      0xd503201f,  // [0x3c] nop (padding)
      // 0x49d00 — small-buffer (<16) path; b.lo target (dead)
      0x8b020004,  // [0x40] add x4, x0, x2
      0xf100105f,  // [0x44] cmp x2, #0x4
      0x54000103,  // [0x48] b.lo +0x20 → 0x68
      0xd343fc43,  // [0x4c] lsr x3, x2, #3
      0xcb030885,  // [0x50] sub x5, x4, x3, lsl #2
      0xbd000000,  // [0x54] str s0, [x0]
      0xbc237800,  // [0x58] str s0, [x0, x3, lsl #2]
      0xbc1fc0a0,  // [0x5c] stur s0, [x5, #-0x4]
      0xbc1fc080,  // [0x60] stur s0, [x4, #-0x4]
      0xd65f03c0,  // [0x64] ret
      // 0x49d28 — sub-4-byte path (dead)
      0xb40000a2,  // [0x68] cbz x2, +0x14 → 0x7c
      0xd341fc43,  // [0x6c] lsr x3, x2, #1
      0x39000001,  // [0x70] strb w1, [x0]
      0x38236801,  // [0x74] strb w1, [x0, x3]
      0x381ff081,  // [0x78] sturb w1, [x4, #-0x1]
      0xd65f03c0,  // [0x7c] ret
      // 0x49d40 — >= 64-byte path; b.hs target (TAKEN)
      0x927cec03,  // [0x80] and x3, x0, #0xfffffffffffffff0
      0xf102005f,  // [0x84] cmp x2, #0x80
      0x540000c8,  // [0x88] b.hi +0x18 → 0xa0
      // 0x49d4c — 64..128-byte path (dead)
      0xad000000,  // [0x8c] stp q0, q0, [x0]
      0xad010000,  // [0x90] stp q0, q0, [x0, #0x20]
      0xad3e0080,  // [0x94] stp q0, q0, [x4, #-0x40]
      0xad3f0080,  // [0x98] stp q0, q0, [x4, #-0x20]
      0xd65f03c0,  // [0x9c] ret
      // 0x49d60 — large-size path; b.hi target (TAKEN)
      0x3d800000,  // [0xa0] str q0, [x0]
      0x3d800460,  // [0xa4] str q0, [x3, #0x10]
      0x72001c3f,  // [0xa8] tst w1, #0xff
      0x54000261,  // [0xac] b.ne +0x4c → 0xf8
      0xd53b00e5,  // [0xb0] mrs x5, DCZID_EL0
      0x924010a5,  // [0xb4] and x5, x5, #0x1f
      0xf10010bf,  // [0xb8] cmp x5, #0x4
      0x540001e1,  // [0xbc] b.ne +0x3c → 0xf8
      // 0x49d80 — dc-zva path (dead for Berberis DCZID=0x10)
      0xad010060,  // [0xc0] stp q0, q0, [x3, #0x20]
      0x927ae403,  // [0xc4] and x3, x0, #0xffffffffffffffc0
      0xcb030082,  // [0xc8] sub x2, x4, x3
      0xd1020042,  // [0xcc] sub x2, x2, #0x80
      0xad3e0080,  // [0xd0] stp q0, q0, [x4, #-0x40]
      0xad3f0080,  // [0xd4] stp q0, q0, [x4, #-0x20]
      0xd503201f,  // [0xd8] nop  (was 0x49d98 nop)
      0xd503201f,  // [0xdc] nop  (was 0x49d9c nop)
      0x91010063,  // [0xe0] add x3, x3, #0x40  (was 0x49da0)
      0xd50b7423,  // [0xe4] dc zva, x3  (dead — interpreter only; never reached)
      0xf1010042,  // [0xe8] subs x2, x2, #0x40
      0x54ffffa8,  // [0xec] b.hi -0xc → 0xe0  (dc-zva loop top, dead)
      0xd65f03c0,  // [0xf0] ret
      // [0xf4] originally was 49db4 nop; replace with ret so RunMultiRegion
      // splits regions at 0xf8 (the b.ne target).  Dead code in production.
      0xd65f03c0,  // [0xf4] ret  (was 0x49db4 nop)
      // 0x49db8 — fallback tail (b.ne target, TAKEN)
      0xcb030082,  // [0xf8] sub x2, x4, x3
      0xd1018042,  // [0xfc] sub x2, x2, #0x60
      0xad010060,  // [0x100] stp q0, q0, [x3, #0x20]   (loop top, b.hi target)
      0xad020060,  // [0x104] stp q0, q0, [x3, #0x40]
      0x91010063,  // [0x108] add x3, x3, #0x40
      0xf1010042,  // [0x10c] subs x2, x2, #0x40
      0x54ffff88,  // [0x110] b.hi -0x10 → 0x100
      0xad3e0080,  // [0x114] stp q0, q0, [x4, #-0x40]
      0xad3f0080,  // [0x118] stp q0, q0, [x4, #-0x20]
      0xd65f03c0,  // [0x11c] ret
  };
  static_assert(sizeof(code) == 0x120, "code buffer must span 0x49cc0..0x49ddc inclusive");

  constexpr size_t kSize = 1024;
  alignas(64) static uint8_t buffer[kSize];
  for (size_t i = 0; i < kSize / 4; ++i) {
    reinterpret_cast<uint32_t*>(buffer)[i] = 0xdeadbeefU;
  }

  // x30 set to "past end of code" so the final ret terminates cleanly.
  GuestAddr stop_addr = ToGuestAddr(code) + sizeof(code);
  state_.cpu.x[0] = ToGuestAddr(buffer);
  state_.cpu.x[1] = 0;
  state_.cpu.x[2] = kSize;
  state_.cpu.x[30] = stop_addr;

  EXPECT_TRUE(RunMultiRegion(code, stop_addr));

  // Every byte of the 1024-byte buffer must be zero.  Any non-zero byte
  // means a STR Q / STP Q got silently dropped — the JIT mistranslated
  // some part of the prologue+body path that the standalone unrolled and
  // b.hi-loop tests don't exercise (most likely the b.hs/b.hi forward
  // branches or the mrs DCZID+cmp+b.ne sequence at 0x49d70..0x49d7c).
  size_t first_nonzero = kSize;
  for (size_t i = 0; i < kSize; ++i) {
    if (buffer[i] != 0u) {
      first_nonzero = i;
      break;
    }
  }
  EXPECT_EQ(first_nonzero, kSize)
      << "first non-zero byte at offset " << first_nonzero
      << " (value 0x" << std::hex
      << static_cast<unsigned>(buffer[first_nonzero == kSize ? 0 : first_nonzero])
      << "); full __dl___memset_aarch64 body must zero every byte of a "
         "1024-byte 16-aligned buffer";
}

// Companion isolation test: just the DCZID b.ne sequence from
// __dl___memset_aarch64+0xb0..+0xc0.  After mrs DCZID_EL0 + and #0x1f +
// cmp #0x4, the b.ne must take when x5 != 4.  Berberis's JIT and
// interpreter both return DCZID=0x10, so b.ne must always take and
// branch to the b.ne target.  If this test FAILS, the JIT mis-emits
// flags from cmp x5, #0x4 (or the mrs+and chain leaves x5 != 0x10).
TEST_F(Arm64LiteTranslateRegionTest, MrsDczidEl0_BneTakenWhenNotFour) {
  // The branch target is past the end of the buffer (offset 0x14 -> code[5]
  // and beyond).  If b.ne is NOT taken, the fall-through instruction writes
  // a poison value to x6 that the test detects.
  static const uint32_t code[] = {
      0xd53b00e5,  // [ 0] mrs x5, DCZID_EL0    -> x5 = 0x10
      0x924010a5,  // [ 4] and x5, x5, #0x1f    -> x5 = 0x10
      0xf10010bf,  // [ 8] cmp x5, #0x4          -> Z=0 (10 != 4)
      0x54000061,  // [12] b.ne +0xc → past end (skip 2 fall-through insns)
      0xd2818006,  // [16] mov x6, #0xc00       (poison if b.ne NOT taken)
      0xd503201f,  // [20] nop
  };

  state_.cpu.x[5] = 0xdeadbeefULL;
  state_.cpu.x[6] = 0;  // expect to stay 0 if b.ne is taken

  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));

  EXPECT_EQ(state_.cpu.x[5], 0x10ULL)
      << "DCZID_EL0 must read as 0x10 (Berberis convention: DZP=1, BS=0)";
  EXPECT_EQ(state_.cpu.x[6], 0ULL)
      << "b.ne must be TAKEN when x5 (0x10) != 4 — if x6 == 0xc00, the "
         "fall-through executed, meaning the JIT mis-emitted flags from "
         "cmp x5, #0x4 or the mrs+and chain produced x5 == 4";
}

// Bionic's AddToMap (CdEntryMapZip32::AddToMap) writes each ZIP central-
// directory bucket with a read-modify-write that BFI-splices a 12-bit
// name_length into bits[31:20] of the 20-bit name_offset already stored
// there.  The hot sequence at linker offsets 0x9ccc8..0x9ccd8 is:
//
//   ldr w9, [x8, x24, lsl #2]   ; bucket value = name_offset (low 20 bits)
//   bfi w9, w19, #20, #12       ; splice in name_length at bits[31:20]
//   str w9, [x8, x24, lsl #2]   ; commit back
//
// The bucket-corruption signature observed in VkCaps' wedge (top12 == 0,
// low20 != 0) is consistent with the second STR being silently dropped
// after BFI: the first half of the RMW happened (low20 written), but the
// second store didn't commit.  Earlier debugging ruled out the b.hi-loop
// region-transition theory; this test probes the next-most-likely
// suspect: STR (register, 32-bit) with shifted-register offset under a
// dispatch-enabled backward branch.
//
// The loop body's entry PC is the b.hi target, so EmitDirectDispatch
// reaches the cached region via TranslationCache lookup — same path as
// production.  256 iterations with a unique x24 per iteration mean every
// slot of the bucket table participates exactly once.
TEST_F(Arm64LiteTranslateRegionDispatchTest, AddToMapBucketRmwUnderDispatch) {
  // Encodings cross-checked with aarch64-linux-gnu-as round-trip.
  static const uint32_t code[] = {
      0xb8787909,  // [0]  ldr w9, [x8, x24, lsl #2]
      0x330c2e69,  // [4]  bfi w9, w19, #20, #12
      0xb8387909,  // [8]  str w9, [x8, x24, lsl #2]
      0x91000718,  // [12] add x24, x24, #1
      0xf1000442,  // [16] subs x2, x2, #1
      0x54ffff68,  // [20] b.hi -20  -> back to [0]
  };

  // 256-entry bucket table, each entry pre-filled with a recognizable
  // sentinel.  After the loop every slot must be (0xAAA << 20) | (0x45678) =
  // 0xAAA45678.  Any slot left at 0x12345678 means the STR didn't commit
  // (or was clobbered, or BFI's destination spilled stale).
  constexpr size_t kNumSlots = 256;
  alignas(16) static uint32_t buckets[kNumSlots + 2];  // +2 = guard slots
  buckets[0] = 0xfeedface;  // leading guard
  for (size_t i = 0; i < kNumSlots; ++i) {
    buckets[i + 1] = 0x12345678U;
  }
  buckets[kNumSlots + 1] = 0xdeadbeef;  // trailing guard

  state_.cpu.x[8] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;
  state_.cpu.x[2] = kNumSlots;
  state_.cpu.x[19] = 0xAAA;
  // Pre-load x9 with a poison value so a silently-skipped LDR is caught.
  state_.cpu.x[9] = 0xbaadf00dULL;

  EXPECT_TRUE(RunWithDispatch(code, ToGuestAddr(code) + sizeof(code)));

  // SUBS x2, x2, #1 with b.hi exits when x2 transitions to 0 (HI is C && !Z).
  // 256 iterations -> x2 ends at 0.
  EXPECT_EQ(state_.cpu.x[2], 0ULL) << "loop counter must reach zero";
  EXPECT_EQ(state_.cpu.x[24], kNumSlots) << "x24 must have advanced by N";

  // Every slot must be 0xAAA45678.  Find the first mis-stored slot for a
  // clean diagnostic.
  size_t first_bad = kNumSlots;
  uint32_t first_bad_value = 0;
  for (size_t i = 0; i < kNumSlots; ++i) {
    if (buckets[i + 1] != 0xAAA45678U) {
      first_bad = i;
      first_bad_value = buckets[i + 1];
      break;
    }
  }
  EXPECT_EQ(first_bad, kNumSlots)
      << "first mis-stored slot at index " << first_bad
      << " (value 0x" << std::hex << first_bad_value
      << "); expected 0xAAA45678 in every slot — a slot left at the "
         "0x12345678 sentinel means the STR didn't commit under dispatch";

  // Guard slots must not have been touched — a wrong base or wrong shift
  // would smear writes outside the table.
  EXPECT_EQ(buckets[0], 0xfeedfaceU)
      << "leading guard clobbered — STR base/shift bug";
  EXPECT_EQ(buckets[kNumSlots + 1], 0xdeadbeefU)
      << "trailing guard clobbered — STR base/shift bug";
}

// Production AddToMap two-step insert (FULL 5-instruction sequence at linker
// offsets 0x9cc68..0x9cc78 of CdEntryMapZip32<ZipStringOffset20>::AddToMap):
//
//   str  w8,  [x25, x24, lsl #2]    ; STORE 1: bucket = name_offset (low 20)
//   ldr  x8,  [x21, #0x8]            ; reload x8 from map's bucket-pointer
//                                    ;   (after the reload, x8 == x25)
//   ldr  w9,  [x8,  x24, lsl #2]    ; reload the just-stored bucket value
//   bfi  w9,  w19, #20, #12         ; splice 12-bit name_length at bits[31:20]
//   str  w9,  [x8,  x24, lsl #2]   ; STORE 2: bucket = (length << 20) | offset
//
// The peek-tool live capture in the wedged VkCapsViewer showed 118/256 buckets
// with length=0 and offset!=0 — exactly the signature of STORE 2 being
// effectively dropped after STORE 1 committed.  This test runs the FULL 5-
// instruction production sequence under dispatch with a backward-branch loop
// (so the dispatch path with EmitDirectDispatch is exercised), driven over
// 256 iterations, with the bucket array initially all zero (matching the
// linker's calloc'd allocation).  After the loop, every bucket must have its
// length field populated; any bucket with length=0 means STORE 2 didn't
// commit for that iteration.
//
// Differences from AddToMapBucketRmwUnderDispatch above:
//   * Includes STORE 1 (via x25), not just STORE 2 (via x8 after reload).
//   * Includes the LDR x8 reload from a memory slot that aliases x25 — same
//     bucket array reached via two different base registers.  The JIT must
//     correctly serialize STORE 1's effect through the address-aliased LDR.
//   * Pre-fills buckets to ZERO (matching calloc), not 0x12345678.  A length=0
//     after the loop means STORE 2 didn't commit; with the all-zero pre-fill
//     it's unambiguous (no risk of a sentinel value still being there).
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       AddToMapBucketTwoStepInsertUnderDispatch_Full5Insn) {
  // Encodings round-tripped through aarch64-linux-gnu-as.
  static const uint32_t code[] = {
      0xb8387b28,  // [ 0] str  w8, [x25, x24, lsl #2]   ; STORE 1
      0xf94006a8,  // [ 4] ldr  x8, [x21, #0x8]           ; reload x8 = bucket base
      0xb8787909,  // [ 8] ldr  w9, [x8, x24, lsl #2]    ; reload bucket
      0x330c2e69,  // [12] bfi  w9, w19, #20, #12        ; splice length
      0xb8387909,  // [16] str  w9, [x8, x24, lsl #2]   ; STORE 2
      0x91000718,  // [20] add  x24, x24, #1
      0xf1000442,  // [24] subs x2,  x2, #1
      0x54ffff28,  // [28] b.hi -28  -> back to [0]
  };

  constexpr size_t kNumSlots = 256;
  alignas(16) static uint32_t buckets[kNumSlots + 2];  // +2 guards
  buckets[0] = 0xfeedfaceU;                            // leading guard
  for (size_t i = 0; i < kNumSlots; ++i) {
    buckets[i + 1] = 0;  // calloc-equivalent pre-fill (production's case)
  }
  buckets[kNumSlots + 1] = 0xdeadbeefU;                // trailing guard

  // Pointer-alias slot: a uint64_t at [x21 + 0x8] that holds &buckets[1].
  // Production has the CdEntryMapZip32 object at x21 with the hash_table_
  // bucket-pointer field at offset +0x8; we replicate that layout here so
  // `ldr x8, [x21, #0x8]` materializes the bucket array base.
  alignas(8) static uint64_t map_struct[4];
  map_struct[0] = 0;                                   // would be other fields
  map_struct[1] = reinterpret_cast<uint64_t>(&buckets[1]);  // [x21+0x8]
  map_struct[2] = 0;
  map_struct[3] = 0;

  state_.cpu.x[21] = ToGuestAddr(&map_struct[0]);
  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;
  state_.cpu.x[2] = kNumSlots;
  state_.cpu.x[19] = 0xAAA;
  // x8 initially holds the "name_offset" for this hypothetical insert —
  // a non-zero unique value so STORE 1 has something distinct to write.
  state_.cpu.x[8] = 0x12345ULL;

  EXPECT_TRUE(RunWithDispatch(code, ToGuestAddr(code) + sizeof(code)));

  EXPECT_EQ(state_.cpu.x[2], 0ULL) << "loop must exit (x2 reaches 0)";
  EXPECT_EQ(state_.cpu.x[24], kNumSlots) << "x24 must reach kNumSlots";

  // Each bucket must have length=0xAAA in bits[31:20] (the BFI'd value).
  // Whether the offset bits[19:0] is the original 0x12345 (iter 0) or the
  // low 20 bits of &buckets[1] (subsequent iters, because the LDR x8 reload
  // overwrites x8 = bucket-array base, and STORE 1 in the NEXT iter writes
  // that address back) doesn't matter — the test only checks the length
  // half, which is what 118/256 production buckets are missing.
  size_t first_length_zero = kNumSlots;
  uint32_t first_bad_bucket = 0;
  size_t count_length_zero = 0;
  for (size_t i = 0; i < kNumSlots; ++i) {
    const uint32_t bucket = buckets[i + 1];
    const uint32_t length = (bucket >> 20) & 0xfff;
    if (length == 0) {
      if (first_length_zero == kNumSlots) {
        first_length_zero = i;
        first_bad_bucket = bucket;
      }
      ++count_length_zero;
    }
  }
  EXPECT_EQ(first_length_zero, kNumSlots)
      << "production-signature bug: " << count_length_zero << "/" << kNumSlots
      << " buckets have length=0 (STORE 2 dropped); first at i=" << first_length_zero
      << " value=0x" << std::hex << first_bad_bucket;

  // Guards intact.
  EXPECT_EQ(buckets[0], 0xfeedfaceU);
  EXPECT_EQ(buckets[kNumSlots + 1], 0xdeadbeefU);
}

// Same 5-instruction insert sequence as the previous test, but with an
// explicit region split forced at the production boundary observed via the
// REGION_END_LOW diagnostic in lite_translate_region.cc:
//
//   Region A: contains only the STORE 1 (str w8, [x25, x24, lsl #2])
//   Region B: contains the LDR x8 reload, LDR w9, BFI w9, STORE 2, advance,
//             subs, b.hi (back-edge to Region A)
//
// In production VkCapsViewer the IsGpRegPoolLow early-termination fires at
// guest PCs `linker_base+0x9cc6c` (= LDR x8 reload, immediately after STORE 1)
// and `linker_base+0x9cc7c` (= one past STORE 2).  This test pins whether the
// 5-instruction sequence remains correct under the SAME region-split topology.
//
// If this test FAILS while the no-split variant above PASSES, that proves the
// production wedge's bucket-corruption signature (length=0, offset!=0) is a
// JIT bug specific to the region-boundary state between STORE 1 and STORE 2 —
// either cross-region register live-state tracking, signal-check interaction,
// or some other inter-region effect.
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       AddToMapBucketTwoStepInsert_ExplicitSplitAtProductionBoundary) {
  static const uint32_t code[] = {
      0xb8387b28,  // [ 0] str  w8, [x25, x24, lsl #2]   ; STORE 1 — Region A
      0xf94006a8,  // [ 4] ldr  x8, [x21, #0x8]           ; Region B start
      0xb8787909,  // [ 8] ldr  w9, [x8, x24, lsl #2]
      0x330c2e69,  // [12] bfi  w9, w19, #20, #12
      0xb8387909,  // [16] str  w9, [x8, x24, lsl #2]   ; STORE 2
      0x91000718,  // [20] add  x24, x24, #1
      0xf1000442,  // [24] subs x2,  x2, #1
      0x54ffff28,  // [28] b.hi -28
  };

  constexpr size_t kNumSlots = 256;
  alignas(16) static uint32_t buckets[kNumSlots + 2];
  buckets[0] = 0xfeedfaceU;
  for (size_t i = 0; i < kNumSlots; ++i) {
    buckets[i + 1] = 0;
  }
  buckets[kNumSlots + 1] = 0xdeadbeefU;

  alignas(8) static uint64_t map_struct[4];
  map_struct[0] = 0;
  map_struct[1] = reinterpret_cast<uint64_t>(&buckets[1]);
  map_struct[2] = 0;
  map_struct[3] = 0;

  state_.cpu.x[21] = ToGuestAddr(&map_struct[0]);
  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;
  state_.cpu.x[2] = kNumSlots;
  state_.cpu.x[19] = 0xAAA;
  state_.cpu.x[8] = 0x12345ULL;

  GuestAddr code_start = ToGuestAddr(code);
  GuestAddr code_end = code_start + sizeof(code);
  GuestAddr split_pc = code_start + 4;  // Right after STORE 1

  state_.cpu.insn_addr = code_start;
  auto* cache = TranslationCache::GetInstance();

  // Region A: STORE 1 only (end_pc forces termination after one instruction).
  MachineCode mc_a;
  auto [success_a, stop_a] = TryLiteTranslateRegion(
      code_start, &mc_a,
      LiteTranslateParams{.end_pc = split_pc, .allow_dispatch = true});
  ASSERT_TRUE(success_a);
  ASSERT_EQ(stop_a, split_pc);
  GuestCodeEntry* entry_a = cache->AddAndLockForTranslation(code_start, 0);
  ASSERT_NE(entry_a, nullptr);
  HostCodeAddr host_code_a = GetDefaultCodePoolInstance()->Add(&mc_a);
  cache->SetTranslatedAndUnlock(code_start, entry_a,
                                static_cast<uint32_t>(stop_a - code_start),
                                GuestCodeEntry::Kind::kLiteTranslated,
                                {host_code_a, mc_a.install_size()});

  // Region B: LDR x8 reload through b.hi.
  MachineCode mc_b;
  auto [success_b, stop_b] = TryLiteTranslateRegion(
      split_pc, &mc_b,
      LiteTranslateParams{.end_pc = code_end, .allow_dispatch = true});
  ASSERT_TRUE(success_b);
  ASSERT_EQ(stop_b, code_end);
  GuestCodeEntry* entry_b = cache->AddAndLockForTranslation(split_pc, 0);
  ASSERT_NE(entry_b, nullptr);
  HostCodeAddr host_code_b = GetDefaultCodePoolInstance()->Add(&mc_b);
  cache->SetTranslatedAndUnlock(split_pc, entry_b,
                                static_cast<uint32_t>(stop_b - split_pc),
                                GuestCodeEntry::Kind::kLiteTranslated,
                                {host_code_b, mc_b.install_size()});

  TestingRunGeneratedCode(&state_, AsHostCode(host_code_a), code_end);

  EXPECT_EQ(state_.cpu.insn_addr, code_end);
  EXPECT_EQ(state_.cpu.x[2], 0ULL);
  EXPECT_EQ(state_.cpu.x[24], kNumSlots);

  size_t first_length_zero = kNumSlots;
  uint32_t first_bad_bucket = 0;
  size_t count_length_zero = 0;
  for (size_t i = 0; i < kNumSlots; ++i) {
    const uint32_t bucket = buckets[i + 1];
    const uint32_t length = (bucket >> 20) & 0xfff;
    if (length == 0) {
      if (first_length_zero == kNumSlots) {
        first_length_zero = i;
        first_bad_bucket = bucket;
      }
      ++count_length_zero;
    }
  }
  EXPECT_EQ(first_length_zero, kNumSlots)
      << "FORCED-SPLIT bug reproduces production signature: "
      << count_length_zero << "/" << kNumSlots
      << " buckets have length=0 (STORE 2 dropped); first at i="
      << first_length_zero << " value=0x" << std::hex << first_bad_bucket;

  EXPECT_EQ(buckets[0], 0xfeedfaceU);
  EXPECT_EQ(buckets[kNumSlots + 1], 0xdeadbeefU);

  cache->InvalidateGuestRange(code_start, code_end);
}

// Same 5-instruction insert as AddToMapBucketTwoStepInsert_ExplicitSplit-
// AtProductionBoundary above, but forces a THREE-region topology that
// exactly matches the production VkCapsViewer IsGpRegPoolLow split points.
// In production, the early-termination check fires at BOTH guest PCs
// `linker_base+0x9cc6c` (just before LDR x8) AND `linker_base+0x9cc7c`
// (just before ADD x24, one past STORE 2).  The existing test only forces
// the first split; this test forces both:
//
//   Region A: STORE 1                     (offset 0..4   = 0x9cc68..0x9cc6c)
//   Region B: LDR x8, LDR w9, BFI w9,
//             STORE 2                     (offset 4..20  = 0x9cc6c..0x9cc7c)
//   Region C: add x24, subs x2, b.hi      (offset 20..32 = 0x9cc7c..0x9cc88)
//
// If this test FAILS while the two-region split test PASSES, the bug is
// specific to the Region B/C boundary (the split between STORE 2 and the
// loop tail) — a cross-region effect not exercised by the existing tests.
// If both pass, the production-only condition is something OTHER than the
// region-split topology (deeper mapped-register state in Region A, the
// physical-PC of the dispatch chain, signal interaction, or cache-line
// alignment of the host-emitted dispatch tail).
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       AddToMapBucketTwoStepInsert_ThreeRegionSplitAtProductionBoundaries) {
  static const uint32_t code[] = {
      0xb8387b28,  // [ 0] str  w8, [x25, x24, lsl #2]   ; STORE 1 — Region A
      0xf94006a8,  // [ 4] ldr  x8, [x21, #0x8]           ; Region B start
      0xb8787909,  // [ 8] ldr  w9, [x8, x24, lsl #2]
      0x330c2e69,  // [12] bfi  w9, w19, #20, #12
      0xb8387909,  // [16] str  w9, [x8, x24, lsl #2]   ; STORE 2 (end Region B)
      0x91000718,  // [20] add  x24, x24, #1             ; Region C start
      0xf1000442,  // [24] subs x2,  x2, #1
      0x54ffff28,  // [28] b.hi -28
  };

  constexpr size_t kNumSlots = 256;
  alignas(16) static uint32_t buckets[kNumSlots + 2];
  buckets[0] = 0xfeedfaceU;
  for (size_t i = 0; i < kNumSlots; ++i) {
    buckets[i + 1] = 0;
  }
  buckets[kNumSlots + 1] = 0xdeadbeefU;

  alignas(8) static uint64_t map_struct[4];
  map_struct[0] = 0;
  map_struct[1] = reinterpret_cast<uint64_t>(&buckets[1]);
  map_struct[2] = 0;
  map_struct[3] = 0;

  state_.cpu.x[21] = ToGuestAddr(&map_struct[0]);
  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;
  state_.cpu.x[2] = kNumSlots;
  state_.cpu.x[19] = 0xAAA;
  state_.cpu.x[8] = 0x12345ULL;

  GuestAddr code_start = ToGuestAddr(code);
  GuestAddr code_end = code_start + sizeof(code);
  GuestAddr split_1 = code_start + 4;   // After STORE 1 / before LDR x8
  GuestAddr split_2 = code_start + 20;  // After STORE 2 / before ADD x24

  state_.cpu.insn_addr = code_start;
  auto* cache = TranslationCache::GetInstance();

  // Region A: STORE 1 only.
  MachineCode mc_a;
  auto [success_a, stop_a] = TryLiteTranslateRegion(
      code_start, &mc_a,
      LiteTranslateParams{.end_pc = split_1, .allow_dispatch = true});
  ASSERT_TRUE(success_a);
  ASSERT_EQ(stop_a, split_1);
  GuestCodeEntry* entry_a = cache->AddAndLockForTranslation(code_start, 0);
  ASSERT_NE(entry_a, nullptr);
  HostCodeAddr host_code_a = GetDefaultCodePoolInstance()->Add(&mc_a);
  cache->SetTranslatedAndUnlock(code_start, entry_a,
                                static_cast<uint32_t>(stop_a - code_start),
                                GuestCodeEntry::Kind::kLiteTranslated,
                                {host_code_a, mc_a.install_size()});

  // Region B: LDR x8 reload .. STORE 2.
  MachineCode mc_b;
  auto [success_b, stop_b] = TryLiteTranslateRegion(
      split_1, &mc_b,
      LiteTranslateParams{.end_pc = split_2, .allow_dispatch = true});
  ASSERT_TRUE(success_b);
  ASSERT_EQ(stop_b, split_2);
  GuestCodeEntry* entry_b = cache->AddAndLockForTranslation(split_1, 0);
  ASSERT_NE(entry_b, nullptr);
  HostCodeAddr host_code_b = GetDefaultCodePoolInstance()->Add(&mc_b);
  cache->SetTranslatedAndUnlock(split_1, entry_b,
                                static_cast<uint32_t>(stop_b - split_1),
                                GuestCodeEntry::Kind::kLiteTranslated,
                                {host_code_b, mc_b.install_size()});

  // Region C: advance, subs, b.hi (with backward branch into Region A).
  MachineCode mc_c;
  auto [success_c, stop_c] = TryLiteTranslateRegion(
      split_2, &mc_c,
      LiteTranslateParams{.end_pc = code_end, .allow_dispatch = true});
  ASSERT_TRUE(success_c);
  ASSERT_EQ(stop_c, code_end);
  GuestCodeEntry* entry_c = cache->AddAndLockForTranslation(split_2, 0);
  ASSERT_NE(entry_c, nullptr);
  HostCodeAddr host_code_c = GetDefaultCodePoolInstance()->Add(&mc_c);
  cache->SetTranslatedAndUnlock(split_2, entry_c,
                                static_cast<uint32_t>(stop_c - split_2),
                                GuestCodeEntry::Kind::kLiteTranslated,
                                {host_code_c, mc_c.install_size()});

  TestingRunGeneratedCode(&state_, AsHostCode(host_code_a), code_end);

  EXPECT_EQ(state_.cpu.insn_addr, code_end);
  EXPECT_EQ(state_.cpu.x[2], 0ULL);
  EXPECT_EQ(state_.cpu.x[24], kNumSlots);

  size_t first_length_zero = kNumSlots;
  uint32_t first_bad_bucket = 0;
  size_t count_length_zero = 0;
  for (size_t i = 0; i < kNumSlots; ++i) {
    const uint32_t bucket = buckets[i + 1];
    const uint32_t length = (bucket >> 20) & 0xfff;
    if (length == 0) {
      if (first_length_zero == kNumSlots) {
        first_length_zero = i;
        first_bad_bucket = bucket;
      }
      ++count_length_zero;
    }
  }
  EXPECT_EQ(first_length_zero, kNumSlots)
      << "THREE-REGION SPLIT reproduces production signature: "
      << count_length_zero << "/" << kNumSlots
      << " buckets have length=0 (STORE 2 dropped); first at i="
      << first_length_zero << " value=0x" << std::hex << first_bad_bucket;

  EXPECT_EQ(buckets[0], 0xfeedfaceU);
  EXPECT_EQ(buckets[kNumSlots + 1], 0xdeadbeefU);

  cache->InvalidateGuestRange(code_start, code_end);
}

// Deep mapped-register state: the 5-insn AddToMap insert sequence preceded
// by a 7-instruction prelude touching x4-x7 and x10-x12 (none used by the
// insert sequence proper), exhausting the JIT's permanent-mapping pool
// before STORE 1 even starts decoding (the allocator caps permanent
// mappings at 13 - kReservedTempRegs = 7 guest regs; the prelude consumes
// exactly all 7 slots).
//
// With the fixed temp reserve, register pressure must NOT split or fail
// the region: every guest register the insert sequence touches past the
// prelude (x8/x25/x24/x21/x19/x9/x2) is unmapped and goes through the
// GetReg/SetReg spill-through-ThreadState path, and the whole loop —
// prelude, both stores, the BFI read-modify-write, and the SUBS/B.HI
// tail — must translate as ONE region and execute 256 iterations
// correctly.  (This test originally pinned the production VkCapsViewer
// three-region pressure-split topology; the explicit-split variants above
// still cover that topology via forced end_pc.)
//
// Each prelude insn is `add xN, xN, xzr` (encoded by hand below) — it
// reads xN, writes xN, leaves xN's value unchanged, and does NOT touch
// NZCV (it's ADD, not ADDS), so the b.hi at the loop tail still reads
// only the SUBS-set flags.
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       AddToMapBucketTwoStepInsert_DeepMappedRegState_SpillsSingleRegion) {
  static const uint32_t code[] = {
      // --- Prelude: pre-map x4-x7 and x10-x12 into JIT permanent slots
      //     (7 regs, each `add xN, xN, xzr` keeps xN's value unchanged) ---
      0x8B1F0084,  // [ 0] add  x4,  x4,  xzr   ; map x4
      0x8B1F00A5,  // [ 4] add  x5,  x5,  xzr   ; map x5
      0x8B1F00C6,  // [ 8] add  x6,  x6,  xzr   ; map x6
      0x8B1F00E7,  // [12] add  x7,  x7,  xzr   ; map x7
      0x8B1F014A,  // [16] add  x10, x10, xzr   ; map x10
      0x8B1F016B,  // [20] add  x11, x11, xzr   ; map x11
      0x8B1F018C,  // [24] add  x12, x12, xzr   ; map x12

      // --- Production AddToMap 5-insn insert sequence ---
      0xb8387b28,  // [28] str  w8, [x25, x24, lsl #2]  ; STORE 1 (Region A end)
      0xf94006a8,  // [32] ldr  x8, [x21, #0x8]          ; Region B start
      0xb8787909,  // [36] ldr  w9, [x8, x24, lsl #2]
      0x330c2e69,  // [40] bfi  w9, w19, #20, #12
      0xb8387909,  // [44] str  w9, [x8, x24, lsl #2]  ; STORE 2 (Region B end)
      0x91000718,  // [48] add  x24, x24, #1            ; Region C start
      0xf1000442,  // [52] subs x2,  x2, #1
      0x54fffe48,  // [56] b.hi -56  -> back to prelude start (offset 0 = Region A entry)
  };

  constexpr size_t kNumSlots = 256;
  alignas(16) static uint32_t buckets[kNumSlots + 2];
  buckets[0] = 0xfeedfaceU;
  for (size_t i = 0; i < kNumSlots; ++i) {
    buckets[i + 1] = 0;
  }
  buckets[kNumSlots + 1] = 0xdeadbeefU;

  alignas(8) static uint64_t map_struct[4];
  map_struct[0] = 0;
  map_struct[1] = reinterpret_cast<uint64_t>(&buckets[1]);
  map_struct[2] = 0;
  map_struct[3] = 0;

  state_.cpu.x[21] = ToGuestAddr(&map_struct[0]);
  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;
  state_.cpu.x[2] = kNumSlots;
  state_.cpu.x[19] = 0xAAA;
  state_.cpu.x[8] = 0x12345ULL;
  // Sentinel values for the pre-mapped regs (verified intact after the loop).
  state_.cpu.x[4]  = 0xdead0004ULL;
  state_.cpu.x[5]  = 0xdead0005ULL;
  state_.cpu.x[6]  = 0xdead0006ULL;
  state_.cpu.x[7]  = 0xdead0007ULL;
  state_.cpu.x[10] = 0xdead000aULL;
  state_.cpu.x[11] = 0xdead000bULL;
  state_.cpu.x[12] = 0xdead000cULL;

  GuestAddr code_start = ToGuestAddr(code);
  GuestAddr code_end = code_start + sizeof(code);
  state_.cpu.insn_addr = code_start;
  auto* cache = TranslationCache::GetInstance();

  // The whole loop must translate as a single region: the prelude fills all
  // 7 permanent mapping slots, and everything after runs on the spill path.
  // Register pressure must neither fail the translation nor cut the region
  // short of its natural end (the b.hi at code_end).
  MachineCode mc_a;
  auto [success_a, stop_a] = TryLiteTranslateRegion(
      code_start, &mc_a,
      LiteTranslateParams{.end_pc = code_end, .allow_dispatch = true});
  ASSERT_TRUE(success_a);
  ASSERT_EQ(stop_a, code_end)
      << "register pressure split the region at offset " << (stop_a - code_start)
      << "; with the fixed temp reserve it must reach the natural region end";
  GuestCodeEntry* entry_a = cache->AddAndLockForTranslation(code_start, 0);
  ASSERT_NE(entry_a, nullptr);
  HostCodeAddr host_code_a = GetDefaultCodePoolInstance()->Add(&mc_a);
  cache->SetTranslatedAndUnlock(code_start, entry_a,
                                static_cast<uint32_t>(stop_a - code_start),
                                GuestCodeEntry::Kind::kLiteTranslated,
                                {host_code_a, mc_a.install_size()});

  // The b.hi back-edge targets offset 0 (the region's own start), so the
  // 256 loop iterations exit and re-enter this single region through the
  // dispatch path, re-running the idempotent prelude each time.
  TestingRunGeneratedCode(&state_, AsHostCode(host_code_a), code_end);

  EXPECT_EQ(state_.cpu.insn_addr, code_end);
  EXPECT_EQ(state_.cpu.x[2], 0ULL);
  EXPECT_EQ(state_.cpu.x[24], kNumSlots);

  // Sentinel regs must be untouched.
  EXPECT_EQ(state_.cpu.x[4],  0xdead0004ULL);
  EXPECT_EQ(state_.cpu.x[5],  0xdead0005ULL);
  EXPECT_EQ(state_.cpu.x[6],  0xdead0006ULL);
  EXPECT_EQ(state_.cpu.x[7],  0xdead0007ULL);
  EXPECT_EQ(state_.cpu.x[10], 0xdead000aULL);
  EXPECT_EQ(state_.cpu.x[11], 0xdead000bULL);
  EXPECT_EQ(state_.cpu.x[12], 0xdead000cULL);

  // Bucket-array integrity: every bucket's bits[31:20] (length field) must
  // equal 0xAAA (the BFI'd value).  A length=0 bucket means STORE 2 was
  // dropped by the spill path under deep mapped state.
  size_t first_length_zero = kNumSlots;
  uint32_t first_bad_bucket = 0;
  size_t count_length_zero = 0;
  for (size_t i = 0; i < kNumSlots; ++i) {
    const uint32_t bucket = buckets[i + 1];
    const uint32_t length = (bucket >> 20) & 0xfff;
    if (length == 0) {
      if (first_length_zero == kNumSlots) {
        first_length_zero = i;
        first_bad_bucket = bucket;
      }
      ++count_length_zero;
    }
  }
  EXPECT_EQ(first_length_zero, kNumSlots)
      << "spill path dropped STORE 2 under deep mapped state: "
      << count_length_zero << "/" << kNumSlots
      << " buckets have length=0; first at i=" << first_length_zero
      << " value=0x" << std::hex << first_bad_bucket;

  EXPECT_EQ(buckets[0], 0xfeedfaceU);
  EXPECT_EQ(buckets[kNumSlots + 1], 0xdeadbeefU);

  cache->InvalidateGuestRange(code_start, code_end);
}

// Hypothesis G.2c.1 — w9 pre-BFI contents trigger a JIT RMW mis-translation.
//
// Handoff-279's peek dump showed 118/256 buckets in the wedged VkCapsViewer
// have bits[31:20]=0 (length field zeroed) and bits[19:0]!=0 (offset
// preserved).  Determinism across cold starts rules out signal-clobber.  The
// existing 5-insn-under-dispatch tests with default w9 patterns PASS, so the
// hypothesis is that some specific bit pattern of w9 at the moment BFI runs
// causes the JIT's BFI lowering to emit a no-op or wrong-mask for that value.
//
// This test sweeps w9's pre-BFI contents across representative non-zero
// patterns.  For each pattern: pre-seed buckets[0] = w9_pattern, drive a
// single-iteration insert (kNumSlots=1) through the SAME 5-insn-under-
// dispatch path used by AddToMapBucketTwoStepInsertUnderDispatch_Full5Insn,
// and verify the bucket ends up with bits[31:20] = 0xAAA (the BFI'd length).
//
// We seed via x[8] (which STORE 1 writes into buckets[0], and which LDR w9
// then reloads — so the value w9 holds at BFI is precisely the low-32 of
// x[8]).  If ANY pattern produces a bucket with length=0, G.2c.1 is
// reproduced in isolation and we have a unit-level repro to drive a fix.
// If all patterns PASS, G.2c.1 is disproved at this depth; the next move is
// G.2c.2 (decoder mis-dispatch of the specific BFI encoding variant).
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       AddToMapBucketTwoStepInsert_W9PatternSweep) {
  // Same 5-insn insert + loop tail as AddToMapBucketTwoStepInsertUnderDispatch
  // _Full5Insn, but parameterized over kNumSlots and a per-run w8 pattern.
  static const uint32_t code[] = {
      0xb8387b28,  // [ 0] str  w8, [x25, x24, lsl #2]   ; STORE 1
      0xf94006a8,  // [ 4] ldr  x8, [x21, #0x8]           ; reload x8 = base
      0xb8787909,  // [ 8] ldr  w9, [x8, x24, lsl #2]    ; w9 = bucket value
      0x330c2e69,  // [12] bfi  w9, w19, #20, #12        ; splice length
      0xb8387909,  // [16] str  w9, [x8, x24, lsl #2]   ; STORE 2
      0x91000718,  // [20] add  x24, x24, #1
      0xf1000442,  // [24] subs x2,  x2, #1
      0x54ffff28,  // [28] b.hi -28  -> back to [0]
  };

  // Patterns chosen to span: all-zero (baseline), all-ones, the length-field
  // already all-ones (0xfff00000), offset-only (low 20), high-byte-only,
  // single-bit-in-length-field, and a few arbitrary 32-bit values.  If the
  // JIT's BFI lowering has a value-dependent miscompile, one of these should
  // trigger length=0 in the STORE 2 result.
  static const uint32_t kW8Patterns[] = {
      0x00000000U,  // all zero (control — already tested elsewhere, passes)
      0xFFFFFFFFU,  // all ones (BFI must clear bits[31:20] before OR'ing 0xAAA)
      0xFFF00000U,  // length field already full of 1s
      0x00012345U,  // offset-only pattern (default test uses this)
      0x000FFFFFU,  // max-offset-only (low 20 bits set, high 12 clear)
      0xFFF12345U,  // length=0xFFF + non-zero offset
      0x00100000U,  // single bit at length[0]
      0x80000000U,  // sign bit only
      0x7FFFFFFFU,  // all bits except sign
      0xAAAAAAAAU,  // alternating bits
      0x55555555U,  // alternating bits (complement)
      0xDEADBEEFU,  // arbitrary
      0xCAFEBABEU,  // arbitrary
      0x12345678U,  // arbitrary
      0x00000FFFU,  // low 12 bits set (might collide with the field mask
                    // computed in the JIT — important to test)
      0xFFF80000U,  // length=0xFFF + bit at offset[19]
  };

  for (uint32_t w8_pattern : kW8Patterns) {
    constexpr size_t kNumSlots = 1;
    alignas(16) static uint32_t buckets[kNumSlots + 2];
    buckets[0] = 0xfeedfaceU;
    buckets[1] = 0;  // calloc-equivalent pre-fill — STORE 1 will overwrite.
    buckets[2] = 0xdeadbeefU;

    alignas(8) static uint64_t map_struct[4];
    map_struct[0] = 0;
    map_struct[1] = reinterpret_cast<uint64_t>(&buckets[1]);
    map_struct[2] = 0;
    map_struct[3] = 0;

    std::memset(&state_.cpu, 0, sizeof(state_.cpu));
    state_.cpu.x[21] = ToGuestAddr(&map_struct[0]);
    state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
    state_.cpu.x[24] = 0;
    state_.cpu.x[2] = kNumSlots;
    state_.cpu.x[19] = 0xAAA;
    state_.cpu.x[8] = static_cast<uint64_t>(w8_pattern);

    ASSERT_TRUE(RunWithDispatch(code, ToGuestAddr(code) + sizeof(code)))
        << "RunWithDispatch failed for pattern 0x" << std::hex << w8_pattern;

    EXPECT_EQ(state_.cpu.x[2], 0ULL) << "loop must exit (x2 reaches 0) for pattern 0x"
                                     << std::hex << w8_pattern;
    EXPECT_EQ(state_.cpu.x[24], kNumSlots) << "x24 must reach kNumSlots for pattern 0x"
                                           << std::hex << w8_pattern;

    const uint32_t bucket = buckets[1];
    const uint32_t length = (bucket >> 20) & 0xfff;
    EXPECT_EQ(length, 0xAAAU)
        << "G.2c.1 REPRODUCED for pattern 0x" << std::hex << w8_pattern
        << ": bucket=0x" << bucket << " (length=0x" << length
        << ", expected 0xAAA — STORE 2's BFI was dropped)";

    // Sanity: the offset half must equal the pattern's low 20 bits (what
    // STORE 1 wrote and was preserved through BFI).
    const uint32_t offset = bucket & 0xfffffU;
    EXPECT_EQ(offset, w8_pattern & 0xfffffU)
        << "STORE 1's offset half corrupted for pattern 0x" << std::hex
        << w8_pattern << ": got 0x" << offset;

    EXPECT_EQ(buckets[0], 0xfeedfaceU)
        << "leading guard clobbered for pattern 0x" << std::hex << w8_pattern;
    EXPECT_EQ(buckets[2], 0xdeadbeefU)
        << "trailing guard clobbered for pattern 0x" << std::hex << w8_pattern;
  }
}

// Hypothesis C — surrounding-code interaction.
//
// Combines production's bucket-FIND loop body (LDR + ANDS + b.eq) AND the
// bucket-INSERT 5-instruction sequence in ONE contiguous block, run 256x
// under multi-region dispatch.  Mirrors the FULL execution path of
// CdEntryMapZip32<ZipStringOffset20>::AddToMap at linker offsets
// 0x9cc20..0x9cc78 for the "empty bucket on first probe" path.
//
// Each outer iteration:
//   1. LDR w8 = buckets[x24]   (always 0; pre-fill is calloc-equivalent)
//   2. ANDS x9, x8, #0xfffff   (Z=1 because bucket is empty)
//   3. b.eq insert             (taken)
//   4. INSERT 5-insn sequence: STORE 1 + LDR x8 + LDR w9 + BFI + STORE 2
//   5. x24++, subs x2,#1, b.hi top  (256 iterations total)
//
// Hypothesis A (signal clobber) and B (deep mapped-register state /
// spill-restore) are DISPROVED in earlier work; do NOT re-test them.
// Hypothesis C theorizes the bug lives in an instruction OUTSIDE the 5-insn
// insert sequence pinned by the existing tests — specifically the b.eq
// cross-region dispatch from FIND to INSERT, or the LDR/ANDS pair preceding
// it.  In production, the find loop runs 1-3 times per AddToMap call before
// hitting an empty bucket, then dispatches to the insert.  If b.eq's
// cross-region dispatch (or its surrounding code) occasionally drops x19
// (the BFI source = name_length), ~half the buckets end up with length=0 —
// matching the production signature.
//
// If this test FAILS, the bug is reproduced deterministically under host
// conditions and bisection can localize.
//
// If this test PASSES, hypothesis C's "1-step find then insert" form is
// disproved; the next target is hypothesis D (region invalidation /
// re-translation race during the live VkCapsViewer run, where trans#N
// climbed to ~290/sec).
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       AddToMapBucketFindThenInsertCombinedUnderDispatch_256x) {
  static const uint32_t code[] = {
      // --- FIND loop body (always hits empty bucket via b.eq) ---
      0xb8785b28,  // [ 0] loop_top: ldr w8, [x25, w24, uxtw #2]
      0xf2404d09,  // [ 4]           ands x9, x8, #0xfffff
      0x54000080,  // [ 8]           b.eq +0x10 (-> insert at offset 24)
      0x31000708,  // [12]           adds w8, w24, #1      ; advance (dead)
      0x0a1a0118,  // [16]           and  w24, w8, w26     ; (dead)
      0x17fffffb,  // [20]           b    -0x14 (-> loop_top, dead)
      // --- INSERT 5-insn sequence (production 0x9cc58..0x9cc78) ---
      0x4b160289,  // [24] insert:   sub  w9, w20, w22     ; w9 = name_offset
      0x2a1f03e0,  // [28]           mov  w0, wzr
      0x12004d29,  // [32]           and  w9, w9, #0xfffff
      0x2a090108,  // [36]           orr  w8, w8, w9       ; w8 = offset (len=0)
      0xb8387b28,  // [40]           str  w8, [x25, x24, lsl #2]   ; STORE 1
      0xf94006a8,  // [44]           ldr  x8, [x21, #0x8]  ; reload via x21
      0xb8787909,  // [48]           ldr  w9, [x8, x24, lsl #2]
      0x330c2e69,  // [52]           bfi  w9, w19, #20, #12 ; splice length
      0xb8387909,  // [56]           str  w9, [x8, x24, lsl #2]    ; STORE 2
      0x91000718,  // [60]           add  x24, x24, #1     ; next bucket idx
      0xf1000442,  // [64]           subs x2,  x2, #1
      0x54fffde8,  // [68]           b.hi -0x44 (-> loop_top, 256 iters)
  };

  constexpr size_t kNumSlots = 256;
  alignas(16) static uint32_t buckets[kNumSlots + 2];
  buckets[0] = 0xfeedfaceU;                       // leading guard
  for (size_t i = 0; i < kNumSlots; ++i) {
    buckets[i + 1] = 0;
  }
  buckets[kNumSlots + 1] = 0xdeadbeefU;           // trailing guard

  alignas(8) static uint64_t map_struct[4];
  map_struct[0] = 0;
  map_struct[1] = reinterpret_cast<uint64_t>(&buckets[1]);
  map_struct[2] = 0;
  map_struct[3] = 0;

  state_.cpu.x[21] = ToGuestAddr(&map_struct[0]);
  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;
  state_.cpu.x[26] = kNumSlots - 1;               // mask = 0xff
  state_.cpu.x[2]  = kNumSlots;
  state_.cpu.x[19] = 0xAAA;                        // BFI source: 12-bit length
  state_.cpu.x[20] = 0x12345ULL;
  state_.cpu.x[22] = 0;

  EXPECT_TRUE(RunMultiRegion(code, ToGuestAddr(code) + sizeof(code)));

  EXPECT_EQ(state_.cpu.x[2],  0ULL) << "loop must exit (x2 reaches 0)";
  EXPECT_EQ(state_.cpu.x[24], kNumSlots) << "x24 must reach kNumSlots";

  // Production-signature check: every bucket must have length=0xAAA in
  // bits[31:20].  Any bucket with length=0 reproduces the wedge.
  size_t first_length_zero = kNumSlots;
  uint32_t first_bad_bucket = 0;
  size_t count_length_zero = 0;
  for (size_t i = 0; i < kNumSlots; ++i) {
    const uint32_t bucket = buckets[i + 1];
    const uint32_t length = (bucket >> 20) & 0xfff;
    if (length == 0) {
      if (first_length_zero == kNumSlots) {
        first_length_zero = i;
        first_bad_bucket = bucket;
      }
      ++count_length_zero;
    }
  }
  EXPECT_EQ(first_length_zero, kNumSlots)
      << "HYPOTHESIS C CONFIRMED: " << count_length_zero << "/" << kNumSlots
      << " buckets have length=0 (production wedge signature reproduced "
      << "under combined FIND+INSERT host test); first at i="
      << first_length_zero << " value=0x" << std::hex << first_bad_bucket;

  EXPECT_EQ(buckets[0], 0xfeedfaceU);
  EXPECT_EQ(buckets[kNumSlots + 1], 0xdeadbeefU);
}

// Production AddToMap bucket-FIND loop at linker offset 0x9cc80..0x9ccb4 in
// CdEntryMapZip32<ZipStringOffset20>::AddToMap.  Uses the UXTW
// shifted-register addressing form (option=010, S=1), which is a DIFFERENT
// JIT code path from the UXTX/LSL form (option=011) covered by
// AddToMapBucketRmwUnderDispatch above.  Live debugging of a wedged
// VkCapsViewer this cycle showed:
//   - bucket array (256 × uint32_t at x25) is all zero
//   - x24 = 75 (probe index), x26 = 0xff (mask)
//   - thread spins forever in this loop
//   - the bucket array is empty, so b.eq must take on iteration 0 yet
//     the loop never exits
// This pins the wedge on the UXTW LDR path.  The test runs an all-zero
// 256-entry bucket array and asserts the loop exits on iteration 0.
// Minimal pin-test for the production AddToMap bucket-FIND load:
//   ldr w8, [x25, w24, uxtw #2]   (encoding 0xb8785b28, option=010 UXTW, S=1)
// All existing host tests use option=011 (LSL/UXTX, encoding 0xb8787909).
// Direct memory dump of a wedged VkCapsViewer this cycle showed the 256-entry
// bucket array at x25 is fully zero, yet the linker's bucket-find loop
// (CdEntryMapZip32<ZipStringOffset20>::AddToMap) does not exit via its
// b.eq empty-bucket branch.  This pins the JIT's UXTW load path on a
// minimal-no-branch sequence so we can rule it in or out cleanly.
TEST_F(Arm64LiteTranslateRegionTest, LdrW_UXTW_ShiftedReg_ReadsZeroFromZeroBucket) {
  // bucket[75] = 0, all guard bytes recognizable.
  constexpr size_t kNumSlots = 256;
  alignas(16) static uint32_t buckets[kNumSlots + 2];
  buckets[0] = 0xfeedfaceU;
  for (size_t i = 0; i < kNumSlots; ++i) {
    buckets[i + 1] = 0u;
  }
  buckets[kNumSlots + 1] = 0xdeadbeefU;

  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);  // bucket array base
  state_.cpu.x[24] = 75;                         // probe index (matches debuggerd snapshot)
  state_.cpu.x[8] = 0xbaadf00dULL;               // poison so a skipped LDR is caught
  state_.cpu.x[0] = 0xbaadf00dULL;

  // Two instructions: the LDR, plus a MOV that copies x8 to x0 (so even if
  // x8 is mapped/spilled differently, the result is observable via x0).
  static const uint32_t code[] = {
      0xb8785b28,  // ldr w8, [x25, w24, uxtw #2]
      0xaa0803e0,  // mov x0, x8
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));

  // The JIT must read 0 from bucket[75] and write that into x8 (and via
  // the mov, into x0).  Both must be 0.  Any non-zero result is the JIT
  // bug: the UXTW address computation read from somewhere other than
  // &buckets[1+75], OR the 32-bit load did not zero-extend correctly.
  EXPECT_EQ(state_.cpu.x[8], 0ULL)
      << "LDR-UXTW read 0x" << std::hex << state_.cpu.x[8]
      << " from bucket[75] (which is verifiably zero in memory at "
      << ToGuestAddr(&buckets[1 + 75]) << ").  Address computed by JIT was wrong.";
  EXPECT_EQ(state_.cpu.x[0], 0ULL)
      << "mov x0, x8 propagated x8=0x" << std::hex << state_.cpu.x[0]
      << " — confirms x8 was set to non-zero by the LDR.";

  // Guards untouched.
  EXPECT_EQ(buckets[0], 0xfeedfaceU);
  EXPECT_EQ(buckets[kNumSlots + 1], 0xdeadbeefU);
}

// Same shape, but with a non-zero bucket value, to verify the LDR DOES
// read the correct address (i.e., this test must PASS regardless of the
// JIT-UXTW bug — it just confirms the addressing math is reachable).
TEST_F(Arm64LiteTranslateRegionTest, LdrW_UXTW_ShiftedReg_ReadsNonZeroFromBucket75) {
  constexpr size_t kNumSlots = 256;
  alignas(16) static uint32_t buckets[kNumSlots + 2];
  for (size_t i = 0; i < kNumSlots + 2; ++i) {
    buckets[i] = 0xcafebabeU;  // recognizable sentinel everywhere
  }
  buckets[1 + 75] = 0x12345678U;  // distinct value at the indexed slot

  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 75;
  state_.cpu.x[8] = 0xbaadf00dULL;
  state_.cpu.x[0] = 0xbaadf00dULL;

  static const uint32_t code[] = {
      0xb8785b28,  // ldr w8, [x25, w24, uxtw #2]
      0xaa0803e0,  // mov x0, x8
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));

  EXPECT_EQ(state_.cpu.x[8], 0x12345678ULL);
  EXPECT_EQ(state_.cpu.x[0], 0x12345678ULL);
}

// Production AddToMap bucket-FIND loop, dispatch-enabled.  This mirrors
// the 8-instruction guest loop at linker offset 0x9cc80..0x9ccb4 inside
// CdEntryMapZip32<ZipStringOffset20>::AddToMap, with a 2-instruction
// SUBS/B.LS watchdog appended so the test fails cleanly instead of
// hanging if the b.eq empty-bucket exit fails to fire.
//
// Bucket layout: 256 × uint32_t, all zero.  x24=0 (probe index),
// x26=0xff (mask), x25=bucket base, x19=10 (search-key length).
// Iteration 0: LDR reads bucket[0]=0; ANDS x9,x8,#0xfffff sets Z;
// b.eq must take and exit to exit_success.  If b.eq is broken, the
// loop continues into the advance section, x24 increments, and after
// 1000 watchdog iterations exits to exit_fail.
//
// This is the dispatch-enabled multi-region counterpart to the
// LdrW_UXTW_ShiftedReg_ReadsZeroFromZeroBucket pin-test that PASSES
// in isolation but the production loop wedges on.  If this test
// PASSES, the wedge is elsewhere (a different region transition, a
// different operand shape, or interpreter fallback that re-enters
// after some other instruction).  If it FAILS, the bug is in the
// ANDS-imm flag setting, the b.eq read of Z, or the dispatch
// round-trip across the b.eq forward branch.
TEST_F(Arm64LiteTranslateRegionDispatchTest, AddToMapBucketFindUnderDispatch_UXTW) {
  // Encodings cross-checked with aarch64-linux-gnu-as round-trip.
  // loop_top (0x00..0x14), advance (0x18..0x2c), done_found (0x30),
  // exit_fail (0x34), exit_success (0x38).
  static const uint32_t code[] = {
      0xb8785b28,  // [0]  loop_top: ldr w8, [x25, w24, uxtw #2]
      0xf2404d09,  // [4]            ands x9, x8, #0xfffff
      0x54000180,  // [8]            b.eq exit_success (+0x30)
      0xeb48527f,  // [12]           cmp x19, x8, lsr #20
      0x54000041,  // [16]           b.ne advance (+0x08)
      0x14000007,  // [20]           b done_found (+0x1c)
      0x31000708,  // [24] advance:  adds w8, w24, #0x1
      0x540000c2,  // [28]           b.hs exit_fail (+0x18)
      0x0a1a0118,  // [32]           and w24, w8, w26
      0xf1000442,  // [36]           subs x2, x2, #0x1  (watchdog)
      0x54000069,  // [40]           b.ls exit_fail (+0x0c)
      0x17fffff5,  // [44]           b loop_top (-0x2c)
      0xd503201f,  // [48] done_found: nop
      0xd503201f,  // [52] exit_fail: nop
      0xd503201f,  // [56] exit_success: nop
  };

  constexpr size_t kNumSlots = 256;
  alignas(16) static uint32_t buckets[kNumSlots + 2];
  buckets[0] = 0xfeedfaceU;  // leading guard
  for (size_t i = 0; i < kNumSlots; ++i) {
    buckets[i + 1] = 0u;
  }
  buckets[kNumSlots + 1] = 0xdeadbeefU;  // trailing guard

  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;        // probe index
  state_.cpu.x[26] = 0xff;     // mask (N-1 for N=256 buckets)
  state_.cpu.x[19] = 10;       // search-key length (irrelevant since b.eq fires first)
  state_.cpu.x[2]  = 1000;     // watchdog
  state_.cpu.x[8]  = 0xbaadf00dULL;
  state_.cpu.x[9]  = 0xbaadf00dULL;

  // Expected exit: b.eq fires on iter 0 -> exit_success at offset 0x38.
  GuestAddr exit_success_addr = ToGuestAddr(code) + 0x38;

  EXPECT_TRUE(RunWithDispatch(code, exit_success_addr));

  EXPECT_EQ(state_.cpu.insn_addr, exit_success_addr)
      << "Expected exit to exit_success (b.eq empty-bucket).  insn_addr=0x"
      << std::hex << state_.cpu.insn_addr
      << ".  If 0x" << (ToGuestAddr(code) + 0x18) << ", b.eq did NOT fire — "
         "advance section reached on iter 0.  If 0x"
      << (ToGuestAddr(code) + 0x34) << ", watchdog exhausted (loop spun); "
         "b.eq never fired across many iterations.";

  EXPECT_EQ(state_.cpu.x[24], 0ULL)
      << "x24 must stay at 0 (b.eq exits on iter 0).  Got x24=0x"
      << std::hex << state_.cpu.x[24]
      << " — loop advanced even though bucket[0]=0 and ANDS should have set Z.";

  EXPECT_EQ(state_.cpu.x[2], 1000ULL)
      << "Watchdog must not have decremented (loop must not iterate).  x2=0x"
      << std::hex << state_.cpu.x[2];

  EXPECT_EQ(state_.cpu.x[8], 0ULL) << "LDR must have read bucket[0]=0";
  EXPECT_EQ(state_.cpu.x[9], 0ULL) << "ANDS x9,x8,#0xfffff with x8=0 must yield 0";

  EXPECT_EQ(buckets[0], 0xfeedfaceU);
  EXPECT_EQ(buckets[kNumSlots + 1], 0xdeadbeefU);
}

// production AddToMap bucket-FIND loop, single-region pin
// for the no-match (b.ne) path.  The existing UXTW dispatch test only
// exercises the iter-0 b.eq fast path (bucket[0] empty).  This test fills
// bucket[0] with a non-matching hash (top12 != x19) and exact non-zero
// offset bits, then verifies the JIT:
//   1. loads bucket[0] correctly via UXTW shifted-register addressing,
//   2. computes ANDS with #0xfffff producing a non-zero result (Z=0),
//   3. correctly does NOT take the b.eq forward branch,
//   4. computes CMP x19, x8, lsr #20 with non-zero LSR result,
//   5. correctly TAKES the b.ne forward branch dispatching to advance_addr.
//
// RunWithDispatch translates a single region starting at code[0]; the
// dispatch out to advance_addr returns to the runtime (no second region
// is pre-translated).  insn_addr at exit therefore equals advance_addr if
// the JIT got step 5 right.  This pins all five steps in a single region
// — the inner instructions of the production AddToMap loop body — without
// requiring multi-region cache wiring.  If the JIT mis-evaluated b.ne
// (e.g. taking it as b.eq), insn_addr would land at done_found instead.
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       AddToMapBucketFindUnderDispatch_UXTW_NonMatchTakesBNe) {
  static const uint32_t code[] = {
      0xb8785b28,  // [0]  loop_top: ldr w8, [x25, w24, uxtw #2]
      0xf2404d09,  // [4]            ands x9, x8, #0xfffff
      0x54000180,  // [8]            b.eq exit_success (+0x30)
      0xeb48527f,  // [12]           cmp x19, x8, lsr #20
      0x54000041,  // [16]           b.ne advance (+0x08)
      0x14000007,  // [20]           b done_found (+0x1c)
      0x31000708,  // [24] advance:  adds w8, w24, #0x1
      0x540000c2,  // [28]           b.hs exit_fail (+0x18)
      0x0a1a0118,  // [32]           and w24, w8, w26
      0xf1000442,  // [36]           subs x2, x2, #0x1
      0x54000069,  // [40]           b.ls exit_fail (+0x0c)
      0x17fffff5,  // [44]           b loop_top (-0x2c)
      0xd503201f,  // [48] done_found: nop
      0xd503201f,  // [52] exit_fail: nop
      0xd503201f,  // [56] exit_success: nop
  };

  // bucket[0] = (0xAAA << 20) | 0x100 = non-empty, hash field = 0xAAA.
  // x19 = 0xBBB so cmp mismatches, b.ne must fire.
  constexpr uint32_t kStoredHash = 0xAAA;
  constexpr uint32_t kStoredOffset = 0x100;
  constexpr uint64_t kSearchHash = 0xBBB;
  alignas(16) static uint32_t buckets[3];
  buckets[0] = 0xfeedfaceU;  // leading guard
  buckets[1] = (kStoredHash << 20) | kStoredOffset;
  buckets[2] = 0xdeadbeefU;  // trailing guard

  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;
  state_.cpu.x[26] = 0;          // mask irrelevant (one slot)
  state_.cpu.x[19] = kSearchHash;
  state_.cpu.x[2]  = 1000;
  state_.cpu.x[8]  = 0xbaadf00dULL;
  state_.cpu.x[9]  = 0xbaadf00dULL;

  GuestAddr advance_addr = ToGuestAddr(code) + 0x18;
  GuestAddr done_found_addr = ToGuestAddr(code) + 0x30;
  GuestAddr exit_success_addr = ToGuestAddr(code) + 0x38;

  // The framework translates only the first region; b.ne dispatches to
  // advance_addr which has no cached region, so execution stops there.
  // EXPECT_TRUE fails its internal insn_addr assertion when the actual
  // stop != expected — we pass advance_addr so the assertion is happy.
  EXPECT_TRUE(RunWithDispatch(code, advance_addr));

  EXPECT_EQ(state_.cpu.insn_addr, advance_addr)
      << "Expected JIT to dispatch via b.ne to advance_addr=0x" << std::hex
      << advance_addr << ".  Got insn_addr=0x" << state_.cpu.insn_addr
      << ".  If 0x" << done_found_addr
      << ", b.ne FAILED to fire — fall-through executed the unconditional "
         "branch.  If 0x" << exit_success_addr
      << ", b.eq spuriously fired despite non-empty bucket.";

  // x24 must still be 0 (advance block did not execute).
  EXPECT_EQ(state_.cpu.x[24], 0ULL) << "x24 should not have advanced yet";
  EXPECT_EQ(state_.cpu.x[2], 1000ULL) << "watchdog must not have decremented";

  // x8 must hold the loaded bucket value; x9 = bucket & 0xfffff.
  EXPECT_EQ(state_.cpu.x[8], buckets[1])
      << "LDR with UXTW#2 must read bucket[0]=0x" << std::hex << buckets[1];
  EXPECT_EQ(state_.cpu.x[9], static_cast<uint64_t>(kStoredOffset))
      << "ANDS x9, x8, #0xfffff must produce offset bits = 0x"
      << std::hex << kStoredOffset;

  EXPECT_EQ(buckets[0], 0xfeedfaceU);
  EXPECT_EQ(buckets[2], 0xdeadbeefU);
}

// production AddToMap bucket-FIND loop, multi-region,
// PARTIALLY POPULATED bucket array.  Pre-translates every region within
// the code array so cross-region dispatches resolve via TranslationCache.
//
// This is the test the VkCapsViewer wedge needs: it exercises the FULL
// iteration cycle that the cached-JIT spin walks through in production —
// loop-top region (ldr/ands/b.eq/cmp/b.ne) -> advance region (adds/b.hs/
// and/subs/b.ls/b) -> back-edge dispatch to loop top.  K iterations of
// "non-matching, non-empty bucket" before b.eq fires on the empty slot.
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       AddToMapBucketFindMultiRegion_PartiallyPopulated) {
  static const uint32_t code[] = {
      0xb8785b28,  // [0]  loop_top: ldr w8, [x25, w24, uxtw #2]
      0xf2404d09,  // [4]            ands x9, x8, #0xfffff
      0x54000180,  // [8]            b.eq exit_success (+0x30)
      0xeb48527f,  // [12]           cmp x19, x8, lsr #20
      0x54000041,  // [16]           b.ne advance (+0x08)
      0x14000007,  // [20]           b done_found (+0x1c)
      0x31000708,  // [24] advance:  adds w8, w24, #0x1
      0x540000c2,  // [28]           b.hs exit_fail (+0x18)
      0x0a1a0118,  // [32]           and w24, w8, w26
      0xf1000442,  // [36]           subs x2, x2, #0x1
      0x54000069,  // [40]           b.ls exit_fail (+0x0c)
      0x17fffff5,  // [44]           b loop_top (-0x2c)
      0xd503201f,  // [48] done_found: nop
      0xd503201f,  // [52] exit_fail: nop
      0xd503201f,  // [56] exit_success: nop
  };

  constexpr size_t kNumSlots = 16;
  constexpr size_t kEmptyIdx = 3;
  constexpr uint32_t kStoredHash = 0xAAA;
  constexpr uint64_t kSearchHash = 0xBBB;
  alignas(16) static uint32_t buckets[kNumSlots + 2];
  buckets[0] = 0xfeedfaceU;
  for (size_t i = 0; i < kNumSlots; ++i) {
    if (i == kEmptyIdx) {
      buckets[i + 1] = 0u;
    } else {
      buckets[i + 1] = (kStoredHash << 20) | (0x100 + static_cast<uint32_t>(i));
    }
  }
  buckets[kNumSlots + 1] = 0xdeadbeefU;

  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;
  state_.cpu.x[26] = kNumSlots - 1;
  state_.cpu.x[19] = kSearchHash;
  state_.cpu.x[2]  = 1000;
  state_.cpu.x[8]  = 0xbaadf00dULL;
  state_.cpu.x[9]  = 0xbaadf00dULL;

  GuestAddr exit_success_addr = ToGuestAddr(code) + 0x38;
  GuestAddr exit_fail_addr = ToGuestAddr(code) + 0x34;
  GuestAddr done_found_addr = ToGuestAddr(code) + 0x30;

  EXPECT_TRUE(RunMultiRegion(code, exit_success_addr));

  EXPECT_EQ(state_.cpu.insn_addr, exit_success_addr)
      << "Expected b.eq to fire on bucket[" << kEmptyIdx << "].  Got 0x"
      << std::hex << state_.cpu.insn_addr << ".  If 0x" << done_found_addr
      << ": cmp+b.ne wrong direction (spurious match path).  If 0x"
      << exit_fail_addr << ": watchdog exhausted — loop spun forever, the "
         "production VkCaps wedge signature reproduced under host test.";

  EXPECT_EQ(state_.cpu.x[24], static_cast<uint64_t>(kEmptyIdx))
      << "x24 must equal " << kEmptyIdx << " (empty bucket idx).";
  EXPECT_EQ(state_.cpu.x[8], 0ULL) << "last LDR must read bucket[empty]=0";
  EXPECT_EQ(state_.cpu.x[9], 0ULL) << "ANDS with x8=0 yields 0";
  EXPECT_EQ(state_.cpu.x[2], 1000ULL - kEmptyIdx)
      << "watchdog should have decremented exactly " << kEmptyIdx << " times";

  EXPECT_EQ(buckets[0], 0xfeedfaceU);
  EXPECT_EQ(buckets[kNumSlots + 1], 0xdeadbeefU);
}

// production AddToMap bucket-FIND loop, multi-region,
// FULLY POPULATED bucket array with non-matching hashes.  Equivalent to
// the genuine pathological-data hypothesis (-266 hypothesis B): every
// bucket is non-empty AND no hash matches.  The ARM ARM-defined loop
// SHOULD spin forever in this case (until the b.hs overflow at iter
// 0xFFFFFFFF, far beyond any real bucket count).
//
// We verify this with a watchdog: after 50 iterations the b.ls fires
// and we exit_fail.  If the loop terminates EARLIER (insn_addr ==
// exit_success_addr), the JIT spuriously took b.eq when no bucket was
// empty — i.e. ANDS with non-zero result set Z=1.
TEST_F(Arm64LiteTranslateRegionDispatchTest,
       AddToMapBucketFindMultiRegion_FullyPopulatedSpins) {
  static const uint32_t code[] = {
      0xb8785b28,  // [0]  loop_top: ldr w8, [x25, w24, uxtw #2]
      0xf2404d09,  // [4]            ands x9, x8, #0xfffff
      0x54000180,  // [8]            b.eq exit_success (+0x30)
      0xeb48527f,  // [12]           cmp x19, x8, lsr #20
      0x54000041,  // [16]           b.ne advance (+0x08)
      0x14000007,  // [20]           b done_found (+0x1c)
      0x31000708,  // [24] advance:  adds w8, w24, #0x1
      0x540000c2,  // [28]           b.hs exit_fail (+0x18)
      0x0a1a0118,  // [32]           and w24, w8, w26
      0xf1000442,  // [36]           subs x2, x2, #0x1
      0x54000069,  // [40]           b.ls exit_fail (+0x0c)
      0x17fffff5,  // [44]           b loop_top (-0x2c)
      0xd503201f,  // [48] done_found: nop
      0xd503201f,  // [52] exit_fail: nop
      0xd503201f,  // [56] exit_success: nop
  };

  constexpr size_t kNumSlots = 16;
  constexpr uint32_t kStoredHash = 0xAAA;
  constexpr uint64_t kSearchHash = 0xBBB;
  alignas(16) static uint32_t buckets[kNumSlots + 2];
  buckets[0] = 0xfeedfaceU;
  for (size_t i = 0; i < kNumSlots; ++i) {
    // Every bucket non-empty (lower 20 bits != 0), hash != kSearchHash.
    buckets[i + 1] = (kStoredHash << 20) | (0x100 + static_cast<uint32_t>(i));
  }
  buckets[kNumSlots + 1] = 0xdeadbeefU;

  state_.cpu.x[25] = ToGuestAddr(&buckets[1]);
  state_.cpu.x[24] = 0;
  state_.cpu.x[26] = kNumSlots - 1;
  state_.cpu.x[19] = kSearchHash;
  state_.cpu.x[2]  = 50;
  state_.cpu.x[8]  = 0xbaadf00dULL;
  state_.cpu.x[9]  = 0xbaadf00dULL;

  GuestAddr exit_success_addr = ToGuestAddr(code) + 0x38;
  GuestAddr exit_fail_addr = ToGuestAddr(code) + 0x34;

  EXPECT_TRUE(RunMultiRegion(code, exit_fail_addr));

  EXPECT_EQ(state_.cpu.insn_addr, exit_fail_addr)
      << "Expected watchdog to fire (loop spins on fully-populated, no-"
         "match table).  Got 0x" << std::hex << state_.cpu.insn_addr
      << ".  If 0x" << exit_success_addr
      << ": ANDS spuriously set Z=1 on a non-empty bucket.";

  // After 50 iterations of the watchdog (subs x2,x2,#1 with b.ls), the
  // loop exits.  x2 should be 0 (b.ls takes when C=0 or Z=1; subs with
  // x2 going 50->...->1 keeps C=1 (no borrow) until x2=1->0 which sets
  // Z=1 and C=1, so b.ls=(C==0 OR Z==1) fires at x2=0).
  EXPECT_EQ(state_.cpu.x[2], 0ULL) << "watchdog should reach 0";
}

// Hypothesis G.1 — JIT `adds Wd, Wn, #imm` (W-form)
// must set ARM C=1 when the 32-bit unsigned sum wraps, so that a following
// `b.hs target` (HS = C==1) takes the branch.
//
// Production AddToMap inner loop at linker64 offsets 0x9cc48-0x9cc4c emits:
//     adds  w8, w24, #0x1
//     b.hs  0x9cccc           ; -> ubsan_handle_add_overflow_minimal_abort
// simpleperf + /proc/PID/mem dump shows VkCapsViewer's qtMainLoopThread
// spends 84% of CPU in the JIT translation of this code range.  If the JIT
// for `adds w8, w24, #1` fails to set C correctly when w24 wraps from
// 0xFFFFFFFF, `b.hs` falls through and the loop never exits via overflow.
//
// The existing FullyPopulatedSpins multi-region test verifies the watchdog
// fires (loop spins on a fully populated table) but does NOT exercise the
// w24 == 0xFFFFFFFF boundary case where b.hs should TAKE.  This test pins
// that boundary directly: it sets w24 = 0xFFFFFFFF, runs adds + b.hs, and
// verifies the branch target is reached.
TEST_F(Arm64LiteTranslateRegionTest, AddsW32OverflowSetsCarryBhsFires) {
  // Encodings cross-checked with the ARM ARM C6.2.4 (ADDS imm) and C6.2.27
  // (B.cond): adds w8, w24, #1 == 0x31000708; b.hs +0x10 == 0x54000082.
  // MOVZ w24, #0xFFFF == 0x529FFFF8; MOVK w24, #0xFFFF, lsl #16 == 0x72BFFFF8.
  static const uint32_t code[] = {
      0x529FFFF8,                 // [0]   MOVZ w24, #0xFFFF
      0x72BFFFF8,                 // [4]   MOVK w24, #0xFFFF, lsl #16
                                  //       -> w24 = 0xFFFFFFFF
      0x31000708,                 // [8]   ADDS w8, w24, #1
                                  //       -> w8 = 0 (32-bit wrap), C=1, Z=1
      Bcond(kCondCS, 0x10),       // [12]  B.HS +0x10  -> code + 0x1c
      MovzX(0, 0xDEAD),           // [16]  fall-through (BUG path)
      kNop,                       // [20]
      kNop,                       // [24]
      MovzX(0, 0xC0DE),           // [28]  b.hs target (not translated)
  };
  state_.cpu.x[0] = 0xBAADF00DULL;
  state_.cpu.x[8] = 0xBAADF00DULL;

  // Expected: b.hs takes, JIT region exits at code + 0x1c.
  GuestAddr expected_branch_target = ToGuestAddr(code) + 0x1c;
  EXPECT_TRUE(Run(code, expected_branch_target));

  EXPECT_EQ(state_.cpu.insn_addr, expected_branch_target)
      << "HYPOTHESIS G.1 OUTCOME: b.hs did NOT fire after `adds w8, "
         "w24=0xFFFFFFFF, #1`.  ARM ARM requires C=1 on 32-bit unsigned "
         "overflow; if insn_addr=0x" << std::hex << (ToGuestAddr(code) + 0x10)
      << ", the JIT's W-form ADDS carry-flag emission is buggy.";

  EXPECT_EQ(state_.cpu.x[24], 0xFFFFFFFFULL)
      << "Setup invariant: w24 must hold 0xFFFFFFFF after MOVZ+MOVK.";

  EXPECT_EQ(state_.cpu.x[8], 0ULL)
      << "ARM ARM: ADDS w8, w24=0xFFFFFFFF, #1 must produce w8 = 0 "
         "(32-bit wrap, upper 32 bits zero from W-form zero-extend).  "
         "Got 0x" << std::hex << state_.cpu.x[8];

  EXPECT_EQ(state_.cpu.x[0], 0xBAADF00DULL)
      << "Fall-through `MOVZ x0, #0xDEAD` must NOT have executed.";
}

// Negative companion: `adds w8, w24=0x7FFFFFFE, #1` -> w8 = 0x7FFFFFFF,
// C=0, b.hs must NOT fire.  Pins the no-overflow path so we can detect
// either polarity error (b.hs spuriously firing OR failing).
TEST_F(Arm64LiteTranslateRegionTest, AddsW32NoOverflowBhsFallsThrough) {
  // MOVZ w24, #0xFFFE       = 0x529FFFD8
  // MOVK w24, #0x7FFF, lsl #16 = 0x72AFFFF8  -> w24 = 0x7FFFFFFE
  static const uint32_t code[] = {
      0x529FFFD8,                 // [0]   MOVZ w24, #0xFFFE
      0x72AFFFF8,                 // [4]   MOVK w24, #0x7FFF, lsl #16
      0x31000708,                 // [8]   ADDS w8, w24, #1
                                  //       -> w8 = 0x7FFFFFFF, C=0
      Bcond(kCondCS, 0x10),       // [12]  B.HS  (must NOT fire)
  };
  state_.cpu.x[8] = 0xBAADF00DULL;

  // b.hs falls through; JIT region ends at fall-through PC (code + 16).
  GuestAddr fall_through = ToGuestAddr(code) + sizeof(code);
  EXPECT_TRUE(Run(code, fall_through));

  EXPECT_EQ(state_.cpu.insn_addr, fall_through)
      << "b.hs spuriously fired on a non-overflowing adds.  C must be 0 "
         "when w24=0x7FFFFFFE + 1 = 0x7FFFFFFF (no unsigned wrap).";
  EXPECT_EQ(state_.cpu.x[24], 0x7FFFFFFEULL) << "Setup invariant";
  EXPECT_EQ(state_.cpu.x[8], 0x7FFFFFFFULL)
      << "ARM ARM: adds w8, 0x7FFFFFFE, #1 -> 0x7FFFFFFF.  Got 0x"
      << std::hex << state_.cpu.x[8];
}

// G.1 boundary completeness: full pre-mask state w24=0xFFFFFFFE.
// adds w8, 0xFFFFFFFE, #1 -> w8 = 0xFFFFFFFF, C=0 (no wrap), b.hs must NOT fire.
// This is the immediate predecessor of the wrap case above; if the JIT
// computes C from the 64-bit sum instead of the 32-bit sum, it would
// already show a difference here.
TEST_F(Arm64LiteTranslateRegionTest, AddsW32JustBelowOverflowBhsFallsThrough) {
  // MOVZ w24, #0xFFFE         = 0x529FFFD8
  // MOVK w24, #0xFFFF, lsl #16 = 0x72BFFFF8  -> w24 = 0xFFFFFFFE
  static const uint32_t code[] = {
      0x529FFFD8,                 // [0]   MOVZ w24, #0xFFFE
      0x72BFFFF8,                 // [4]   MOVK w24, #0xFFFF, lsl #16
      0x31000708,                 // [8]   ADDS w8, w24, #1
                                  //       -> w8 = 0xFFFFFFFF, C=0
      Bcond(kCondCS, 0x10),       // [12]  B.HS  (must NOT fire)
  };
  state_.cpu.x[8] = 0xBAADF00DULL;

  GuestAddr fall_through = ToGuestAddr(code) + sizeof(code);
  EXPECT_TRUE(Run(code, fall_through));

  EXPECT_EQ(state_.cpu.insn_addr, fall_through)
      << "b.hs spuriously fired on adds w8, 0xFFFFFFFE, #1 = 0xFFFFFFFF.  "
         "Result max-uint32 but no carry — JIT may be misreading C from "
         "high-bit of result instead of the actual overflow bit.";
  EXPECT_EQ(state_.cpu.x[24], 0xFFFFFFFEULL) << "Setup invariant";
  EXPECT_EQ(state_.cpu.x[8], 0xFFFFFFFFULL);
}

// BFM (BFI / BFXIL) JIT
// BFM merges bits of src into a destination register, leaving the other
// destination bits alone.  Two ARM ARM aliases that share this encoding
// are exercised here:
//   BFI Wd, Wn, #lsb, #width  -> BFM Wd, Wn, #(-lsb mod 32), #(width-1)
//   BFXIL Wd, Wn, #lsb, #width -> BFM Wd, Wn, #lsb, #(lsb+width-1)
// These pin the JIT's BFM path on the exact pattern Bionic's AddToMap
// uses to encode CdEntryMapZip32 buckets:  the bucket stores
// (name_length << 20) | (name_offset & 0xfffff); the second store does
// `bfi w9, w19, #20, #12` to write the 12-bit length at bit 20.
// If BFM's JIT (or its interpreter fallback) silently drops STORE 2,
// the bucket ends up with top12bits == 0 — exactly the wedged-VkCaps
// signature earlier debugging chased.
//
// Encodings cross-checked with the ARM ARM C6.2.34 / C6.2.35 / C6.2.36.
//   BFI w9, w19, #20, #12   = 0x330C2E69  (sf=0, opc=01, immr=12, imms=11)
//   BFI x9, x19, #20, #12   = 0xB36C2E69  (sf=1, N=1, immr=44, imms=11)
//   BFXIL w0, w1, #4, #8    = 0x33042C20  (sf=0, immr=4,  imms=11)
//   BFXIL x0, x1, #16, #32  = 0xB350BC20  (sf=1, immr=16, imms=47)
//   BFC w0, #8, #16         = 0x33183FE0  (BFI Wd, WZR, ...)
TEST_F(Arm64LiteTranslateRegionTest, BfiW_AddToMapInsertPattern) {
  // bfi w9, w19, #20, #12:  bucket = (length << 20) | (bucket & 0x000fffff)
  // Pre-load w9 with name_offset (already OR'd from STORE 1).
  // Pre-load w19 with name_length (12-bit value; high bits must be ignored).
  state_.cpu.x[9]  = 0x00007a64ULL;            // STORE 1 result: only low 20 set.
  state_.cpu.x[19] = 0x12345AAAULL;            // length=0xAAA (high bits noise).
  static const uint32_t code[] = {
      0x330C2E69,  // bfi w9, w19, #20, #12
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  // Expected: w9 = (0xAAA << 20) | 0x7a64 = 0xAAA07A64; upper 32 bits zero.
  EXPECT_EQ(state_.cpu.x[9], 0xAAA07A64ULL);
  EXPECT_EQ(state_.cpu.x[19], 0x12345AAAULL) << "src register must be preserved";
}

TEST_F(Arm64LiteTranslateRegionTest, BfiW_PreservesOtherBitsAndZeroesUpper) {
  // bfi w9, w19, #4, #8: write low 8 bits of w19 to bits[11:4] of w9.
  state_.cpu.x[9]  = 0xFFFFFFFFFFFFFFFFULL;    // all ones; upper 32 must become 0.
  state_.cpu.x[19] = 0x000000A5ULL;
  // Encoding: BFM w9, w19, #(-4 mod 32 = 28), #(8-1 = 7)
  static const uint32_t code[] = {
      0x331C1E69,  // bfi w9, w19, #4, #8
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  // bits [11:4] -> 0xA5; other low-32 bits unchanged; upper 32 -> 0.
  EXPECT_EQ(state_.cpu.x[9], 0x00000000FFFFFA5FULL);
}

TEST_F(Arm64LiteTranslateRegionTest, BfiX_64BitInsert) {
  // bfi x9, x19, #20, #12: 64-bit form.
  state_.cpu.x[9]  = 0xDEADBEEF00007A64ULL;
  state_.cpu.x[19] = 0x12345AAAULL;
  static const uint32_t code[] = {
      0xB36C2E69,  // bfi x9, x19, #20, #12
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  // Expected: bits[31:20] of x9 become 0xAAA; everything else unchanged.
  EXPECT_EQ(state_.cpu.x[9], 0xDEADBEEFAAA07A64ULL);
}

TEST_F(Arm64LiteTranslateRegionTest, BfxilW_ExtractAndDeposit) {
  // bfxil w0, w1, #4, #8: copy bits[11:4] of w1 to bits[7:0] of w0.
  state_.cpu.x[0] = 0xFFFFFFFFFFFFFF00ULL;
  state_.cpu.x[1] = 0x00000A50ULL;             // bits[11:4] = 0xA5.
  static const uint32_t code[] = {
      0x33042C20,  // bfxil w0, w1, #4, #8
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  // bits[7:0] of w0 become 0xA5; other low-32 bits unchanged; upper 32 -> 0.
  EXPECT_EQ(state_.cpu.x[0], 0x00000000FFFFFFA5ULL);
}

TEST_F(Arm64LiteTranslateRegionTest, BfxilX_FullWidth) {
  // bfxil x0, x1, #16, #32: copy bits[47:16] of x1 to bits[31:0] of x0.
  state_.cpu.x[0] = 0xAAAAAAAABBBBBBBBULL;
  state_.cpu.x[1] = 0x1234567890ABCDEFULL;     // bits[47:16] = 0x567890AB.
  static const uint32_t code[] = {
      0xB350BC20,  // bfxil x0, x1, #16, #32
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[0], 0xAAAAAAAA567890ABULL);
}

TEST_F(Arm64LiteTranslateRegionTest, BfcW_ClearBitfield) {
  // bfc w0, #8, #16: clear bits[23:8] of w0 (BFI with src=WZR).
  state_.cpu.x[0] = 0xFFFFFFFFFFFFFFFFULL;
  static const uint32_t code[] = {
      0x33183FE0,  // bfc w0, #8, #16
  };
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  EXPECT_EQ(state_.cpu.x[0], 0x00000000FF0000FFULL);
}

// INS (element) JIT
// INS Vd.<T>[dst_idx], Vn.<T>[src_idx] — copy one esize-byte lane from Vn
// to one lane of Vd, leaving every other lane of Vd unchanged.  These
// tests pin the new JIT path's correctness on the four lane widths
// (B/H/S/D), the self-INS (rd == rn) aliasing case, and the "don't
// touch the other lanes" property that distinguishes INS-element from
// DUP/scalar broadcasts.
//
// Encodings verified via aarch64-linux-gnu-as round-trip.
constexpr uint32_t kInsElemB0_FromB1   = 0x6e010c20;  // ins v0.b[0], v1.b[1]
constexpr uint32_t kInsElemB5_FromB10  = 0x6e0b5420;  // ins v0.b[5], v1.b[10]
constexpr uint32_t kInsElemH3_FromH1   = 0x6e0e1420;  // ins v0.h[3], v1.h[1]
constexpr uint32_t kInsElemS2_FromS0   = 0x6e140420;  // ins v0.s[2], v1.s[0]
constexpr uint32_t kInsElemD1_FromD0   = 0x6e180420;  // ins v0.d[1], v1.d[0]
constexpr uint32_t kInsElemSelfS0FromS3 = 0x6e046400; // ins v0.s[0], v0.s[3]

TEST_F(Arm64LiteTranslateRegionTest, InsElemB0_FromB1) {
  // ins v0.b[0], v1.b[1]  — only byte 0 of v0 changes (to 0xAB),
  // every other byte of v0 keeps the sentinel.
  std::memset(&state_.cpu.v[0], 0xCC, 16);
  uint8_t v1[16] = {0x11, 0xAB, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,
                    0x88, 0x99, 0xAA, 0xBB, 0xDD, 0xEE, 0xFF, 0x00};
  std::memcpy(&state_.cpu.v[1], v1, 16);
  static const uint32_t code[] = {kInsElemB0_FromB1};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  EXPECT_EQ(r[0], 0xABu) << "dst lane 0 took src v1.b[1]";
  for (int i = 1; i < 16; ++i) {
    EXPECT_EQ(r[i], 0xCCu) << "untouched byte " << i;
  }
}

TEST_F(Arm64LiteTranslateRegionTest, InsElemB5_FromB10) {
  // ins v0.b[5], v1.b[10]  — high-index source + non-zero dst index.
  std::memset(&state_.cpu.v[0], 0x55, 16);
  uint8_t v1[16] = {0};
  v1[10] = 0xAB;
  std::memcpy(&state_.cpu.v[1], v1, 16);
  static const uint32_t code[] = {kInsElemB5_FromB10};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  for (int i = 0; i < 16; ++i) {
    uint8_t expected = (i == 5) ? 0xAB : 0x55;
    EXPECT_EQ(r[i], expected) << "byte " << i;
  }
}

TEST_F(Arm64LiteTranslateRegionTest, InsElemH3_FromH1) {
  // ins v0.h[3], v1.h[1]  — halfword copy from src idx 1 to dst idx 3.
  std::memset(&state_.cpu.v[0], 0xCC, 16);
  uint16_t v1[8] = {0x1111, 0xBEEF, 0x2222, 0x3333,
                    0x4444, 0x5555, 0x6666, 0x7777};
  std::memcpy(&state_.cpu.v[1], v1, 16);
  static const uint32_t code[] = {kInsElemH3_FromH1};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint16_t r[8];
  std::memcpy(r, &state_.cpu.v[0], 16);
  for (int i = 0; i < 8; ++i) {
    uint16_t expected = (i == 3) ? 0xBEEFu : 0xCCCCu;
    EXPECT_EQ(r[i], expected) << "halfword " << i;
  }
}

TEST_F(Arm64LiteTranslateRegionTest, InsElemS2_FromS0) {
  // ins v0.s[2], v1.s[0]  — 32-bit lane copy.
  std::memset(&state_.cpu.v[0], 0xAA, 16);
  uint32_t v1[4] = {0xDEADBEEFu, 0x11111111u, 0x22222222u, 0x33333333u};
  std::memcpy(&state_.cpu.v[1], v1, 16);
  static const uint32_t code[] = {kInsElemS2_FromS0};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint32_t r[4];
  std::memcpy(r, &state_.cpu.v[0], 16);
  EXPECT_EQ(r[0], 0xAAAAAAAAu) << "s lane 0 untouched";
  EXPECT_EQ(r[1], 0xAAAAAAAAu) << "s lane 1 untouched";
  EXPECT_EQ(r[2], 0xDEADBEEFu) << "s lane 2 took v1.s[0]";
  EXPECT_EQ(r[3], 0xAAAAAAAAu) << "s lane 3 untouched";
}

TEST_F(Arm64LiteTranslateRegionTest, InsElemD1_FromD0) {
  // ins v0.d[1], v1.d[0]  — 64-bit lane copy; the full 64 bits must
  // make it across (pins the Movq-not-Movl discipline for the doubleword
  // form).
  std::memset(&state_.cpu.v[0], 0x77, 16);
  uint64_t v1[2] = {0xFEEDFACECAFEBABEULL, 0x0123456789ABCDEFULL};
  std::memcpy(&state_.cpu.v[1], v1, 16);
  static const uint32_t code[] = {kInsElemD1_FromD0};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint64_t r[2];
  std::memcpy(r, &state_.cpu.v[0], 16);
  EXPECT_EQ(r[0], 0x7777777777777777ULL) << "d lane 0 untouched";
  EXPECT_EQ(r[1], 0xFEEDFACECAFEBABEULL) << "d lane 1 took full 64 bits";
}

TEST_F(Arm64LiteTranslateRegionTest, InsElemSelfS0FromS3) {
  // ins v0.s[0], v0.s[3]  — rd == rn aliasing: load Vn.s[3] then store
  // back to Vd.s[0].  Verifies the JIT loads into a temp register before
  // touching Vd, so the source isn't clobbered mid-copy.
  uint32_t v0[4] = {0x00000000u, 0x11111111u, 0x22222222u, 0xCAFEF00Du};
  std::memcpy(&state_.cpu.v[0], v0, 16);
  static const uint32_t code[] = {kInsElemSelfS0FromS3};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint32_t r[4];
  std::memcpy(r, &state_.cpu.v[0], 16);
  EXPECT_EQ(r[0], 0xCAFEF00Du) << "s lane 0 took s lane 3";
  EXPECT_EQ(r[1], 0x11111111u) << "s lane 1 untouched";
  EXPECT_EQ(r[2], 0x22222222u) << "s lane 2 untouched";
  EXPECT_EQ(r[3], 0xCAFEF00Du) << "s lane 3 (source) preserved";
}

// SQADD/UQADD/SQSUB/UQSUB vector JIT (byte/halfword)
//
// Encoding (DDI 0487 §C7.2 Advanced SIMD three same):
//   0 Q U 01110 size 1 Rm opcode 1 Rn Rd
// SQADD/UQADD opcode = 0b00001 (U=0 signed / U=1 unsigned).
// SQSUB/UQSUB opcode = 0b00101 (U=0 signed / U=1 unsigned).
// JIT covers 8-bit (size=00) and 16-bit (size=01) lanes; 32/64-bit lanes
// fall back to the interpreter (Undefined()) — x86 has no direct
// saturating PADD/PSUB for those widths.

TEST_F(Arm64LiteTranslateRegionTest, SqaddVec16BSaturate) {
  // SQADD V0.16B, V1.16B, V2.16B — signed saturation at INT8 boundaries.
  int8_t n[16] = {  127,  127, -128, -128,    0,    1,   -1,   50,
                     10,  -10,   64,  -64,  100, -100,    7,   -7};
  int8_t m[16] = {    1,  -1,   -1,    1,    0,    1,   -1,  100,
                     20,  -20,  100, -100,   50,  -50,   -3,    3};
  std::memcpy(&state_.cpu.v[1], n, 16);
  std::memcpy(&state_.cpu.v[2], m, 16);
  std::memset(&state_.cpu.v[0], 0xAA, 16);
  static const uint32_t code[] = {
      SimdThreeSame(/*q=*/1, /*u=*/0, /*size=*/0b00,
                    /*opcode=*/0b00001, 0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  int8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  EXPECT_EQ(r[0],  127);   // 127 + 1   → saturate +127
  EXPECT_EQ(r[1],  126);   // 127 + -1
  EXPECT_EQ(r[2], -128);   // -128 + -1 → saturate -128
  EXPECT_EQ(r[3], -127);   // -128 + 1
  EXPECT_EQ(r[4],    0);
  EXPECT_EQ(r[5],    2);
  EXPECT_EQ(r[6],   -2);
  EXPECT_EQ(r[7],  127);   // 50 + 100 = 150 → saturate +127
  EXPECT_EQ(r[8],   30);
  EXPECT_EQ(r[9],  -30);
  EXPECT_EQ(r[10], 127);   // 64 + 100 = 164 → saturate +127
  EXPECT_EQ(r[11],-128);   // -64 + -100 = -164 → saturate -128
  EXPECT_EQ(r[12], 127);   // 100 + 50 = 150 → saturate +127
  EXPECT_EQ(r[13],-128);   // -100 + -50 = -150 → saturate -128
  EXPECT_EQ(r[14],   4);
  EXPECT_EQ(r[15],  -4);
}

TEST_F(Arm64LiteTranslateRegionTest, SqaddVec8BUpperZero) {
  // Q=0 .8B form: upper 8 bytes of Vd must be zero, including when V[0]
  // had non-zero garbage pre-seed.
  int8_t n[16] = {127, 0, 0, 0, 0, 0, 0, 0, 99, 99, 99, 99, 99, 99, 99, 99};
  int8_t m[16] = {  1, 0, 0, 0, 0, 0, 0, 0, 99, 99, 99, 99, 99, 99, 99, 99};
  std::memcpy(&state_.cpu.v[1], n, 16);
  std::memcpy(&state_.cpu.v[2], m, 16);
  std::memset(&state_.cpu.v[0], 0x77, 16);
  static const uint32_t code[] = {
      SimdThreeSame(/*q=*/0, /*u=*/0, /*size=*/0b00,
                    /*opcode=*/0b00001, 0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  uint8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  EXPECT_EQ(static_cast<int8_t>(r[0]), 127);  // saturate
  for (int i = 8; i < 16; i++) {
    EXPECT_EQ(r[i], 0u) << "upper lane " << i << " not zeroed";
  }
}

TEST_F(Arm64LiteTranslateRegionTest, SqaddVec8HSaturate) {
  int16_t n[8] = { 32767, 32767, -32768, -32768,     0,   100, -100,   200};
  int16_t m[8] = {     1,    -1,     -1,      1,     0, 32700,-32700,   300};
  std::memcpy(&state_.cpu.v[1], n, 16);
  std::memcpy(&state_.cpu.v[2], m, 16);
  std::memset(&state_.cpu.v[0], 0xAA, 16);
  static const uint32_t code[] = {
      SimdThreeSame(/*q=*/1, /*u=*/0, /*size=*/0b01,
                    /*opcode=*/0b00001, 0, 1, 2)};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  int16_t r[8];
  std::memcpy(r, &state_.cpu.v[0], 16);
  EXPECT_EQ(r[0],  32767);    // saturate +
  EXPECT_EQ(r[1],  32766);
  EXPECT_EQ(r[2], -32768);    // saturate -
  EXPECT_EQ(r[3], -32767);
  EXPECT_EQ(r[4],      0);
  EXPECT_EQ(r[5],  32767);    // 100 + 32700 = 32800 → saturate +
  EXPECT_EQ(r[6], -32768);    // -100 + -32700 = -32800 → saturate -
  EXPECT_EQ(r[7],    500);
}

