  uint16_t in_n[8] = {0x0000, 0xFFFF, 0x0008, 0x0007, 0x8000, 0x7FFF, 0x1234, 0xABCD};
  std::memcpy(&state_.cpu.v[1], in_n, 16);
  std::memset(&state_.cpu.v[0], 0xAA, 16);
  static const uint32_t code[] = {kUrshrVec8H_3};
