  static const uint32_t code[] = {kSsraVec16B_4};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
  int8_t r[16];
  std::memcpy(r, &state_.cpu.v[0], 16);
  const int8_t expect[16] = {1, -1, 6, -7, 17, -3, 0, -1,
                             3,  0, 7,  0,  5,  5, 7,  7};
