  std::memcpy(&state_.cpu.v[1], in_vn, 16);
  std::memcpy(&state_.cpu.v[0], in_vd, 16);
  static const uint32_t code[] = {kUsraVec8B_4};
  EXPECT_TRUE(Run(code, ToGuestAddr(code) + sizeof(code)));
